-- ============================================================
-- 圣经全文（新改訳2017）· 数据文件（分拆版） 4/6
-- 先运行 bible_cuv_schema.sql 建表（已运行过可跳过），再按序号运行。
-- 可重复运行（冲突自动跳过）。本文件 5200 节。
-- ============================================================
-- 本文件为 bible_jpn_data_04.sql 的第 b 半（原文件超过 SQL Editor 体积上限，故拆分）。
-- 运行顺序：01a → 01b → 02a → 02b → … → 06b。可重复运行（冲突自动跳过）。
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '以赛亚书', 23, 59, 1, '見よ。主の手が短くて救えないのではない。その耳が遠くて聞こえないのではない。'),
('JPN', '以赛亚书', 23, 59, 2, 'むしろ、あなたがたの咎が、あなたがたと、あなたがたの神との仕切りとなり、あなたがたの罪が御顔を隠させ、聞いてくださらないようにしたのだ。'),
('JPN', '以赛亚书', 23, 59, 3, '実に、あなたがたの手は血で、指は咎で汚れている。あなたがたの唇は偽りを語り、舌は不正を告げる。'),
('JPN', '以赛亚书', 23, 59, 4, '義をもって訴える者はなく、真実をもって弁護する者もいない。空しいことに頼り、噓を言い、邪悪をはらみ、不正を産む。'),
('JPN', '以赛亚书', 23, 59, 5, '彼らは、まむしの卵をかえし、くもの巣を織る。その卵を食べる者は死に、卵をつぶすと毒蛇が飛び出す。'),
('JPN', '以赛亚书', 23, 59, 6, 'そのくもの巣は衣にはならず、自分の作ったもので身をおおうこともできない。彼らのわざは不義のわざ、暴虐の行いがその手にある。'),
('JPN', '以赛亚书', 23, 59, 7, 'その足は悪に走り、咎なき者の血を流すのに速い。その思いは不義の思い。暴行と破滅が彼らの大路にある。'),
('JPN', '以赛亚书', 23, 59, 8, '彼らは平和の道を知らず、その道筋には公正がない。自分の通り道を曲げ、そこを歩む者はだれも平和を知らない。'),
('JPN', '以赛亚书', 23, 59, 9, 'それゆえ、公正は私たちから遠く離れ、義は私たちに届かない。私たちは光を待ち望んでいたが、見よ、闇。輝きを待ち望んでいたが、歩くのは暗闇の中。'),
('JPN', '以赛亚书', 23, 59, 10, '私たちは見えない人のように壁を手さぐりし、目が無いかのように手さぐりする。真昼でも、たそがれ時のようにつまずき、強健な者の中にいる死人のようだ。'),
('JPN', '以赛亚书', 23, 59, 11, '私たちはみな、熊のようにうなり、鳩のようにぶつぶつうめく。公正を待ち望むが、それはなく、救いを待ち望むが、私たちから遠く離れている。'),
('JPN', '以赛亚书', 23, 59, 12, 'それは、私たちの背きが御前で多くなり、私たちの罪が不利な証言をするからだ。まことに、私たちの背きは私たちとともにあり、私たちは自分の咎をよく知っている。'),
('JPN', '以赛亚书', 23, 59, 13, '私たちは主に背き、主を否んで、私たちの神に従うことをやめ、虐げと反逆を語り、心に偽りのことばをはらんで告げる。'),
('JPN', '以赛亚书', 23, 59, 14, 'こうして公正は退けられ、正義は遠く離れて立っている。それは、真理が広場でつまずき、正直さが中に入ることもできないからだ。'),
('JPN', '以赛亚书', 23, 59, 15, 'そこでは真理は失われ、悪から遠ざかっている者も略奪される。主はこれを見て、公正がないことに心を痛められた。'),
('JPN', '以赛亚书', 23, 59, 16, '主は人がいないのを見て、とりなす者がいないことに啞然とされた。それで、ご自分の御腕で救いをもたらし、ご自分の義を支えとされた。'),
('JPN', '以赛亚书', 23, 59, 17, '主は義をよろいのように着て、救いのかぶとを頭にかぶり、復讐の衣を身にまとい、ねたみを外套として身をおおわれた。'),
('JPN', '以赛亚书', 23, 59, 18, '主は彼らの仕打ちに応じて報い、はむかう者に憤り、敵に報復し、島々にも報復をされる。'),
('JPN', '以赛亚书', 23, 59, 19, 'そうして、西の方では主の御名が、日の昇る方では主の栄光が恐れられる。それは、主が激しい流れのように来られ、その中で主の息が吹きまくっているからだ。'),
('JPN', '以赛亚书', 23, 59, 20, '「しかし、シオンには贖い主として来る。ヤコブの中の、背きから立ち返る者のところに。──主のことば。」'),
('JPN', '以赛亚书', 23, 59, 21, '「これは、彼らと結ぶわたしの契約である──主は言われる──。あなたの上にあるわたしの霊、わたしがあなたの口に置いたわたしのことばは、あなたの口からも、あなたの子孫の口からも、子孫の子孫の口からも、今よりとこしえに離れない──主は言われる。」'),
('JPN', '以赛亚书', 23, 60, 1, '「起きよ。輝け。まことに、あなたの光が来る。主の栄光があなたの上に輝く。'),
('JPN', '以赛亚书', 23, 60, 2, '見よ、闇が地をおおっている。暗黒が諸国の民を。しかし、あなたの上には主が輝き、主の栄光があなたの上に現れる。'),
('JPN', '以赛亚书', 23, 60, 3, '国々はあなたの光のうちを歩み、王たちはあなたの輝きに照らされて歩む。'),
('JPN', '以赛亚书', 23, 60, 4, '目を上げて、あたりを見渡せ。彼らはみな集まって、あなたのもとに来る。あなたの息子たちは遠くから来る。娘たちは脇に抱かれながら。'),
('JPN', '以赛亚书', 23, 60, 5, 'そのとき、あなたはこれを見て晴れやかになり、心は震えて、喜ぶ。それは、海の富があなたのところに移され、国々の財宝もあなたのもとに来るからだ。'),
('JPN', '以赛亚书', 23, 60, 6, 'らくだの大群が、ミディアンとエファの若いらくだが、あなたのところをおおい尽くす。これらシェバから来るものはみな、金と乳香を携えて、主の誉れを宣べ伝える。'),
('JPN', '以赛亚书', 23, 60, 7, 'ケダルの羊もみな、あなたのもとに集まり、ネバヨテの雄羊は、あなたに仕える。これは受け入れられ、わたしの祭壇に献げられる。わたしは、わたしの輝かしい家をさらに輝かす。'),
('JPN', '以赛亚书', 23, 60, 8, '雨雲のように飛ぶ者、鳩のように巣に帰る者はだれか。'),
('JPN', '以赛亚书', 23, 60, 9, 'まことに、島々はわたしを待ち望み、タルシシュの船は真っ先に、あなたの子らを遠くから運んで来る。彼らの銀と金とともに。それは、あなたの神、主の名のため、イスラエルの聖なる者のためであり、主があなたを輝かせたからである。'),
('JPN', '以赛亚书', 23, 60, 10, '異国の民もあなたの城壁を築き直し、その王たちもあなたに仕える。わたしは激しく怒って、あなたを打ったが、恵みをもって、あなたをあわれむからだ。'),
('JPN', '以赛亚书', 23, 60, 11, 'あなたの門はいつも開かれ、昼も夜も閉じられない。国々の財宝があなたのところに運ばれ、その王たちが導かれて来るためである。'),
('JPN', '以赛亚书', 23, 60, 12, 'あなたに仕えない国民や王国は滅び、これらの国々は荒れ果てる。'),
('JPN', '以赛亚书', 23, 60, 13, 'レバノンの栄光は、もみの木、すずかけ、檜も、ともに、あなたのもとに来て、わたしの聖所を輝かせる。わたしは、自分の足台を栄光あるものとする。'),
('JPN', '以赛亚书', 23, 60, 14, 'あなたを苦しめた者たちの子らは、身をかがめてあなたのところに来る。あなたを侮った者どもはみな、あなたの足もとにひれ伏して、あなたを『主の都、イスラエルの聖なる方のシオン』と呼ぶ。'),
('JPN', '以赛亚书', 23, 60, 15, 'あなたは捨てられ、憎まれて、通り過ぎる人もなかったが、わたしはあなたを永遠の誇り、代々の喜びに変える。'),
('JPN', '以赛亚书', 23, 60, 16, 'あなたは国々の乳を吸い、王たちの乳房を吸う。あなたは、わたしが主、あなたを救う者、あなたを贖う者、ヤコブの力強き者であることを知る。'),
('JPN', '以赛亚书', 23, 60, 17, 'わたしは青銅の代わりに金を運び入れ、鉄の代わりに銀、木の代わりに青銅、石の代わりに鉄を運び入れ、平和をあなたの管理者とし、正義をあなたの監督者とする。'),
('JPN', '以赛亚书', 23, 60, 18, 'あなたの国には暴虐はもう聞かれず、あなたの領土には暴行と破滅は聞かれない。あなたは、あなたの城壁を救いと呼び、あなたの門を賛美と呼ぶ。'),
('JPN', '以赛亚书', 23, 60, 19, '太陽はもはや、あなたの昼の光とはならず、月の明かりもあなたを照らさない。主があなたの永遠の光となり、あなたの神があなたの輝きとなる。'),
('JPN', '以赛亚书', 23, 60, 20, 'あなたの太陽はもう沈むことがなく、あなたの月は陰ることがない。主があなたの永遠の光となり、あなたの嘆き悲しむ日が終わるからである。'),
('JPN', '以赛亚书', 23, 60, 21, 'あなたの民はみな正しい者となり、永遠にその地を所有する。彼らは栄光を現す、わたしが植えた枝。わたしの手で造ったもの。'),
('JPN', '以赛亚书', 23, 60, 22, '最も小さい者も軍団となり、最も弱い者も強国となる。わたしは主。時が来れば、速やかにそれをする。」'),
('JPN', '以赛亚书', 23, 61, 1, '神である主の霊がわたしの上にある。貧しい人に良い知らせを伝えるため、心の傷ついた者を癒やすため、主はわたしに油を注ぎ、わたしを遣わされた。捕らわれ人には解放を、囚人には釈放を告げ、'),
('JPN', '以赛亚书', 23, 61, 2, '主の恵みの年、われらの神の復讐の日を告げ、すべての嘆き悲しむ者を慰めるために。'),
('JPN', '以赛亚书', 23, 61, 3, 'シオンの嘆き悲しむ者たちに、灰の代わりに頭の飾りを、嘆きの代わりに喜びの油を、憂いの心の代わりに賛美の外套を着けさせるために。彼らは、義の樫の木、栄光を現す、主の植木と呼ばれる。'),
('JPN', '以赛亚书', 23, 61, 4, '彼らは昔の廃墟を建て直し、かつての荒れ跡を復興し、廃墟の町々、代々の荒れ跡を一新する。'),
('JPN', '以赛亚书', 23, 61, 5, '他国の人は立って、あなたがたの羊の群れを飼い、異国の民があなたがたの農夫となり、ぶどう作りとなる。'),
('JPN', '以赛亚书', 23, 61, 6, 'しかし、あなたがたは主の祭司と呼ばれ、われわれの神に仕える者と言われる。あなたがたは国々の財宝を味わい、彼らの富を誇る。'),
('JPN', '以赛亚书', 23, 61, 7, 'あなたがたは恥に代えて、二倍のものを受け、人々は侮辱に代えて、その分け前に喜び歌う。それゆえ、人々は自分の地で二倍のものを所有し、とこしえの喜びが自分のものとなる。'),
('JPN', '以赛亚书', 23, 61, 8, '「まことに、わたしは主、公正を愛し、不法な略奪を憎む。わたしは真実をもって彼らのわざに報い、永遠の契約を彼らと結ぶ。'),
('JPN', '以赛亚书', 23, 61, 9, '彼らの子孫は国々のうちで、末裔は諸国の民のうちで知れ渡る。彼らを見る者はみな、彼らが主に祝福された子孫であることを認める。」'),
('JPN', '以赛亚书', 23, 61, 10, '私は主にあって大いに楽しみ、私のたましいも私の神にあって喜ぶ。主が私に救いの衣を着せ、正義の外套をまとわせ、花婿のように栄冠をかぶらせ、花嫁のように宝玉で飾ってくださるからだ。'),
('JPN', '以赛亚书', 23, 61, 11, '地が芽を出し、園が蒔かれた種を芽生えさせるように、神である主が、正義と賛美をすべての国々の前に芽生えさせるからだ。'),
('JPN', '以赛亚书', 23, 62, 1, 'シオンのために、わたしは黙っていない。エルサレムのために沈黙はしない。その義が明るく光を放ち、その救いが、たいまつのように燃えるまでは。'),
('JPN', '以赛亚书', 23, 62, 2, 'そのとき、国々はあなたの義を、すべての王があなたの栄光を見る。そのとき、あなたは新しい名で呼ばれる。主の御口が名づける名で。'),
('JPN', '以赛亚书', 23, 62, 3, 'あなたは主の手にある輝かしい冠となり、あなたの神の手のひらにある王のかぶり物となる。'),
('JPN', '以赛亚书', 23, 62, 4, 'あなたはもう、「見捨てられた」と言われず、あなたの土地は「荒れ果てている」とは言われない。かえって、あなたは「わたしの喜びは彼女にある」と呼ばれ、あなたの国は「夫のある国」と呼ばれる。それは、主の喜びがあなたにあり、あなたの国が夫を得るからである。'),
('JPN', '以赛亚书', 23, 62, 5, '若い男が若い女の夫となるように、あなたの息子たちはあなたの夫となる。花婿が花嫁を喜ぶように、あなたの神はあなたを喜ぶ。'),
('JPN', '以赛亚书', 23, 62, 6, '「エルサレムよ、わたしはあなたの城壁の上に見張り番を置いた。終日終夜、彼らは、一時も黙っていてはならない。思い起こしていただこうと主に求める者たちよ、休んではならない。'),
('JPN', '以赛亚书', 23, 62, 7, '主を休ませてはならない。主がエルサレムを堅く立て、この地の誉れとするまで。」'),
('JPN', '以赛亚书', 23, 62, 8, '主は右の手と力強い腕によって誓われた。「わたしはあなたの穀物を再び敵に食物として与えはしない。あなたが労して作った新しいぶどう酒を、異国の民が飲むことはない。'),
('JPN', '以赛亚书', 23, 62, 9, '取り入れをした者が、それを食べて主をほめたたえ、ぶどうを取り集めた者が、わたしの聖所の庭でそれを飲む。」'),
('JPN', '以赛亚书', 23, 62, 10, '通れ、通れ、城門を。この民の道を整えよ。盛り上げ、土を盛り上げて、大路を造れ。石を除いて、もろもろの民の上に旗を揚げよ。'),
('JPN', '以赛亚书', 23, 62, 11, '見よ、主は地の果てに聞かせられた。「娘シオンに言え。『見よ、あなたの救いが来る。見よ、その報いは主とともにあり、その報酬は主の前にある』と。」'),
('JPN', '以赛亚书', 23, 62, 12, '彼らは、聖なる民、主に贖われた者と呼ばれ、あなたは、追い求められる者、見捨てられることのない都と呼ばれる。'),
('JPN', '以赛亚书', 23, 63, 1, '「エドムから来るこの方はだれだろう。ボツラから深紅の衣を着て来る方は。その装いには威光があり、大いなる力をもって進んで来る。」「わたしは正義をもって語り、救いをもたらす大いなる者。」'),
('JPN', '以赛亚书', 23, 63, 2, '「なぜ、あなたの装いは赤く、衣はぶどう踏みをする者のようなのですか。」'),
('JPN', '以赛亚书', 23, 63, 3, '「わたしはひとりでぶどう踏みをした。諸国の民のうちで、事をともにする者はだれもいなかった。わたしは怒って彼らを踏み、憤って彼らを踏みにじった。彼らの血の滴りはわたしの衣にはねかかり、わたしの装いをすっかり汚してしまった。'),
('JPN', '以赛亚书', 23, 63, 4, '復讐の日がわたしの心のうちにあり、わたしの贖いの年が来たからだ。'),
('JPN', '以赛亚书', 23, 63, 5, '見回しても、助ける者はだれもなく、支える者がだれもいないことに啞然とした。それで、わたしの腕がわたしの救いとなり、わたしの憤り、それがわたしの支えとなった。'),
('JPN', '以赛亚书', 23, 63, 6, 'わたしは怒って諸国の民を踏みつけ、わたしの憤りをもって彼らを酔わせ、彼らの血の滴りを地に流れさせた。」'),
('JPN', '以赛亚书', 23, 63, 7, '私は主の恵みを語り告げる。主の奇しいみわざの数々を。主が与えてくださったすべてのことを。そのあわれみと豊かな恵みにしたがって与えてくださった、イスラエルの家への豊かな恵みを。'),
('JPN', '以赛亚书', 23, 63, 8, '主は言われた。「まことに、彼らはわたしの民、偽りのない子たちだ」と。こうして主は彼らの救い主になられた。'),
('JPN', '以赛亚书', 23, 63, 9, '彼らが苦しむときには、いつも主も苦しみ、主の臨在の御使いが彼らを救った。その愛とあわれみによって、主は彼らを贖い、昔からずっと彼らを背負い、担ってくださった。'),
('JPN', '以赛亚书', 23, 63, 10, 'しかし彼らは逆らって、主の聖なる御霊を悲しませたので、主は彼らの敵となり、自ら彼らと戦われた。'),
('JPN', '以赛亚书', 23, 63, 11, 'そのとき、主の民はいにしえのモーセの日を思い出した。彼らを、ご自分の群れの牧者たちとともに海から導き上った方は、どこにおられるのか。その中に主の聖なる御霊を置いた方は、どこにおられるのか。'),
('JPN', '以赛亚书', 23, 63, 12, 'その輝かしい御腕をモーセの右に進ませ、彼らの前で水を分けて、永遠の名を成し、'),
('JPN', '以赛亚书', 23, 63, 13, '彼らに深みの底を歩ませた方は、どこにおられるのか。荒野の中を行く馬のように、彼らはつまずくことはなかった。'),
('JPN', '以赛亚书', 23, 63, 14, '谷に下る家畜のように、主の御霊が彼らを憩わせた。このようにして、あなたはご自分の民を導き、ご自分のために輝かしい名を成されました。'),
('JPN', '以赛亚书', 23, 63, 15, 'どうか、天から見下ろし、ご覧ください。あなたの聖なる輝かしい御住まいから。あなたの熱心と力あるわざは、どこにあるのでしょう。私へのたぎる思いとあわれみを、あなたは抑えておられるのですか。'),
('JPN', '以赛亚书', 23, 63, 16, 'まことに、あなたは私たちの父です。たとえ、アブラハムが私たちを知らず、イスラエルが私たちを認めなくても、主よ、あなたは私たちの父です。あなたの御名は、とこしえから「私たちの贖い主」。'),
('JPN', '以赛亚书', 23, 63, 17, '主よ。なぜあなたは私たちをあなたの道から迷い出させ、私たちの心を頑なにして、あなたを恐れなくされるのですか。あなたのしもべたち、あなたのゆずりの地の部族のために、どうかお帰りください。'),
('JPN', '以赛亚书', 23, 63, 18, 'あなたの聖なる民がこの地を所有して間もなく、私たちの敵はあなたの聖所を踏みつけました。'),
('JPN', '以赛亚书', 23, 63, 19, '私たちは、とこしえから、あなたに支配されたこともなく、御名で呼ばれたこともない者のようです。'),
('JPN', '以赛亚书', 23, 64, 1, 'ああ、あなたが天を裂いて降りて来られると、山々はあなたの御前で揺れ動きます。'),
('JPN', '以赛亚书', 23, 64, 2, '火が柴に燃えつき、火が水を沸き立たせるように、あなたの御名はあなたの敵に知られ、国々はあなたの御前で震えます。'),
('JPN', '以赛亚书', 23, 64, 3, '予期しない恐ろしいことをあなたが行われるとき、あなたは降りて来られ、山々はあなたの御前で揺れ動きます。'),
('JPN', '以赛亚书', 23, 64, 4, 'とこしえから聞いたこともなく、耳にしたこともなく、目で見たこともありません。あなた以外の神が自分を待ち望む者のために、このようにするのを。'),
('JPN', '以赛亚书', 23, 64, 5, 'あなたは会ってくださいます。喜び、正義を行う者たちに。彼らは、あなたの道であなたを心に留めます。実にあなたは、激しく怒られました。私たちはその道で久しく罪の中にいたのです。私たちは救われるでしょうか。'),
('JPN', '以赛亚书', 23, 64, 6, '私たちはみな、汚れた者のようになり、その義はみな、不潔な衣のようです。私たちはみな、木の葉のように枯れ、その咎は風のように私たちを吹き上げます。'),
('JPN', '以赛亚书', 23, 64, 7, 'しかし、あなたの御名を呼ぶ者はなく、奮い立って、あなたにすがる者もいません。あなたは私たちから御顔を隠し、私たちの咎によって、私たちを弱められました。'),
('JPN', '以赛亚书', 23, 64, 8, 'しかし、今、主よ、あなたは私たちの父です。私たちは粘土で、あなたは私たちの陶器師です。私たちはみな、あなたの御手のわざです。'),
('JPN', '以赛亚书', 23, 64, 9, '主よ、どうか激しく怒らないでください。いつまでも、咎を覚えていないでください。どうか今、私たちがみな、あなたの民であることに目を留めてください。'),
('JPN', '以赛亚书', 23, 64, 10, 'あなたの聖なる町々は荒野となっています。シオンは荒野となり、エルサレムは荒れ果てています。'),
('JPN', '以赛亚书', 23, 64, 11, '私たちの聖なる美しい宮、私たちの先祖があなたをほめたたえたその場所は火で焼かれ、私たちが宝とした所は、すべて廃墟となりました。'),
('JPN', '以赛亚书', 23, 64, 12, '主よ。それでも、あなたはじっとこらえ、黙っていて、私たちをこんなに苦しめるのですか。'),
('JPN', '以赛亚书', 23, 65, 1, '「わたしを尋ねなかった者たちに、わたしは尋ね求められ、わたしを探さなかった者たちに、わたしは見出された。わたしの名を呼び求めなかった国民に向かって、『わたしはここだ、わたしはここだ』と言った。'),
('JPN', '以赛亚书', 23, 65, 2, 'わたしは終日、頑なな民に手を差し伸べた。自分の考えのまま、良くない道を歩む者たちに。'),
('JPN', '以赛亚书', 23, 65, 3, 'この民はいつもわたしに逆らってわたしの怒りを引き起こす。園の中でいけにえを献げ、れんがの上で犠牲を供え、'),
('JPN', '以赛亚书', 23, 65, 4, '墓地に座り、見張り小屋に宿り、豚の肉を食べ、汚れた肉の汁を器に入れ、'),
('JPN', '以赛亚书', 23, 65, 5, '『そこに立っていよ。私に近寄るな。私はあなたにはあまりにも聖なるものだ』と言う。これらは、わたしの怒りの煙、終日、燃え続ける火である。'),
('JPN', '以赛亚书', 23, 65, 6, '見よ、これはわたしの前に書かれている。わたしは黙っていない。必ず報いる。わたしは彼らの懐に報いる。'),
('JPN', '以赛亚书', 23, 65, 7, 'おまえたちの咎とおまえたちの先祖の咎をともどもに。──主は言われる──彼らは山の上で犠牲を供え、丘の上でわたしをそしった。わたしは、彼らのかつての行いを量って、彼らの懐に報いる。」'),
('JPN', '以赛亚书', 23, 65, 8, '主はこう言われる。「ぶどうの房の中に甘い汁があるのを見れば、『それを損なうな。その中に祝福があるから』と言うように、わたしも、わたしのしもべたちのために、そのすべては滅ぼさない。'),
('JPN', '以赛亚书', 23, 65, 9, 'わたしは、ヤコブから子孫をユダから、わたしの山々を所有する者を生まれさせる。わたしの選んだ者がこれを所有し、わたしのしもべたちがそこに住む。'),
('JPN', '以赛亚书', 23, 65, 10, 'わたしを求めた、わたしの民にとって、シャロンは羊の群れの牧場、アコルの谷は牛の群れの伏すところとなる。'),
('JPN', '以赛亚书', 23, 65, 11, 'しかし、おまえたち、主を捨てる者たちよ、わたしの聖なる山を忘れる者、ガドのために食卓を整える者、メニのために、混ぜ合わせた酒を盛る者たちよ。'),
('JPN', '以赛亚书', 23, 65, 12, 'わたしはおまえたちを剣に渡す。それで、おまえたちはみな、虐殺されて倒れる。わたしが呼んでも答えず、わたしが語りかけても聞かず、わたしの目に悪であることを行い、わたしが喜ばないことを選んだからだ。」'),
('JPN', '以赛亚书', 23, 65, 13, 'それゆえ、神である主はこう言われる。「見よ、わたしのしもべたちは食べる。しかし、おまえたちは飢える。見よ、わたしのしもべたちは飲む。しかし、おまえたちは渇く。見よ、わたしのしもべたちは喜ぶ。しかし、おまえたちは恥を見る。'),
('JPN', '以赛亚书', 23, 65, 14, '見よ、わたしのしもべたちは心の底から喜び歌う。しかし、おまえたちは心の痛みによって叫び、霊に傷を受けて泣き叫ぶ。'),
('JPN', '以赛亚书', 23, 65, 15, 'おまえたちは自分の名を、わたしの選んだ者たちにのろいとして残す。神である主は、おまえたちを殺す。しかし、自分のしもべたちをほかの名で呼ぶ。'),
('JPN', '以赛亚书', 23, 65, 16, 'この地で祝福される者はまことの神によって祝福され、この地で誓う者はまことの神によって誓う。かつての苦難は忘れられ、わたしの目から隠されるからだ。'),
('JPN', '以赛亚书', 23, 65, 17, '見よ、わたしは新しい天と新しい地を創造する。先のことは思い出されず、心に上ることもない。'),
('JPN', '以赛亚书', 23, 65, 18, 'だから、わたしが創造するものを、いついつまでも楽しみ喜べ。見よ。わたしはエルサレムを創造して喜びとし、その民を楽しみとする。'),
('JPN', '以赛亚书', 23, 65, 19, 'わたしはエルサレムを喜び、わたしの民を楽しむ。そこではもう、泣き声も叫び声も聞かれない。'),
('JPN', '以赛亚书', 23, 65, 20, 'そこにはもう、数日しか生きない乳飲み子も、寿命を全うしない老人もいない。百歳で死ぬ者は若かったとされ、百歳にならないで死ぬ者は、のろわれた者とされる。'),
('JPN', '以赛亚书', 23, 65, 21, '彼らは家を建てて住み、ぶどう畑を作って、その実を食べる。'),
('JPN', '以赛亚书', 23, 65, 22, '彼らが建てて他人が住むことはなく、彼らが植えて他人が食べることはない。わたしの民の寿命は、木の寿命に等しく、わたしの選んだ者たちは、自分の手で作った物を存分に用いることができるからだ。'),
('JPN', '以赛亚书', 23, 65, 23, '彼らは無駄に労することもなく、子を産んで、突然その子が死ぬこともない。彼らは主に祝福された者の末裔であり、その子孫たちは彼らとともにいるからだ。'),
('JPN', '以赛亚书', 23, 65, 24, '彼らが呼ばないうちに、わたしは答え、彼らがまだ語っているうちに、わたしは聞く。'),
('JPN', '以赛亚书', 23, 65, 25, '狼と子羊はともに草をはみ、獅子は牛のように藁を食べ、蛇はちりを食べ物とし、わたしの聖なる山のどこにおいても、これらは害を加えず、滅ぼすこともない。──主は言われる。」'),
('JPN', '以赛亚书', 23, 66, 1, '主はこう言われる。「天はわたしの王座、地はわたしの足台。あなたがたがわたしのために建てる家は、いったいどこにあるのか。わたしの安息の場は、いったいどこにあるのか。'),
('JPN', '以赛亚书', 23, 66, 2, 'これらすべては、わたしの手が造った。それで、これらすべては存在するのだ。──主のことば──わたしが目を留める者、それは、貧しい者、霊の砕かれた者、わたしのことばにおののく者だ。'),
('JPN', '以赛亚书', 23, 66, 3, '牛を屠る者が、人を打ち殺す者。羊をいけにえにする者が、犬の首を折る者。穀物のささげ物を献げる者が、豚の血を献げる者。乳香を記念として献げる者が、偶像をたたえる者。実に彼らは自分の道を選び、そのたましいは忌まわしいものを喜ぶ。'),
('JPN', '以赛亚书', 23, 66, 4, 'わたしも彼らを厳しく扱うことを選び、彼らに恐怖をもたらす。それは、わたしが呼んでもだれも答えず、わたしが語りかけても聞かず、わたしの目に悪であることを行い、わたしの喜ばないことを選んだからだ。」'),
('JPN', '以赛亚书', 23, 66, 5, '主のことばにおののく者たちよ、主のことばを聞け。「あなたがたを憎み、わたしの名のゆえにあなたがたを押しのける、あなたがたの同胞は言った。『主に栄光を現させよ。おまえたちの楽しみを見てやろう』と。しかし、彼らは恥を見る。」'),
('JPN', '以赛亚书', 23, 66, 6, '都から騒ぎが、宮から声が聞こえる。敵に報復する主の御声が。'),
('JPN', '以赛亚书', 23, 66, 7, '「彼女は産みの苦しみが来る前に産み、陣痛が来る前に男の子を産み落とす。'),
('JPN', '以赛亚书', 23, 66, 8, 'だれが、このようなことを聞き、だれが、これらのことを見たか。地は一日の苦しみで産み出されるだろうか。国は一瞬にして生まれるだろうか。ところがシオンは、産みの苦しみと同時に子たちを産む。'),
('JPN', '以赛亚书', 23, 66, 9, 'わたしが胎を開きながら、産ませないだろうか。──主は言われる──わたしは産ませる者なのに、胎を閉ざすだろうか。──あなたの神は仰せられる。」'),
('JPN', '以赛亚书', 23, 66, 10, 'エルサレムとともに喜べ。すべて彼女を愛する者よ、彼女とともに楽しめ。すべて彼女のために悲しむ者よ、彼女とともに喜び喜べ。'),
('JPN', '以赛亚书', 23, 66, 11, 'あなたが彼女の慰めの乳房から飲んで満ち足り、その豊かな乳房から吸って喜びを得るために。'),
('JPN', '以赛亚书', 23, 66, 12, '主はこう言われる。「見よ。わたしは川のように繁栄を彼女に与え、あふれる流れのように国々の栄光を与える。あなたがたは乳を飲み、脇に抱かれ、膝の上でかわいがられる。'),
('JPN', '以赛亚书', 23, 66, 13, '母に慰められる者のように、わたしはあなたがたを慰める。エルサレムであなたがたは慰められる。'),
('JPN', '以赛亚书', 23, 66, 14, 'あなたがたがこれを見るとき、その心は喜び、骨は若草のように生き返る。主の手はそのしもべたちに知られる。その憤りは敵たちに。」'),
('JPN', '以赛亚书', 23, 66, 15, '見よ。主は火を伴って進んで来られる。その戦車はつむじ風のよう。主は激しい憤りをもって、怒りを下し、火の炎をもって、叱責を下す。'),
('JPN', '以赛亚书', 23, 66, 16, '実に、主は火をもってさばき、その剣で、すべての肉なる者をさばく。主に刺し殺された者は多い。'),
('JPN', '以赛亚书', 23, 66, 17, '「自分の身を聖別し、身をきよめて園に行き、その中にある一つのものに従って、豚の肉、忌むべき物、ねずみを食らう者たちは、みなともに絶ち滅ぼされる。──主のことば。」'),
('JPN', '以赛亚书', 23, 66, 18, '「わたしは彼らのわざと思いを知っている。わたしはすべての国々と種族を集めに来る。彼らは来て、わたしの栄光を見る。'),
('JPN', '以赛亚书', 23, 66, 19, 'わたしは彼らの中にしるしを置き、彼らのうちの逃れた者たちを諸国に遣わす。すなわち、タルシシュ、プル、弓を引く者ルデ、トバル、ヤワン、そして、わたしのうわさを聞いたことも、わたしの栄光を見たこともない遠い島々に。彼らはわたしの栄光を諸国の民に告げ知らせる。'),
('JPN', '以赛亚书', 23, 66, 20, '彼らはすべての国々から、あなたがたの同胞をみな主への贈り物として、馬、車、輿、らば、らくだに乗せて、わたしの聖なる山エルサレムに連れて来る──主は言われる──。それはちょうど、イスラエルの子らが穀物のささげ物をきよい器に入れて、主の宮に携えて来るのと同じである。'),
('JPN', '以赛亚书', 23, 66, 21, 'わたしは彼らの中からも、ある者を選んで祭司とし、レビ人とする──主は言われる。'),
('JPN', '以赛亚书', 23, 66, 22, 'わたしが造る新しい天と新しい地が、わたしの前にいつまでも続くのと同じように、──主のことば──あなたがたの子孫とあなたがたの名もいつまでも続く。'),
('JPN', '以赛亚书', 23, 66, 23, '新月の祭りごとに、安息日ごとに、すべての肉なる者がわたしの前に来て礼拝する。──主は言われる──'),
('JPN', '以赛亚书', 23, 66, 24, '彼らは出て行って、わたしに背いた者たちの屍を見る。そのうじ虫は死なず、その火も消えず、それはすべての肉なる者の嫌悪の的となる。」'),
('JPN', '耶利米书', 24, 1, 1, 'ベニヤミンの地、アナトテにいた祭司の一人、ヒルキヤの子エレミヤのことば。'),
('JPN', '耶利米书', 24, 1, 2, 'このエレミヤに主のことばがあった。ユダの王、アモンの子ヨシヤの時代、その治世の第十三年のことである。'),
('JPN', '耶利米书', 24, 1, 3, 'それはさらに、ユダの王、ヨシヤの子エホヤキムの時代にもあり、ユダの王、ヨシヤの子ゼデキヤの第十一年の終わりまで、すなわち、その年の第五の月、エルサレムの民の捕囚まで続いた。'),
('JPN', '耶利米书', 24, 1, 4, '次のような主のことばが私にあった。'),
('JPN', '耶利米书', 24, 1, 5, '「わたしは、あなたを胎内に形造る前からあなたを知り、あなたが母の胎を出る前からあなたを聖別し、国々への預言者と定めていた。」'),
('JPN', '耶利米书', 24, 1, 6, '私は言った。「ああ、神、主よ、ご覧ください。私はまだ若くて、どう語ってよいか分かりません。」'),
('JPN', '耶利米书', 24, 1, 7, '主は私に言われた。「まだ若い、と言うな。わたしがあなたを遣わすすべてのところへ行き、わたしがあなたに命じるすべてのことを語れ。'),
('JPN', '耶利米书', 24, 1, 8, '彼らの顔を恐れるな。わたしがあなたとともにいて、あなたを救い出すからだ。──主のことば。」'),
('JPN', '耶利米书', 24, 1, 9, 'そのとき主は御手を伸ばし、私の口に触れられた。主は私に言われた。「見よ、わたしは、わたしのことばをあなたの口に与えた。'),
('JPN', '耶利米书', 24, 1, 10, '見なさい。わたしは今日、あなたを諸国の民と王国の上に任命する。引き抜き、引き倒し、滅ぼし、壊し、建て、また植えるために。」'),
('JPN', '耶利米书', 24, 1, 11, '主のことばが私にあった。「エレミヤ、あなたは何を見ているのか。」私は言った。「アーモンドの枝を見ています。」'),
('JPN', '耶利米书', 24, 1, 12, 'すると主は私に言われた。「あなたの見たとおりだ。わたしは、わたしのことばを実現しようと見張っている。」'),
('JPN', '耶利米书', 24, 1, 13, '再び主のことばが私にあった。「あなたは何を見ているのか。」私は言った。「煮え立った釜を見ています。それは北からこちらに傾いています。」'),
('JPN', '耶利米书', 24, 1, 14, 'すると主は私に言われた。「わざわいが北から、この地の全住民の上に降りかかる。'),
('JPN', '耶利米书', 24, 1, 15, '今わたしは、北のすべての王国の民に呼びかけている。──主のことば──彼らはやって来て、エルサレムの門の入り口で、周囲のすべての城壁とユダのすべての町に向かいそれぞれ王座を設ける。'),
('JPN', '耶利米书', 24, 1, 16, 'わたしは、この地の全住民の悪に対してことごとくさばきを下す。彼らがわたしを捨てて、ほかの神々に犠牲を供え、自分の手で造った物を拝んだからだ。'),
('JPN', '耶利米书', 24, 1, 17, 'さあ、あなたは腰に帯を締めて立ち上がり、わたしがあなたに命じるすべてのことを語れ。彼らの顔におびえるな。さもないと、わたしがあなたを彼らの顔の前でおびえさせる。'),
('JPN', '耶利米书', 24, 1, 18, '見よ。わたしは今日、あなたを全地に対して、ユダの王たち、首長たち、祭司たち、民衆に対して要塞の町、鉄の柱、青銅の城壁とする。'),
('JPN', '耶利米书', 24, 1, 19, '彼らはあなたと戦っても、あなたに勝てない。わたしがあなたとともにいて、──主のことば──あなたを救い出すからだ。」'),
('JPN', '耶利米书', 24, 2, 1, '次のような主のことばが私にあった。'),
('JPN', '耶利米书', 24, 2, 2, '「さあ、行ってエルサレムの人々に宣言せよ。『主はこう言われる。わたしは、あなたの若いころの真実の愛、婚約時代の愛、種も蒔かれていなかった地、荒野でのわたしへの従順を覚えている。'),
('JPN', '耶利米书', 24, 2, 3, 'イスラエルは主の聖なるもの、その収穫の初穂であった。これを食らう者はだれでも罰を受け、わざわいを被った。──主のことば──'),
('JPN', '耶利米书', 24, 2, 4, 'ヤコブの家よ、イスラエルの家の全部族よ、主のことばを聞け。'),
('JPN', '耶利米书', 24, 2, 5, '主はこう言われる。あなたがたの先祖は、わたしにどんな不正を見つけたというのか。わたしから遠く離れ、空しいものに従って行き、空しいものになってしまうとは。'),
('JPN', '耶利米书', 24, 2, 6, '彼らはこう尋ねることさえしなかった。「主はどこにおられるのか。われわれをエジプトの地から上らせた方、われわれに、あの荒野、穴だらけの荒れた地を、乾いた、死の陰の地、人も通らず、だれも住まない地を行かせた方は。」'),
('JPN', '耶利米书', 24, 2, 7, 'わたしはあなたがたを、実り豊かな地に伴い、その良い実を食べさせた。ところが、あなたがたは入って来て、わたしの地を汚し、わたしのゆずりの地を忌み嫌うべきものにした。'),
('JPN', '耶利米书', 24, 2, 8, '祭司たちは、「主はどこにおられるのか」と言うことがなく、律法を扱う者たちも、わたしを知らず、牧者たちもわたしに背き、預言者たちはバアルによって預言し、役立たずのものに従って行った。'),
('JPN', '耶利米书', 24, 2, 9, 'それゆえ、わたしはなお、あなたがたと争う。──主のことば──また、あなたがたの子孫と争う。'),
('JPN', '耶利米书', 24, 2, 10, 'キティムの島々に渡って、よく見よ。ケダルに人を遣わして見極めよ。このようなことがあったかどうか、確かめよ。'),
('JPN', '耶利米书', 24, 2, 11, 'かつて、自分の神々を、神々でないものと取り替えた国民があっただろうか。ところが、わたしの民は自分たちの栄光を役に立たないものと取り替えた。'),
('JPN', '耶利米书', 24, 2, 12, '天よ、このことに呆れ果てよ。おぞ気立て。涸れ果てよ。──主のことば──'),
('JPN', '耶利米书', 24, 2, 13, 'わたしの民は二つの悪を行った。いのちの水の泉であるわたしを捨て、多くの水溜めを自分たちのために掘ったのだ。水を溜めることのできない、壊れた水溜めを。'),
('JPN', '耶利米书', 24, 2, 14, 'イスラエルは奴隷なのか。それとも家に生まれたしもべなのか。なぜ、獲物にされたのか。'),
('JPN', '耶利米书', 24, 2, 15, '若獅子は彼に向かって吼えたけり、うなり声をあげて、その地を荒れ果てさせる。その町々は焼かれて、住む者がいなくなる。'),
('JPN', '耶利米书', 24, 2, 16, 'メンフィスとタフパンヘスの子らも、あなたの頭の頂を剃り上げる。'),
('JPN', '耶利米书', 24, 2, 17, 'あなたの神、主があなたに道を進ませたとき、あなたが主を捨てたために、このことがあなたに起こったのではないか。'),
('JPN', '耶利米书', 24, 2, 18, '今、ナイル川の水を飲みにエジプトへの道に向かうとは、いったいどうしたことか。大河の水を飲みにアッシリアへの道に向かうとは、いったいどうしたことか。'),
('JPN', '耶利米书', 24, 2, 19, 'あなたの悪があなたを懲らしめ、あなたの背信があなたを責める。だから、知り、見極めよ。あなたがあなたの神、主を捨てて、わたしを恐れないのは、いかに悪く苦いことかを。──万軍の神、主のことば。'),
('JPN', '耶利米书', 24, 2, 20, '実に、遠い昔にあなたは自分のくびきを砕き、自分のかせを打ち砕いて、「私は仕えない」と言った。まさしく、あなたはすべての高い丘の上や、青々と茂るあらゆる木の下で、寝そべって淫行を行っている。'),
('JPN', '耶利米书', 24, 2, 21, 'わたしは、あなたをみな、純種の良いぶどうとして植えたのに、どうしてあなたは、わたしにとって、質の悪い雑種のぶどうに変わってしまったのか。'),
('JPN', '耶利米书', 24, 2, 22, 'たとえ、あなたが重曹で身を洗い、たくさんの灰汁を使っても、あなたの咎は、わたしの前に汚れたままだ。──神である主のことば──'),
('JPN', '耶利米书', 24, 2, 23, 'どうしてあなたは、「私は汚れていない。バアルの神々に従わなかった」と言えるのか。谷の中でのあなたの行いを省み、自分が何をしたかを知れ。あなたは、あちらこちら道を走り回るすばやい雌のらくだ。'),
('JPN', '耶利米书', 24, 2, 24, 'また、欲情に息あえぐ荒野に慣れた野ろばだ。さかりのとき、だれがこれを制し得るだろう。これを探す者は苦労しない。発情の月に見つけることができる。'),
('JPN', '耶利米书', 24, 2, 25, '裸足にならないように、喉が渇かないようにせよ。しかし、あなたは言う。「あきらめられません。他国の男たちが好きなので、私は彼らについて行きます」と。'),
('JPN', '耶利米书', 24, 2, 26, '盗人が、見つかったときに恥を見るように、イスラエルの家も恥を見る。彼らの王たち、首長たち、祭司たち、預言者たちも。'),
('JPN', '耶利米书', 24, 2, 27, '彼らは木に向かって「あなたは私の父」、石に向かって「あなたは私を生んだ」と言っている。実に、彼らはわたしに背を向け、顔を向けない。それなのに、わざわいのときには「立って、私たちを救ってください」と言う。'),
('JPN', '耶利米书', 24, 2, 28, 'では、あなたが造った神々はどこにいるのか。あなたのわざわいのときには彼らが立って救えばよい。ユダよ、あなたの神々はあなたの町の数ほどもいるではないか。'),
('JPN', '耶利米书', 24, 2, 29, 'なぜ、あなたがたはわたしと争うのか。あなたがたはみな、わたしに背いてきた。──主のことば──'),
('JPN', '耶利米书', 24, 2, 30, 'わたしはあなたがたの子らを打ったが、無駄だった。彼らはその懲らしめを受け入れなかった。あなたがたの剣は、食い滅ぼす獅子のように、あなたがたの預言者たちを食い尽くした。'),
('JPN', '耶利米书', 24, 2, 31, 'あなたがた、この時代の人々よ。主のことばに心せよ。わたしはイスラエルにとって荒野であったのか。あるいは暗黒の地であったのか。なぜわたしの民は、「私たちは、さまよい歩きます。もうあなたのところには行きません」と言うのか。'),
('JPN', '耶利米书', 24, 2, 32, 'おとめが自分の飾り物を、花嫁が自分の飾り帯を忘れるだろうか。しかし、わたしの民はわたしを忘れた。その日数は数えきれない。'),
('JPN', '耶利米书', 24, 2, 33, 'あなたが愛を求める方法は、なんと巧みなことか。そのようにして、あなたは悪い女にさえ、巧みに自分の方法を教えたのだ。'),
('JPN', '耶利米书', 24, 2, 34, 'あなたの裾に見つかるのは、咎なき貧しい人たちの、いのちの血。彼らが押し入るのを、あなたが見たわけでもないのに。しかも、これらすべてのことにもかかわらず、'),
('JPN', '耶利米书', 24, 2, 35, 'あなたは言う。「私は潔白だ。確かに、御怒りは私から去った」と。あなたが「私は罪を犯してはいない」と言うので、今、わたしはあなたをさばく。'),
('JPN', '耶利米书', 24, 2, 36, 'あなたはなんと簡単に自分の道を変えることか。アッシリアによって恥を見たのと同様に、あなたはエジプトによっても恥を見る。'),
('JPN', '耶利米书', 24, 2, 37, 'そこからも、あなたは両手を頭に置いて出て来るだろう。主が、あなたの拠り頼むものを退けられるので、あなたが彼らによって栄えることは決してない。'),
('JPN', '耶利米书', 24, 3, 1, 'もし、人が自分の妻を去らせ、彼女が彼のもとを去って、ほかの男のものになったら、この人は再び先の妻のもとに戻れるだろうか。そのような地は大いに汚れていないだろうか。あなたは、多くの愛人と淫行を行って、しかも、わたしのところに帰るというのか。──主のことば──'),
('JPN', '耶利米书', 24, 3, 2, '目を上げて裸の丘を見よ。あなたが共寝しなかったところがどこにあるか。荒野のアラビア人がするように、あなたは道端で相手を待って座り込み、淫行と悪行によって、この地を汚した。'),
('JPN', '耶利米书', 24, 3, 3, 'それで大雨はとどめられ、後の雨はなかった。それでも、あなたは遊女の額をして、恥じることを拒んでいる。'),
('JPN', '耶利米书', 24, 3, 4, '今でもあなたは、わたしにこう呼びかけているではないか。「父よ、あなたは私の若いころの恋人です。'),
('JPN', '耶利米书', 24, 3, 5, 'いつまでも恨みを抱かれるのですか。永久に持ち続けるのですか」と。なんと、あなたはこう言っていながら、あらん限りの悪を行っている。』」'),
('JPN', '耶利米书', 24, 3, 6, 'ヨシヤ王の時代に、主は私に言われた。「あなたは、背信の女イスラエルが行ったことを見たか。彼女はあらゆる高い山の上、青々と茂るあらゆる木の下に行き、そこで淫行を行った。'),
('JPN', '耶利米书', 24, 3, 7, 'わたしは思った。彼女がこれらすべてを行った後で、わたしに帰って来るだろうと。しかし、帰っては来なかった。そして裏切る女、妹のユダもこれを見た。'),
('JPN', '耶利米书', 24, 3, 8, '背信の女イスラエルが姦通をしたので、わたしは離縁状を渡して追い出した。しかし、裏切る女、妹のユダが恐れもせず、自分も行って淫行を行ったのをわたしは見た。'),
('JPN', '耶利米书', 24, 3, 9, '彼女は、自分の淫行を軽く見て、地を汚し、石や木と姦通した。'),
('JPN', '耶利米书', 24, 3, 10, 'このようなことをしながら、裏切る女、妹のユダは、心のすべてをもってわたしに立ち返らず、ただ偽ってそうしただけだった──主のことば。」'),
('JPN', '耶利米书', 24, 3, 11, '主は私に言われた。「背信の女イスラエルは、裏切る女ユダよりも正しかった。'),
('JPN', '耶利米书', 24, 3, 12, '行って、次のことばを北の方に叫べ。『背信の女イスラエルよ、帰れ。──主のことば──わたしはあなたがたに顔を伏せはしない。わたしは恵み深いから。──主のことば──わたしは、いつまでも恨みはしない。'),
('JPN', '耶利米书', 24, 3, 13, 'ただ、あなたはあなたの咎を認めよ。あなたはあなたの神、主に背いて、青々と茂るあらゆる木の下で、他国の男と勝手なまねをし、わたしの声に聞き従わなかった。──主のことば。'),
('JPN', '耶利米书', 24, 3, 14, '背信の子らよ、立ち返れ──主のことば──。わたしが、あなたがたの夫であるからだ。わたしはあなたがたを、町から一人、氏族から二人選び取り、シオンに連れて来る。'),
('JPN', '耶利米书', 24, 3, 15, 'また、あなたがたに、わたしの心にかなう牧者たちを与える。彼らは知識と判断力をもってあなたがたを育てるだろう。'),
('JPN', '耶利米书', 24, 3, 16, 'あなたがたが地に増えて多くの子を生むとき、その日には──主のことば──人々はもう、主の契約の箱について語ることもなく、それが心に上ることもない。彼らがそれを思い出すことも、調べることもなく、それが再び作られることもない。'),
('JPN', '耶利米书', 24, 3, 17, 'そのとき、エルサレムは主の御座と呼ばれ、万国の民はこの御座、主の名のあるエルサレムに集められ、彼らは二度と頑なな悪い心のままに歩むことはない。'),
('JPN', '耶利米书', 24, 3, 18, 'その日、ユダの家はイスラエルの家に加わり、彼らはともどもに、北の国から、わたしが彼らの先祖に受け継がせた地に帰って来る。'),
('JPN', '耶利米书', 24, 3, 19, 'わたしは思っていた。どのようにして、あなたを息子たちの中に入れ、あなたに慕わしい地を与えようかと。国々のうちで最も麗しいゆずりの地を。また、あなたがわたしを父と呼び、わたしに従って、もう離れないと思っていた。'),
('JPN', '耶利米书', 24, 3, 20, 'ところが、なんと、妻が夫を裏切るように、あなたがたはわたしを裏切った。イスラエルの家よ──主のことば──。'),
('JPN', '耶利米书', 24, 3, 21, '一つの声が裸の丘の上で聞こえる。イスラエルの子らの哀願の泣き声だ。彼らが自分たちの道を曲げ、自分たちの神、主を忘れたからだ。'),
('JPN', '耶利米书', 24, 3, 22, '背信の子らよ、立ち返れ。わたしがあなたがたの背信を癒やそう。』」「今、私たちはあなたのもとに参ります。あなたこそ、私たちの神、主だからです。'),
('JPN', '耶利米书', 24, 3, 23, 'まことに、もろもろの丘も、山の騒ぎも、偽りでした。確かに、私たちの神、主にイスラエルの救いがあります。'),
('JPN', '耶利米书', 24, 3, 24, 'しかし、私たちが若いころから、恥ずべきものが、私たちの先祖の労苦の実、彼らの羊の群れ、牛の群れ、息子、娘たちを食い尽くしてきました。'),
('JPN', '耶利米书', 24, 3, 25, '私たちは恥の中に伏し、恥辱が私たちの覆いとなっています。私たちの神、主に対し、私たちも先祖も、若いころから今日まで罪の中にいて、私たちの神、主の御声に聞き従わなかったからです。」'),
('JPN', '耶利米书', 24, 4, 1, '「イスラエルよ、もし帰るのなら、──主のことば──わたしのもとに帰れ。もし、あなたが忌まわしいものをわたしの前から取り除き、迷い出ないなら、'),
('JPN', '耶利米书', 24, 4, 2, 'また、あなたが真実と公正と義によって『主は生きておられる』と誓うなら、国々は主によって互いに祝福し合い、互いに主を誇りとする。」'),
('JPN', '耶利米书', 24, 4, 3, 'まことに、主はユダの人とエルサレムに、こう言われる。「耕地を開拓せよ。茨の中に種を蒔くな。'),
('JPN', '耶利米书', 24, 4, 4, 'ユダの人とエルサレムの住民よ。主のために割礼を受け、心の包皮を取り除け。そうでないと、あなたがたの悪い行いのゆえに、わたしの憤りが火のように出て燃え上がり、消す者もいないだろう。」'),
('JPN', '耶利米书', 24, 4, 5, '「ユダに告げ、エルサレムに聞かせて言え。国中に角笛を吹け。大声で叫べ。『集まれ。城壁のある町に逃れよう』と。'),
('JPN', '耶利米书', 24, 4, 6, 'シオンに向けて旗を掲げよ。自分の身を守れ。立ち止まるな。わたしが北からわざわいを、大いなる破滅をもたらすからだ。'),
('JPN', '耶利米书', 24, 4, 7, '獅子はその茂みから立ち上がり、国々を滅ぼす者はその国から出て来る。あなたの地を荒れ果てさせるために。あなたの町々は滅び、住む者はいなくなる。」'),
('JPN', '耶利米书', 24, 4, 8, 'このことのために、粗布をまとって悲しみ嘆け。主の燃える怒りが、私たちから去らないからだ。'),
('JPN', '耶利米书', 24, 4, 9, '「その日には──主のことば──王の心や、高官たちの心は萎え、祭司は啞然とし、預言者はたじろぐ。」'),
('JPN', '耶利米书', 24, 4, 10, '私は言った。「ああ、神、主よ。まことに、あなたはこの民とエルサレムを完全に欺かれました。『あなたがたには平和が来る』と言われたのに、剣が私たちの喉に触れています。」'),
('JPN', '耶利米书', 24, 4, 11, 'そのとき、この民とエルサレムに告げられる。「荒野にある裸の丘から、熱風は、娘であるわたしの民の方に吹く。ふるい分けるためでも、より分けるためでもない。'),
('JPN', '耶利米书', 24, 4, 12, 'それよりも、もっと激しい風が、わたしのために吹いて来る。今や、わたしが彼らにさばきを下す。」'),
('JPN', '耶利米书', 24, 4, 13, '見よ、それは雲のように上って来る。その戦車はつむじ風のよう。その馬は鷲よりも速い。ああ、私たちは荒らされる。'),
('JPN', '耶利米书', 24, 4, 14, '「エルサレムよ。救われるために、悪から心を洗いきよめよ。いつまで、自分のうちによこしまな思いを宿らせているのか。'),
('JPN', '耶利米书', 24, 4, 15, 'ああ、ダンから告げる声がある。エフライムの山からわざわいを告げ知らせている。'),
('JPN', '耶利米书', 24, 4, 16, '国々に語り告げよ。さあ、エルサレムに告げ知らせよ。包囲する者たちが遠くの地から来て、ユダの町々に対して、ときの声をあげる。'),
('JPN', '耶利米书', 24, 4, 17, '彼らは畑の番人のように、ユダを取り囲む。それは、ユダがわたしに逆らったからだ。──主のことば──'),
('JPN', '耶利米书', 24, 4, 18, 'あなたの生き方と、あなたの行いが、あなたの身にこれを招いたのだ。これはあなたへのわざわいで、なんと苦いことか。もう、あなたの心臓にまで達している。」'),
('JPN', '耶利米书', 24, 4, 19, '私のはらわた、私のはらわたよ、私は悶える。私の心臓の壁よ、私の心は高鳴り、私は黙っていられない。私のたましいが、角笛の音と戦いの雄叫びを聞いたからだ。'),
('JPN', '耶利米书', 24, 4, 20, '破滅に次ぐ破滅が知らされる。まことに、地のすべてが荒らされる。突然、私の天幕が、一瞬のうちに私の幕屋が荒らされる。'),
('JPN', '耶利米书', 24, 4, 21, 'いつまで私は旗を見て、角笛の音を聞かなければならないのか。'),
('JPN', '耶利米书', 24, 4, 22, '「実に、わたしの民は鈍く、わたしを知らない。愚かな子らで悟ることがない。悪事を働くことには賢く、善を行うことを知らない。」'),
('JPN', '耶利米书', 24, 4, 23, '私が地を見ると、見よ、茫漠として何もなく、天を見ると、その光はなかった。'),
('JPN', '耶利米书', 24, 4, 24, '私が山々を見ると、見よ、それは揺れ動き、すべての丘は震えていた。'),
('JPN', '耶利米书', 24, 4, 25, '私が見ると、見よ、人の姿はなく、空の鳥もみな飛び去っていた。'),
('JPN', '耶利米书', 24, 4, 26, '私が見ると、見よ、豊かな地は荒野となり、町々は主の前で、その燃える怒りによって打ち壊されていた。'),
('JPN', '耶利米书', 24, 4, 27, 'まことに、主はこう言われる。「全地は荒れ果てる。ただし、わたしは滅ぼし尽くしはしない。'),
('JPN', '耶利米书', 24, 4, 28, 'このため地は喪に服し、上の天は暗くなる。わたしが語り、企てたからだ。わたしは悔いず、やめることもしない。」'),
('JPN', '耶利米书', 24, 4, 29, '騎兵と射手の雄叫びに、町中の人は逃げ去り、草むらに入り、岩によじ登った。すべての町が捨てられ、そこに住む人はいない。'),
('JPN', '耶利米书', 24, 4, 30, '踏みにじられた女よ、あなたはいったい何をしているのか。緋の衣をまとい、金の飾りで身を飾りたて、目を塗って大きく見せたりして。美しく見せても無駄だ。恋人たちはあなたを嫌い、あなたのいのちを取ろうとしている。'),
('JPN', '耶利米书', 24, 4, 31, 'まことに、私は、産みの苦しみにある女のような声、初子を産む女のようなうめき、娘シオンの声を聞いた。彼女はあえぎ、手を伸ばして言う。「ああ、私は殺す者たちの前で疲れ果てた。」'),
('JPN', '耶利米书', 24, 5, 1, '「エルサレムの通りを行き巡り、さあ、見て知るがよい。その広場を探し回って、もしも、だれか公正を行う、真実を求める者を見つけたなら、わたしはエルサレムを赦そう。'),
('JPN', '耶利米书', 24, 5, 2, '彼らが、主は生きておられる、と言うからこそ、彼らの誓いは偽りなのだ。」'),
('JPN', '耶利米书', 24, 5, 3, '「主よ、あなたの目は真実に届かないのでしょうか。あなたが彼らを打たれたのに、彼らは痛みもしませんでした。絶ち滅ぼそうとされたのに、彼らは懲らしめを受けることを拒みました。彼らは顔を岩よりも硬くして、立ち返ることを拒みました。」'),
('JPN', '耶利米书', 24, 5, 4, '私は思った。「彼らは、卑しい者たちにすぎない。しかも愚かだ。主の道も、自分の神のさばきも知らない。'),
('JPN', '耶利米书', 24, 5, 5, 'だから、身分の高い者たちのところへ行って、その人たちと語ろう。彼らなら、主の道も、自分の神のさばきも知っているから」と。ところが彼らもみな、くびきを砕き、かせを断ち切っていた。'),
('JPN', '耶利米书', 24, 5, 6, 'そのため、森の獅子が彼らを殺し、荒れた地の狼が彼らを荒らす。豹が彼らの町々をうかがい、町から出る者をみなかみ裂く。彼らは背くことが多く、その背信がすさまじいからだ。'),
('JPN', '耶利米书', 24, 5, 7, '「これでは、どうして、あなたを赦すことができるだろうか。あなたの子らはわたしを捨て、神でないものによって誓っていた。わたしが彼らを満ち足らせると、彼らは姦通し、遊女の家で身を傷つけた。'),
('JPN', '耶利米书', 24, 5, 8, '彼らは、肥え太ってさかりのついた馬のように、それぞれ隣の妻を慕っていななく。'),
('JPN', '耶利米书', 24, 5, 9, 'これらについて、わたしが罰しないだろうか。──主のことば──このような国に、わたしが復讐しないだろうか。'),
('JPN', '耶利米书', 24, 5, 10, 'ぶどう畑の石垣に上り、それをつぶせ。ただ、根絶やしにしてはならない。そのつるを除け。それらは主のものではないからだ。'),
('JPN', '耶利米书', 24, 5, 11, '実に、イスラエルの家とユダの家は、ことごとくわたしを裏切った。──主のことば──'),
('JPN', '耶利米书', 24, 5, 12, '彼らは主を否定してこう言った。『主は何もしない。わざわいは私たちを襲わない。剣も飢饉も、私たちは見ない』と。'),
('JPN', '耶利米书', 24, 5, 13, '預言者たちは風になり、彼らのうちにみことばはない。彼らはそのようにされればよい。」'),
('JPN', '耶利米书', 24, 5, 14, 'それゆえ、万軍の神、主はこう言われる。「あなたがたがこのようなことを言ったので、見よ、わたしはあなたの口にあるわたしのことばを火とする。この民は薪となり、火は彼らを焼き尽くす。'),
('JPN', '耶利米书', 24, 5, 15, 'イスラエルの家よ。見よ。わたしはあなたがたを攻めるために、遠くの地から一つの国を来させる。──主のことば──それは古くからある国、昔からある国、その言語をあなたは知らず、何を話しているのか聞き取れない国。'),
('JPN', '耶利米书', 24, 5, 16, 'その矢筒は開いた墓のよう。彼らはみな勇士たち。'),
('JPN', '耶利米书', 24, 5, 17, '彼らは、あなたの収穫とパンを食らい、あなたの息子と娘を食らい、羊の群れと牛の群れを食らい、ぶどうといちじくを食らい、あなたが拠り頼む城壁のある町々を剣で打ち破る。'),
('JPN', '耶利米书', 24, 5, 18, 'しかし、その日にも──主のことば──わたしはあなたがたを滅ぼし尽くすことはない。'),
('JPN', '耶利米书', 24, 5, 19, '『われわれの神、主は、何の報いとして、これらすべてのことを私たちにしたのか』と尋ねられたら、あなたは彼らにこう言え。『あなたがたが、わたしを捨て、自分の地で異国の神々に仕えたように、あなたがたは自分の地ではない地で、他国の人に仕えるようになる。』'),
('JPN', '耶利米书', 24, 5, 20, 'ヤコブの家にこれを告げ、ユダに言い聞かせよ。'),
('JPN', '耶利米书', 24, 5, 21, 'さあ、これを聞け。愚かで思慮のない民よ。彼らは目があっても見ることがなく、耳があっても聞くことがない。'),
('JPN', '耶利米书', 24, 5, 22, 'あなたがたは、わたしを恐れないのか。──主のことば──わたしの前で震えないのか。わたしは砂浜を海の境とした。それは永遠の境界で、越えることはできない。波が逆巻いても勝てず、鳴りとどろいても越えられない。'),
('JPN', '耶利米书', 24, 5, 23, 'しかしこの民には、強情で逆らう心があった。それで彼らは離れて行った。'),
('JPN', '耶利米书', 24, 5, 24, '彼らは心の中でさえこう言わなかった。『さあ、私たちの神、主を恐れよう。主は大雨を、初めの雨と後の雨を、時にかなって与え、刈り入れのために定められた数週を守ってくださる』と。'),
('JPN', '耶利米书', 24, 5, 25, 'あなたがたの咎がこれを追いやり、あなたがたの罪がこの良いものを拒んだのだ。'),
('JPN', '耶利米书', 24, 5, 26, 'それは、わが民のうちに悪しき者たちがいるからだ。彼らは野鳥を捕る者のように待ち伏せし、罠を仕掛けて人々を捕らえる。'),
('JPN', '耶利米书', 24, 5, 27, '鳥でいっぱいの鳥かごのように、彼らの家は欺きで満ちている。だから、彼らは大いなる者となり、富む者となる。'),
('JPN', '耶利米书', 24, 5, 28, '彼らは肥えてつややかになり、悪事において限りがない。孤児のために正しいさばきをして幸いを見させることをせず、貧しい人々の権利を擁護しない。'),
('JPN', '耶利米书', 24, 5, 29, 'これらに対して、わたしが罰しないだろうか。──主のことば──このような国に、わたしが復讐しないだろうか。'),
('JPN', '耶利米书', 24, 5, 30, '荒廃とおぞましいことが、この地に起こっている。'),
('JPN', '耶利米书', 24, 5, 31, '預言者は偽りの預言をし、祭司は自分勝手に治め、わたしの民はそれを愛している。結局、あなたがたはどうするつもりなのか。」'),
('JPN', '耶利米书', 24, 6, 1, 'ベニヤミンの子らよ、エルサレムの中から逃れ出よ。テコアで角笛を吹き、ベテ・ハ・ケレムでのろしを上げよ。わざわいが北から見下ろしているからだ。大いなる破壊が。'),
('JPN', '耶利米书', 24, 6, 2, '娘シオンよ、おまえは麗しい牧場にたとえられるではないか。'),
('JPN', '耶利米书', 24, 6, 3, 'そこに羊飼いたちは自分の群れを連れて行き、その周りに天幕を張り、群れの羊は、それぞれ自分の草を食べる。'),
('JPN', '耶利米书', 24, 6, 4, '「シオンに向かって聖戦を布告せよ。立て。われわれは真昼に上ろう。」「ああ、残念だ。日が傾いた。夕日の影が伸びてきた。」'),
('JPN', '耶利米书', 24, 6, 5, '「立て。われわれは夜の間に上って、その宮殿を滅ぼそう。」'),
('JPN', '耶利米书', 24, 6, 6, 'まことに、万軍の主はこう言われる。「木を切って、エルサレムに向かって塁を築け。これは罰せられる都。その中には虐げだけがある。'),
('JPN', '耶利米书', 24, 6, 7, '井戸が水を湧き出させるように、エルサレムは自分の悪を湧き出させた。暴虐と暴行がその中に聞こえる。病と打ち傷がいつもわたしの前にある。'),
('JPN', '耶利米书', 24, 6, 8, 'エルサレムよ、懲らしめを受けよ。そうでないと、わたしの心はおまえから離れ、おまえを、人も住まない荒れ果てた地とする。」'),
('JPN', '耶利米书', 24, 6, 9, '万軍の主はこう言われる。「ぶどうの残りを摘むように、イスラエルの残りの者をすっかり摘み取れ。ぶどうを収穫する者のように、あなたの手をもう一度、その枝に伸ばせ。」'),
('JPN', '耶利米书', 24, 6, 10, '私はだれに語りかけ、だれを諭して聞かせようか。見よ。彼らの耳は閉じたままで、聞くこともできない。見よ。主のことばは彼らにとって、そしりの的となっている。彼らはそれを喜ばない。'),
('JPN', '耶利米书', 24, 6, 11, '主の憤りで私は満たされ、これを収めておくのに耐えられない。「それを、道端にいる幼子の上にも、若い男がたむろする上にも、注ぎ出せ。夫はその妻とともに、年寄りも齢の満ちた者も、ともに捕らえられる。'),
('JPN', '耶利米书', 24, 6, 12, '彼らの家は、畑や妻もろとも、他人の手に渡る。わたしがこの地の住民に手を伸ばすからだ。──主のことば──'),
('JPN', '耶利米书', 24, 6, 13, 'なぜなら、身分の低い者から高い者まで、みな利得を貪り、預言者から祭司に至るまで、みな偽りを行っているからだ。'),
('JPN', '耶利米书', 24, 6, 14, '彼らはわたしの民の傷をいいかげんに癒やし、平安がないのに、『平安だ、平安だ』と言っている。'),
('JPN', '耶利米书', 24, 6, 15, '彼らは忌み嫌うべきことをして、恥を見たか。全く恥じもせず、辱めが何であるかも知らない。だから彼らは、倒れる者の中に倒れ、自分の刑罰の時に、よろめき倒れる。──主は言われる。」'),
('JPN', '耶利米书', 24, 6, 16, '主はこう言われる。「道の分かれ目に立って見渡せ。いにしえからの通り道、幸いの道はどれであるかを尋ね、それに歩んで、たましいに安らぎを見出せ。彼らは『私たちは歩まない』と言った。'),
('JPN', '耶利米书', 24, 6, 17, 'わたしは、あなたがたの上に見張りを立て、『角笛の音に注意せよ』と命じたのに、彼らは『注意しない』と言った。'),
('JPN', '耶利米书', 24, 6, 18, 'それゆえ、諸国の民よ、聞け。会衆よ、知れ。彼らに何が起こるかを。'),
('JPN', '耶利米书', 24, 6, 19, 'この国よ、聞け。見よ、わたしはこの民にわざわいをもたらす。これは彼らの企みの実。彼らがわたしのことばに注意を払わず、わたしの律法を退けたからだ。'),
('JPN', '耶利米书', 24, 6, 20, 'いったい何のために、シェバから乳香が、また、遠い国から香りの良い菖蒲がわたしのところに来るのか。あなたがたの全焼のささげ物は受け入れられず、あなたがたのいけにえはわたしには心地よくない。」'),
('JPN', '耶利米书', 24, 6, 21, 'それゆえ、主はこう言われる。「見よ、わたしはこの民につまずきを与える。父も子も、ともにこれにつまずき、隣人も友人も滅びる。」'),
('JPN', '耶利米书', 24, 6, 22, '主はこう言われる。「見よ、一つの民が北の地から来る。大きな国が地の果てから奮い立つ。'),
('JPN', '耶利米书', 24, 6, 23, '彼らは弓と投げ槍を固く握り、残忍で、あわれみがない。その声は海のようにとどろく。娘シオンよ。彼らは馬にまたがり、あなたに向かい、一団となって陣を敷いている。」'),
('JPN', '耶利米书', 24, 6, 24, '私たちは、そのうわさを聞いて気力を失い、苦しみが私たちをとらえた。産婦のような激痛が。'),
('JPN', '耶利米书', 24, 6, 25, '畑に出るな。道を歩くな。敵の剣がそこにあり、恐怖が取り囲んでいるからだ。'),
('JPN', '耶利米书', 24, 6, 26, '娘である私の民よ。粗布を身にまとい、灰の中を転げ回れ。ひとり子を失ったように喪に服し、苦しみ嘆け。荒らす者が突然、私たちに襲いかかるからだ。'),
('JPN', '耶利米书', 24, 6, 27, '「わたしはあなたを、わたしの民の中で、試す者とし、城壁のある町とした。彼らの行いを知り、これを試せ。」'),
('JPN', '耶利米书', 24, 6, 28, '彼らはみな、頑なな反逆者、中傷して歩き回る者。青銅や鉄。彼らはみな、堕落した者たちだ。'),
('JPN', '耶利米书', 24, 6, 29, '吹子で激しく吹いて、鉛を火で溶かす。鉛は溶けた。溶けたが、無駄だった。悪いものは除かれなかった。'),
('JPN', '耶利米书', 24, 6, 30, '彼らは捨てられた銀と呼ばれる。主が彼らを捨てられたのだ。'),
('JPN', '耶利米书', 24, 7, 1, '主からエレミヤにあったことばは、次のとおりである。'),
('JPN', '耶利米书', 24, 7, 2, '「主の宮の門に立ち、そこでこのことばを叫べ。『主を礼拝するために、これらの門に入るすべてのユダの人々よ、主のことばを聞け。'),
('JPN', '耶利米书', 24, 7, 3, 'イスラエルの神、万軍の主はこう言われる。あなたがたの生き方と行いを改めよ。そうすれば、わたしはあなたがたをこの場所に住まわせる。'),
('JPN', '耶利米书', 24, 7, 4, 'あなたがたは、「これは主の宮、主の宮、主の宮だ」という偽りのことばに信頼してはならない。'),
('JPN', '耶利米书', 24, 7, 5, 'もし、本当に、あなたがたが生き方と行いを改め、あなたがたの間で公正を行い、'),
('JPN', '耶利米书', 24, 7, 6, '寄留者、孤児、やもめを虐げず、咎なき者の血をこの場所で流さず、ほかの神々に従って自分の身にわざわいを招くようなことをしなければ、'),
('JPN', '耶利米书', 24, 7, 7, 'わたしはこの場所、わたしがあなたがたの先祖に与えたこの地に、とこしえからとこしえまで、あなたがたを住まわせる。'),
('JPN', '耶利米书', 24, 7, 8, '見よ、あなたがたは、役に立たない偽りのことばを頼りにしている。'),
('JPN', '耶利米书', 24, 7, 9, 'あなたがたは盗み、人を殺し、姦淫し、偽って誓い、バアルに犠牲を供え、あなたがたの知らなかったほかの神々に従っている。'),
('JPN', '耶利米书', 24, 7, 10, 'そして、わたしの名がつけられているこの宮の、わたしの前にやって来て立ち、「私たちは救われている」と言うが、それは、これらすべての忌み嫌うべきことをするためか。'),
('JPN', '耶利米书', 24, 7, 11, 'わたしの名がつけられているこの家は、あなたがたの目に強盗の巣と見えたのか。見よ、このわたしもそう見ていた──主のことば──。'),
('JPN', '耶利米书', 24, 7, 12, 'だが、シロにあったわたしの住まい、先にわたしの名を住まわせた場所へ行って、わたしの民イスラエルの悪のゆえに、そこでわたしがしたことを見てみよ。'),
('JPN', '耶利米书', 24, 7, 13, '今、あなたがたは、これらのことをみな行い──主のことば──わたしがあなたがたに、絶えずしきりに語りかけたのに、あなたがたは聞こうともせず、わたしが呼んだのに、答えもしなかったので、'),
('JPN', '耶利米书', 24, 7, 14, 'わたしの名がつけられているこの家、あなたがたが頼みとするこの家、また、わたしが、あなたがたと、あなたがたの先祖に与えたこの場所に対して、わたしはシロにしたのと同様のことを行う。'),
('JPN', '耶利米书', 24, 7, 15, 'わたしは、かつて、あなたがたのすべての兄弟、エフライムのすべての子孫を追い払ったように、あなたがたをわたしの前から追い払う。』'),
('JPN', '耶利米书', 24, 7, 16, 'あなたは、この民のために祈ってはならない。彼らのために叫んだり、祈りをささげたりしてはならない。わたしにとりなしをしてはならない。わたしはあなたの願いを聞かないからだ。'),
('JPN', '耶利米书', 24, 7, 17, '彼らがユダの町々や、エルサレムの通りで何をしているのか、あなたは見ていないのか。'),
('JPN', '耶利米书', 24, 7, 18, '子どもたちは薪を集め、父たちは火をたき、女たちは麦粉をこねて『天の女王』のための供えのパン菓子を作り、また、ほかの神々に注ぎのぶどう酒を注いで、わたしの怒りを引き起こそうとしている。'),
('JPN', '耶利米书', 24, 7, 19, 'わたしの怒りを彼らが引き起こしているというのか──主のことば──。むしろ、自分たちを怒らせ、自分たちの恥をさらすことになっているのではないか。」'),
('JPN', '耶利米书', 24, 7, 20, 'それゆえ、神である主はこう言われる。「見よ。わたしの怒りと憤りは、この場所に、人と家畜、畑の木と地の産物に注がれ、それは燃えて、消えることがない。」'),
('JPN', '耶利米书', 24, 7, 21, 'イスラエルの神、万軍の主はこう言われる。「あなたがたの全焼のささげ物を、いけにえに加え、その肉を食べよ。'),
('JPN', '耶利米书', 24, 7, 22, 'わたしは、あなたがたの先祖をエジプトの地から導き出したとき、彼らに全焼のささげ物や、いけにえについては何も語らず、命じもしなかった。'),
('JPN', '耶利米书', 24, 7, 23, 'ただ、次のことを彼らに命じて言った。『わたしの声に聞き従え。そうすれば、わたしはあなたがたの神となり、あなたがたはわたしの民となる。あなたがたが幸せになるために、わたしが命じるすべての道に歩め。』'),
('JPN', '耶利米书', 24, 7, 24, 'しかし、彼らは聞かず、耳を傾けず、頑なで悪い心のはかりごとによって歩み、前進どころか後退した。'),
('JPN', '耶利米书', 24, 7, 25, 'あなたがたの先祖がエジプトの地を出た日から今日まで、わたしはあなたがたに、わたしのしもべであるすべての預言者たちを早くからたびたび遣わしたが、'),
('JPN', '耶利米书', 24, 7, 26, '彼らはわたしに聞かず、耳を傾けもせず、うなじを固くする者となり、先祖たちよりも悪くなった。'),
('JPN', '耶利米书', 24, 7, 27, 'あなたが彼らにこれらのことをすべて語っても、彼らはあなたに聞かず、彼らを呼んでも、彼らはあなたに答えない。'),
('JPN', '耶利米书', 24, 7, 28, 'そこであなたは彼らに言え。この民は、自分の神、主の声を聞かず、懲らしめを受け入れなかった民だ。真実は消え失せ、彼らの口から断たれた。'),
('JPN', '耶利米书', 24, 7, 29, '『あなたの長い髪を切り捨て、裸の丘の上で哀歌を歌え。主が、御怒りを引き起こした世代を退け、捨てられたからだ。』'),
('JPN', '耶利米书', 24, 7, 30, 'それは、ユダの子らが、わたしの目に悪であることを行ったからだ──主のことば──。彼らは、わたしの名がつけられているこの宮に忌まわしいものを置いて、これを汚した。'),
('JPN', '耶利米书', 24, 7, 31, 'また自分の息子、娘を火で焼くために、ベン・ヒノムの谷にあるトフェトに高き所を築いたが、これは、わたしが命じたこともなく、思いつきもしなかったことだ。'),
('JPN', '耶利米书', 24, 7, 32, 'それゆえ、見よ、その時代が来る──主のことば──。そのとき、もはやそこは、トフェトとかベン・ヒノムの谷と呼ばれない。ただ虐殺の谷と呼ばれる。人々はトフェトに、隙間がないほどに葬る。'),
('JPN', '耶利米书', 24, 7, 33, 'この民の屍は、空の鳥や地の獣の餌食となるが、これを追い払う者もいない。'),
('JPN', '耶利米书', 24, 7, 34, 'わたしは、ユダの町々とエルサレムの通りから、楽しみの声と喜びの声、花婿の声と花嫁の声を絶えさせる。この地が廃墟となるからである。」'),
('JPN', '耶利米书', 24, 8, 1, '「そのとき──主のことば──人々は、ユダの王たちの骨、首長たちの骨、祭司たちの骨、預言者たちの骨、エルサレムの住民の骨を、墓から取り出し、'),
('JPN', '耶利米书', 24, 8, 2, 'それらを、彼らが愛し、仕え、従い、伺いを立て、拝んだ日や月や天の万象の前にさらす。それらは集められることなく、葬られることもなく、地の面の肥やしとなる。'),
('JPN', '耶利米书', 24, 8, 3, 'また、この悪しき一族の中から残された残りの者はみな、わたしが追いやったすべての場所で、いのちよりも死を選ぶようになる──万軍の主のことば。'),
('JPN', '耶利米书', 24, 8, 4, 'あなたは、彼らに言え。『主はこう言われる。人は倒れたら、起き上がるものではないか。離れたら、帰って来るものではないか。'),
('JPN', '耶利米书', 24, 8, 5, 'なぜ、この民エルサレムは、背信者となり、いつまでも背信を続けているのか。彼らは偽りを握りしめ、帰って来ることを拒む。'),
('JPN', '耶利米书', 24, 8, 6, 'わたしは気をつけて聞いたが、彼らは正しくないことを語り、「私は何ということをしたのか」と言って自分の悪を悔いる者は、一人もいない。彼らはみな、戦いに突き進む馬のように、自分の走路に走り去る。'),
('JPN', '耶利米书', 24, 8, 7, '空のこうのとりも、自分の季節を知っている。山鳩も燕も鶴も、自分の帰る時を守る。しかし、わが民は主の定めを知らない。'),
('JPN', '耶利米书', 24, 8, 8, 'どうして、あなたがたは、「私たちは知恵ある者、私たちには主の律法がある」と言えるのか。だが、見よ、書記たちの偽りの筆が、それを偽りにしてしまった。'),
('JPN', '耶利米书', 24, 8, 9, '知恵ある者たちは恥を見、うろたえて、捕らえられる。見よ。主のことばを退けたからには、彼らに何の知恵があろうか。'),
('JPN', '耶利米书', 24, 8, 10, 'それゆえ、わたしは彼らの妻を他人に、彼らの畑を侵略者に与える。なぜなら、身分の低い者から高い者まで、みな利得を貪り、預言者から祭司に至るまで、みな偽りを行っているからだ。'),
('JPN', '耶利米书', 24, 8, 11, '彼らは、わたしの民の傷を簡単に手当てし、平安がないのに、「平安だ、平安だ」と言っている。'),
('JPN', '耶利米书', 24, 8, 12, '彼らは忌み嫌うべきことをして、恥を見たか。全く恥じもせず、辱めが何であるかも知らない。だから彼らは、倒れる者の中に倒れ、自分の刑罰の時に、よろめき倒れる。──主は言われる。'),
('JPN', '耶利米书', 24, 8, 13, 'わたしは彼らを刈り入れたい。──主のことば──しかし、ぶどうの木には、ぶどうがなく、いちじくの木には、いちじくがなく、葉はしおれている。わたしはそれらをそのままにしておく。』」'),
('JPN', '耶利米书', 24, 8, 14, '「何のために私たちは座っているのか。集まって、城壁のある町々に行き、そこで滅んでしまおう。私たちの神、主が、私たちを滅びに定め、主が私たちに毒の水を飲ませられる。私たちが主に罪を犯したからだ。'),
('JPN', '耶利米书', 24, 8, 15, '平安を待ち望んでも、幸いはなく、癒やしの時を待ち望んでも、見よ、恐怖しかない。」'),
('JPN', '耶利米书', 24, 8, 16, '「ダンから馬の鼻息が聞こえる。その荒馬のいななきの声に、全地は震える。彼らは来て、地と、それに満ちているものを、町とその住民を食らう。'),
('JPN', '耶利米书', 24, 8, 17, '見よ。わたしがまじないの効かないコブラや、まむしをあなたがたの中に送り、あなたがたをかませるからだ。──主のことば。」'),
('JPN', '耶利米书', 24, 8, 18, '私の悲しみは癒やされず、私の心は弱り果てている。'),
('JPN', '耶利米书', 24, 8, 19, '見よ。遠い地から娘である私の民の叫び声がする。「主はシオンにおられないのか。シオンの王は、そこにおられないのか。」「なぜ、彼らは自分たちが刻んだ像、異国の空しいものによって、わたしの怒りを引き起こしたのか。」'),
('JPN', '耶利米书', 24, 8, 20, '「刈り入れ時は過ぎ、夏も終わった。しかし、私たちは救われない。」'),
('JPN', '耶利米书', 24, 8, 21, '娘である私の民の傷のために、私は傷ついた。うなだれる中、恐怖が私をとらえる。'),
('JPN', '耶利米书', 24, 8, 22, '乳香はギルアデにないのか。医者はそこにいないのか。なぜ、娘である私の民の傷は癒えなかったのか。'),
('JPN', '耶利米书', 24, 9, 1, 'ああ、私の頭が水であり、私の目が涙の泉であったなら、娘である私の民の殺された者たちのために昼も夜も、泣こうものを。'),
('JPN', '耶利米书', 24, 9, 2, 'ああ、私が荒野に旅人の宿を持っていたなら、私の民を置いて、彼らから離れることができようものを。彼らはみな姦通する者、裏切り者の集まりなのだ。'),
('JPN', '耶利米书', 24, 9, 3, '「彼らは弓を張り、舌をつがえて偽りを放つ。地にはびこるが、それは真実のゆえではない。悪から悪へ彼らは進み、わたしを知らないからだ。──主のことば──'),
('JPN', '耶利米书', 24, 9, 4, 'それぞれ互いに友を警戒せよ。どの兄弟も信用してはならない。どの兄弟も人を出し抜き、どの友も中傷して歩き回るからだ。'),
('JPN', '耶利米书', 24, 9, 5, '彼らはそれぞれ、互いに友をだまして、真実を語らない。偽りを語ることを自分の舌に教え、疲れきるまで悪事を働く。'),
('JPN', '耶利米书', 24, 9, 6, 'あなたは欺きのただ中に住み、欺きの中でわたしを知ることを拒む。──主のことば。」'),
('JPN', '耶利米书', 24, 9, 7, 'それゆえ、万軍の主はこう言われる。「見よ、わたしは彼らを精錬して試す。いったい、娘であるわたしの民に対してほかに何ができるだろうか。'),
('JPN', '耶利米书', 24, 9, 8, '彼らの舌はとがった矢。人を欺くことを言う。口先では友に向かって平和を語るが、心の中では待ち伏せを企む。'),
('JPN', '耶利米书', 24, 9, 9, 'これらについて、わたしが彼らを罰しないだろうか。──主のことば──このような国に、わたしが復讐しないだろうか。」'),
('JPN', '耶利米书', 24, 9, 10, '私は山々のために泣き声をあげて嘆き、荒野の牧場のために哀歌を歌う。そこは、焼き払われて通る人もなく、群れの声も聞こえず、空の鳥から家畜まで、みな逃げ去っているからだ。'),
('JPN', '耶利米书', 24, 9, 11, '「わたしはエルサレムを石ころの山とし、ジャッカルの住みかとする。ユダの町々を荒れ果てた地とし、住む者のいない所とする。」'),
('JPN', '耶利米书', 24, 9, 12, '知恵があって、これを悟ることのできる者はだれか。主の御口が自分に語られたことを告げ知らせることのできる者はだれか。何のために、この国は滅びたのか。荒野のように滅ぼされ、通る人もいないのか。'),
('JPN', '耶利米书', 24, 9, 13, '主は言われる。「それは、彼らが、わたしが彼らの前に与えたわたしの律法を捨て、わたしの声に聞き従わず、律法に歩まず、'),
('JPN', '耶利米书', 24, 9, 14, '彼らの頑なな心のままに歩み、先祖たちが彼らに教えたバアルの神々に従って歩んだからだ。」'),
('JPN', '耶利米书', 24, 9, 15, 'それゆえ、イスラエルの神、万軍の主はこう言われる。「見よ。わたしはこの民に苦よもぎを食べさせ、毒の水を飲ませる。'),
('JPN', '耶利米书', 24, 9, 16, '彼らも先祖も知らなかった国々に彼らを散らし、剣を彼らのうしろに送り、ついに彼らを絶ち滅ぼす。」'),
('JPN', '耶利米书', 24, 9, 17, '万軍の主はこう言われる。「よく考えて、泣き女を呼んで来させよ。人を遣わして、巧みな女を来させよ。」'),
('JPN', '耶利米书', 24, 9, 18, '彼女たちを急がせて、私たちのために嘆きの声をあげさせよ。私たちの目から涙を流れさせ、私たちのまぶたに水をあふれさせよ。'),
('JPN', '耶利米书', 24, 9, 19, 'シオンから嘆きの声が聞こえるからだ。ああ、私たちは踏みにじられ、ひどく恥を見た。私たちが地を見捨て、自分たちの住まいが投げ捨てられたからだ。'),
('JPN', '耶利米书', 24, 9, 20, '女たちよ、主のことばを聞け。あなたがたの耳に、主の言われることばを受けとめさせよ。あなたがたの娘に嘆きの歌を、隣の女に哀歌を教えよ。'),
('JPN', '耶利米书', 24, 9, 21, '死が、私たちの窓によじ登り、私たちの高殿に入り、道端で幼子を、広場で若い男を絶ち滅ぼすからだ。'),
('JPN', '耶利米书', 24, 9, 22, '「語れ。主のことばはこうだ。『人間の死体は、畑の肥やしのように、刈り入れ人のうしろの、集める者もない束のように落ちる。'),
('JPN', '耶利米书', 24, 9, 23, '──主はこう言われる──知恵ある者は自分の知恵を誇るな。力ある者は自分の力を誇るな。富ある者は自分の富を誇るな。'),
('JPN', '耶利米书', 24, 9, 24, '誇る者は、ただ、これを誇れ。悟りを得て、わたしを知っていることを。わたしは主であり、地に恵みと公正と正義を行う者であるからだ。まことに、わたしはこれらのことを喜ぶ。──主のことば。』」'),
('JPN', '耶利米书', 24, 9, 25, '「見よ、その時代が来る──主のことば──。そのとき、わたしはすべて包皮に割礼を受けている者を罰する。'),
('JPN', '耶利米书', 24, 9, 26, 'エジプト、ユダ、エドム、アンモンの子ら、モアブ、および荒野の住人で、もみ上げを刈り上げているすべての者を罰する。すべての国々は無割礼で、イスラエルの全家も心に割礼を受けていないからだ。」'),
('JPN', '耶利米书', 24, 10, 1, 'イスラエルの家よ、主があなたがたに語られたことばを聞け。'),
('JPN', '耶利米书', 24, 10, 2, '「主はこう言われる。諸国の道を見習うな。天のしるしにうろたえるな。諸国がそれらにうろたえても。'),
('JPN', '耶利米书', 24, 10, 3, '国々の民の慣わしは空しいからだ。それは、林から切り出された木、木工が、なたで作った物にすぎない。'),
('JPN', '耶利米书', 24, 10, 4, 'それは銀と金で飾られ、釘や槌で、ぐらつかないよう打ち付けられる。'),
('JPN', '耶利米书', 24, 10, 5, 'それは、きゅうり畑のかかしのようで、ものも言えず、歩けないので、運んでやらなければならない。そんなものを恐れるな。害になることも益になることもしないからだ。」'),
('JPN', '耶利米书', 24, 10, 6, '主よ、あなたに並ぶものはありません。あなたは大いなる方。あなたの御名は、力ある大いなるものです。'),
('JPN', '耶利米书', 24, 10, 7, '国々の王である方、あなたを恐れない者がいるでしょうか。そのことは、あなたにとっては当然のことです。まことに、国々のすべての知恵ある者の中にも、そのすべての王国の中にも、あなたに並ぶものはありません。'),
('JPN', '耶利米书', 24, 10, 8, '彼らはみな間抜けであり、愚かなことをする。空しい神々の訓戒──それは木にすぎない。'),
('JPN', '耶利米书', 24, 10, 9, '銀箔はタルシシュから、金はウファズから運ばれる。これは木工と金細工人の手のわざ。これらの衣は青色と紫色、すべて名匠の作。'),
('JPN', '耶利米书', 24, 10, 10, 'しかし、主はまことの神、生ける神、とこしえの王。その御怒りに地は震え、その憤りに国々は耐えられない。'),
('JPN', '耶利米书', 24, 10, 11, '「あなたがたは、彼らにこう言え。『天と地を造らなかった神々は、地からも、この天の下からも滅びる』と。」'),
('JPN', '耶利米书', 24, 10, 12, '主は、御力をもって地を造り、知恵をもって世界を堅く据え、英知をもって天を張られた。'),
('JPN', '耶利米书', 24, 10, 13, '主の御声に、天では水のざわめきが起こる。主は地の果てから雲を上らせ、雨のために稲妻を造り、ご自分の倉から風を出される。'),
('JPN', '耶利米书', 24, 10, 14, 'すべての人間は愚かで無知だ。すべての金細工人は、偶像のために恥を見る。その鋳た像は偽りで、その中には息がない。'),
('JPN', '耶利米书', 24, 10, 15, 'それは空しいもの、物笑いの種だ。刑罰の時に、それらは滅びる。'),
('JPN', '耶利米书', 24, 10, 16, 'ヤコブの受ける分はこのようなものではない。主は万物を造る方。イスラエルは主のゆずりの民。その御名は万軍の主である。'),
('JPN', '耶利米书', 24, 10, 17, '包囲されている女よ、あなたの荷物を地から取り集めよ。'),
('JPN', '耶利米书', 24, 10, 18, 'まことに主はこう言われる。「見よ。わたしはこの国の住民を今度こそ放り出して苦しめる。彼らが思い知るためだ。」'),
('JPN', '耶利米书', 24, 10, 19, 'ああ、私は悲しい。この傷のために。この打ち傷は癒やしがたい。しかし、私は言った。「まことに、これこそ私が負わなければならない病だ。」'),
('JPN', '耶利米书', 24, 10, 20, '私の天幕は荒らされ、そのすべての綱は断たれ、私の子らも私から去って、もういない。もう私の天幕を張る者はなく、その幕を広げる者もいない。'),
('JPN', '耶利米书', 24, 10, 21, '牧者たちは愚かで、主を求めなかった。それゆえ、彼らは栄えず、彼らが飼うものはみな散らされる。'),
('JPN', '耶利米书', 24, 10, 22, '声がする。見よ、一つの知らせが届いた。大いなるざわめきが北の地から来る。ユダの町々を荒れ果てた地とし、ジャッカルの住みかとするために。'),
('JPN', '耶利米书', 24, 10, 23, '主よ、私は知っています。人間の道はその人によるのではなく、歩むことも、その歩みを確かにすることも、人によるのではないことを。'),
('JPN', '耶利米书', 24, 10, 24, '主よ、私を懲らしめてください。御怒りによらないで、ただ、公正をもって。そうでなければ、私は無に帰してしまいます。'),
('JPN', '耶利米书', 24, 10, 25, 'あなたを知らない国々の上に、あなたの御名を呼ばない諸氏族の上に、あなたの憤りを注いでください。彼らはヤコブを食らい、これを食らって滅ぼし、その牧場を荒らしたからです。'),
('JPN', '耶利米书', 24, 11, 1, '主からエレミヤにあったことばは、次のとおりである。'),
('JPN', '耶利米书', 24, 11, 2, '「この契約のことばを聞け。これをユダの人とエルサレムの住民に語れ。'),
('JPN', '耶利米书', 24, 11, 3, '『イスラエルの神、主はこう言われる。この契約のことばを聞かない者は、のろわれる。'),
('JPN', '耶利米书', 24, 11, 4, 'これは、わたしがあなたがたの先祖をエジプトの地、鉄の炉から導き出したとき、「わたしの声に聞き従い、すべてわたしがあなたがたに命じるように、それを行え。そうすれば、あなたがたはわたしの民となり、わたしはあなたがたの神となる」と言って、彼らに命じたものだ。'),
('JPN', '耶利米书', 24, 11, 5, 'それは、わたしがあなたがたの父祖たちに対して、乳と蜜の流れる地を与えると誓ったことを、今日のとおり成就するためであった。』」私は答えた。「アーメン。主よ。」'),
('JPN', '耶利米书', 24, 11, 6, 'すると、主は私に言われた。「これらのことばのすべてを、ユダの町々と、エルサレムの通りで叫べ。『この契約のことばを聞いて、これを行え。'),
('JPN', '耶利米书', 24, 11, 7, 'わたしは、あなたがたの先祖をエジプトの地から導き出したとき、厳しく彼らを戒め、また今日まで、「わたしの声を聞け」と言って、しばしば戒めてきた。'),
('JPN', '耶利米书', 24, 11, 8, 'しかし彼らは聞かず、耳を傾けず、それぞれ頑なで悪い心のままに歩んだ。そのため、わたしはこの契約のことばをことごとく彼らの上に臨ませた。わたしが行うように命じたのに、彼らが行わなかったからである。』」'),
('JPN', '耶利米书', 24, 11, 9, '主は私に言われた。「ユダの人、エルサレムの住民の間に、謀反がある。'),
('JPN', '耶利米书', 24, 11, 10, '彼らはわたしのことばを聞くことを拒んだ自分たちのかつての先祖の咎に戻り、彼ら自身もほかの神々に従って、これに仕えた。イスラエルの家とユダの家は、わたしが彼らの父祖たちと結んだわたしの契約を破った。'),
('JPN', '耶利米书', 24, 11, 11, 'それゆえ──主はこう言われる──見よ、わたしは彼らにわざわいを下す。彼らはそれから逃れることができない。彼らがわたしに叫んでも、わたしは聞かない。'),
('JPN', '耶利米书', 24, 11, 12, 'ユダの町々とエルサレムの住民は、自分たちが犠牲を供えている神々のもとに行って叫ぶだろうが、これらは、彼らのわざわいの時に、決して彼らを救わない。'),
('JPN', '耶利米书', 24, 11, 13, '『まことに、ユダよ、あなたの神々は、あなたの町の数ほどもある。あなたがたは、恥ずべきもののための祭壇、バアルのために犠牲を供える祭壇を、エルサレムの通りの数ほども設けた。』'),
('JPN', '耶利米书', 24, 11, 14, 'あなたは、この民のために祈ってはならない。彼らのために叫んだり、祈りをささげたりしてはならない。彼らがわざわいにあって、わたしを呼び求めても、わたしは聞かないからだ。'),
('JPN', '耶利米书', 24, 11, 15, '『わたしの愛する者は、わたしの家で何をしているのか。いろいろと何を企んでいるのか。聖なるいけにえの肉が、わざわいをあなたから過ぎ去らせるのか。そのときには喜び躍るがよい。'),
('JPN', '耶利米书', 24, 11, 16, '主はかつてあなたの名を、「実りの良い、緑のオリーブの木」と呼ばれた。だが、大きな騒ぎの声が起こると、主がこれに火をつけ、その枝は台無しになる。'),
('JPN', '耶利米书', 24, 11, 17, 'あなたを植えた万軍の主が、あなたにわざわいを告げる。イスラエルの家とユダの家が悪を行い、バアルに犠牲を供え、わたしの怒りを引き起こしたからである。』」'),
('JPN', '耶利米书', 24, 11, 18, '「主が私に知らせてくださったので、私はそれを知りました。それからあなたは、彼らのわざを私に見せてくださいました。'),
('JPN', '耶利米书', 24, 11, 19, '私は、屠り場に引かれて行く、おとなしい子羊のようでした。彼らが私に敵対して計略をめぐらしていたことを、私は知りませんでした。『木を実とともに滅ぼそう。彼を生ける者の地から断って、その名が二度と思い出されないようにしよう』と。'),
('JPN', '耶利米书', 24, 11, 20, 'しかし、正しいさばきをし、心とその奥にあるものを試す万軍の主よ。あなたが彼らに復讐するのを私は見るでしょう。私があなたに、私の訴えを打ち明けたからです。」'),
('JPN', '耶利米书', 24, 11, 21, 'それゆえ、主はアナトテの人々について、こう言われる。「彼らはあなたのいのちを狙い、『主の名によって預言するな。われわれの手にかかって、あなたが死なないように』と言っている。'),
('JPN', '耶利米书', 24, 11, 22, 'それゆえ──万軍の主はこう言われる──見よ、わたしは彼らを罰する。若い男は剣で死に、彼らの息子、娘は飢えで死に、'),
('JPN', '耶利米书', 24, 11, 23, '彼らには残る者がいなくなる。わたしがアナトテの人々にわざわいを下し、刑罰の年をもたらすからだ。」'),
('JPN', '耶利米书', 24, 12, 1, '「主よ。私があなたと論じても、あなたのほうが正しいのです。それでも、私はさばきについてあなたにお聞きしたいのです。なぜ、悪者の道が栄え、裏切りを働く者がみな安らかなのですか。'),
('JPN', '耶利米书', 24, 12, 2, 'あなたが彼らを植え、彼らは根を張り、伸びて実を結びました。あなたは、彼らの口には近いのですが、彼らの心の奥からは遠く離れておられます。'),
('JPN', '耶利米书', 24, 12, 3, '主よ。あなたは私を知り、私を見て、あなたに対する私の心を試されます。どうか彼らを、屠られる羊のように引きずり出し、殺戮の日のために取り分けてください。'),
('JPN', '耶利米书', 24, 12, 4, 'いつまで、この地は喪に服し、すべての畑の青草は枯れているのでしょうか。そこに住む者たちの悪のために、家畜も鳥も取り去られています。人々は『神はわれわれの最期を見ない』と言っています。」'),
('JPN', '耶利米书', 24, 12, 5, '「あなたは徒歩の者と競走して疲れるのに、どうして馬と走り競うことができるだろうか。平穏な地で安心して過ごしているのに、どうしてヨルダンの密林で過ごせるだろうか。'),
('JPN', '耶利米书', 24, 12, 6, 'あなたの兄弟や、父の家の者さえ、彼らさえ、あなたを裏切り、彼らでさえ、あなたのうしろから大声で叫ぶ。だから彼らがあなたに親切そうに語りかけても、彼らを信じてはならない。'),
('JPN', '耶利米书', 24, 12, 7, 'わたしは、わたしの家を捨て、わたしのゆずりの地を見放し、わたしが心から愛するものを、敵の手中に渡した。'),
('JPN', '耶利米书', 24, 12, 8, 'わたしのゆずりの民は、わたしにとって、林の中の獅子のようだ。それはわたしに向かって、うなり声をあげる。それゆえ、わたしはこの地を憎む。'),
('JPN', '耶利米书', 24, 12, 9, 'わたしのゆずりの民は、わたしにとって、一羽の斑の猛禽なのか。それを猛禽どもが取り巻いているではないか。さあ、すべての野の獣を集めよ。それらを連れて来て、食べさせよ。'),
('JPN', '耶利米书', 24, 12, 10, '多くの牧者が、わがぶどう畑を荒らし、わたしの地所を踏みつけて、わたしの慕う地所を恐怖の荒野にした。'),
('JPN', '耶利米书', 24, 12, 11, 'それは恐怖と化し、荒れ果てて、わたしに向かって嘆き悲しんでいる。全地は荒らされて、まことに、だれも心に留める者はいない。'),
('JPN', '耶利米书', 24, 12, 12, '荒野にあるすべての裸の丘の上に、荒らす者が来た。主の剣が、地の果てから地の果てに至るまで食い尽くすので、すべての肉なる者には平安がない。'),
('JPN', '耶利米书', 24, 12, 13, '小麦を蒔いても、茨を刈り取り、労苦しても無駄になる。あなたがたは、自分たちの収穫で恥を見る。主の燃える怒りによって。」'),
('JPN', '耶利米书', 24, 12, 14, '主はこう言われる。「わたしの民イスラエルに受け継がせたゆずりの地に侵入する、悪い隣国の民について。見よ。わたしはその土地から彼らを引き抜き、彼らの間からユダの家も引き抜く。'),
('JPN', '耶利米书', 24, 12, 15, 'しかし、彼らを引き抜いた後、わたしは再び彼らをあわれみ、彼らをそれぞれ自分のゆずりの地、あるいは自分の土地に帰らせる。'),
('JPN', '耶利米书', 24, 12, 16, '彼らがかつて、バアルによって誓うことをわたしの民に教えたように、もし彼らがわたしの民の道をよく学び、わたしの名によって『主は生きておられる』と誓うなら、彼らはわたしの民のうちに建てられる。'),
('JPN', '耶利米书', 24, 12, 17, 'しかし、彼らが聞かなければ、わたしはその国を根こそぎ滅ぼす──主のことば。」'),
('JPN', '耶利米书', 24, 13, 1, '主は私にこう言われた。「行って亜麻布の帯を買い、それを腰に締めよ。水の中に入れてはならない。」'),
('JPN', '耶利米书', 24, 13, 2, '私は主のことばのとおり、帯を買って、腰に締めた。'),
('JPN', '耶利米书', 24, 13, 3, '再び次のような主のことばが私にあった。'),
('JPN', '耶利米书', 24, 13, 4, '「あなたが買って腰に着けているその帯を取り、ユーフラテス川に行って、そこの岩の割れ目にそれを隠せ。」'),
('JPN', '耶利米书', 24, 13, 5, 'そこで、主が私に命じられたとおり、私は行って、それをユーフラテス川のほとりに隠した。'),
('JPN', '耶利米书', 24, 13, 6, '多くの日を経て、主は私に言われた。「さあ、ユーフラテス川へ行き、わたしが隠せとあなたに命じたあの帯を取り出せ。」'),
('JPN', '耶利米书', 24, 13, 7, '私はユーフラテス川に行って掘り、隠した場所から帯を取り出した。すると見よ。その帯はぼろぼろになって、何の役にも立たなくなっていた。'),
('JPN', '耶利米书', 24, 13, 8, 'すると、私に次のような主のことばがあった。'),
('JPN', '耶利米书', 24, 13, 9, '主はこう言われた。「わたしはこのように、ユダとエルサレムの大きな誇りをぼろぼろにする。'),
('JPN', '耶利米书', 24, 13, 10, 'わたしのことばに聞くことを拒み、その頑なな心のままに、ほかの神々に従って歩んで、それらに仕え、それらを拝むこの悪しき民は、何の役にも立たないこの帯のようになる。'),
('JPN', '耶利米书', 24, 13, 11, '帯が人の腰に着けられるように、わたしはイスラエルの全家とユダの全家をわたしに着けた──主のことば──。それは、彼らがわたしの民となり、名声となり、栄誉となり、栄えとなるためだった。しかし彼らはわたしに聞き従わなかったのだ。'),
('JPN', '耶利米书', 24, 13, 12, 'あなたは彼らにこのことばを伝えよ。『イスラエルの神、主はこう言われる。酒壺には酒が満たされる。』彼らがあなたに『酒壺に酒が満たされることくらい、分かりきっているではないか』と言ったなら、'),
('JPN', '耶利米书', 24, 13, 13, 'あなたは彼らに言え。『主はこう言われる。見よ。わたしは、この地の全住民を、ダビデの王座に着いている王たち、祭司、預言者、およびエルサレムの全住民を酔いで満たし、'),
('JPN', '耶利米书', 24, 13, 14, '彼らを互いにぶつけて砕く。父も子も、ともに──主のことば──。わたしは容赦せず、惜しまず、あわれみをかけずに、彼らを滅ぼす。』」'),
('JPN', '耶利米书', 24, 13, 15, '耳を傾けて聞け。高ぶるな。主が語られたからだ。'),
('JPN', '耶利米书', 24, 13, 16, 'あなたがたの神、主に、栄光を帰せよ。まだ主が闇を送らないうちに、まだあなたがたの足が夕暮れの山でつまずかないうちに。あなたがたが光を待ち望んでも、主はそれを死の陰に変え、暗黒とされる。'),
('JPN', '耶利米书', 24, 13, 17, 'もし、あなたがたがこれに聞かなければ、私は隠れたところであなたがたの高ぶりのために嘆き、涙にくれ、私の目には涙があふれる。主の群れが捕らわれて行くからだ。'),
('JPN', '耶利米书', 24, 13, 18, '「王と王母に告げよ。『低い座に着け。あなたがたの頭から、輝かしい冠が落ちたから。』'),
('JPN', '耶利米书', 24, 13, 19, 'ネゲブの町々は閉ざされて、だれも開ける者はいない。ユダはことごとく捕らえ移される。一人残らず捕らえ移される。'),
('JPN', '耶利米书', 24, 13, 20, 'あなたがたの目を上げ、北から来る者たちを見よ。あなたに対して与えられた群れ、あなたの美しい羊の群れはどこにいるのか。'),
('JPN', '耶利米书', 24, 13, 21, '最も親しい友としてあなたが教えてきた者たちが、あなたの上に、かしらとして立てられるとき、あなたは何と言うのか。激しい痛みがあなたをとらえないだろうか。子を産む女のように。'),
('JPN', '耶利米书', 24, 13, 22, 'あなたが心の中で『なぜ、こんなことが私の身に起こったのか』と言うなら、それは、あなたの多くの咎のためだ。それで、あなたの裾はまくられて、あなたのかかとは傷を負うのだ。'),
('JPN', '耶利米书', 24, 13, 23, 'クシュ人がその皮膚を、豹がその斑点を、変えることができるだろうか。それができるなら、悪に慣れたあなたがたも善を行うことができるだろう。'),
('JPN', '耶利米书', 24, 13, 24, 'わたしは彼らを、荒野の風に吹き飛ばされる藁のように散らす。'),
('JPN', '耶利米书', 24, 13, 25, 'これが、あなたへの割り当て、わたしがあなたに量り与える分である。──主のことば──あなたがわたしを忘れ、偽りに拠り頼んだためだ。'),
('JPN', '耶利米书', 24, 13, 26, 'わたしも、あなたの裾を顔の上までまくるので、あなたの恥ずべきところが現れる。'),
('JPN', '耶利米书', 24, 13, 27, 'あなたの姦淫、あなたの興奮のいななき、あなたの淫行のわざ──数々の忌まわしいものを、わたしは丘の上や野原で見た。ああ、エルサレムよ。あなたはいつまで、きよめられないままなのか。」'),
('JPN', '耶利米书', 24, 14, 1, '日照りのことについて、エレミヤにあった主のことば。'),
('JPN', '耶利米书', 24, 14, 2, '「ユダは喪に服し、その門は打ちしおれ、地に伏して嘆き悲しみ、エルサレムは哀れな叫びをあげる。'),
('JPN', '耶利米书', 24, 14, 3, '高貴な人は、召使いに水を汲みに行かせるが、彼らが水溜めのところに来ても、水は見つからず、空の器のままで帰る。彼らは恥を見、辱められて、頭をおおう。'),
('JPN', '耶利米书', 24, 14, 4, '地には秋の大雨が降らず、地面は割れて、農夫たちは恥を見、頭をおおう。'),
('JPN', '耶利米书', 24, 14, 5, '野の雌鹿さえ、子を産んでも捨てる。若草がないからだ。'),
('JPN', '耶利米书', 24, 14, 6, '野ろばは裸の丘の上に立ち、ジャッカルのようにあえぎ、目も衰え果てる。青草がないからだ。」'),
('JPN', '耶利米书', 24, 14, 7, '「私たちの咎が、私たちに不利な証言をしても、主よ、あなたの御名のために事をなしてください。まことに私たちの背信は大きく、私たちはあなたの御前で罪の中にいます。'),
('JPN', '耶利米书', 24, 14, 8, 'イスラエルの望みである方、苦難の時の救い主よ。どうしてあなたは、この地にいる寄留者や、一晩だけ立ち寄る旅人のようにされるのですか。'),
('JPN', '耶利米书', 24, 14, 9, 'なぜ、あなたは驚いているだけの人や、人を救えない勇士のようにされるのですか。主よ。あなたは私たちのただ中におられ、私たちはあなたの御名をもって呼ばれているのです。私たちを置き去りにしないでください。」'),
('JPN', '耶利米书', 24, 14, 10, 'この民について、主はこう言われる。「このように、彼らはさまようことを愛し、その足を制することもしない。そのため、主は彼らを受け入れず、今、彼らの咎を覚えて、その罪を罰する。」'),
('JPN', '耶利米书', 24, 14, 11, '主は私に言われた。「この民のために幸いを祈ってはならない。'),
('JPN', '耶利米书', 24, 14, 12, '彼らが断食しても、わたしは彼らの叫びを聞かない。全焼のささげ物や穀物のささげ物を献げても、わたしはそれを受け入れない。かえって、剣と飢饉と疫病で、彼らを絶ち滅ぼす。」'),
('JPN', '耶利米书', 24, 14, 13, '私は言った。「ああ、神、主よ。ご覧ください。預言者たちは、『あなたがたは剣を見ず、飢饉もあなたがたに起こらない。かえって、わたしはこの場所で、まことの平安をあなたがたに与える』と人々に言っているではありませんか。」'),
('JPN', '耶利米书', 24, 14, 14, '主は私に言われた。「あの預言者たちは、わたしの名によって偽りを預言している。わたしは彼らを遣わしたこともなく、彼らに命じたこともなく、語ったこともない。彼らは、偽りの幻と、空しい占いと、自分の心の幻想を、あなたがたに預言しているのだ。'),
('JPN', '耶利米书', 24, 14, 15, 'それゆえ、わたしの名によって預言はするが、わたしが遣わしたのではない預言者たち、『剣や飢饉がこの地に起こらない』と言っているこの預言者たちについて、主はこう言う。『剣と飢饉によって、その預言者たちは滅び失せる。』'),
('JPN', '耶利米书', 24, 14, 16, '彼らの預言を聞いた民も、飢饉と剣によってエルサレムの道端に放り出され、彼らを葬る者もいない。彼らも、その妻も、息子、娘もそのようになる。わたしは、彼らの上に彼ら自身の悪を注ぎかける。'),
('JPN', '耶利米书', 24, 14, 17, 'あなたは彼らに、このことばを言え。『私の目は、夜も昼も涙を流して止まることのないように。おとめである娘、私の民の打たれた傷は大きく、それは癒やしがたい、ひどい打ち傷。'),
('JPN', '耶利米书', 24, 14, 18, '野に出ると、見よ、剣で刺し殺された者たち。町に入ると、見よ、飢えて病む者たち。まことに、預言者も祭司も、地を行き巡って、仕事に精を出し、何も知らない。』」'),
('JPN', '耶利米书', 24, 14, 19, '「あなたはユダを全く退けられたのですか。あなたはシオンを嫌われたのですか。なぜ、あなたは私たちを打ち、癒やしてくださらないのですか。私たちが平安を待ち望んでも、幸いはなく、癒やしの時を待ち望んでも、ご覧ください、恐怖しかありません。'),
('JPN', '耶利米书', 24, 14, 20, '主よ、私たちは自分たちの悪と、先祖の咎をよく知っています。本当に私たちは、あなたの御前で罪の中にあります。'),
('JPN', '耶利米书', 24, 14, 21, '御名のために、私たちを退けないでください。あなたの栄光の御座を辱めないでください。私たちとのあなたの契約を覚えていて、それを破らないでください。'),
('JPN', '耶利米书', 24, 14, 22, '国々の空しい神々の中に、大雨を降らせる者がいるでしょうか。それとも、天が夕立を降らせるのでしょうか。私たちの神、主よ、それは、あなたではありませんか。私たちはあなたを待ち望みます。あなたが、これらすべてをなさるからです。」'),
('JPN', '耶利米书', 24, 15, 1, '主は私に言われた。「たとえモーセとサムエルがわたしの前に立っても、わたしの心はこの民に向かわない。この民をわたしの前から追い出し、立ち去らせよ。'),
('JPN', '耶利米书', 24, 15, 2, '彼らがあなたに『どこへ去ろうか』と言うなら、あなたは彼らに言え。『主はこう言われる。死に定められた者は死に、剣に定められた者は剣に、飢饉に定められた者は飢饉に、捕囚に定められた者は捕囚に。』'),
('JPN', '耶利米书', 24, 15, 3, 'わたしは四種類のもので彼らを罰する──主のことば──。切り殺すための剣、引きずるための犬、食い尽くして滅ぼすための空の鳥と地の獣である。'),
('JPN', '耶利米书', 24, 15, 4, 'わたしは彼らを、地のすべての王国にとって、おののきのもとにする。ユダの王ヒゼキヤの子マナセがエルサレムで行ったことのためである。'),
('JPN', '耶利米书', 24, 15, 5, 'エルサレムよ、いったい、だれがおまえを深くあわれむだろう。だれがおまえのために嘆くだろう。だれが立ち寄って、おまえの安否を尋ねるだろう。'),
('JPN', '耶利米书', 24, 15, 6, 'おまえはわたしを捨てた。──主のことば──おまえはわたしから退いて行ったのだ。わたしはおまえに手を伸ばし、おまえを滅ぼす。わたしはあわれむのに疲れた。'),
('JPN', '耶利米书', 24, 15, 7, 'わたしはこの地の町囲みの中で、熊手で彼らを追い散らし、彼らに子を失わせ、わたしの民を滅ぼす。彼らはその生き方から立ち返らなかった。'),
('JPN', '耶利米书', 24, 15, 8, 'わたしはそのやもめの数を海の砂よりも多くする。わたしは若い男の母親に対し、真昼に荒らす者を送って、突然、彼女の上に苦痛と恐怖を臨ませる。'),
('JPN', '耶利米书', 24, 15, 9, '七人の子を産んだ女は打ちしおれ、その息はあえぐ。彼女の太陽は、まだ昼のうちに沈み、彼女は恥を見て、屈辱を受ける。わたしは彼らの残りの者を、彼らの敵の前で剣に渡す。──主のことば。」'),
('JPN', '耶利米书', 24, 15, 10, 'ああ、悲しいことだ。私の母が私を産んだので、私は全地にとって争いの相手、また口論する者となっている。私は貸したことも、借りたこともないのに、皆が私を呪っている。'),
('JPN', '耶利米书', 24, 15, 11, '主は言われた。「必ずわたしはあなたを解き放って、幸せにする。必ずわたしは、わざわいの時、苦難の時に、敵があなたにとりなしを頼むようにする。'),
('JPN', '耶利米书', 24, 15, 12, '人は鉄を、北からの鉄や青銅を砕くことができるだろうか。'),
('JPN', '耶利米书', 24, 15, 13, 'わたしは、あなたの財宝、あなたの宝物を、あなたの領土のいたるところで、戦利品として、ただで引き渡す。あなたの罪のゆえに。'),
('JPN', '耶利米书', 24, 15, 14, 'わたしはあなたを、あなたが知らない地で敵に仕えさせる。わたしの怒りに火がつき、あなたがたに向かって燃えるからだ。」'),
('JPN', '耶利米书', 24, 15, 15, '「主よ、あなたはよくご存じです。私を思い起こし、私を顧み、迫害する者たちに、私のために復讐してください。あなたの御怒りを遅くして、私を取り去らないでください。私があなたのためにそしりを受けていることを知ってください。'),
('JPN', '耶利米书', 24, 15, 16, '私はあなたのみことばが見つかったとき、それを食べました。そうして、あなたのみことばは、私にとって楽しみとなり、心の喜びとなりました。万軍の神、主よ、私はあなたの名で呼ばれているからです。'),
('JPN', '耶利米书', 24, 15, 17, '私は、戯れる者がたむろする場に座ったり、喜び躍ったりしたことはありません。私はあなたの御手によって、ひとり座っていました。あなたが私を憤りで満たされたからです。'),
('JPN', '耶利米书', 24, 15, 18, 'なぜ、私の痛みはいつまでも続き、私の打ち傷は治らず、癒えようもないのでしょう。あなたは、私にとって、欺く小川の流れ、当てにならない水のようになられるのですか。」'),
('JPN', '耶利米书', 24, 15, 19, 'それで、主はこう言われた。「もし、あなたが帰って来るなら、わたしはあなたを帰らせ、わたしの前に立たせる。もし、あなたが、卑しいことではなく、高貴なことを語るなら、あなたはわたしの口のようになる。彼らがあなたのところに帰ることがあっても、あなたは彼らのところに帰ってはならない。'),
('JPN', '耶利米书', 24, 15, 20, 'この民に対して、わたしはあなたを堅固な青銅の城壁とする。彼らは、あなたと戦っても勝てない。わたしがあなたとともにいて、あなたを救い、あなたを助け出すからだ。──主のことば──'),
('JPN', '耶利米书', 24, 15, 21, 'わたしは、あなたを悪しき者たちの手から救い出し、横暴な者たちの手から贖い出す。」'),
('JPN', '耶利米书', 24, 16, 1, '次のような主のことばが私にあった。'),
('JPN', '耶利米书', 24, 16, 2, '「あなたはこの場所で、妻をめとるな。息子や娘も持つな。」'),
('JPN', '耶利米书', 24, 16, 3, 'まことに主は、この場所で生まれる息子や娘について、また、この地で彼らを産む母親たちや、彼らをもうける父親たちについて、こう言われる。'),
('JPN', '耶利米书', 24, 16, 4, '「彼らはひどい病気で死ぬ。彼らは悼み悲しまれることなく、葬られることもなく、地の面の肥やしとなる。また、剣と飢饉で滅ぼされ、屍は空の鳥や地の獣の餌食となる。」'),
('JPN', '耶利米书', 24, 16, 5, 'まことに主はこう言われる。「あなたは、弔いの家に入ってはならない。悼みに行ってはならない。彼らのために嘆いてはならない。わたしがこの民から、わたしの平安を、また恵みと、あわれみを取り去ったからだ──主のことば──。'),
('JPN', '耶利米书', 24, 16, 6, 'この地の身分の高い者や低い者が死んでも葬られず、だれも彼らを悼み悲しまず、彼らのために身を傷つけず、髪も剃らない。'),
('JPN', '耶利米书', 24, 16, 7, '死者を悼む人のために、葬儀でパンが裂かれることはなく、父や母の場合でさえ、悼む人に慰めの杯が差し出されることもない。'),
('JPN', '耶利米书', 24, 16, 8, 'あなたは弔いの宴会の家に行き、一緒に座って食べたり飲んだりしてはならない。」'),
('JPN', '耶利米书', 24, 16, 9, 'まことに、イスラエルの神、万軍の主はこう言われる。「見よ。わたしはこの場所から、楽しみの声と喜びの声、花婿の声と花嫁の声を絶えさせる。あなたがたの目の前で。あなたがたが生きているうちに。」'),
('JPN', '耶利米书', 24, 16, 10, '「あなたがこの民に、このすべてのことばを告げるとき、彼らがあなたに、『何のために、主は私たちに、この大きなわざわいを語られたのか。私たちの咎とは何か。私たちの神、主に対して犯したという、私たちの罪とは何か』と尋ねたら、'),
('JPN', '耶利米书', 24, 16, 11, 'あなたは彼らにこう言え。『あなたがたの先祖がわたしを捨て──主のことば──ほかの神々に従い、これに仕え、これを拝み、またわたしを捨てて、わたしの律法を守らなかったことだ。'),
('JPN', '耶利米书', 24, 16, 12, 'さらに、あなたがた自身が、自分たちの先祖以上に悪事を働き、しかも、見よ、それぞれ頑なで悪い心のままに歩み、わたしに聞かないでいる。'),
('JPN', '耶利米书', 24, 16, 13, 'それで、わたしはあなたがたをこの地から放り出し、あなたがたも先祖も知らなかった地に行かせる。あなたがたは、そこで昼も夜も、ほかの神々に仕える。わたしはあなたがたに、いつくしみを施さない。』'),
('JPN', '耶利米书', 24, 16, 14, 'それゆえ、見よ、その時代が来る──主のことば──。そのとき、もはや人々は『イスラエルの子らをエジプトの地から連れ上った主は生きておられる』と言うことはなく、'),
('JPN', '耶利米书', 24, 16, 15, 'ただ『イスラエルの子らを、北の地から、彼らが散らされたすべての地方から上らせた主は生きておられる』と言うようになる。わたしは彼らの先祖に与えた彼らの土地に彼らを帰らせる。'),
('JPN', '耶利米书', 24, 16, 16, '見よ。わたしは多くの漁夫を遣わして──主のことば──彼らを捕まえさせる。それから、わたしは多くの狩人を遣わして、あらゆる山、あらゆる丘、岩の割れ目から彼らを捕らえさせる。'),
('JPN', '耶利米书', 24, 16, 17, 'わたしの目は彼らのすべての行いを見ているからだ。それらはわたしの前で隠れず、彼らの咎もわたしの目の前から隠されはしない。'),
('JPN', '耶利米书', 24, 16, 18, 'わたしはまず、彼らの咎と罪に対し二倍の報復をする。彼らがわたしの地を忌まわしいものの屍で汚し、忌み嫌うべきことで、わたしが与えたゆずりの地を満たしたからである。」'),
('JPN', '耶利米书', 24, 16, 19, '「主よ、私の力、私の砦、苦難の日の私の逃れ場よ。あなたのもとに、諸国の民が地の果てから来て言うでしょう。『私たちの父祖が受け継いだものは、ただ偽りのもの、何の役にも立たない空しいものばかり。'),
('JPN', '耶利米书', 24, 16, 20, '人間は、自分のために神々を造れるだろうか。そのようなものは神ではない』と。」'),
('JPN', '耶利米书', 24, 16, 21, '「それゆえ、見よ、わたしは彼らに知らせる。今度こそ彼らに、わたしの手、わたしの力を知らせる。そのとき彼らは、わたしの名が主であることを知る。」'),
('JPN', '耶利米书', 24, 17, 1, '「ユダの罪は、鉄の筆と金剛石の先端で記され、彼らの心の板と彼らの祭壇の角に刻まれている。'),
('JPN', '耶利米书', 24, 17, 2, '彼らの子たちまでもが、その祭壇や、高い丘の青々と茂る木のそばにあるアシェラ像を覚えているほどだ。'),
('JPN', '耶利米书', 24, 17, 3, '野にあるわたしの山よ。あなたの領土のいたるところで犯した罪ゆえに、わたしは、あなたの財宝、すべての宝物を、高き所とともに、戦利品として引き渡す。'),
('JPN', '耶利米书', 24, 17, 4, 'あなたは、わたしが与えたゆずりの地を手放さなければならない。またわたしは、あなたの知らない国で、あなたを敵に仕えさせる。あなたがたが、わたしの怒りに火をつけたので、それはとこしえまでも燃える。」'),
('JPN', '耶利米书', 24, 17, 5, '主はこう言われる。「人間に信頼する者はのろわれよ。肉なる者を自分の腕とし、心が主から離れている者は。'),
('JPN', '耶利米书', 24, 17, 6, 'そのような者は荒れ地の灌木。幸せが訪れても出会うことはなく、焼けついた荒野、住む者のいない塩地に住む。'),
('JPN', '耶利米书', 24, 17, 7, '主に信頼する者に祝福があるように。その人は主を頼みとする。'),
('JPN', '耶利米书', 24, 17, 8, 'その人は、水のほとりに植えられた木。流れのほとりに根を伸ばし、暑さが来ても暑さを知らず、葉は茂って、日照りの年にも心配なく、実を結ぶことをやめない。'),
('JPN', '耶利米书', 24, 17, 9, '人の心は何よりもねじ曲がっている。それは癒やしがたい。だれが、それを知り尽くすことができるだろうか。'),
('JPN', '耶利米书', 24, 17, 10, 'わたし、主が心を探り、心の奥を試し、それぞれその生き方により、行いの実にしたがって報いる。」'),
('JPN', '耶利米书', 24, 17, 11, 'しゃこが自分で産まなかった卵を抱くように、公正によらないで富を得る者がいる。彼の生涯の半ばで、富が彼を置き去りにし、その末は愚か者に終わる。'),
('JPN', '耶利米书', 24, 17, 12, '私たちの聖所がある場所は、初めから高く上げられた栄光の王座だ。'),
('JPN', '耶利米书', 24, 17, 13, '「イスラエルの望みである主よ。あなたを捨てる者は、みな恥を見ます。」「わたしから離れ去る者は、地にその名が記される。いのちの水の泉である主を捨てたからだ。」'),
('JPN', '耶利米书', 24, 17, 14, '「私を癒やしてください、主よ。そうすれば、私は癒やされます。私をお救いください。そうすれば、私は救われます。あなたこそ、私の賛美だからです。'),
('JPN', '耶利米书', 24, 17, 15, 'ご覧ください。彼らは私に言っています。『主のことばはどこへ行ったのか。さあ、それを来させよ。』'),
('JPN', '耶利米书', 24, 17, 16, 'しかし私は、あなたに従う牧者になることを避けたことはありません。癒やされない日を望んだこともありません。あなたは、私の唇から出るものが御前にあることをよくご存じです。'),
('JPN', '耶利米书', 24, 17, 17, '私を恐れさせないでください。あなたは、わざわいの日の、私の身の避け所です。'),
('JPN', '耶利米书', 24, 17, 18, '私を迫害する者たちが恥を見て、私が恥を見ることのないようにしてください。彼らがうろたえ、私がうろたえることのないようにしてください。彼らの上にわざわいの日を来たらせ、破れを倍にして、彼らを打ち破ってください。」'),
('JPN', '耶利米书', 24, 17, 19, '主は私にこう言われる。「行って、ユダの王たちが出入りする、この民の子らの門と、エルサレムのすべての門に立ち、'),
('JPN', '耶利米书', 24, 17, 20, '彼らに言え。『これらの門の内に入るユダの王たち、ユダ全体、エルサレムの全住民よ、主のことばを聞け。'),
('JPN', '耶利米书', 24, 17, 21, '主はこう言われる。あなたがた自身、気をつけて、安息日に荷物を運ぶな。また、それをエルサレムの門の内に持ち込むな。'),
('JPN', '耶利米书', 24, 17, 22, 'また、安息日に荷物を家から出すな。いかなる仕事もするな。安息日を聖なるものとせよ。わたしがあなたがたの先祖に命じたとおりだ。'),
('JPN', '耶利米书', 24, 17, 23, 'しかし、彼らは聞かず、耳を傾けず、うなじを固くする者となって聞こうとせず、戒めを受けなかった。'),
('JPN', '耶利米书', 24, 17, 24, 'もし、あなたがたが、本当にわたしに聞き従い──主のことば──安息日にこの都の門の内に荷物を持ち込まず、安息日を聖なるものとし、この日にいかなる仕事もしないなら、'),
('JPN', '耶利米书', 24, 17, 25, 'ダビデの王座に就く王たちや、車や馬に乗る首長たち、すなわち王たちとその首長たち、ユダの人、エルサレムの住民は、この都の門の内に入り、この都はとこしえに人の住む所となる。'),
('JPN', '耶利米书', 24, 17, 26, 'ユダの町々やエルサレムの周辺から、ベニヤミンの地やシェフェラから、また山地やネゲブから、全焼のささげ物、いけにえ、穀物のささげ物、乳香を携えて来る者、また感謝のいけにえを携えて来る者が、主の宮に来る。'),
('JPN', '耶利米书', 24, 17, 27, 'しかし、もし、わたしの言うことを聞き入れず、安息日を聖なるものとせず、安息日に荷物を運んでエルサレムの門の内に入るなら、わたしはその門に火をつけ、火はエルサレムの宮殿をなめ尽くし、消えることがない。』」'),
('JPN', '耶利米书', 24, 18, 1, '主からエレミヤに、このようなことばがあった。'),
('JPN', '耶利米书', 24, 18, 2, '「立って、陶器師の家に下れ。そこで、あなたにわたしのことばを聞かせる。」'),
('JPN', '耶利米书', 24, 18, 3, '私が陶器師の家に下って行くと、見よ、彼はろくろで仕事をしているところだった。'),
('JPN', '耶利米书', 24, 18, 4, '陶器師が粘土で制作中の器は、彼の手で壊されたが、それは再び、陶器師自身の気に入るほかの器に作り替えられた。'),
('JPN', '耶利米书', 24, 18, 5, 'それから、私に次のような主のことばがあった。'),
('JPN', '耶利米书', 24, 18, 6, '「イスラエルの家よ、わたしがこの陶器師のように、あなたがたにすることはできないだろうか──主のことば──。見よ。粘土が陶器師の手の中にあるように、イスラエルの家よ、あなたがたはわたしの手の中にある。'),
('JPN', '耶利米书', 24, 18, 7, 'わたしが、一つの国、一つの王国について、引き抜き、打ち倒し、滅ぼすと言ったそのとき、'),
('JPN', '耶利米书', 24, 18, 8, 'もし、わたしがわざわいを予告したその民が立ち返るなら、わたしは下そうと思っていたわざわいを思い直す。'),
('JPN', '耶利米书', 24, 18, 9, 'わたしが、一つの国、一つの王国について、建て直し、植えると言ったそのとき、'),
('JPN', '耶利米书', 24, 18, 10, 'もし、それがわたしの声に聞き従わず、わたしの目に悪であることを行うなら、わたしはそれに与えると言った幸せを思い直す。'),
('JPN', '耶利米书', 24, 18, 11, 'さあ今、ユダの人とエルサレムの住民に言え。『主はこう言われる。見よ。わたしはあなたがたに対してわざわいを考え出し、策をめぐらしている。さあ、それぞれ悪の道から立ち返り、あなたがたの生き方と行いを改めよ。』'),
('JPN', '耶利米书', 24, 18, 12, 'しかし、彼らは言う。『いや。私たちは自分の計画にしたがって歩み、それぞれ、頑なで悪い心のままに行います。』」'),
('JPN', '耶利米书', 24, 18, 13, 'それゆえ、主はこう言われる。「さあ、国々の中で尋ねてみよ。だれか、こんなことを聞いたことがあるだろうか。おとめイスラエルは、実におぞましいことを行った。'),
('JPN', '耶利米书', 24, 18, 14, 'レバノンの雪は、野の岩から消え去るだろうか。ほかの国から流れて来る冷たい水は、涸れることがあるだろうか。'),
('JPN', '耶利米书', 24, 18, 15, 'それなのに、わたしの民はわたしを忘れ、空しいものに犠牲を供える。それらは、わたしの民をその道、いにしえの道でつまずかせ、小道に、まだ整えられていない道に行かせ、'),
('JPN', '耶利米书', 24, 18, 16, '彼らの地を恐怖のもととし、永久に嘲りの的とする。そこを通り過ぎる者はみな、呆気にとられて頭を振る。'),
('JPN', '耶利米书', 24, 18, 17, '東風のように、わたしは彼らを敵の前で散らす。彼らの災難の日に、わたしは彼らに背を向け、顔を向けない。」'),
('JPN', '耶利米书', 24, 18, 18, '彼らは言った。「さあ、私たちは策をめぐらしてエレミヤを倒そう。祭司から律法が、知恵のある者から助言が、預言者からことばが滅び失せることはないはずだから。さあ、舌で彼を打ち、彼のすべてのことばに耳を傾けることがないようにしよう。」'),
('JPN', '耶利米书', 24, 18, 19, '「主よ、私に耳を傾け、私と争う者の声を聞いてください。'),
('JPN', '耶利米书', 24, 18, 20, '善に悪をもって報いてよいでしょうか。まことに彼らは、私のいのちを取ろうとして穴を掘りました。私が御前に立って、彼らへのあなたの憤りをやめていただくために、彼らについて良いことを語ったことを、思い起こしてください。'),
('JPN', '耶利米书', 24, 18, 21, 'それゆえ、彼らの子らを飢饉に渡し、彼らを剣で殺してください。妻たちは子を失い、また、やもめになり、夫たちは虐殺されて死に、若い男たちは戦いで剣に殺されますように。'),
('JPN', '耶利米书', 24, 18, 22, '突然、あなたが略奪隊に彼らを襲わせるとき、彼らの家から悲鳴が聞こえます。彼らは私を捕らえようとして穴を掘り、私の足もとに罠を設けたからです。'),
('JPN', '耶利米书', 24, 18, 23, '主よ、あなたはみなご存じです。私を殺そうとする彼らのはかりごとを。どうか彼らの咎を赦さず、彼らの罪を御前からぬぐい去らないでください。彼らを御前で打ち倒し、御怒りの時に、彼らに報いてください。」'),
('JPN', '耶利米书', 24, 19, 1, '主はこう言われる。「行って、土の焼き物の瓶を買い、民の長老と年長の祭司のうちの数人とともに、'),
('JPN', '耶利米书', 24, 19, 2, '陶片の門の入り口にあるベン・ヒノムの谷に出かけ、そこで、わたしがあなたに語ることばを叫べ。'),
('JPN', '耶利米书', 24, 19, 3, '『ユダの王たちとエルサレムの住民よ、主のことばを聞け。イスラエルの神、万軍の主はこう言われる。見よ、わたしはこの場所にわざわいをもたらす。だれでもそのことを聞く者は、両耳が鳴る。'),
('JPN', '耶利米书', 24, 19, 4, '彼らがわたしを捨てて、この場所を見知らぬ所としたからである。彼らはこの場所で、彼らも彼らの先祖も、ユダの王たちも知らなかったほかの神々に犠牲を供え、この場所を咎なき者の血で満たし、'),
('JPN', '耶利米书', 24, 19, 5, 'バアルのために自分の子どもたちを全焼のささげ物として火で焼くため、バアルの高き所を築いた。このようなことは、わたしが命じたこともなく、語ったこともなく、思いつきもしなかった。'),
('JPN', '耶利米书', 24, 19, 6, 'それゆえ、見よ、その時代が来る──主のことば──。そのとき、もはやこの場所はトフェトとかベン・ヒノムの谷と呼ばれない。ただ虐殺の谷と呼ばれる。'),
('JPN', '耶利米书', 24, 19, 7, 'また、わたしはこの場所で、ユダとエルサレムのはかりごとを打ち砕く。わたしは敵の前で彼らを剣で倒し、また、いのちを狙う者の手によって倒し、その屍を空の鳥や地の獣に餌食として与える。'),
('JPN', '耶利米书', 24, 19, 8, 'また、わたしはこの都を恐怖のもと、また嘲りの的とする。そこを通り過ぎる者はみな呆気にとられ、そのすべての打ち傷を見てあざ笑う。'),
('JPN', '耶利米书', 24, 19, 9, 'またわたしは、包囲と、彼らの敵、いのちを狙う者がもたらす窮乏のために、彼らに自分の息子の肉、娘の肉を食べさせる。彼らは互いに、その友の肉を食べ合う。』'),
('JPN', '耶利米书', 24, 19, 10, 'そこであなたは、同行の人たちの目の前でその瓶を砕いて、'),
('JPN', '耶利米书', 24, 19, 11, '彼らに言え。『万軍の主はこう言われる。陶器師の器が砕かれると、二度と直すことはできない。このように、わたしはこの民と、この都を砕く。人々はトフェトに空き地がないまでに葬る。'),
('JPN', '耶利米书', 24, 19, 12, 'わたしはこの場所と──主のことば──その住民にこのようにする。わたしはこの都をトフェトのようにする。'),
('JPN', '耶利米书', 24, 19, 13, 'エルサレムの家々とユダの王の家々、すなわち、屋上で天の万象に犠牲を供え、ほかの神々に注ぎのぶどう酒を注いだすべての家々は、トフェトの地のように汚される。』」'),
('JPN', '耶利米书', 24, 19, 14, 'そこでエレミヤは、主が預言のために遣わしたトフェトから帰って、主の宮の庭に立ち、民全体に言った。'),
('JPN', '耶利米书', 24, 19, 15, '「イスラエルの神、万軍の主はこう言われる。見よ。わたしはこの都とすべての町に、わたしが告げたすべてのわざわいをもたらす。彼らがうなじを固くする者となって、わたしのことばに聞き従おうとしなかったからである。」'),
('JPN', '耶利米书', 24, 20, 1, 'さて、主の宮のつかさ、また監督者である、イメルの子、祭司パシュフルは、エレミヤがこれらのことばを預言するのを聞いた。'),
('JPN', '耶利米书', 24, 20, 2, 'パシュフルは、預言者エレミヤを打ち、彼を主の宮にある、上のベニヤミンの門にある足かせにつないだ。'),
('JPN', '耶利米书', 24, 20, 3, '翌日になって、パシュフルがエレミヤを足かせから解いたとき、エレミヤは彼に言った。「主はあなたの名をパシュフルではなく、『恐怖が取り囲んでいる』と呼ばれる。'),
('JPN', '耶利米书', 24, 20, 4, 'まことに主はこう言われる。見よ。わたしはあなたを、あなた自身とあなたの愛するすべての者にとって恐怖とする。彼らは、あなたが見ている前で、敵の剣に倒れる。また、わたしはユダの人すべてをバビロンの王の手に渡す。彼は彼らをバビロンへ引いて行き、剣で打ち殺す。'),
('JPN', '耶利米书', 24, 20, 5, 'また、わたしはこの都のすべての富と、すべての労苦の実と、すべての宝を渡し、ユダの王たちの財宝を敵の手に渡す。彼らはそれをかすめ奪い、略奪してバビロンへ運ぶ。'),
('JPN', '耶利米书', 24, 20, 6, 'パシュフルよ。あなたとあなたの家に住むすべての者は、捕らわれの身となってバビロンに行き、そこで死んで、そこに葬られる。あなたも、あなたが偽って預言を語り聞かせた、あなたの愛するすべての者たちも。」'),
('JPN', '耶利米书', 24, 20, 7, '「主よ。あなたが私を惑わしたので、私はあなたに惑わされました。あなたは私をつかみ、思いのままにされました。私は一日中笑いものとなり、皆が私を嘲ります。'),
('JPN', '耶利米书', 24, 20, 8, '私は、語るたびに大声を出して『暴虐だ。暴行だ』と叫ばなければなりません。主のことばが、一日中、私への嘲りのもととなり、笑いぐさとなるのです。'),
('JPN', '耶利米书', 24, 20, 9, '私が、『主のことばは宣べ伝えない。もう御名によっては語らない』と思っても、主のことばは私の心のうちで、骨の中に閉じ込められて、燃えさかる火のようになり、私は内にしまっておくのに耐えられません。もうできません。'),
('JPN', '耶利米书', 24, 20, 10, '私が、多くの人のささやきを聞いたからです。『「恐怖が取り囲んでいる」と告げよ。われわれも彼に告げたいのだ』と。私の親しい者もみな、私がつまずくのを待ちかまえています。『たぶん彼は惑わされるから、われわれは彼に勝って、復讐できるだろう』と。'),
('JPN', '耶利米书', 24, 20, 11, 'しかし、主は私とともにいて、荒々しい勇士のようです。ですから、私を迫害する者たちはつまずき、勝つことができません。彼らは成功しないので、大いに恥をかき、忘れられることのない永久の恥となります。'),
('JPN', '耶利米书', 24, 20, 12, '正しい者を試し、思いと心を見る万軍の主よ。あなたが彼らに復讐するのを私に見させてください。私の訴えをあなたに打ち明けたのですから。」'),
('JPN', '耶利米书', 24, 20, 13, '主に向かって歌い、主をほめたたえよ。主が貧しい者のいのちを、悪を行う者どもの手から救い出されたからだ。'),
('JPN', '耶利米书', 24, 20, 14, '「私の生まれた日は、のろわれよ。母が私を産んだその日は、祝福されるな。'),
('JPN', '耶利米书', 24, 20, 15, 'のろわれよ。私の父に、『男の子が生まれた』と知らせて、大いに喜ばせた人は。'),
('JPN', '耶利米书', 24, 20, 16, 'その人は、主があわれみもなく打ち倒す町々のようになれ。朝には彼に悲鳴を聞かせ、真昼には、ときの声を聞かせよ。'),
('JPN', '耶利米书', 24, 20, 17, '彼は、私が胎内にいるときに私を殺さず、母を私の墓とせず、その胎を、永久に身ごもったままにしなかったからだ。'),
('JPN', '耶利米书', 24, 20, 18, 'なぜ、私は労苦と悲しみにあうために胎を出たのか。私の一生は恥のうちに終わるのか。」'),
('JPN', '耶利米书', 24, 21, 1, '主からエレミヤにあったことば。ゼデキヤ王が、マルキヤの子パシュフルと、マアセヤの子、祭司ゼパニヤをエレミヤのもとに遣わして、'),
('JPN', '耶利米书', 24, 21, 2, '「どうか、私たちのために主に尋ねてください。バビロンの王ネブカドネツァルが私たちを攻めています。主がかつて、あらゆる奇しいみわざを行われたように、私たちにも行い、彼を私たちのところから引き揚げさせてくださるかもしれませんから」と言ったときのことである。'),
('JPN', '耶利米书', 24, 21, 3, 'エレミヤは彼らに言った。「あなたがたは、ゼデキヤにこう言いなさい。'),
('JPN', '耶利米书', 24, 21, 4, '『イスラエルの神、主はこう言われる。あなたがたは、城壁の外からあなたがたを囲むバビロンの王とカルデア人に向かって戦っているが、見よ、わたしはあなたがたが手にしている武具の向きを変え、それを集めてこの都のただ中に向ける。'),
('JPN', '耶利米书', 24, 21, 5, 'わたし自身が、伸ばされた手と力強い腕をもって、怒り、憤り、大いなる激怒をもって、あなたがたと戦う。'),
('JPN', '耶利米书', 24, 21, 6, 'この都に住むものは、人も家畜もわたしは打つ。彼らは激しい疫病で死ぬ。'),
('JPN', '耶利米书', 24, 21, 7, 'その後で──主のことば──わたしはユダの王ゼデキヤとその家来、また、その民と、この都で疫病や剣や飢饉から逃れて生き残った者たちを、バビロンの王ネブカドネツァルの手、敵の手、いのちを狙う者たちの手に渡す。彼は彼らを剣の刃で討ち、彼らを惜しまず、容赦せず、あわれみをかけない。』」'),
('JPN', '耶利米书', 24, 21, 8, '「あなたは、この民に言え。『主はこう言われる。見よ、わたしはあなたがたの前に、いのちの道と死の道を置く。'),
('JPN', '耶利米书', 24, 21, 9, 'この都にとどまる者は、剣と飢饉と疫病によって死ぬ。出て行ってあなたがたを囲んでいるカルデア人に降伏する者は生き、自分のいのちを戦勝品として得る。'),
('JPN', '耶利米书', 24, 21, 10, 'なぜなら、わたしがこの都に顔を向けるのは、幸いのためではなく、わざわいのためだからだ──主のことば──。この都は、バビロンの王の手に渡され、彼はこれを火で焼く。』」'),
('JPN', '耶利米书', 24, 21, 11, 'ユダの王家について。「主のことばを聞け。'),
('JPN', '耶利米书', 24, 21, 12, 'ダビデの家よ、主はこう言われる。朝ごとに、公正にさばきを行い、かすめられている者を、虐げる者の手から救い出せ。そうでないと、あなたがたの悪行のために、わたしの憤りが火のように燃えて焼き尽くし、消す者はいなくなる。'),
('JPN', '耶利米书', 24, 21, 13, '見よ、わたしはあなたに敵対する。この谷に住む者、平地の岩よ──主のことば──。あなたがたはこう言っている。『だれが、このところに下って来るだろう。だれが、この住まいに入って来るだろう』と。'),
('JPN', '耶利米书', 24, 21, 14, 'わたしはあなたがたを、その行いの実にしたがって罰する。──主のことば──わたしはその森に火をつける。火は、その周りをことごとく焼き尽くす。」'),
('JPN', '耶利米书', 24, 22, 1, '主はこう言われる。「ユダの王の家に下り、そこでこのことばを語れ。'),
('JPN', '耶利米书', 24, 22, 2, '『ダビデの王座に着くユダの王よ。あなたも、これらの門の内に入って来るあなたの家来も、またあなたの民も、主のことばを聞け。'),
('JPN', '耶利米书', 24, 22, 3, '主はこう言われる。公正と正義を行い、かすめ取られている者を、虐げる者の手から救い出せ。寄留者、みなしご、やもめを苦しめたり、いじめたりしてはならない。また、咎なき者の血をここで流してはならない。'),
('JPN', '耶利米书', 24, 22, 4, 'もし、あなたがたがこのことばを忠実に行うなら、ダビデの王座に着く王たちは車や馬に乗り、彼らも、その家来も、またその民も、この家の門の内に入ることができる。'),
('JPN', '耶利米书', 24, 22, 5, 'しかし、もしこのことばを聞かなければ、わたしは自分にかけて誓うが──主のことば──この家は必ず廃墟となる。』」'),
('JPN', '耶利米书', 24, 22, 6, 'まことに、ユダの王の家について、主はこう言われる。「あなたは、わたしにとってはギルアデ、レバノンの頂だが、必ず、わたしはあなたを荒野にし、住む人もいない町々にする。'),
('JPN', '耶利米书', 24, 22, 7, 'わたしはあなたを攻めるために、それぞれ武具を持つ破壊者たちを取り分ける。彼らは、最も美しいあなたの杉の木を切り倒して火に投げ入れる。'),
('JPN', '耶利米书', 24, 22, 8, '多くの国々の者がこの都のそばを過ぎ、彼らが互いに、『何のために、主はこの大きな都をこのようにしたのだろうか』と言えば、'),
('JPN', '耶利米书', 24, 22, 9, '人々は、『彼らが、自分の神、主の契約を捨ててほかの神々を拝み、仕えたからだ』と言う。」'),
('JPN', '耶利米书', 24, 22, 10, '死んだ者のために泣くな。その者のために嘆くな。去って行く者のために、大いに泣け。彼が再び帰って、故郷を見ることがないからだ。'),
('JPN', '耶利米书', 24, 22, 11, '父ヨシヤに代わって王となった、ヨシヤの子、ユダの王シャルムについて、主はまことにこう言われる。「彼はこの場所から出て行って、二度とここには帰らない。'),
('JPN', '耶利米书', 24, 22, 12, '彼は引いて行かれた場所で死に、再びこの地を見ることはない。」'),
('JPN', '耶利米书', 24, 22, 13, '「わざわいだ。不義によって自分の家を建て、不正によって自分の高殿を建てる者たち。隣人をただで働かせて報酬も払わず、'),
('JPN', '耶利米书', 24, 22, 14, '『私は自分のために、広い家、ゆったりとした高殿を建てよう』と言い、それに窓を取り付けて、杉の板でおおい、朱を塗る者は。'),
('JPN', '耶利米书', 24, 22, 15, 'あなたは杉の木で競って、王になろうとするのか。あなたの父は食べたり飲んだりし、公正と義を行ったではないか。そのとき、彼は幸福であった。'),
('JPN', '耶利米书', 24, 22, 16, '虐げられた人、貧しい人の訴えを擁護し、彼は、そのとき幸福であった。それが、わたしを知っていることではないのか。──主のことば──'),
('JPN', '耶利米书', 24, 22, 17, 'しかし、あなたの目と心は、自分の利得に、さらには、咎なき者の血を流すこと、虐げと暴虐を行うことにだけ向けられている。」'),
('JPN', '耶利米书', 24, 22, 18, 'それゆえ、ヨシヤの子、ユダの王エホヤキムについて、主はこう言われる。「だれも、『ああ、悲しい、私の兄弟よ。ああ、悲しい、私の姉妹よ』と言って彼を悼まず、だれも、『ああ、悲しい、主よ。ああ、悲しい、陛下よ』と言って彼を悼まない。'),
('JPN', '耶利米书', 24, 22, 19, '彼はエルサレムの門の外へ引きずられ、投げ捨てられて、ろばが埋められるように埋められる。」'),
('JPN', '耶利米书', 24, 22, 20, '「レバノンに上って叫び、バシャンで声をあげ、アバリムから叫べ。あなたの恋人たちがみな、砕かれたからだ。'),
('JPN', '耶利米书', 24, 22, 21, 'あなたが平穏であったときに、わたしはあなたに語りかけたが、あなたは『私は聞かない』と言った。わたしの声に聞き従わないということ、これが、若いころからのあなたの生き方だった。'),
('JPN', '耶利米书', 24, 22, 22, 'あなたの牧者たちはみな風に追い立てられ、あなたの恋人たちは捕らわれの身となって行く。そのとき、あなたは自分のすべての悪のゆえに、恥を見、辱めを受ける。'),
('JPN', '耶利米书', 24, 22, 23, 'レバノンの中に住み、杉の木の中に巣ごもりする女よ。あなたに陣痛が、産婦のような激痛が襲うとき、あなたはどんなにうめくことだろう。」'),
('JPN', '耶利米书', 24, 22, 24, '「わたしは生きている──主のことば──。ユダの王、エホヤキムの子エコンヤは、わたしの右手の指輪の印ではあるが、わたしは必ずあなたを指から抜き取り、'),
('JPN', '耶利米书', 24, 22, 25, 'あなたのいのちを狙う者たちの手、あなたが恐れている者たちの手、バビロンの王ネブカドネツァルの手、カルデア人の手に渡し、'),
('JPN', '耶利米书', 24, 22, 26, 'あなたと、あなたの産みの母を、あなたがたが生まれたところではない、ほかの地に放り出し、そこであなたがたは死ぬことになる。'),
('JPN', '耶利米书', 24, 22, 27, '彼らが帰りたいと心から望むこの地に、彼らは決して帰らない。」'),
('JPN', '耶利米书', 24, 22, 28, 'この人エコンヤは、蔑まれて砕かれる像なのか。だれにも顧みられない器なのか。なぜ、彼とその子孫は投げ捨てられ、見も知らぬ地に投げやられるのか。'),
('JPN', '耶利米书', 24, 22, 29, '地よ、地よ、地よ、主のことばを聞け。'),
('JPN', '耶利米书', 24, 22, 30, '「主はこう言われる。この人を『子を残さず、一生栄えない男』と記録せよ。彼の子孫のうち一人も、ダビデの王座に着いて栄え、再びユダを治める者はいないからだ。」'),
('JPN', '耶利米书', 24, 23, 1, '「わざわいだ。わたしの牧場の群れを滅ぼし散らしている牧者たち──主のことば。」'),
('JPN', '耶利米书', 24, 23, 2, 'それゆえ、イスラエルの神、主は、私の民を牧する牧者たちについてこう言われる。「あなたがたはわたしの群れを散らし、これを追い散らして顧みなかった。見よ、わたしはあなたがたの悪しき行いを罰する──主のことば──。'),
('JPN', '耶利米书', 24, 23, 3, 'しかしわたしは、わたしの群れの残りの者を、わたしが追い散らしたすべての地から集め、元の牧場に帰らせる。彼らは多くの子を生んで増える。'),
('JPN', '耶利米书', 24, 23, 4, 'わたしは彼らの上に牧者たちを立てて、彼らを牧させる。彼らは二度と恐れることなく、おびえることなく、失われることもない──主のことば。'),
('JPN', '耶利米书', 24, 23, 5, '見よ、その時代が来る。──主のことば──そのとき、わたしはダビデに一つの正しい若枝を起こす。彼は王となって治め、栄えて、この地に公正と義を行う。'),
('JPN', '耶利米书', 24, 23, 6, '彼の時代にユダは救われ、イスラエルは安らかに住む。『主は私たちの義』。それが、彼の呼ばれる名である。'),
('JPN', '耶利米书', 24, 23, 7, 'それゆえ、見よ、その時代が来る──主のことば──。そのとき、もはや人々は『イスラエルの子らをエジプトの地から上らせた主は生きておられる』と言うことはなく、'),
('JPN', '耶利米书', 24, 23, 8, '『イスラエルの家の末裔を、北の地や、彼らが散らされていたすべての地から上らせた主は、生きておられる』と言って、自分たちの土地に住むようになる。」'),
('JPN', '耶利米书', 24, 23, 9, '預言者たちについて──私の心は、うちに砕かれ、私の骨はみな震える。私は酔いどれのように、ぶどう酒に負けた男のようになった。主と、主の聖なることばのために。'),
('JPN', '耶利米书', 24, 23, 10, '地が姦通する者で満ちているからだ。地はのろわれて喪に服し、荒野の牧場は乾ききる。彼らの走る道は悪で、その力は正しくないことに使われる。'),
('JPN', '耶利米书', 24, 23, 11, '「実に、預言者も祭司も汚れている。わたしの家の中にも、わたしは彼らの悪を見出した。──主のことば──'),
('JPN', '耶利米书', 24, 23, 12, 'それゆえ、彼らの道は、暗闇の中の滑りやすい場所のようになり、彼らは押しやられて、そこに倒れる。わたしが彼らにわざわいをもたらし、刑罰の年をもたらすからだ。──主のことば──'),
('JPN', '耶利米书', 24, 23, 13, 'サマリアの預言者たちの中に、わたしはごまかしを見た。彼らはバアルによって預言し、わたしの民イスラエルを迷わせた。'),
('JPN', '耶利米书', 24, 23, 14, 'エルサレムの預言者たちの中に、わたしはおぞましいことを見た。彼らは姦通し、噓をついて歩き、悪を行う者どもの手を強くして、その悪から、だれも立ち返らせない。彼らはみな、わたしにはソドムのようであり、その住民はゴモラのようだ。」'),
('JPN', '耶利米书', 24, 23, 15, 'それゆえ、万軍の主は、預言者たちについてこう言われる。「見よ。わたしは彼らに、苦よもぎを食べさせ、毒の水を飲ませる。不敬虔がエルサレムの預言者たちから出て、全土に広がったからだ。」'),
('JPN', '耶利米书', 24, 23, 16, '万軍の主はこう言われる。「あなたがたに預言する預言者たちのことばを聞くな。彼らはあなたがたを空しいものにしようとしている。彼らは主の御口からではなく、自分の心の幻を語っている。'),
('JPN', '耶利米书', 24, 23, 17, '彼らは、わたしを侮る者に向かって、『主はあなたがたに平安があると告げられた』としきりに言い、頑なな心のままに歩むすべての者に向かって、『あなたがたにはわざわいが来ない』と言っている。」'),
('JPN', '耶利米书', 24, 23, 18, 'しかし、だれが、主との親しい交わりに加わり、主のことばを見聞きしたか。だれが、耳を傾けて主のことばを聞いたか。'),
('JPN', '耶利米书', 24, 23, 19, '見よ。主のつむじ風が憤りとなって出て行く。荒れ狂う暴風が悪者の頭上で荒れ狂う。'),
('JPN', '耶利米书', 24, 23, 20, '主の怒りは、その心の御思いを行って成し遂げるまで去ることはない。終わりの日に、あなたがたはそれを明らかに悟る。'),
('JPN', '耶利米书', 24, 23, 21, '「わたしはこのような預言者たちを遣わさなかったのに、彼らは走り続ける。わたしは彼らに語らなかったのに、彼らは預言している。'),
('JPN', '耶利米书', 24, 23, 22, 'わたしとの親しい交わりに加わっていたなら、彼らは、わたしの民にわたしのことばを聞かせ、民をその悪い生き方から、その悪しき行いから立ち返らせたであろうに。'),
('JPN', '耶利米书', 24, 23, 23, 'わたしは近くにいれば、神なのか。──主のことば──遠くにいれば、神ではないのか。'),
('JPN', '耶利米书', 24, 23, 24, '人が隠れ場に身を隠したら、わたしはその人を見ることができないのか。──主のことば──天にも地にも、わたしは満ちているではないか。──主のことば。'),
('JPN', '耶利米书', 24, 23, 25, 'わたしの名によって偽りを預言する預言者たちが、『私は夢を見た。夢を見た』と言うのを、わたしは聞いた。'),
('JPN', '耶利米书', 24, 23, 26, 'いつまで、あの預言者たちの心に偽りの預言があるのか。心の偽りごとを語る預言者たちのうちに。'),
('JPN', '耶利米书', 24, 23, 27, '彼らの先祖がバアルのゆえにわたしの名を忘れたように、彼らはそれぞれ自分たちの夢を述べ、わたしの民にわたしの名を忘れさせようと、企んでいるのか。'),
('JPN', '耶利米书', 24, 23, 28, '夢を見た預言者は夢を語るがよい。しかし、わたしのことばを受けた者は、わたしのことばを忠実に語らなければならない。麦は藁と何の関わりがあるだろうか。──主のことば──'),
('JPN', '耶利米书', 24, 23, 29, 'わたしのことばは火のようではないか──主のことば──。岩を砕く金槌のようではないか。'),
('JPN', '耶利米书', 24, 23, 30, 'それゆえ、見よ──主のことば──。わたしは、互いにわたしのことばを盗み合う預言者たちの敵となる。'),
('JPN', '耶利米书', 24, 23, 31, '見よ。わたしは──主のことば──自分の舌を操って、これがみことばだ、と言う預言者たちの敵となる。'),
('JPN', '耶利米书', 24, 23, 32, '見よ。わたしは偽りの夢を預言する者たちの敵となる──主のことば──。彼らは、偽りと自慢話をわたしの民に語って迷わせている。わたしは彼らを遣わさず、彼らに命じもしなかった。彼らは、この民にとって何の役にも立たない──主のことば。'),
('JPN', '耶利米书', 24, 23, 33, 'この民、あるいは預言者か祭司が、『主の宣告とは何か』とあなたに尋ねたら、あなたは彼らに言え。『あなたが、宣告とは何かと言うので、わたしはあなたがたを捨てる──主のことば。』'),
('JPN', '耶利米书', 24, 23, 34, '預言者でも、祭司でも、民でも、主の宣告と言う者があれば、わたしはその者とその家を罰する。」'),
('JPN', '耶利米书', 24, 23, 35, 'あなたがたは互いに「主はどう答えられたか。主はどう語られたか」と言うがよい。'),
('JPN', '耶利米书', 24, 23, 36, 'しかし、主の宣告ということを二度と述べてはならない。その宣告自体がそれを言う人自身のことばであり、あなたがたが、生ける神、万軍の主、私たちの神のことばを曲げることになるからだ。'),
('JPN', '耶利米书', 24, 23, 37, '「あの預言者たちにこう言え。『主はどう答えられたか。主はどう語られたか。'),
('JPN', '耶利米书', 24, 23, 38, 'もし、あなたがたが主の宣告と言うなら、それに対して、主はこう言われる。わたしはあなたがたに、主の宣告と言うなと言い送ったのに、あなたがたは主の宣告というこのことばを使っている。'),
('JPN', '耶利米书', 24, 23, 39, 'それゆえ、見よ、わたしはあなたがたを全く忘れ、あなたがたとあなたがたの先祖に与えたこの都を、あなたがたとともに、わたしの前から捨てて、'),
('JPN', '耶利米书', 24, 23, 40, '永遠の恥辱、忘れられることのない永遠の侮辱をあなたがたに与える。』」'),
('JPN', '耶利米书', 24, 24, 1, 'バビロンの王ネブカドネツァルが、ユダの王、エホヤキムの子エコンヤと、ユダの高官たち、職人、鍛冶をエルサレムから捕らえ移してバビロンに連れて行った後のこと、主は私にこのように示された。見よ、主の神殿の前に、二かごのいちじくが置かれていた。'),
('JPN', '耶利米书', 24, 24, 2, '一つのかごにあるのは非常に良いいちじくで、初なりのいちじくの実のようであり、もう一つのかごにあるのは非常に悪いいちじくで、悪くて食べられないものであった。'),
('JPN', '耶利米书', 24, 24, 3, 'そのとき、主が私に、「エレミヤ、あなたは何を見ているのか」と言われたので、私は言った。「いちじくです。良いいちじくは非常に良く、悪いほうは非常に悪く、悪くて食べられないものです。」'),
('JPN', '耶利米书', 24, 24, 4, 'すると、私に次のような主のことばがあった。'),
('JPN', '耶利米书', 24, 24, 5, '「イスラエルの神、主はこう言う。わたしは、この場所からカルデア人の地に送ったユダの捕囚の民を、この良いいちじくのように、良いものであると見なそう。'),
('JPN', '耶利米书', 24, 24, 6, 'わたしは、彼らを幸せにしようと彼らに目をかける。彼らをこの地に帰らせ、建て直して、壊すことなく、植えて、引き抜くことはない。'),
('JPN', '耶利米书', 24, 24, 7, 'わたしは、わたしが主であることを知る心を彼らに与える。彼らはわたしの民となり、わたしは彼らの神となる。彼らが心のすべてをもってわたしに立ち返るからである。'),
('JPN', '耶利米书', 24, 24, 8, 'しかし、悪くて食べられないあの悪いいちじくのように──まことに主は言われる──わたしはユダの王ゼデキヤと、その高官たち、エルサレムの残りの者と、この地に残されている者、およびエジプトの地に住んでいる者を、このようにする。'),
('JPN', '耶利米书', 24, 24, 9, 'わたしは彼らを、地のすべての王国にとって、おののきのもと、悪しきものとする。また、わたしが追い散らす、すべての場所で、そしりと嘲りの的、物笑いの種、ののしりの的とする。'),
('JPN', '耶利米书', 24, 24, 10, 'わたしは彼らのうちに、剣と飢饉と疫病を送り、彼らとその先祖に与えた地から彼らを滅ぼし尽くす。」'),
('JPN', '耶利米书', 24, 25, 1, 'ユダの王、ヨシヤの子エホヤキムの第四年、バビロンの王ネブカドネツァルの元年に、ユダの民全体についてエレミヤにあったみことば。'),
('JPN', '耶利米书', 24, 25, 2, '預言者エレミヤは、それをユダの民全体とエルサレムの全住民に語り、こう言った。'),
('JPN', '耶利米书', 24, 25, 3, '「ユダの王、アモンの子ヨシヤの第十三年から今日まで、この二十三年間、私に主のことばがあり、私はあなたがたに絶えず、しきりに語りかけたのに、あなたがたは聞かなかった。'),
('JPN', '耶利米书', 24, 25, 4, 'また、主はあなたがたに、主のしもべである預言者たちを早くからたびたび遣わされたのに、あなたがたは聞かず、聞こうと耳を傾けもしなかった。'),
('JPN', '耶利米书', 24, 25, 5, '主は言われた。『さあ、それぞれ悪の道から、あなたがたの悪い行いから立ち返り、主があなたがたと先祖たちに与えた土地に、いつまでも、とこしえに住め。'),
('JPN', '耶利米书', 24, 25, 6, 'ほかの神々に従い、それに仕え、それを拝んではならない。あなたがたが手で造った物によって、わたしの怒りを引き起こしてはならない。そのようにすれば、わたしも、あなたがたにわざわいを下さない。'),
('JPN', '耶利米书', 24, 25, 7, 'しかし、あなたがたはわたしに聞き従わなかった──主のことば──。そして、あなたがたは手で造った物でわたしの怒りを引き起こし、身にわざわいを招いた。』'),
('JPN', '耶利米书', 24, 25, 8, 'それゆえ、万軍の主はこう言われる。『あなたがたがわたしのことばに聞き従わなかったから、'),
('JPN', '耶利米书', 24, 25, 9, '見よ、わたしは北のすべての種族を呼び寄せる──主のことば──。わたしのしもべ、バビロンの王ネブカドネツァルを呼び寄せて、この国とその住民、その周りのすべての国々を攻めさせ、これを聖絶して、恐怖のもと、嘲りの的、永遠の廃墟とする。'),
('JPN', '耶利米书', 24, 25, 10, 'わたしは彼らから楽しみの声と喜びの声、花婿の声と花嫁の声、ひき臼の音と、ともしびの光を消し去る。'),
('JPN', '耶利米书', 24, 25, 11, 'この地はすべて廃墟となり荒れ果てて、これらの国々はバビロンの王に七十年仕える。'),
('JPN', '耶利米书', 24, 25, 12, '七十年の終わりに、わたしはバビロンの王とその民を──主のことば──またカルデア人の地を、彼らの咎のゆえに罰し、これを永遠に荒れ果てた地とする。'),
('JPN', '耶利米书', 24, 25, 13, 'わたしは、この地の上にわたしが語ったすべてのことばを実現させる。それは、エレミヤが万国について預言したことで、この書に記されているすべての事柄である。'),
('JPN', '耶利米书', 24, 25, 14, '多くの国々と大王たちは彼らを奴隷にして使い、わたしも彼らに、その行いに応じ、その手のわざに応じて報いる。』」'),
('JPN', '耶利米书', 24, 25, 15, 'まことにイスラエルの神、主は、私にこう言われた。「この憤りのぶどう酒の杯をわたしの手から取り、わたしがあなたを遣わすすべての国々に、これを飲ませよ。'),
('JPN', '耶利米书', 24, 25, 16, '彼らは飲んで、ふらつき、狂ったようになる。わたしが彼らの間に送る剣のゆえである。」'),
('JPN', '耶利米书', 24, 25, 17, 'そこで、私は主の御手からその杯を受け取り、主が私を遣わされたすべての国々の民に飲ませた。'),
('JPN', '耶利米书', 24, 25, 18, 'まず、エルサレムとユダの町々とその王たち、高官たちに。彼らを今日のように廃墟とし、恐怖のもと、嘲りとののしりの的とするためである。'),
('JPN', '耶利米书', 24, 25, 19, 'また、エジプトの王ファラオと、その家来たち、首長たち、そのすべての民、'),
('JPN', '耶利米书', 24, 25, 20, 'すべての混血の民、ウツの地のすべての王たち、ペリシテ人の地のすべての王たち、すなわちアシュケロン、ガザ、エクロン、アシュドデの残りの者たち、'),
('JPN', '耶利米书', 24, 25, 21, 'エドム、モアブ、アンモン人、'),
('JPN', '耶利米书', 24, 25, 22, 'ツロのすべての王たち、シドンのすべての王たち、海のかなたにある島の王たち、'),
('JPN', '耶利米书', 24, 25, 23, 'デダン、テマ、ブズ、もみ上げを刈り上げているすべての者たち、'),
('JPN', '耶利米书', 24, 25, 24, 'アラビアのすべての王たち、荒野に住む混血の民のすべての王たち、'),
('JPN', '耶利米书', 24, 25, 25, 'ジムリのすべての王たち、エラムのすべての王たち、メディアのすべての王たち、'),
('JPN', '耶利米书', 24, 25, 26, '北国のすべての王たち、近い者も遠い者も一人ひとり、地の面のすべての王国である。そして、彼らの後でバビロンの王が飲む。'),
('JPN', '耶利米书', 24, 25, 27, '「あなたは彼らに言え。『イスラエルの神、万軍の主はこう言われる。わたしがあなたがたの間に送る剣のゆえに、飲め、酔え、吐け。倒れて起き上がるな。』'),
('JPN', '耶利米书', 24, 25, 28, 'もし、彼らが、あなたの手からその杯を取って飲むことを拒むなら、彼らに言え。『万軍の主はこう言われる。あなたがたは必ず飲むことになる。'),
('JPN', '耶利米书', 24, 25, 29, '見よ。わたしの名がつけられているこの都に対して、わたしはわざわいを下し始めているからだ。あなたがたは罰を免れようとするのか。免れることはできない。わたしがこの地の全住民の上に、剣を呼び寄せているからだ──万軍の主のことば。』'),
('JPN', '耶利米书', 24, 25, 30, 'あなたは彼らにこのすべてのことばを預言して言え。『主は高い所からほえ、聖なる御住まいから声をあげられる。その牧場に向かって猛々しくほえ、ぶどう踏みをする者のように、地の全住民に向かって叫び声をあげられる。'),
('JPN', '耶利米书', 24, 25, 31, 'その叫び声は地の果てまでも響き渡る。主が諸国の民と争い、すべての肉なる者をさばき、悪者どもを剣に渡されるからだ。──主のことば──'),
('JPN', '耶利米书', 24, 25, 32, '万軍の主はこう言われる。見よ。わざわいが国から国へと移り行き、大いなる暴風が地の果てから起こる。'),
('JPN', '耶利米书', 24, 25, 33, 'その日、主に殺される者が地の果てから地の果てまでに及び、彼らは悼み悲しまれることなく、集められることなく、葬られることもなく、地の面の肥やしとなる。』」'),
('JPN', '耶利米书', 24, 25, 34, '牧者たちよ、泣き叫べ。群れの飼い主たちよ、灰の中を転げ回れ。あなたがたが屠られ、散らされる日が来たからだ。あなたがたは、尊い器が砕かれるように倒れる。'),
('JPN', '耶利米书', 24, 25, 35, '逃げ場は牧者たちのうちから消え失せる。逃れ場は、群れの飼い主たちのうちから。'),
('JPN', '耶利米书', 24, 25, 36, '牧者たちの叫ぶ声がする。群れの飼い主たちの泣き声が。主が彼らの牧場を荒らしておられるからだ。'),
('JPN', '耶利米书', 24, 25, 37, '平和な牧場も、主の燃える怒りによって荒れすたれる。'),
('JPN', '耶利米书', 24, 25, 38, '主は若獅子のように仮庵を捨てた。虐げる者の怒り、主の燃える怒りによって、彼らの国が荒れ果てるからだ。'),
('JPN', '耶利米书', 24, 26, 1, 'ユダの王、ヨシヤの子エホヤキムの治世の初めに、主から次のようなことばがあった。'),
('JPN', '耶利米书', 24, 26, 2, '主はこう言われた。「主の宮の庭に立ち、主の宮に礼拝しに来るユダのすべての町の者に、わたしがあなたに語れと命じたことばを残らず語れ。一言も省くな。'),
('JPN', '耶利米书', 24, 26, 3, '彼らがそれを聞いて、それぞれ悪の道から立ち返るかもしれない。そうすればわたしは、彼らの悪い行いのために彼らに下そうと考えていたわざわいを思い直す。'),
('JPN', '耶利米书', 24, 26, 4, '彼らに言え。『主はこう言われる。もし、あなたがたがわたしに聞き従わず、あなたがたの前に置いたわたしの律法に歩まず、'),
('JPN', '耶利米书', 24, 26, 5, 'あなたがたに早くからたびたび遣わしてきた、わたしのしもべである預言者たちのことばに聞き従わないなら──実際、あなたがたは聞き従わなかった──'),
('JPN', '耶利米书', 24, 26, 6, 'わたしはこの宮をシロのようにし、この都を地上のすべての国々の、ののしりの的とする。』」'),
('JPN', '耶利米书', 24, 26, 7, '祭司と預言者と民全体は、エレミヤがこのことばを主の宮で語るのを聞いた。'),
('JPN', '耶利米书', 24, 26, 8, '主が民全体に語れと命じたことをみな、エレミヤが語り終えたとき、祭司と預言者とすべての民は彼を捕らえて言った。「あなたは必ず死ななければならない。'),
('JPN', '耶利米书', 24, 26, 9, 'なぜ、この宮がシロのようになり、この都がだれも住む者のいない廃墟となると、主の名によって預言したのか。」そこで、民全体は主の宮のエレミヤのところに集まった。'),
('JPN', '耶利米书', 24, 26, 10, 'これらのことを聞いてユダの首長たちは、王の宮殿から主の宮に上り、主の宮の新しい門の入り口で座に着いた。'),
('JPN', '耶利米书', 24, 26, 11, '祭司たちと預言者たちは、首長たちと民全体に次のように言った。「この者は死刑に当たる。彼がこの都に対して、あなたがたが自分の耳で聞いたとおりの預言をしたからだ。」'),
('JPN', '耶利米书', 24, 26, 12, 'エレミヤは、すべての首長と民に告げた。「主が、この神殿とこの都に対して、あなたがたの聞いたすべてのことばを預言するよう、私を遣わされたのです。'),
('JPN', '耶利米书', 24, 26, 13, 'さあ今、あなたがたの生き方と行いを改め、あなたがたの神、主の御声に聞き従いなさい。そうすれば、主も、あなたがたに語ったわざわいを思い直されます。'),
('JPN', '耶利米书', 24, 26, 14, 'このとおり、私自身はあなたがたの手の中にあります。私を、あなたがたの目に良いと思うよう、気に入るようにしなさい。'),
('JPN', '耶利米书', 24, 26, 15, 'ただ、もしあなたがたが私を殺すなら、あなたがた自身が咎なき者の血の責任を、自分たちと、この都と、その住民に及ぼすのだということを、はっきり知っておきなさい。なぜなら、本当に主が私をあなたがたのもとに送り、これらすべてのことばをあなたがたの耳に語らせたのですから。」'),
('JPN', '耶利米书', 24, 26, 16, 'すると、首長たちと民全体は、祭司たちと預言者たちに言った。「この人は死刑に当たらない。彼は私たちの神、主の名によって、私たちに語ったのだから。」'),
('JPN', '耶利米书', 24, 26, 17, 'それで、この地の長老たちの何人かが立って、民全体に言った。'),
('JPN', '耶利米书', 24, 26, 18, '「かつてモレシェテ人ミカも、ユダの王ヒゼキヤの時代に預言して、ユダの民全体にこう語ったことがある。万軍の主はこう言われる。シオンは畑のように耕され、エルサレムは瓦礫の山となり、神殿の山は木々におおわれた丘となる。'),
('JPN', '耶利米书', 24, 26, 19, 'そのとき、ユダの王ヒゼキヤとユダのすべては彼を殺しただろうか。ヒゼキヤが主を恐れ、主に願ったので、主も彼らに語ったわざわいを思い直されたではないか。ところが、私たちはわが身に大きなわざわいを招こうとしている。」'),
('JPN', '耶利米书', 24, 26, 20, '主の御名によって預言している人がもう一人いた。キルヤテ・エアリム出身のシェマヤの子ウリヤで、彼はこの都とこの地に対して、エレミヤのことばすべてと同じような預言をしていた。'),
('JPN', '耶利米书', 24, 26, 21, 'エホヤキム王、すべての勇士、首長たちは、彼のことばを聞いた。王は彼を殺そうとしたが、ウリヤはこれを聞いて恐れ、エジプトへ逃げて行った。'),
('JPN', '耶利米书', 24, 26, 22, 'そこで、エホヤキム王は人々をエジプトに遣わした。すなわち、アクボルの子エルナタンに人々を随行させて、エジプトに送った。'),
('JPN', '耶利米书', 24, 26, 23, '彼らはウリヤをエジプトから導き出し、エホヤキム王のところに連れて来たので、王は彼を剣で打ち殺し、その屍を共同墓地に捨てさせた。'),
('JPN', '耶利米书', 24, 26, 24, 'しかし、シャファンの子アヒカムはエレミヤをかばい、エレミヤが民の手に渡されて殺されることのないようにした。'),
('JPN', '耶利米书', 24, 27, 1, 'ユダの王、ヨシヤの子のエホヤキムの治世の初めに、主からエレミヤに次のようなことばがあった。'),
('JPN', '耶利米书', 24, 27, 2, '主は私にこう言われた。「あなたは縄とかせを作り、それをあなたの首に付けよ。'),
('JPN', '耶利米书', 24, 27, 3, 'そうして、エルサレムのユダの王ゼデキヤのところに来る使者たちによって、エドムの王、モアブの王、アンモン人の王、ツロの王、シドンの王に伝言を送り、'),
('JPN', '耶利米书', 24, 27, 4, '彼らがそれぞれの主君に次のことを言うように命じよ。『イスラエルの神、万軍の主はこう言われる。あなたがたは主君にこう言え。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '耶利米书', 24, 27, 5, 'わたしは、大いなる力と伸ばした腕をもって、地と、地の面にいる人と獣を造った。わたしは、わたしの目にかなった者に、この地を与える。'),
('JPN', '耶利米书', 24, 27, 6, '今わたしは、これらすべての地域をわたしのしもべ、バビロンの王ネブカドネツァルの手に与え、野の生き物も彼に与えて彼に仕えさせる。'),
('JPN', '耶利米书', 24, 27, 7, '彼の地に時が来るまで、すべての国は、彼とその子と、その子の子に仕える。しかしその後で、多くの民や大王たちが彼を自分たちの奴隷にする。'),
('JPN', '耶利米书', 24, 27, 8, 'バビロンの王ネブカドネツァルに仕えず、またバビロンの王のくびきに首を差し出さない国や王国があれば、わたしは剣と飢饉と疫病をもってその民を罰し──主のことば──彼の手で彼らを皆殺しにする。'),
('JPN', '耶利米书', 24, 27, 9, 'だから、あなたがたは、バビロンの王に仕えることはないと言っているあなたがたの預言者、占い師、夢見る者、卜者、呪術者に聞き従ってはならない。'),
('JPN', '耶利米书', 24, 27, 10, '彼らは、あなたがたに偽りを預言しているからだ。それで、あなたがたは自分たちの土地から遠くに移され、わたしはあなたがたを追い散らして、あなたがたは滅びることになる。'),
('JPN', '耶利米书', 24, 27, 11, 'しかし、バビロンの王のくびきに首を差し出して彼に仕える国を、わたしはその土地にとどまらせる──主のことば──。こうして、人々はその土地を耕し、そこに住む。』」'),
('JPN', '耶利米书', 24, 27, 12, 'ユダの王ゼデキヤにも、私はこのことばのとおりに言った。「あなたがたはバビロンの王のくびきに首を差し出し、彼とその民に仕えて生きよ。'),
('JPN', '耶利米书', 24, 27, 13, 'なぜ、あなたとあなたの民は、主がバビロンの王に仕えない国に向かって語られたように、剣と飢饉と疫病で死のうとするのか。'),
('JPN', '耶利米书', 24, 27, 14, '『バビロンの王に仕えることはない』とあなたがたに語る預言者たちのことばに聞き従ってはならない。彼らがあなたがたに偽りを預言しているからだ。」'),
('JPN', '耶利米书', 24, 27, 15, '「わたしは彼らを遣わさなかったのに──主のことば──彼らはわたしの名によって偽りを預言している。わたしがあなたがたを追い散らし、あなたがたも、あなたがたに預言している預言者たちも、滅びることになるのだ。」'),
('JPN', '耶利米书', 24, 27, 16, '私はまた、祭司たちとこの民全体に向かって語った。「主はこう言われる。あなたがたは、『見よ、主の宮の器は、バビロンから今すぐにも戻される』とあなたがたに預言している、あなたがたの預言者のことばに聞き従ってはならない。彼らはあなたがたに偽りを預言しているのだ。'),
('JPN', '耶利米书', 24, 27, 17, '彼らに聞き従ってはならない。バビロンの王に仕えて生きよ。どうして、この都が廃墟になってよいであろうか。'),
('JPN', '耶利米书', 24, 27, 18, 'もし彼らが預言者であるなら、もし彼らに主のことばがあるなら、彼らは、主の宮、ユダの王の宮殿、またエルサレムに残されている器がバビロンに持って行かれないよう、万軍の主にとりなしをするはずだ。'),
('JPN', '耶利米书', 24, 27, 19, 'まことに万軍の主は、神殿の柱、『海』、車輪付きの台、また、この都に残されているほかの器について、こう言われる。'),
('JPN', '耶利米书', 24, 27, 20, '──これらの物は、バビロンの王ネブカドネツァルがユダの王、エホヤキムの子エコンヤ、およびユダとエルサレムのすべてのおもだった人々をエルサレムからバビロンへ引いて行ったときに、奪い取らなかったものである──'),
('JPN', '耶利米书', 24, 27, 21, 'まことに、イスラエルの神、万軍の主は、主の宮とユダの王の宮殿とエルサレムに残された器について、こう言われる。'),
('JPN', '耶利米书', 24, 27, 22, '『それらはバビロンに運ばれて、わたしがそれを顧みる日まで、そこにある──主のことば──。そしてわたしはそれらを携え上り、この場所に戻す。』」'),
('JPN', '耶利米书', 24, 28, 1, 'その同じ年、ユダの王ゼデキヤの治世の初め、第四年の第五の月に、ギブオン出身の預言者、アズルの子ハナンヤが、主の宮で、祭司たちと民全体の前で、私に語って言った。'),
('JPN', '耶利米书', 24, 28, 2, '「イスラエルの神、万軍の主はこう言われる。わたしは、バビロンの王のくびきを砕く。'),
('JPN', '耶利米书', 24, 28, 3, '二年のうちに、わたしは、バビロンの王ネブカドネツァルがこの場所から奪い取ってバビロンに運んだ主の宮のすべての器をこの場所に戻す。'),
('JPN', '耶利米书', 24, 28, 4, 'バビロンに行ったユダの王、エホヤキムの子エコンヤと、ユダのすべての捕囚の民も、わたしはこの場所に帰らせる──主のことば──。わたしがバビロンの王のくびきを砕くからだ。」'),
('JPN', '耶利米书', 24, 28, 5, 'そこで預言者エレミヤは、主の宮に立っている祭司たちや民全体の前で、預言者ハナンヤに言った。'),
('JPN', '耶利米书', 24, 28, 6, '預言者エレミヤは言った。「アーメン。そのとおりに主がしてくださるように。あなたが預言したことばを主が成就させ、主の宮の器と、すべての捕囚の民をバビロンからこの場所に戻してくださるように。'),
('JPN', '耶利米书', 24, 28, 7, 'しかし、私があなたの耳と、すべての民の耳に語ろうとするこのことばを聞きなさい。'),
('JPN', '耶利米书', 24, 28, 8, '昔から、私と、あなたの先に出た預言者たちは、多くの地域と大きな王国について、戦いとわざわいと疫病を預言した。'),
('JPN', '耶利米书', 24, 28, 9, '平安を預言する預言者については、その預言者のことばが成就して初めて、本当に主が遣わされた預言者だ、と知られるのだ。」'),
('JPN', '耶利米书', 24, 28, 10, 'しかし預言者ハナンヤは、預言者エレミヤの首から例のかせを取り、それを砕いた。'),
('JPN', '耶利米书', 24, 28, 11, 'そしてハナンヤは、民全体の前でこう言った。「主はこう言われる。このとおり、わたしは二年のうちに、バビロンの王ネブカドネツァルのくびきを、すべての国々の首から砕く。」そこで、預言者エレミヤは立ち去った。'),
('JPN', '耶利米书', 24, 28, 12, '預言者ハナンヤが預言者エレミヤの首からかせを取って砕いた後、エレミヤに次のような主のことばがあった。'),
('JPN', '耶利米书', 24, 28, 13, '「行って、ハナンヤに次のように言え。『主はこう言われる。あなたは木のかせを砕いたが、その代わりに、鉄のかせを作ることになる。'),
('JPN', '耶利米书', 24, 28, 14, 'まことに、イスラエルの神、万軍の主はこう言われる。わたしは鉄のくびきをこれらすべての国の首にはめて、バビロンの王ネブカドネツァルに仕えさせる。彼らは彼に仕える。野の生き物まで、わたしは彼に与えた。』」'),
('JPN', '耶利米书', 24, 28, 15, 'そこで預言者エレミヤは、預言者ハナンヤに言った。「ハナンヤ、聞きなさい。主はあなたを遣わされていない。あなたはこの民を偽りに拠り頼ませた。'),
('JPN', '耶利米书', 24, 28, 16, 'それゆえ、主はこう言われる。見よ、わたしはあなたを地の面から追い出す。今年、あなたは死ぬ。主への反逆をそそのかしたからだ。」'),
('JPN', '耶利米书', 24, 28, 17, '預言者ハナンヤは、その年の第七の月に死んだ。'),
('JPN', '耶利米书', 24, 29, 1, '預言者エレミヤは、ネブカドネツァルがエルサレムからバビロンへ引いて行った捕囚の民、すなわち、長老で生き残っている者たち、祭司たち、預言者たち、および民全体に、エルサレムから次のような手紙を送った。'),
('JPN', '耶利米书', 24, 29, 2, 'この手紙は、エコンヤ王、王母、宦官たち、ユダとエルサレムの首長たち、職人、鍛冶がエルサレムを去った後、'),
('JPN', '耶利米书', 24, 29, 3, 'ユダの王ゼデキヤが、バビロンの王ネブカドネツァルのもと、バビロンへ遣わした、シャファンの子エルアサとヒルキヤの子ゲマルヤの手に託したもので、そのことばは次のとおりである。'),
('JPN', '耶利米书', 24, 29, 4, '「イスラエルの神、万軍の主はこう言われる。『エルサレムからバビロンへわたしが引いて行かせたすべての捕囚の民に。'),
('JPN', '耶利米书', 24, 29, 5, '家を建てて住み、果樹園を造って、その実を食べよ。'),
('JPN', '耶利米书', 24, 29, 6, '妻を迎えて、息子、娘を生み、あなたがたの息子には妻を迎え、娘を嫁がせて、息子、娘を産ませ、そこで増えよ。減ってはならない。'),
('JPN', '耶利米书', 24, 29, 7, 'わたしがあなたがたを引いて行かせた、その町の平安を求め、その町のために主に祈れ。その町の平安によって、あなたがたは平安を得ることになるのだから。』'),
('JPN', '耶利米书', 24, 29, 8, 'まことに、イスラエルの神、万軍の主はこう言われる。『あなたがたのうちにいる預言者たちや、占い師たちにごまかされるな。また、あなたがたが見ている夢に聞き従ってはならない。'),
('JPN', '耶利米书', 24, 29, 9, 'なぜなら、彼らはわたしの名を使って、偽りをあなたがたに預言しているからだ。わたしは彼らを遣わしていない──主のことば。』'),
('JPN', '耶利米书', 24, 29, 10, 'まことに、主はこう言われる。『バビロンに七十年が満ちるころ、わたしはあなたがたを顧み、あなたがたにいつくしみの約束を果たして、あなたがたをこの場所に帰らせる。'),
('JPN', '耶利米书', 24, 29, 11, 'わたし自身、あなたがたのために立てている計画をよく知っている──主のことば──。それはわざわいではなく平安を与える計画であり、あなたがたに将来と希望を与えるためのものだ。'),
('JPN', '耶利米书', 24, 29, 12, 'あなたがたがわたしに呼びかけ、来て、わたしに祈るなら、わたしはあなたがたに耳を傾ける。'),
('JPN', '耶利米书', 24, 29, 13, 'あなたがたがわたしを捜し求めるとき、心を尽くしてわたしを求めるなら、わたしを見つける。'),
('JPN', '耶利米书', 24, 29, 14, 'わたしはあなたがたに見出される──主のことば──。わたしは、あなたがたを元どおりにする。あなたがたを追い散らした先のあらゆる国々とあらゆる場所から、あなたがたを集める──主のことば──。わたしはあなたがたを、引いて行った先から元の場所へ帰らせる。』'),
('JPN', '耶利米书', 24, 29, 15, 'あなたがたは、『主はバビロンで、私たちのために預言者を起こされた』と言っていた。'),
('JPN', '耶利米书', 24, 29, 16, 'まことに、主はこう言われる。ダビデの王座に着いている王と、この都に住んでいるすべての人々と、捕囚としてあなたがたとともに出て行かなかったあなたがたの同胞について、'),
('JPN', '耶利米书', 24, 29, 17, '万軍の主はこう言われる。『見よ。わたしは彼らの中に剣と飢饉と疫病を送り、彼らを悪くて食べられない腐ったいちじくのようにする。'),
('JPN', '耶利米书', 24, 29, 18, 'わたしは剣と飢饉と疫病で彼らを追い、彼らを地のすべての王国にとっておののきのもととし、わたしが彼らを追い散らした先のすべての国々で、のろいと恐怖のもと、嘲りとそしりの的とする。'),
('JPN', '耶利米书', 24, 29, 19, '彼らがわたしのことばを聞かなかったからだ──主のことば──。わたしは彼らに、わたしのしもべである預言者たちを早くからたびたび遣わしたのに、あなたがたは聞かなかったのだ──主のことば。』'),
('JPN', '耶利米书', 24, 29, 20, '私がエルサレムからバビロンへ送ったすべての捕囚の民よ、主のことばを聞け。'),
('JPN', '耶利米书', 24, 29, 21, '『イスラエルの神、万軍の主は、わたしの名によってあなたがたに偽りを預言している、コラヤの子アハブと、マアセヤの子ゼデキヤについてこう言う。見よ。わたしはこの者たちを、バビロンの王ネブカドネツァルの手に渡す。王は、あなたがたの目の前で二人を打ち殺す。'),
('JPN', '耶利米书', 24, 29, 22, 'バビロンにいるユダの捕囚の民はみな、彼らのゆえに、次のようなのろいのことばを唱える。主がおまえを、バビロンの王が火で焼いたゼデキヤとアハブのようにされるように。'),
('JPN', '耶利米书', 24, 29, 23, 'それは、二人がイスラエルの中で恥辱となることを行い、隣人の妻たちと姦淫し、わたしが命じもしなかった偽りのことばをわたしの名によって語ったからだ。わたしはそれを知っており、その証人である──主のことば。』」'),
('JPN', '耶利米书', 24, 29, 24, '「あなたはネヘラム人シェマヤに対して、次のように言わなければならない。'),
('JPN', '耶利米书', 24, 29, 25, 'イスラエルの神、万軍の主は言われる。あなたは、あなたの名によって、エルサレムにいる民全体と、マアセヤの子祭司ゼパニヤ、および、すべての祭司に次のような手紙を送った。'),
('JPN', '耶利米书', 24, 29, 26, '『主は、祭司エホヤダの代わりに、あなたを祭司とされましたが、それは、あなたを主の宮の監督者に任じて、すべて気がふれて預言をする者に対処し、そういう者に足かせや首かせをはめるためでした。'),
('JPN', '耶利米书', 24, 29, 27, 'それなのに、なぜ、今あなたは、あなたがたに預言しているアナトテ人エレミヤを責めないのですか。'),
('JPN', '耶利米书', 24, 29, 28, 'というのは、彼はバビロンの私たちのところに使いをよこして、捕囚は長く続くので、家を建てて住み、園を造ってその実を食べよ、と言ったからです。』」'),
('JPN', '耶利米书', 24, 29, 29, 'この手紙を、祭司ゼパニヤは預言者エレミヤに読んで聞かせたのだった。'),
('JPN', '耶利米书', 24, 29, 30, 'そのとき、次のような主のことばがエレミヤにあった。'),
('JPN', '耶利米书', 24, 29, 31, '「すべての捕囚の民に言い送れ。『主はネヘラム人シェマヤについてこう言われる。わたしはシェマヤを遣わさなかったのに、シェマヤはあなたがたに預言し、あなたがたを偽りに拠り頼ませた。'),
('JPN', '耶利米书', 24, 29, 32, 'それゆえ──主はこう言われる──見よ。わたしはネヘラム人シェマヤとその子孫を罰する。彼に属する者で、この民の中に住んで、わたしがわたしの民に行おうとしている良いことを見る者は、だれもいない──主のことば──。彼が主への反逆をそそのかしたからである。』」'),
('JPN', '耶利米书', 24, 30, 1, '主からエレミヤにあったことばは、次のとおりである。'),
('JPN', '耶利米书', 24, 30, 2, 'イスラエルの神、主はこう言われる。「わたしがあなたに語ったことばをみな、書物に書き記せ。'),
('JPN', '耶利米书', 24, 30, 3, '見よ、その時代が来る──主のことば──。そのとき、わたしはわたしの民イスラエルとユダを回復させる──主は言われる──。わたしは彼らを、その父祖に与えた地に帰らせる。彼らはそれを所有する。」'),
('JPN', '耶利米书', 24, 30, 4, '主がイスラエルとユダについて語られたことばは次のとおりである。'),
('JPN', '耶利米书', 24, 30, 5, 'まことに主はこう言われる。「恐れてわななく声を、われわれは聞いた。『恐怖だ。平安がない』と。'),
('JPN', '耶利米书', 24, 30, 6, 'さあ、男に子が産めるか、尋ねてみよ。なぜ、わたしは勇士がみな産婦のように腰に手を当てているのを見るのか。また、どの顔も青ざめているのを。'),
('JPN', '耶利米书', 24, 30, 7, 'わざわいだ。実にその日は大いなる日、比べようもない日。それはヤコブには苦難の時。だが、彼はそこから救われる。'),
('JPN', '耶利米书', 24, 30, 8, 'その日になると──万軍の主のことば──わたしはあなたの首のくびきを砕き、あなたのかせを解く。他国人が再び彼を奴隷にすることはない。'),
('JPN', '耶利米书', 24, 30, 9, '彼らは彼らの神、主と、わたしが彼らのために立てる彼らの王ダビデに仕える。'),
('JPN', '耶利米书', 24, 30, 10, 'わたしのしもべヤコブよ、恐れるな。──主のことば──イスラエルよ、おののくな。見よ。わたしが、あなたを遠くから、あなたの子孫を捕囚の地から救うからだ。ヤコブは帰って来て、平穏に安らかに生き、脅かす者はだれもいない。'),
('JPN', '耶利米书', 24, 30, 11, 'わたしがあなたとともにいて、──主のことば──あなたを救うからだ。わたしが、あなたを追いやった先のすべての国々を滅ぼし尽くすからだ。しかし、あなたを滅ぼし尽くすことはない。ただし、さばきによってあなたを懲らしめる。決してあなたを罰せずにおくことはない。」'),
('JPN', '耶利米书', 24, 30, 12, 'まことに主はこう言われる。「あなたの傷は癒やされがたく、あなたの打ち傷は痛んでいる。'),
('JPN', '耶利米书', 24, 30, 13, 'あなたの訴えを擁護する者もなく、腫れものに薬を付けて、あなたを癒やす者もいない。'),
('JPN', '耶利米书', 24, 30, 14, 'あなたの恋人たちはみな、あなたを忘れ、あなたを尋ねようともしない。わたしが、敵を打つようにあなたを打ち、容赦なくあなたを懲らしめたからだ。あなたの咎が大きく、あなたの罪が重いために。'),
('JPN', '耶利米书', 24, 30, 15, 'なぜ、あなたは自分の傷のために叫ぶのか。あなたの痛みは癒やされがたい。あなたの咎が大きく、あなたの罪が重いために、わたしはこれらのことを、あなたにしたのだ。'),
('JPN', '耶利米书', 24, 30, 16, 'それゆえ、わたしは言う。あなたを食う者はみな、かえって食われ、あなたの敵はみな、捕らわれの身となって行き、あなたから略奪した者は、略奪され、あなたをかすめ奪った者は、わたしがみな獲物として与える。'),
('JPN', '耶利米书', 24, 30, 17, 'まことに、わたしはあなたの傷を治し、あなたの打ち傷を癒やす。──主のことば──まことに、あなたは『捨てられた女』、『尋ねる者のないシオン』と呼ばれた。'),
('JPN', '耶利米书', 24, 30, 18, '──主はこう言われる──見よ。わたしはヤコブの天幕を回復させ、その住まいをあわれむ。都はその丘の上に建て直され、宮殿はその定められている場所に建つ。'),
('JPN', '耶利米书', 24, 30, 19, '彼らから、感謝の歌と、喜び笑う声が湧き上がる。わたしは人を増やして、減らすことはない。わたしが尊く扱うので、彼らは小さな者ではなくなる。'),
('JPN', '耶利米书', 24, 30, 20, 'その子たちは昔のようになり、その会衆はわたしの前で堅く立てられる。わたしはこれを圧迫する者をみな罰する。'),
('JPN', '耶利米书', 24, 30, 21, 'その権力者は彼らのうちの一人、その支配者はその中から出る。わたしは彼を近づけ、彼はわたしに近づく。いのちをかけてわたしに近づく者は、いったいだれか。──主のことば──'),
('JPN', '耶利米书', 24, 30, 22, 'あなたがたはわたしの民となり、わたしはあなたがたの神となる。」'),
('JPN', '耶利米书', 24, 30, 23, '見よ。主のつむじ風が憤りとなって出て行く。渦巻く暴風が悪者の頭上に荒れ狂う。'),
('JPN', '耶利米书', 24, 30, 24, '主の燃える怒りは、去ることはない。主が心の思うところを行って、成し遂げるまでは。終わりの日に、あなたがたはそれを悟る。'),
('JPN', '耶利米书', 24, 31, 1, '「そのとき──主のことば──わたしはイスラエルのすべての部族の神となり、彼らはわたしの民となる。」'),
('JPN', '耶利米书', 24, 31, 2, '主はこう言われる。「剣を免れて生き残った民は荒野で恵みを見出す。イスラエルよ、出て行って休みを得よ。」'),
('JPN', '耶利米书', 24, 31, 3, '主は遠くから私に現れた。「永遠の愛をもって、わたしはあなたを愛した。それゆえ、わたしはあなたに真実の愛を尽くし続けた。'),
('JPN', '耶利米书', 24, 31, 4, 'おとめイスラエルよ。再びわたしはあなたを建て直し、あなたは建て直される。再びあなたはタンバリンで身を飾り、喜び踊る者たちの輪に入る。'),
('JPN', '耶利米书', 24, 31, 5, '再びあなたはサマリアの山々にぶどう畑を作り、植える者たちは植え、その初物を味わう。'),
('JPN', '耶利米书', 24, 31, 6, 'エフライムの山で、見張る者たちが『さあ、シオンに、私たちの神、主のもとに行こう』と呼びかける日が来るからだ。」'),
('JPN', '耶利米书', 24, 31, 7, 'まことに、主はこう言われる。「ヤコブのために喜び歌え。国々のかしらに向かって叫べ。告げ知らせよ、賛美して言え。『主よ、あなたの民を救ってください。イスラエルの残りの者を。』'),
('JPN', '耶利米书', 24, 31, 8, '見よ。わたしは彼らを北の国から連れ出し、地の果てから彼らを集める。その中には、目の見えない者も足の萎えた者も、身ごもった女も臨月を迎えた女も、ともにいる。彼らは大集団をなして、ここに帰る。'),
('JPN', '耶利米书', 24, 31, 9, '彼らは泣きながらやって来る。わたしは彼らを、慰めながら連れ戻る。わたしは彼らを、水の流れのほとりに、つまずくことのない平らな道に導く。まことに、わたしはイスラエルには父であり、エフライムはわたしの長子である。」'),
('JPN', '耶利米书', 24, 31, 10, '諸国の民よ、主のことばを聞け。遠くの島々に告げ知らせよ。「イスラエルを散らした方がこれを集め、牧者が群れを飼うように、これを守られる」と。'),
('JPN', '耶利米书', 24, 31, 11, '主はヤコブを贖い出し、ヤコブより強い者の手から、これを買い戻されたからだ。'),
('JPN', '耶利米书', 24, 31, 12, '彼らは来て、シオンの丘で喜び歌い、主が与える良きものに、穀物、新しいぶどう酒、オリーブ油、羊の子、牛の子に喜び輝く。彼らのたましいは潤った園のようになり、もう再び、しぼむことはない。'),
('JPN', '耶利米书', 24, 31, 13, 'そのとき、若い女は踊って楽しみ、若い男も年寄りも、ともに楽しむ。「わたしは彼らの悲しみを喜びに変え、彼らの憂いを慰め、楽しませる。'),
('JPN', '耶利米书', 24, 31, 14, '祭司のたましいを髄で潤す。わたしの民は、わたしの恵みに満ち足りる。──主のことば。」'),
('JPN', '耶利米书', 24, 31, 15, '主はこう言われる。「ラマで声が聞こえる。嘆きとむせび泣きが。ラケルが泣いている。その子らのゆえに。慰めを拒んでいる。その子らのゆえに。子らがもういないからだ。」'),
('JPN', '耶利米书', 24, 31, 16, '主はこう言われる。「あなたの泣く声、あなたの目の涙を止めよ。あなたの労苦には報いがあるからだ。──主のことば──彼らは敵の地から帰って来る。'),
('JPN', '耶利米书', 24, 31, 17, 'あなたの将来には望みがある。──主のことば──あなたの子らは自分の土地に帰って来る。'),
('JPN', '耶利米书', 24, 31, 18, 'わたしは、エフライムが悲しみ嘆くのを確かに聞いた。『あなたが私を懲らしめて、私は、くびきに慣れない子牛のように懲らしめを受けました。私を帰らせてください。そうすれば、帰ります。主よ、あなたは私の神だからです。'),
('JPN', '耶利米书', 24, 31, 19, '私は立ち去った後で悔い、悟った後で、ももを打ちました。恥を見て、辱めさえ受けました。若いころの恥辱を私は負っているのです』と。'),
('JPN', '耶利米书', 24, 31, 20, 'エフライムは、わたしの大切な子、喜びの子なのか。わたしは彼を責めるたびに、ますます彼のことを思い起こすようになる。それゆえ、わたしのはらわたは彼のためにわななき、わたしは彼をあわれまずにはいられない。──主のことば──'),
('JPN', '耶利米书', 24, 31, 21, 'あなたは自分のために標識を立てて道しるべを置き、あなたが歩んだ道の大路に心を留めよ。おとめイスラエルよ、帰れ。これらの、あなたの町に帰れ。'),
('JPN', '耶利米书', 24, 31, 22, '背信の娘よ、いつまで迷い歩くのか。主はこの地に、一つの新しいことを創造される。女の優しさが一人の勇士を包む。」'),
('JPN', '耶利米书', 24, 31, 23, 'イスラエルの神、万軍の主はこう言われる。「わたしが彼らを元どおりにするとき、彼らは再び次のことばを、ユダの地とその町々で語る。『義の住まい、聖なる山よ、主があなたを祝福されるように。』'),
('JPN', '耶利米书', 24, 31, 24, 'ユダとそのすべての町の者はそこに住み、農夫たちも、群れを連れて回る者たちも一緒に住む。'),
('JPN', '耶利米书', 24, 31, 25, 'わたしが疲れたたましいを潤し、すべてのしぼんだたましいを満ち足らせるからだ。」'),
('JPN', '耶利米书', 24, 31, 26, 'ここで、私は目覚めて、見回した。私の眠りは心地よかった。'),
('JPN', '耶利米书', 24, 31, 27, '「見よ、その時代が来る──主のことば──。そのとき、わたしはイスラエルの家とユダの家に、人の種と家畜の種を蒔く。'),
('JPN', '耶利米书', 24, 31, 28, 'かつてわたしが、引き抜き、打ち倒し、打ち壊し、滅ぼし、わざわいを下そうと彼らを見張っていたように、今度は、彼らを建て直し、また植えるために見張る──主のことば──。'),
('JPN', '耶利米书', 24, 31, 29, 'その日には、彼らはもはや、『父が酸いぶどうを食べると、子どもの歯が浮く』とは言わない。'),
('JPN', '耶利米书', 24, 31, 30, '人はそれぞれ自分の咎のゆえに死ぬ。だれでも、酸いぶどうを食べる者は歯が浮くのだ。'),
('JPN', '耶利米书', 24, 31, 31, '見よ、その時代が来る──主のことば──。そのとき、わたしはイスラエルの家およびユダの家と、新しい契約を結ぶ。'),
('JPN', '耶利米书', 24, 31, 32, 'その契約は、わたしが彼らの先祖の手を取って、エジプトの地から導き出した日に、彼らと結んだ契約のようではない。わたしは彼らの主であったのに、彼らはわたしの契約を破った──主のことば──。'),
('JPN', '耶利米书', 24, 31, 33, 'これらの日の後に、わたしがイスラエルの家と結ぶ契約はこうである──主のことば──。わたしは、わたしの律法を彼らのただ中に置き、彼らの心にこれを書き記す。わたしは彼らの神となり、彼らはわたしの民となる。'),
('JPN', '耶利米书', 24, 31, 34, '彼らはもはや、それぞれ隣人に、あるいはそれぞれ兄弟に、『主を知れ』と言って教えることはない。彼らがみな、身分の低い者から高い者まで、わたしを知るようになるからだ──主のことば──。わたしが彼らの不義を赦し、もはや彼らの罪を思い起こさないからだ。」'),
('JPN', '耶利米书', 24, 31, 35, '主はこう言われる。太陽を与えて昼間の光とし、月と星を定めて夜の光とし、海をかき立てて波を騒がせる方、その名が万軍の主である方が。'),
('JPN', '耶利米书', 24, 31, 36, '「もしも、これらの掟がわたしの前から去ることがあるなら──主のことば──イスラエルの子孫は絶えて、わたしの前にいつまでも一つの民であることはできない。」'),
('JPN', '耶利米书', 24, 31, 37, '主はこう言われる。「もしも、上の天が測られ、下の地の基が探り出されることがあるなら、わたしも、イスラエルのすべての子孫を、彼らの行ったすべてのことのゆえに退ける。──主のことば。」'),
('JPN', '耶利米书', 24, 31, 38, '「見よ、その時代が来る──主のことば──。そのとき、この都はハナンエルのやぐらから隅の門まで、主のために建て直される。'),
('JPN', '耶利米书', 24, 31, 39, '測り縄は、さらにそれからガレブの丘に伸び、ゴアの方に向かう。'),
('JPN', '耶利米书', 24, 31, 40, '死体と灰の谷の全体と、東の方ではキデロンの谷と馬の門の隅までの畑は、みな主の聖なるものとされ、もはやとこしえに、根こそぎにされず、壊されることはない。」'),
('JPN', '耶利米书', 24, 32, 1, 'ユダの王ゼデキヤの第十年、ネブカドネツァルの第十八年に、主からエレミヤにあったことば。'),
('JPN', '耶利米书', 24, 32, 2, 'そのとき、バビロンの王の軍勢がエルサレムを包囲中であって、預言者エレミヤは、ユダの王の宮殿にある監視の庭に監禁されていた。'),
('JPN', '耶利米书', 24, 32, 3, 'ユダの王ゼデキヤは、エレミヤを監禁するとき、次のように尋ねたのだった。「なぜ、あなたはこのように預言して言うのか。『主はこう言われる。見よ。わたしはこの都をバビロンの王の手に渡す。そして彼はこれを攻め取る。'),
('JPN', '耶利米书', 24, 32, 4, 'ユダの王ゼデキヤは、カルデア人の手から逃れることはできない。ゼデキヤは必ずバビロンの王の手に渡され、口と口で彼と語り、目と目で彼を見る。'),
('JPN', '耶利米书', 24, 32, 5, '彼はゼデキヤをバビロンへ連れて行く。そしてゼデキヤは、わたしが彼を顧みるときまでそこにいる──主のことば──。あなたがたはカルデア人と戦っても、勝つことはできない。』」'),
('JPN', '耶利米书', 24, 32, 6, 'エレミヤは言った。「私に、このような主のことばがあった。'),
('JPN', '耶利米书', 24, 32, 7, '『見よ。あなたのおじシャルムの子ハナムエルが、あなたのところに来て、「アナトテにある畑を買ってくれ。あなたには買い戻す権利があるのだから」と言う。』'),
('JPN', '耶利米书', 24, 32, 8, 'すると、主のことばのとおり、おじの子ハナムエルが私のところ、監視の庭に来て、私に言った。『どうか、ベニヤミンの地のアナトテにある私の畑を買ってください。あなたには所有権もあり、買い戻す権利もありますから、あなたが買い取ってください。』私は、これが主のことばであると知った。'),
('JPN', '耶利米书', 24, 32, 9, 'そこで私は、おじの子ハナムエルから、アナトテにある畑を買い取り、彼に銀十七シェケルを払った。'),
('JPN', '耶利米书', 24, 32, 10, '私は証書に署名して封印し、証人を立てて、秤で銀を量った。'),
('JPN', '耶利米书', 24, 32, 11, 'そして、命令と規則にしたがって、封印された購入証書と封印のない証書を取り、'),
('JPN', '耶利米书', 24, 32, 12, 'おじの子ハナムエルと、購入証書に署名した証人たちと、監視の庭に座しているすべてのユダの人々の前で、購入証書をマフセヤの子ネリヤの子バルクに渡し、'),
('JPN', '耶利米书', 24, 32, 13, '彼らの前でバルクに命じた。'),
('JPN', '耶利米书', 24, 32, 14, '『イスラエルの神、万軍の主はこう言われる。これらの証書、すなわち封印されたこの購入証書と、封印のない証書を取って土の器の中に入れ、これを長い間、保存せよ。'),
('JPN', '耶利米书', 24, 32, 15, 'なぜなら──イスラエルの神、万軍の主はこう言われる──再びこの地で、家や、畑や、ぶどう畑が買われるようになるからだ。』'),
('JPN', '耶利米书', 24, 32, 16, '私は、購入証書をネリヤの子バルクに渡した後、主に祈った。'),
('JPN', '耶利米书', 24, 32, 17, '『ああ、神、主よ、ご覧ください。あなたは大いなる力と、伸ばされた御腕をもって天と地を造られました。あなたにとって不可能なことは一つもありません。'),
('JPN', '耶利米书', 24, 32, 18, 'あなたは、恵みを千代にまで施し、父たちの咎をその後の子らの懐に報いる方、大いなる力強い神、その名は万軍の主。'),
('JPN', '耶利米书', 24, 32, 19, 'そのご計画は大きく、みわざには力があります。御目は人の子らのすべての行いに開いていて、それぞれにその生き方にしたがい、行いの結ぶ実にしたがって報いをされます。'),
('JPN', '耶利米书', 24, 32, 20, 'あなたはエジプトの地で、また今日までイスラエルと人々の間で、しるしと不思議を行い、ご自分の名を今日のようにされました。'),
('JPN', '耶利米书', 24, 32, 21, 'あなたはまた、しるしと不思議と、力強い御手と伸ばされた御腕と、大いなる恐れをもって、御民イスラエルをエジプトの地から導き出し、'),
('JPN', '耶利米书', 24, 32, 22, 'あなたが彼らの父祖たちに与えると誓ったこの地、乳と蜜の流れる地を彼らに与えられました。'),
('JPN', '耶利米书', 24, 32, 23, '彼らはそこに行って、それを所有しましたが、あなたの声に聞き従わず、あなたの律法に歩まず、あなたが彼らにせよと命じたことを何一つ行わなかったので、あなたは彼らを、このすべてのわざわいにあわせられました。'),
('JPN', '耶利米书', 24, 32, 24, 'ご覧ください。この都を攻め取ろうとして、塁が築かれました。この都は、剣と飢饉と疫病のために、攻めているカルデア人の手に渡されようとしています。あなたのお告げになったことは成就しました。ご覧のとおりです。'),
('JPN', '耶利米书', 24, 32, 25, '神、主よ。この都がカルデア人の手に渡されようとしているのに、あなたは私に、金を払ってあの畑を買い、証人を立てよ、と言われます。』」'),
('JPN', '耶利米书', 24, 32, 26, 'すると次のような主のことばがエレミヤにあった。'),
('JPN', '耶利米书', 24, 32, 27, '「見よ。わたしはすべての肉なる者の神、主である。わたしにとって不可能なことが一つでもあろうか。'),
('JPN', '耶利米书', 24, 32, 28, 'それゆえ──主はこう言われる──見よ。わたしはこの都を、カルデア人の手と、バビロンの王ネブカドネツァルの手に渡す。彼はこれを攻め取る。'),
('JPN', '耶利米书', 24, 32, 29, 'また、この都を攻めているカルデア人が来て、この都に火をつけて焼く。また、人々が屋上でバアルに犠牲を供え、ほかの神々に注ぎのぶどう酒を注いで、わたしの怒りを引き起こしたその家々にも火をつけて焼く。'),
('JPN', '耶利米书', 24, 32, 30, 'なぜなら、イスラエルの子らとユダの子らは、若いころから、わたしの目に悪であることを行うのみであったからだ。実に、イスラエルの子らは、その手のわざをもってわたしの怒りを引き起こすばかりであった──主のことば──。'),
('JPN', '耶利米书', 24, 32, 31, 'この都は、建てられた日から今日まで、わたしの怒りと憤りを引き起こしてきたので、わたしはこれをわたしの顔の前から取り除く。'),
('JPN', '耶利米书', 24, 32, 32, 'それは、イスラエルの子らとユダの子らが、すなわち、彼ら自身と、その王、首長、祭司、預言者、またユダの人、エルサレムの住民が、わたしの怒りを引き起こすために行った、すべての悪のゆえである。'),
('JPN', '耶利米书', 24, 32, 33, '彼らはわたしに背を向けて、顔を向けず、わたしがしきりに教えても聞かず、懲らしめを受け入れなかった。'),
('JPN', '耶利米书', 24, 32, 34, '彼らは、わたしの名がつけられている宮に忌まわしいものを置いて、これを汚し、'),
('JPN', '耶利米书', 24, 32, 35, 'ベン・ヒノムの谷にバアルの高き所を築き、自分の息子、娘たちに火の中を通らせてモレクに渡した。しかしわたしは、この忌み嫌うべきことを行わせてユダを罪に陥らせようなどと、命じたことも、心に思い浮かべたこともない。」'),
('JPN', '耶利米书', 24, 32, 36, 'それゆえ今、イスラエルの神、主は、あなたがたが、「剣と飢饉と疫病により、バビロンの王の手に渡される」と言っているこの都について、こう言われる。'),
('JPN', '耶利米书', 24, 32, 37, '「見よ。わたしは、かつてわたしが怒りと憤りと激怒をもって彼らを散らしたすべての国々から、彼らを集めてこの場所に帰らせ、安らかに住まわせる。'),
('JPN', '耶利米书', 24, 32, 38, '彼らはわたしの民となり、わたしは彼らの神となる。'),
('JPN', '耶利米书', 24, 32, 39, 'わたしは、彼らと彼らの後の子孫の幸せのために、わたしをいつも恐れるよう、彼らに一つの心と一つの道を与え、'),
('JPN', '耶利米书', 24, 32, 40, 'わたしが彼らから離れず、彼らを幸せにするために、彼らと永遠の契約を結ぶ。わたしは、彼らがわたしから去らないように、わたしへの恐れを彼らの心に与える。'),
('JPN', '耶利米书', 24, 32, 41, 'わたしは彼らをわたしの喜びとし、彼らを幸せにする。わたしは、真実をもって、心と思いを込めて、彼らをこの地に植える。」'),
('JPN', '耶利米书', 24, 32, 42, 'まことに、主はこう言われる。「わたしがこの大きなわざわいのすべてを、この民にもたらしたように、わたしは、今彼らに語っている幸せのすべてを彼らにもたらす。'),
('JPN', '耶利米书', 24, 32, 43, 'あなたがたが、『この地は荒れ果てて、人も家畜もいなくなり、カルデア人の手に渡される』と言っているこの地で、再び畑が買われる。'),
('JPN', '耶利米书', 24, 32, 44, 'ベニヤミンの地でも、エルサレムの近郊でも、ユダの町々でも、山地の町々でも、シェフェラの町々でも、ネゲブの町々でも、人々は金で畑を買い、証書に署名して封印し、証人を立てるようになる。わたしが彼らを元どおりにするからである──主のことば。」'),
('JPN', '耶利米书', 24, 33, 1, 'エレミヤがまだ監視の庭に閉じ込められていたとき、再びエレミヤに次のような主のことばがあった。'),
('JPN', '耶利米书', 24, 33, 2, '「地を造った主、それを形造って堅く立てた主、その名が主である方が言われる。'),
('JPN', '耶利米书', 24, 33, 3, '『わたしを呼べ。そうすれば、わたしはあなたに答え、あなたが知らない理解を超えた大いなることを、あなたに告げよう。』'),
('JPN', '耶利米书', 24, 33, 4, 'まことに、イスラエルの神である主は、敵の塁や剣に対抗するために取り壊された、この都の家々と、ユダの王たちの家々について、こう言われる。'),
('JPN', '耶利米书', 24, 33, 5, '『彼らはカルデア人と戦おうとして出て行くが、わたしの怒りと憤りによって打ち殺された屍をその家々に満たす。それは、彼らのすべての悪のゆえに、わたしがこの都から顔を隠したからだ。'),
('JPN', '耶利米书', 24, 33, 6, '見よ。わたしはこの都に回復と癒やしを与え、彼らを癒やす。そして彼らに平安と真実を豊かに示す。'),
('JPN', '耶利米书', 24, 33, 7, 'わたしはユダとイスラエルを回復させ、以前のように彼らを建て直す。'),
('JPN', '耶利米书', 24, 33, 8, 'わたしは、彼らがわたしに犯したすべての咎から彼らをきよめ、彼らがわたしに犯し、わたしに背いたすべての咎を赦す。'),
('JPN', '耶利米书', 24, 33, 9, 'この都は、地のすべての国々の間で、わたしにとって喜びの名となり、栄誉となり、栄えとなる。彼らは、わたしがこの民に与えるすべての祝福のことを聞き、わたしがこの都に与えるすべての祝福と平安のゆえに恐れ、震えることになる。』」'),
('JPN', '耶利米书', 24, 33, 10, '主はこう言われる。「あなたがたが、人も家畜もいない廃墟と言うこの場所で、人も住民も家畜もいない、荒れすたれたユダの町々とエルサレムの通りで、'),
('JPN', '耶利米书', 24, 33, 11, '楽しみの声と喜びの声、花婿の声と花嫁の声、主の宮に感謝のいけにえを携えて来る人たちの声が、再び聞かれるようになる。彼らは言う。『万軍の主に感謝せよ。主はまことにいつくしみ深い。その恵みはとこしえまで』と。わたしがこの地を回復させ、以前のようにするからだ──主は言われる。」'),
('JPN', '耶利米书', 24, 33, 12, '万軍の主はこう言われる。「人も家畜もいない廃墟であるこの場所と、そのすべての町に、群れを伏させる羊飼いたちの住まいが再びできる。'),
('JPN', '耶利米书', 24, 33, 13, '山地の町々でも、シェフェラの町々、ネゲブの町々、ベニヤミンの地、エルサレムの近郊、ユダの町々でも、群れが再び、数を数える者の手の下を通り過ぎる──主は言われる。」'),
('JPN', '耶利米书', 24, 33, 14, '「見よ、その時代が来る──主のことば──。そのとき、わたしはイスラエルの家とユダの家に語ったいつくしみの約束を果たす。'),
('JPN', '耶利米书', 24, 33, 15, 'その日、その時、わたしはダビデのために義の若枝を芽生えさせる。彼はこの地に公正と義を行う。'),
('JPN', '耶利米书', 24, 33, 16, 'その日、ユダは救われ、エルサレムは安らかに住み、こうしてこの都は『主は私たちの義』と名づけられる。」'),
('JPN', '耶利米书', 24, 33, 17, 'まことに主はこう言われる。「ダビデには、イスラエルの家の王座に就く者が断たれることはない。'),
('JPN', '耶利米书', 24, 33, 18, 'また、レビ人の祭司たちには、わたしの前で全焼のささげ物を献げ、穀物のささげ物を焼いて煙にし、いけにえを献げる者が、いつまでも絶えることはない。」'),
('JPN', '耶利米书', 24, 33, 19, 'エレミヤに次のような主のことばがあった。'),
('JPN', '耶利米书', 24, 33, 20, '主はこう言われる。「もしもあなたがたが、昼と結んだわたしの契約と、夜と結んだわたしの契約を破ることができ、昼と夜が、定まった時に来ないようにすることができるのであれば、'),
('JPN', '耶利米书', 24, 33, 21, 'わたしのしもべダビデと結んだわたしの契約も破られ、ダビデにはその王座に就く子がいなくなり、わたしに仕えるレビ人の祭司たちと結んだわたしの契約も破られる。'),
('JPN', '耶利米书', 24, 33, 22, '天の万象は数えきれず、海の砂は量れない。そのようにわたしは、わたしのしもべダビデの子孫と、わたしに仕えるレビ人を増やす。」'),
('JPN', '耶利米书', 24, 33, 23, 'エレミヤに次のような主のことばがあった。'),
('JPN', '耶利米书', 24, 33, 24, '「あなたはこの民が、『主は自分で選んだ二つの部族を退けた』と話しているのを知らないのか。彼らはわたしの民を侮っている。『自分たちの目には、もはや一つの国民ではないのだ』と。」'),
('JPN', '耶利米书', 24, 33, 25, '主はこう言われる。「もしも、わたしが昼と夜と契約を結ばず、天と地の諸法則をわたしが定めなかったのであれば、'),
('JPN', '耶利米书', 24, 33, 26, 'わたしは、ヤコブの子孫とわたしのしもべダビデの子孫を退け、その子孫の中から、アブラハム、イサク、ヤコブの子孫を治める者を選ぶということはない。しかし、わたしは彼らを回復させ、彼らをあわれむ。」'),
('JPN', '耶利米书', 24, 34, 1, 'バビロンの王ネブカドネツァルとその全軍勢、および彼の支配下にある地のすべての王国とすべての民族が、エルサレムとそのすべての町を攻めていたとき、主からエレミヤに次のようなことばがあった。'),
('JPN', '耶利米书', 24, 34, 2, '「イスラエルの神、主はこう言う。行って、ユダの王ゼデキヤに告げよ。『主はこう言われる。見よ、わたしはこの都をバビロンの王の手に渡す。彼はこれを火で焼く。'),
('JPN', '耶利米书', 24, 34, 3, 'あなたはその手から逃れることができない。あなたは必ず捕らえられて、彼の手に渡されるからだ。あなたの目はバビロンの王の目を見、彼の口はあなたの口と語り、あなたはバビロンへ行く。'),
('JPN', '耶利米书', 24, 34, 4, 'ただ、主のことばを聞け、ユダの王ゼデキヤよ。主はあなたについてこう言われる。あなたは剣で死ぬことはない。'),
('JPN', '耶利米书', 24, 34, 5, 'あなたは平安のうちに死ぬ。人々は、あなたの先祖たち、あなたの先にいた王たちのために埋葬の香をたいたように、あなたのためにも香をたき、ああ主君よ、と言ってあなたを悼む。このことを語るのはわたしだ──主のことば。』」'),
('JPN', '耶利米书', 24, 34, 6, 'そこで預言者エレミヤは、ユダの王ゼデキヤに、エルサレムでこれらすべてのことばを語った。'),
('JPN', '耶利米书', 24, 34, 7, 'そのとき、バビロンの王の軍勢は、エルサレムとユダの残されたすべての町、ラキシュとアゼカを攻めていた。これらが、ユダの町々で城壁のある町として残っていたからである。'),
('JPN', '耶利米书', 24, 34, 8, 'ゼデキヤ王がエルサレムにいる民全体と契約を結んで、彼らに奴隷の解放を宣言した後、主からエレミヤにあったことば。'),
('JPN', '耶利米书', 24, 34, 9, 'その契約は、各自が、ヘブル人である自分の奴隷や女奴隷を自由の身にし、同胞のユダヤ人を奴隷にしないというものであった。'),
('JPN', '耶利米书', 24, 34, 10, '契約に加わったすべての首長と民は、各自、自分の奴隷や女奴隷を自由の身にして、二度と彼らを奴隷にしないことに同意し、同意してから奴隷を去らせた。'),
('JPN', '耶利米书', 24, 34, 11, 'しかしその後で、彼らは心を翻した。そして、いったん自由の身にした奴隷や女奴隷を連れ戻し、強制的に彼らを奴隷や女奴隷の身分に服させた。'),
('JPN', '耶利米书', 24, 34, 12, 'すると、主からエレミヤに次のような主のことばがあった。'),
('JPN', '耶利米书', 24, 34, 13, '「イスラエルの神、主はこう言われる。『わたしが、あなたがたの先祖をエジプトの地、奴隷の家から導き出した日に、わたしは彼らと契約を結んで言った。'),
('JPN', '耶利米书', 24, 34, 14, '「七年の終わりには、各自、自分のところに売られて来た同胞のヘブル人を去らせなければならない。六年の間あなたに仕えさせ、その後あなたは彼を自由の身にせよ」と。しかし、あなたがたの先祖は、わたしに聞かず、耳を傾けもしなかった。'),
('JPN', '耶利米书', 24, 34, 15, 'ところが、あなたがたは今日、立ち返って、各自が隣人の解放を告げてわたしの目にかなうことを行い、わたしの名がつけられているこの家で、わたしの前に契約を結んだ。'),
('JPN', '耶利米书', 24, 34, 16, 'それなのに、あなたがたは心を翻して、わたしの名を汚した。あなたがたは、それぞれ、いったん彼らの望むとおりに自由の身にした奴隷や女奴隷を連れ戻し、強制的に彼らをあなたがたの奴隷や女奴隷の身分に服させた。』'),
('JPN', '耶利米书', 24, 34, 17, 'それゆえ、主はこう言われる。『あなたがたはわたしに聞き従わず、各自、自分の同胞や隣人に解放を告げなかったので、見よ、わたしはあなたがたに──主のことば──剣と疫病と飢饉の解放を宣言する。わたしは、あなたがたを地のすべての王国にとって、おののきのもとにする。'),
('JPN', '耶利米书', 24, 34, 18, 'また、わたしの前で結んだ契約のことばを守らず、わたしの契約を破った者たちを、彼らが二つに断ち切ってその二つの間を通った、あの子牛のようにする。'),
('JPN', '耶利米书', 24, 34, 19, 'ユダの首長たち、エルサレムの首長たち、宦官と祭司と民衆すべてが、二つに分けた子牛の間を通った者たちである。'),
('JPN', '耶利米书', 24, 34, 20, 'わたしは彼らを、敵の手、いのちを狙う者たちの手に渡す。その屍は空の鳥や地の獣の餌食となる。'),
('JPN', '耶利米书', 24, 34, 21, 'また、わたしはユダの王ゼデキヤとその高官たちを、敵の手、いのちを狙う者たちの手、あなたがたのところから引き揚げたバビロンの王の軍勢の手に渡す。'),
('JPN', '耶利米书', 24, 34, 22, '見よ。わたしは命じて──主のことば──彼らをこの都に引き返させる。彼らはこの都を攻め取り、火で焼く。わたしはユダの町々を、住む者もいない荒れ果てた地とする。』」'),
('JPN', '耶利米书', 24, 35, 1, 'ユダの王、ヨシヤの子エホヤキムの時代に、主からエレミヤに次のようなことばがあった。'),
('JPN', '耶利米书', 24, 35, 2, '「レカブ人の家に行って彼らに語り、主の宮の一室に連れて来て、彼らに酒を飲ませよ。」'),
('JPN', '耶利米书', 24, 35, 3, 'そこで私は、ハバツィンヤの子エレミヤの子であるヤアザンヤと、その兄弟とすべての息子たち、レカブ人の全家を率いて、'),
('JPN', '耶利米书', 24, 35, 4, '主の宮にある、イグダルヤの子、神の人ハナンの子らの部屋に連れて来た。それは首長たちの部屋の隣にあり、入り口を守る者、シャルムの子マアセヤの部屋の上であった。'),
('JPN', '耶利米书', 24, 35, 5, '私は、レカブ人の家の子らの前に、ぶどう酒を満たした壺と杯を出して、「酒を飲みなさい」と言った。'),
('JPN', '耶利米书', 24, 35, 6, 'すると彼らは言った。「私たちはぶどう酒を飲みません。というのは、私たちの先祖レカブの子ヨナダブが私たちに命じて、『あなたがたも、あなたがたの子らも、永久にぶどう酒を飲んではならない。'),
('JPN', '耶利米书', 24, 35, 7, 'あなたがたは家を建てたり、種を蒔いたり、ぶどう畑を作ったり、また所有したりしてはならない。あなたがたが寄留している地の面に末長く生きるために、一生、天幕に住め』と言ったからです。'),
('JPN', '耶利米书', 24, 35, 8, '私たちは、私たちの先祖レカブの子ヨナダブが私たちに命じたすべての命令に聞き従ってきました。私たちも、妻も、息子、娘たちも、一生ぶどう酒を飲まず、'),
('JPN', '耶利米书', 24, 35, 9, '住む家も建てず、ぶどう畑も、畑も、種も持たず、'),
('JPN', '耶利米书', 24, 35, 10, '天幕に住んできました。私たちは、すべて先祖ヨナダブが私たちに命じたとおりに、従い行ってきました。'),
('JPN', '耶利米书', 24, 35, 11, 'しかし、バビロンの王ネブカドネツァルがこの地に攻め上ったとき、私たちは『さあ、カルデアの軍勢とアラムの軍勢を避けてエルサレムに行こう』と言って、エルサレムに住んだのです。」'),
('JPN', '耶利米书', 24, 35, 12, 'すると、エレミヤに次のような主のことばがあった。'),
('JPN', '耶利米书', 24, 35, 13, '「イスラエルの神、万軍の主はこう言う。行って、ユダの人とエルサレムの住民に言え。『あなたがたは訓戒を受け入れて、わたしのことばに聞き従おうとしないのか──主のことば──。'),
('JPN', '耶利米书', 24, 35, 14, 'レカブの子ヨナダブが、酒を飲むなと子らに命じた命令は守られた。彼らは先祖の命令に聞き従ったので、今日まで飲んでいない。ところが、わたしがあなたがたにたびたび語っても、あなたがたはわたしに聞き従わなかった。'),
('JPN', '耶利米书', 24, 35, 15, 'わたしはあなたがたに、わたしのしもべであるすべての預言者たちを早くからたびたび遣わして、さあ、それぞれ悪の道から立ち返り、行いを改めよ、ほかの神々を慕ってそれに仕えてはならない、わたしがあなたがたと先祖たちに与えた土地に住め、と言った。それなのに、あなたがたは耳を傾けず、わたしに聞かなかった。'),
('JPN', '耶利米书', 24, 35, 16, '実に、レカブの子ヨナダブの子らは、先祖が命じた命令を守ってきたが、この民はわたしに聞かなかった。'),
('JPN', '耶利米书', 24, 35, 17, 'それゆえ──イスラエルの神、万軍の神、主はこう言われる──見よ。わたしはユダと、エルサレムの全住民に、わたしが彼らについて語ったすべてのわざわいを下す。わたしが彼らに語ったのに、彼らは聞かず、わたしが彼らに呼びかけたのに、彼らは答えなかったからだ。』」'),
('JPN', '耶利米书', 24, 35, 18, 'エレミヤはレカブ人の家の者に言った。「イスラエルの神、万軍の主はこう言われる。『あなたがたは、先祖ヨナダブの命令に聞き従い、そのすべての命令を守り、すべて彼があなたがたに命じたとおりに行った。'),
('JPN', '耶利米书', 24, 35, 19, 'それゆえ──イスラエルの神、万軍の主はこう言われる──レカブの子ヨナダブには、わたしの前に立つ人がいつまでも絶えることはない。』」'),
('JPN', '耶利米书', 24, 36, 1, 'ユダの王、ヨシヤの子エホヤキムの第四年に、主からエレミヤに次のようなことばがあった。'),
('JPN', '耶利米书', 24, 36, 2, '「あなたは巻物を取り、わたしがあなたに語った日、すなわちヨシヤの時代から今日まで、わたしがイスラエルとユダとすべての国々について、あなたに語ったことばをみな、それに書き記せ。'),
('JPN', '耶利米书', 24, 36, 3, 'ユダの家は、わたしが彼らに下そうと思っているすべてのわざわいを聞いて、それぞれ悪の道から立ち返るかもしれない。そうすれば、わたしも、彼らの咎と罪を赦すことができる。」'),
('JPN', '耶利米书', 24, 36, 4, 'それでエレミヤは、ネリヤの子バルクを呼んだ。バルクはエレミヤの口述にしたがって、彼に語られた主のことばを、ことごとく巻物に書き記した。'),
('JPN', '耶利米书', 24, 36, 5, 'エレミヤはバルクに命じた。「私は閉じ込められていて、主の宮に行けない。'),
('JPN', '耶利米书', 24, 36, 6, 'だから、あなたが行って、あなたが私の口述によって巻物に書き記した主のことばを、断食の日に主の宮で民の耳に読み聞かせよ。また、町々から来るユダ全体の耳にもそれを読み聞かせよ。'),
('JPN', '耶利米书', 24, 36, 7, 'そうすれば、主の前で彼らの嘆願が受け入れられ、それぞれ悪の道から立ち返るかもしれない。主がこの民に語られた怒りと憤りは大きいからだ。」'),
('JPN', '耶利米书', 24, 36, 8, 'そこでネリヤの子バルクは、すべて預言者エレミヤが命じたとおりに、主の宮で主のことばの書物を読んだ。'),
('JPN', '耶利米书', 24, 36, 9, 'ユダの王、ヨシヤの子エホヤキムの第五年、第九の月、エルサレムのすべての民と、ユダの町々からエルサレムに来ているすべての民に、主の前での断食が布告された。'),
('JPN', '耶利米书', 24, 36, 10, 'そのときバルクは、主の宮で民全体に聞こえるように、その書物からエレミヤのことばを読んだ。そこは、主の宮の、新しい門の入り口付近の上庭にあった、書記シャファンの子ゲマルヤの部屋であった。'),
('JPN', '耶利米书', 24, 36, 11, 'シャファンの子ゲマルヤの子ミカヤは、その書物にあるすべての主のことばを聞き、'),
('JPN', '耶利米书', 24, 36, 12, '王宮にある書記の部屋に下ったが、見よ、そこには、すべての首長たちが座っていた。すなわち書記エリシャマ、シェマヤの子デラヤ、アクボルの子エルナタン、シャファンの子ゲマルヤ、ハナンヤの子ゼデキヤ、およびすべての首長たちである。'),
('JPN', '耶利米书', 24, 36, 13, 'ミカヤは、バルクがあの書物を民に読んで聞かせたときに聞いた、すべてのことばを彼らに告げた。'),
('JPN', '耶利米书', 24, 36, 14, 'すべての首長たちは、クシの子シェレムヤの子ネタンヤの子ユディをバルクのもとに遣わして言った。「あなたが民に読んで聞かせたあの巻物、あれを手に持って来なさい。」そこで、ネリヤの子バルクは、巻物を手に持って彼らのところに入って来た。'),
('JPN', '耶利米书', 24, 36, 15, '彼らはバルクに言った。「さあ、座って、私たちにそれを読んで聞かせてくれ。」そこで、バルクは彼らに読んで聞かせた。'),
('JPN', '耶利米书', 24, 36, 16, 'そのすべてのことばを聞いたとき、彼らはみな互いに恐れおののき、バルクに言った。「私たちは、これらのことばをすべて、必ず王に告げなければならない。」'),
('JPN', '耶利米书', 24, 36, 17, '彼らはバルクに尋ねて言った。「さあ、あなたがこれらのことばをすべて、どのようにして書き留めたのか、私たちに教えてくれ。エレミヤが口述したことばを。」'),
('JPN', '耶利米书', 24, 36, 18, 'バルクは彼らに言った。「エレミヤがこれらのことばをすべて私に口述し、私は墨でこの書物に記しました。」'),
('JPN', '耶利米书', 24, 36, 19, 'すると首長たちはバルクに言った。「行って、あなたもエレミヤも身を隠しなさい。あなたがたがどこにいるか、だれにも知られないようにしなさい。」'),
('JPN', '耶利米书', 24, 36, 20, '彼らは巻物を書記エリシャマの部屋に置き、王宮の庭にいる王のところに行って、このすべてのことを報告した。'),
('JPN', '耶利米书', 24, 36, 21, '王はユディに、その巻物を取りに行かせたので、彼はそれを書記エリシャマの部屋から取って来た。ユディはそれを、王と王の傍らに立つすべての首長たちに読んで聞かせた。'),
('JPN', '耶利米书', 24, 36, 22, '第九の月であったので、王は冬の家の座に着いていた。彼の前には暖炉の火が燃えていた。'),
('JPN', '耶利米书', 24, 36, 23, 'ユディが三、四段を読むごとに、王は書記の小刀でそれを裂いては暖炉の火に投げ入れ、ついに、巻物をすべて暖炉の火で焼き尽くした。'),
('JPN', '耶利米书', 24, 36, 24, 'これらすべてのことばを聞いた王も、彼のすべての家来たちも、だれ一人恐れおののくことはなく、衣を引き裂くこともしなかった。'),
('JPN', '耶利米书', 24, 36, 25, 'エルナタンとデラヤとゲマルヤが、巻物を焼かないようにと王に懇願しても、王は聞き入れなかった。'),
('JPN', '耶利米书', 24, 36, 26, '王は、王子エラフメエルと、アズリエルの子セラヤと、アブデエルの子シェレムヤに、書記バルクと預言者エレミヤを捕らえるように命じた。しかし、主は二人を隠された。'),
('JPN', '耶利米书', 24, 36, 27, '王が、あの巻物、バルクがエレミヤの口述で書き記したことばを焼いた後、エレミヤに次のような主のことばがあった。'),
('JPN', '耶利米书', 24, 36, 28, '「あなたは再びもう一つの巻物を取り、ユダの王エホヤキムが焼いた最初の巻物にあった最初のことばを、残らずそれに書き記せ。'),
('JPN', '耶利米书', 24, 36, 29, 'ユダの王エホヤキムについてはこう言え。主はこう言われる。あなたはこの巻物を焼いて言った。『あなたはなぜ、バビロンの王は必ず来てこの地を滅ぼし、ここから人も家畜も絶えさせる、と書いたのか』と。'),
('JPN', '耶利米书', 24, 36, 30, 'それゆえ、主はユダの王エホヤキムについてこう言われる。エホヤキムには、ダビデの王座に就く者がいなくなり、彼の屍は捨てられて、昼は暑さに、夜は寒さにさらされる。'),
('JPN', '耶利米书', 24, 36, 31, 'わたしは、彼とその子孫、その家来たちを、彼らの咎のゆえに罰し、彼らとエルサレムの住民とユダの人々に対して、わたしが告げたが彼らが聞かなかった、あのすべてのわざわいをもたらす。」'),
('JPN', '耶利米书', 24, 36, 32, 'エレミヤは、もう一つの巻物を取り、それをネリヤの子、書記バルクに与えた。彼はエレミヤの口述により、ユダの王エホヤキムが火で焼いたあの書物のことばを残らず書き記した。さらに同じような多くのことばもそれに書き加えた。'),
('JPN', '耶利米书', 24, 37, 1, 'ヨシヤの子ゼデキヤは、エホヤキムの子エコンヤに代わって王となった。バビロンの王ネブカドネツァルが彼をユダの地の王にしたのである。'),
('JPN', '耶利米书', 24, 37, 2, '彼も、その家来たちも、民衆も、預言者エレミヤによって語られた主のことばに聞き従わなかった。'),
('JPN', '耶利米书', 24, 37, 3, 'ゼデキヤ王は、シェレムヤの子ユカルと、マアセヤの子、祭司ゼパニヤを預言者エレミヤのもとに遣わして言った。「どうか、私たちのために、私たちの神、主に祈ってください。」'),
('JPN', '耶利米书', 24, 37, 4, 'エレミヤは民のうちに出入りしていて、まだ獄屋に入れられてはいなかった。'),
('JPN', '耶利米书', 24, 37, 5, 'また、ちょうど、ファラオの軍勢がエジプトから出て来たので、エルサレムを包囲中のカルデア人は、そのうわさを聞いて、エルサレムから引き揚げたときであった。'),
('JPN', '耶利米书', 24, 37, 6, 'そのとき、預言者エレミヤに次のような主のことばがあった。'),
('JPN', '耶利米书', 24, 37, 7, '「イスラエルの神、主はこう言われる。わたしに尋ねるために、あなたがたをわたしのもとに遣わしたユダの王にこう言え。『見よ。あなたがたを助けに出て来たファラオの軍勢は、彼らの地エジプトへ帰り、'),
('JPN', '耶利米书', 24, 37, 8, 'カルデア人が引き返して来て、この都を攻め取り、これを火で焼く。'),
('JPN', '耶利米书', 24, 37, 9, '主はこう言われる。あなたがたは、カルデア人は必ず私たちのところから去る、と言って、自らを欺くな。彼らが去ることはないからだ。'),
('JPN', '耶利米书', 24, 37, 10, 'たとえ、あなたがたが、あなたがたを攻めるカルデアの全軍勢を討ち、そのうちに重傷を負った兵士たちだけが残ったとしても、彼らはそれぞれ、その天幕で立ち上がり、この都を火で焼くようになる。』」'),
('JPN', '耶利米书', 24, 37, 11, 'カルデアの軍勢がファラオの軍勢のゆえにエルサレムから引き揚げたとき、'),
('JPN', '耶利米书', 24, 37, 12, 'エレミヤは、エルサレムから出て行き、ベニヤミンの地に行った。民の間で割り当ての地を受け取るためであった。'),
('JPN', '耶利米书', 24, 37, 13, '彼がベニヤミンの門に来たとき、そこにハナンヤの子シェレムヤの子の、イルイヤという名の当直の者がいて、「あなたはカルデア人のところへ落ちのびるのか」と言い、預言者エレミヤを捕らえた。'),
('JPN', '耶利米书', 24, 37, 14, 'エレミヤは、「違う。私はカルデア人のところに落ちのびるのではない」と言ったが、イルイヤは聞かず、エレミヤを捕らえて、首長たちのところに連れて行った。'),
('JPN', '耶利米书', 24, 37, 15, '首長たちはエレミヤに向かって激しく怒り、彼を打ちたたき、こうして書記ヨナタンの家の牢屋に入れた。そこが獄屋になっていたからである。'),
('JPN', '耶利米书', 24, 37, 16, 'エレミヤは丸天井の地下牢に入れられ、長い間そこにいた。'),
('JPN', '耶利米书', 24, 37, 17, 'ゼデキヤ王は人を遣わして、彼を召し寄せた。王は自分の家で彼にひそかに尋ねて言った。「主から、おことばはあったか。」エレミヤは「ありました」と言った。そして「あなたはバビロンの王の手に渡されます」と言った。'),
('JPN', '耶利米书', 24, 37, 18, 'エレミヤはゼデキヤ王に言った。「あなたや、あなたの家来たちや、この民に対して、私にどんな罪があったというので、私を獄屋に入れたのですか。'),
('JPN', '耶利米书', 24, 37, 19, 'あなたがたに対して『バビロンの王は、あなたがたとこの地を攻めに来ない』と言って預言していた、あなたがたの預言者たちは、どこにいますか。'),
('JPN', '耶利米书', 24, 37, 20, '今、わが主君、王よ、どうか聞いてください。どうか、私の願いを御前に受け入れ、私を書記ヨナタンの家へ帰らせないでください。私がそこで死ぬことがないようにしてください。」'),
('JPN', '耶利米书', 24, 37, 21, 'ゼデキヤ王は命じて、エレミヤを監視の庭に入れさせ、都からすべてのパンが絶えるまで、パン屋街から毎日パン一つを彼に与えさせた。こうして、エレミヤは監視の庭にとどまっていた。'),
('JPN', '耶利米书', 24, 38, 1, 'さて、マタンの子シェファテヤと、パシュフルの子ゲダルヤと、シェレムヤの子ユカルと、マルキヤの子パシュフルは、エレミヤが民全体に次のように語ることばを聞いた。'),
('JPN', '耶利米书', 24, 38, 2, '「主はこう言われる。『この都にとどまる者は、剣と飢饉と疫病で死ぬが、カルデア人のところに出て行く者は生きる。そのいのちは戦勝品として彼のものになり、彼は生きる。』'),
('JPN', '耶利米书', 24, 38, 3, '主はこう言われる。『この都は、必ず、バビロンの王の軍勢の手に渡される。彼はこれを攻め取る。』」'),
('JPN', '耶利米书', 24, 38, 4, 'そこで、首長たちは王に言った。「どうか、あの男を死刑にしてください。彼はこのように、こんなことばを皆に語り、この都に残っている戦士や民全体の士気をくじいているからです。実にあの男は、この民のために、平安ではなくわざわいを求めているのです。」'),
('JPN', '耶利米书', 24, 38, 5, 'するとゼデキヤ王は言った。「見よ、彼はあなたがたの手の中にある。王は、あなたがたに逆らっては何もできない。」'),
('JPN', '耶利米书', 24, 38, 6, 'そこで彼らはエレミヤを捕らえ、監視の庭にある王子マルキヤの穴に投げ込んだ。彼らはエレミヤを綱で降ろしたが、穴の中には水がなく、あるのは泥だったので、エレミヤは泥の中に沈んだ。'),
('JPN', '耶利米书', 24, 38, 7, '王宮にいたクシュ人の宦官エベデ・メレクは、エレミヤが穴に入れられたことを聞いた。また、そのとき王はベニヤミンの門のところに座っていたので、'),
('JPN', '耶利米书', 24, 38, 8, 'エベデ・メレクは王宮から出て行き、王に告げた。'),
('JPN', '耶利米书', 24, 38, 9, '「わが主君、王よ。あの人たちが預言者エレミヤにしたことは、みな悪いことばかりです。彼らはあの人を穴に投げ込みました。もう都にパンはありませんので、あの人はそこで飢え死にするでしょう。」'),
('JPN', '耶利米书', 24, 38, 10, 'すると王は、クシュ人エベデ・メレクに命じた。「あなたはここから三十人を連れて行き、預言者エレミヤを、まだ死なないうちに、その穴から引き上げなさい。」'),
('JPN', '耶利米书', 24, 38, 11, 'エベデ・メレクは人々を率いて、王宮の宝物倉の下に行き、そこから着古した衣服やぼろ切れを取り、それらを綱で穴の中のエレミヤのところに降ろした。'),
('JPN', '耶利米书', 24, 38, 12, 'クシュ人エベデ・メレクはエレミヤに、「さあ、古着やぼろ切れをあなたの脇の下の綱に当てなさい」と言ったので、エレミヤがそのとおりにすると、'),
('JPN', '耶利米书', 24, 38, 13, '彼らはエレミヤを綱で穴から引き上げた。こうして、エレミヤは監視の庭にとどまった。'),
('JPN', '耶利米书', 24, 38, 14, 'ゼデキヤ王は人を送って、預言者エレミヤを自分のところ、主の宮の第三の入り口に召し寄せた。王がエレミヤに、「私はあなたに一言尋ねる。私に何も隠してはならない」と言うと、'),
('JPN', '耶利米书', 24, 38, 15, 'エレミヤはゼデキヤに言った。「もし私があなたに告げれば、あなたは必ず私を殺すのではありませんか。私があなたに忠告しても、あなたは私の言うことを聞かないでしょう。」'),
('JPN', '耶利米书', 24, 38, 16, 'そこでゼデキヤ王は、ひそかにエレミヤに誓った。「私たちの、このいのちを造られた主は生きておられる。私は決してあなたを殺さない。また、あなたのいのちを狙うあの者たちの手に、あなたを渡すことも絶対にしない。」'),
('JPN', '耶利米书', 24, 38, 17, 'すると、エレミヤはゼデキヤに言った。「イスラエルの神、万軍の神、主はこう言われる。『もし、あなたがバビロンの王の首長たちに降伏するなら、あなたのたましいは生きながらえ、この都も火で焼かれず、あなたもあなたの家も生きながらえる。'),
('JPN', '耶利米书', 24, 38, 18, 'あなたがバビロンの王の首長たちに降伏しないなら、この都はカルデア人の手に渡され、火で焼かれ、あなた自身も彼らの手から逃れることができない。』」'),
('JPN', '耶利米书', 24, 38, 19, 'しかし、ゼデキヤ王はエレミヤに言った。「私は、カルデア人に投降したユダヤ人たちのことを恐れている。カルデア人が私を彼らの手に渡し、彼らが私をなぶりものにするのではないか、と。」'),
('JPN', '耶利米书', 24, 38, 20, 'エレミヤは言った。「カルデア人はあなたを渡しません。どうか、主の御声に、私があなたに語っていることに聞き従ってください。そうすれば、あなたは幸せになり、あなたのたましいは生きながらえます。'),
('JPN', '耶利米书', 24, 38, 21, 'しかし、もしあなたが降伏するのを拒むなら、これが、主が私に示されたことばです。'),
('JPN', '耶利米书', 24, 38, 22, '『見よ。ユダの王の家に残された女たちはみな、バビロンの王の首長たちのところに引き出される。聞け。彼女たちは言う。あなたの親しい友たちが、あなたをそそのかして、押し切った。あなたの足が泥に沈むと、彼らは背を向けた。'),
('JPN', '耶利米书', 24, 38, 23, 'あなたの妻たちや子どもたちはみな、カルデア人のところに引き出され、あなた自身も彼らの手から逃れることができずに、バビロンの王の手に捕らえられ、この都も火で焼かれる。』」'),
('JPN', '耶利米书', 24, 38, 24, 'ゼデキヤはエレミヤに言った。「だれにも、これらのことを知らせてはならない。そうすれば、あなたは死なない。'),
('JPN', '耶利米书', 24, 38, 25, 'もし、あの首長たちが、私があなたと話したことを聞いてあなたのところに来て、『さあ、何を王と話したのか、教えろ。隠すな。あなたを殺しはしない。王はあなたに何を話したのか』と言っても、'),
('JPN', '耶利米书', 24, 38, 26, 'あなたは彼らに、『王がヨナタンの家に私を返し、そこで私が死ぬことのないようにと、王の前に嘆願をしていた』と言いなさい。」'),
('JPN', '耶利米书', 24, 38, 27, '首長たちがみなエレミヤのところに来て、彼に尋ねたとき、彼は、王が命じたことばのとおりに彼らに告げたので、彼らは彼と話すのをやめた。あのことは、だれにも聞かれていなかったのである。'),
('JPN', '耶利米书', 24, 38, 28, 'エレミヤは、エルサレムが攻め取られる日まで、監視の庭にとどまっていた。エルサレムが攻め取られた次第は次のとおりである。'),
('JPN', '耶利米书', 24, 39, 1, 'ユダの王ゼデキヤの第九年、第十の月に、バビロンの王ネブカドネツァルは、その全軍勢を率いてエルサレムに攻めて来て、これを包囲した。'),
('JPN', '耶利米书', 24, 39, 2, 'ゼデキヤの第十一年、第四の月の九日に、都は破られ、'),
('JPN', '耶利米书', 24, 39, 3, 'バビロンの王のすべての首長たちが入って来て、中央の門のところに座を占めた。すなわち、ネルガル・サル・エツェル、サムガル・ネブ、ラブ・サリスのサル・セキム、ラブ・マグのネルガル・サル・エツェル、およびバビロンの王の首長の残り全員である。'),
('JPN', '耶利米书', 24, 39, 4, 'ユダの王ゼデキヤとすべての戦士は、彼らを見ると逃げ、夜の間に、王の園の道伝いにある、二重の城壁の間の門を通って都を出て、アラバへの道に出た。'),
('JPN', '耶利米书', 24, 39, 5, 'カルデアの軍勢は彼らの後を追い、エリコの草原でゼデキヤに追いつき、彼を捕らえ、ハマテの地のリブラにいるバビロンの王ネブカドネツァルのもとに連れ上った。バビロンの王は彼に宣告を下した。'),
('JPN', '耶利米书', 24, 39, 6, 'バビロンの王はリブラで、ゼデキヤの息子たちを彼の目の前で虐殺し、ユダのおもだった人たちもみな虐殺した。'),
('JPN', '耶利米书', 24, 39, 7, 'さらに、バビロンの王はゼデキヤの目をつぶし、バビロンに連れて行くため、彼に青銅の足かせをはめた。'),
('JPN', '耶利米书', 24, 39, 8, 'カルデア人は、王宮も民の家も火で焼き、エルサレムの城壁を打ち壊した。'),
('JPN', '耶利米书', 24, 39, 9, '親衛隊の長ネブザルアダンは、都に残されていた残りの民と、王に降伏した投降者たちと、そのほかの残されていた民を、バビロンへ捕らえ移した。'),
('JPN', '耶利米书', 24, 39, 10, 'しかし、親衛隊の長ネブザルアダンは、何も持たない貧しい民の一部をユダの地に残し、同時に彼らにぶどう畑と畑地を与えた。'),
('JPN', '耶利米书', 24, 39, 11, 'バビロンの王ネブカドネツァルは、エレミヤについて、親衛隊の長ネブザルアダンを通して次のように命じた。'),
('JPN', '耶利米书', 24, 39, 12, '「彼を連れ出し、目をかけてやれ。何も悪いことをするな。ただ彼があなたに語るとおりに、彼を扱え。」'),
('JPN', '耶利米书', 24, 39, 13, 'こうして、親衛隊の長ネブザルアダンと、ラブ・サリスのネブシャズバンと、ラブ・マグのネルガル・サル・エツェルと、バビロンの王のすべての高官たちは、'),
('JPN', '耶利米书', 24, 39, 14, '人を遣わして、エレミヤを監視の庭から連れ出し、シャファンの子アヒカムの子ゲダルヤに渡して、家に連れて行かせた。こうして彼は民の間に住んだ。'),
('JPN', '耶利米书', 24, 39, 15, 'エレミヤが監視の庭に閉じ込められているとき、エレミヤに次のような主のことばがあった。'),
('JPN', '耶利米书', 24, 39, 16, '「行って、クシュ人エベデ・メレクに言え。『イスラエルの神、万軍の主はこう言われる。見よ、わたしはこの都にわたしのことばを実現させる。幸いのためではなく、わざわいのためだ。それらはその日、あなたの前で起こる。'),
('JPN', '耶利米书', 24, 39, 17, 'しかしその日、わたしはあなたを救い出す──主のことば──。あなたは、あなたが恐れている者たちの手に渡されることはない。'),
('JPN', '耶利米书', 24, 39, 18, 'わたしは必ずあなたを助け出す。あなたは剣に倒れず、あなたのいのちは戦勝品としてあなたのものになる。あなたがわたしに信頼したからだ──主のことば。』」'),
('JPN', '耶利米书', 24, 40, 1, '主からエレミヤにあったことば。バビロンへ引いて行かれるエルサレムとユダの捕囚の民の間で鎖につながれていたエレミヤを、親衛隊の長ネブザルアダンがラマから釈放した後のことである。'),
('JPN', '耶利米书', 24, 40, 2, '親衛隊の長はエレミヤを連れ出して、彼に言った。「あなたの神、主は、この場所にこのわざわいを下すと語られた。'),
('JPN', '耶利米书', 24, 40, 3, 'そして主はこれを下し、語ったとおりに行われた。あなたがたが主の前に罪ある者となり、その御声に聞き従わなかったので、このことがあなたがたに下ったのだ。'),
('JPN', '耶利米书', 24, 40, 4, 'そこで今、見よ、私は今日、あなたの手にある鎖を解いて、あなたを釈放する。もし私とともにバビロンへ行くのがよいと思うなら、行きなさい。私があなたの世話をしよう。しかし、もし私と一緒にバビロンへ行くのが気に入らないなら、やめなさい。見なさい。全地はあなたの前に広がっている。あなたが行ってよいと思う、気に入ったところへ行きなさい。」'),
('JPN', '耶利米书', 24, 40, 5, 'しかしエレミヤがまだ帰ろうとしないので、「では、バビロンの王がユダの町々を委ねた、シャファンの子アヒカムの子ゲダルヤのところへ帰り、彼とともに民のうちに住みなさい。でなければ、あなたが行くのによいと思うところへ、どこへでも行きなさい。」こうして親衛隊の長は、食糧と品物を与えて、彼を去らせた。'),
('JPN', '耶利米书', 24, 40, 6, 'そこでエレミヤは、ミツパにいるアヒカムの子ゲダルヤのところに行って、彼とともに、その地に残された民の間に住んだ。'),
('JPN', '耶利米书', 24, 40, 7, '野にいた軍の高官たちとその部下たちはみな、バビロンの王がアヒカムの子ゲダルヤをその地の総督にして、バビロンに捕らえ移されなかった男、女、子どもたち、その地の貧しい民たちを彼に委ねたことを聞いた。'),
('JPN', '耶利米书', 24, 40, 8, 'そして彼らはミツパにいるゲダルヤのもとに来た。ネタンヤの子イシュマエル、カレアハの子ヨハナンとヨナタン、タンフメテの子セラヤ、ネトファ人エファイの子ら、マアカ人の子エザンヤ、そして彼らの部下たちであった。'),
('JPN', '耶利米书', 24, 40, 9, 'シャファンの子アヒカムの子ゲダルヤは、彼らとその部下たちに誓った。「カルデア人に仕えることを恐れてはならない。この地に住んで、バビロンの王に仕えなさい。そうすれば、あなたがたは幸せになる。'),
('JPN', '耶利米书', 24, 40, 10, 'この私は、見よ、ミツパに住んで、私たちのところに来るカルデア人の前に立とう。あなたがたは、ぶどう酒、夏の果物、油を収穫して器に納め、自分たちが手に入れた町々に住むがよい。」'),
('JPN', '耶利米书', 24, 40, 11, 'モアブや、アンモン人のところや、エドムや、あらゆる地方にいたユダヤ人もみな、バビロンの王がユダに人を残したこと、シャファンの子アヒカムの子ゲダルヤを彼らの総督に任命したことを聞いた。'),
('JPN', '耶利米书', 24, 40, 12, 'そこで、ユダヤ人はみな、散らされていたすべての場所からユダの地に帰って来て、ミツパのゲダルヤのもとに行き、非常に多くのぶどう酒と夏の果物を収穫した。'),
('JPN', '耶利米书', 24, 40, 13, 'さて、野にいたカレアハの子ヨハナンと、軍のすべての高官たちは、ミツパのゲダルヤのもとに来て、'),
('JPN', '耶利米书', 24, 40, 14, '彼に言った。「あなたは、アンモン人の王バアリスがネタンヤの子イシュマエルを送って、あなたを打ち殺そうとしているのをご存じですか。」しかし、アヒカムの子ゲダルヤは、彼らの言うことを信じなかった。'),
('JPN', '耶利米书', 24, 40, 15, 'カレアハの子ヨハナンは、ミツパでひそかにゲダルヤに話して言った。「では、私が行って、ネタンヤの子イシュマエルを、だれにも分からないように打ち殺しましょう。どうして、彼があなたを打ち殺し、あなたのもとに集められた全ユダヤ人が散らされ、ユダの残りの者が滅びてよいでしょうか。」'),
('JPN', '耶利米书', 24, 40, 16, 'しかし、アヒカムの子ゲダルヤは、カレアハの子ヨハナンに言った。「そんなことをしてはならない。あなたこそ、イシュマエルについて偽りを語っているからだ。」'),
('JPN', '耶利米书', 24, 41, 1, 'ところが第七の月に、王族の一人、エリシャマの子ネタンヤの子イシュマエルは、王の高官と十人の部下とともに、ミツパにいるアヒカムの子ゲダルヤのもとに来て、ミツパで食事をともにした。'),
('JPN', '耶利米书', 24, 41, 2, 'ネタンヤの子イシュマエルと、彼とともにいた十人の部下は立ち上がって、シャファンの子アヒカムの子ゲダルヤを剣で打ち殺した。イシュマエルは、バビロンの王がこの地の総督にした者を殺した。'),
('JPN', '耶利米书', 24, 41, 3, 'ミツパでゲダルヤと一緒にいたすべてのユダの人たちと、そこに居合わせたカルデア人の戦士たちを、イシュマエルは打ち殺した。'),
('JPN', '耶利米书', 24, 41, 4, 'ゲダルヤが殺された次の日、まだ、だれもそれを知らなかったとき、'),
('JPN', '耶利米书', 24, 41, 5, 'シェケム、シロ、サマリアから八十人の者がやって来た。彼らはみな、ひげを剃り、衣を引き裂き、身に傷をつけ、穀物のささげ物や乳香を手にして、主の宮に持って行こうとしていた。'),
('JPN', '耶利米书', 24, 41, 6, 'ネタンヤの子イシュマエルは、彼らを迎えにミツパを出て、泣きながら歩いて行った。そして、彼らに出会ったとき、「アヒカムの子ゲダルヤのところにおいでください」と言った。'),
('JPN', '耶利米书', 24, 41, 7, '彼らが町の中に入ったとき、ネタンヤの子イシュマエルと、彼とともにいた部下たちは、彼らを殺して穴の中に投げ入れた。'),
('JPN', '耶利米书', 24, 41, 8, '彼らのうちの十人がイシュマエルに、「私たちを殺さないでください。私たちには、小麦、大麦、油、蜜など、畑に隠されたものがありますから」と言ったので、彼は、彼らをその仲間とともに殺すのをやめた。'),
('JPN', '耶利米书', 24, 41, 9, 'イシュマエルが、ゲダルヤの指揮下にあった人々を打ち殺し、その死体すべてを投げ入れた穴は、アサ王がイスラエルの王バアシャに備えて作ったものであった。ネタンヤの子イシュマエルはそれを、殺された者で満たした。'),
('JPN', '耶利米书', 24, 41, 10, 'イシュマエルは、ミツパにいた民の残りの者たち、すなわち王の娘たち、および親衛隊の長ネブザルアダンがアヒカムの子ゲダルヤに委ねた、ミツパに残っていたすべての民を捕らわれの身とした。ネタンヤの子イシュマエルは彼らを捕囚にして、アンモン人のところに渡ろうとして出発した。'),
('JPN', '耶利米书', 24, 41, 11, 'しかし、カレアハの子ヨハナンと、彼とともにいた軍のすべての高官たちは、ネタンヤの子イシュマエルが行ったすべての悪を聞くと、'),
('JPN', '耶利米书', 24, 41, 12, '部下をみな連れて、ネタンヤの子イシュマエルと戦うために出て行き、ギブオンにある大池のほとりで彼を見つけた。'),
('JPN', '耶利米书', 24, 41, 13, 'イシュマエルとともにいたすべての民は、カレアハの子ヨハナンと、彼とともにいるすべての高官を見て喜んだ。'),
('JPN', '耶利米书', 24, 41, 14, 'こうして、イシュマエルがミツパから捕らえて来た民のすべては身を翻し、カレアハの子ヨハナンの側についた。'),
('JPN', '耶利米书', 24, 41, 15, 'ネタンヤの子イシュマエルは、八人の者とともにヨハナンの前から逃れ、アンモン人のところへ行った。'),
('JPN', '耶利米书', 24, 41, 16, 'ネタンヤの子イシュマエルがアヒカムの子ゲダルヤを打ち殺した後、カレアハの子ヨハナンと、彼とともにいたすべての高官たちは、ネタンヤの子イシュマエルから取り返したすべての残りの民、すなわちギブオンから連れ帰った勇士たち、戦士たち、女たち、子どもたち、および宦官たちを連れて、ミツパから'),
('JPN', '耶利米书', 24, 41, 17, 'エジプトに行こうとして、ベツレヘムの傍らにあるゲルテ・キムハムへ行き、そこにとどまった。'),
('JPN', '耶利米书', 24, 41, 18, 'バビロンの王がこの地の総督としたアヒカムの子ゲダルヤを、ネタンヤの子イシュマエルが打ち殺したため、カルデア人を恐れたからである。'),
('JPN', '耶利米书', 24, 42, 1, '軍のすべての高官たち、カレアハの子ヨハナン、ホシャヤの子イザンヤ、および身分の低い者も高い者もみな近づいて来て、'),
('JPN', '耶利米书', 24, 42, 2, '預言者エレミヤに言った。「どうか、私たちの願いを受け入れてください。私たちのため、この残りの者すべてのために、あなたの神、主に祈ってください。ご覧のとおり、多くの者の中からわずかに私たちだけが残ったのです。'),
('JPN', '耶利米书', 24, 42, 3, 'あなたの神、主が、私たちの歩むべき道と、なすべきことを私たちに告げてくださいますように。」'),
('JPN', '耶利米书', 24, 42, 4, 'そこで、預言者エレミヤは彼らに言った。「承知しました。見よ。私は、あなたがたのことばのとおり、あなたがたの神、主に祈り、主があなたがたにお答えになることはみな、あなたがたに告げましょう。あなたがたには何事も隠しません。」'),
('JPN', '耶利米书', 24, 42, 5, '彼らはエレミヤに言った。「主が、私たちの間で真実で確かな証人であられますように。私たちは必ず、あなたの神、主が私たちのためにあなたを遣わして告げられることばのとおりに、すべて行います。'),
('JPN', '耶利米书', 24, 42, 6, 'それが良くても悪くても、私たちは、あなたを遣わされた私たちの神、主の御声に聞き従います。私たちの神、主の御声に聞き従って幸せを得るためです。」'),
('JPN', '耶利米书', 24, 42, 7, '十日たって、主のことばがエレミヤにあった。'),
('JPN', '耶利米书', 24, 42, 8, 'エレミヤは、カレアハの子ヨハナンと、彼とともにいる軍のすべての高官たちと、身分の低い者や高い者をみな呼び寄せて、'),
('JPN', '耶利米书', 24, 42, 9, '彼らに言った。「あなたがたは自分たちのために嘆願してもらおうと私を主に遣わしたが、そのイスラエルの神、主はこう言われる。'),
('JPN', '耶利米书', 24, 42, 10, '『もし、あなたがたがこの地にとどまるのであれば、わたしはあなたがたを建て直して、壊すことなく、あなたがたを植えて、引き抜くことはない。わたしは、あなたがたに下したあのわざわいを悔やんでいるからだ。'),
('JPN', '耶利米书', 24, 42, 11, 'あなたがたが恐れているバビロンの王を恐れるな。彼を恐れるな──主のことば──。わたしがあなたがたとともにいて、彼の手からあなたがたを救い、助け出すからだ。'),
('JPN', '耶利米书', 24, 42, 12, 'わたしがあなたがたにあわれみを施すので、彼はあなたがたをあわれんで、あなたがたを自分たちの土地に帰らせる。』'),
('JPN', '耶利米书', 24, 42, 13, 'しかし、あなたがたが『私たちはこの地にとどまらない』と言って、あなたがたの神、主の御声に聞き従わず、'),
('JPN', '耶利米书', 24, 42, 14, '『いや、エジプトの地に行こう。あそこでは戦いにあわず、角笛の音も聞かず、パンに飢えることもない。あそこに私たちは住もう』と言うのであれば、'),
('JPN', '耶利米书', 24, 42, 15, '今、ユダの残りの者よ、主のことばを聞け。イスラエルの神、万軍の主はこう言われる。『もし、あなたがたがエジプトに行こうと決意し、そこに行って寄留するなら、'),
('JPN', '耶利米书', 24, 42, 16, 'あなたがたの恐れている剣が、あのエジプトの地であなたがたを襲い、あなたがたの心配している飢饉が、あのエジプトであなたがたに追い迫り、あなたがたはそこで死ぬ。'),
('JPN', '耶利米书', 24, 42, 17, 'エジプトに行ってそこに寄留しようと決意した者たちはみな、そこで剣と飢饉と疫病で死ぬ。わたしが彼らに下すわざわいから、生き残る者も逃れる者もいない。』'),
('JPN', '耶利米书', 24, 42, 18, 'まことに、イスラエルの神、万軍の主はこう言われる。『わたしの怒りと憤りがエルサレムの住民の上に注がれたように、あなたがたがエジプトに行くとき、わたしの憤りはあなたがたの上に注がれ、あなたがたは、のろいと恐怖のもと、ののしりとそしりの的になり、二度とこの場所を見ることはない。』'),
('JPN', '耶利米书', 24, 42, 19, 'ユダの残りの者よ、主はあなたがたに『エジプトへ行ってはならない』と言われた。私が今日あなたがたに証ししたことを、確かに知らなければならない。'),
('JPN', '耶利米书', 24, 42, 20, 'あなたがたは、自分たちのいのちの危険を冒して迷い出てしまったからだ。あなたがたは私をあなたがたの神、主のもとに遣わして、『私たちのために、私たちの神、主に祈り、すべて私たちの神、主の言われるとおりに、私たちに告げてください。私たちはそれを行います』と言ったのだ。'),
('JPN', '耶利米书', 24, 42, 21, '私は今日、あなたがたに告げたが、あなたがたは、自分たちの神、主の御声を、すなわち、主がそのために私をあなたがたに遣わされたすべてのことを聞こうとしなかった。'),
('JPN', '耶利米书', 24, 42, 22, 'だから今、確かに知らなければならない。あなたがたが、行って寄留したいと思っているその場所で、剣や飢饉や疫病で死ぬことを。」'),
('JPN', '耶利米书', 24, 43, 1, 'エレミヤが民全体に、彼らの神、主のことばを語り終えたときのこと。彼らの神、主はこのすべてのことばをもって、エレミヤを彼らに遣わされたのであるが、'),
('JPN', '耶利米书', 24, 43, 2, 'ホシャヤの子アザルヤ、カレアハの子ヨハナン、および高ぶった人たちはみな、エレミヤにこう告げた。「あなたは偽りを語っている。私たちの神、主は『エジプトに行ってそこに寄留してはならない』と言わせるために、あなたを遣わされたのではない。'),
('JPN', '耶利米书', 24, 43, 3, 'ネリヤの子バルクが、あなたをそそのかして私たちに逆らわせ、私たちをカルデア人の手に渡して、私たちを死なせるか、あるいは、私たちをバビロンへ引いて行かせようとしているのだ。」'),
('JPN', '耶利米书', 24, 43, 4, 'カレアハの子ヨハナンと、軍のすべての高官たちと、民のすべては、「ユダの地にとどまれ」という主の御声に聞き従わなかった。'),
('JPN', '耶利米书', 24, 43, 5, 'そして、カレアハの子ヨハナンと、軍のすべての高官たちは、散らされていた国々からユダの地に住むために帰っていたユダの残りの者すべて、'),
('JPN', '耶利米书', 24, 43, 6, 'すなわち、親衛隊の長ネブザルアダンが、シャファンの子アヒカムの子ゲダルヤに託したすべての者、男、女、子ども、王の娘たち、さらに、預言者エレミヤと、ネリヤの子バルクを連れて、'),
('JPN', '耶利米书', 24, 43, 7, 'エジプトの地に行った。主の御声に聞き従わなかったのである。こうして、彼らはタフパンヘスまで来た。'),
('JPN', '耶利米书', 24, 43, 8, 'タフパンヘスで、エレミヤに次のような主のことばがあった。'),
('JPN', '耶利米书', 24, 43, 9, '「あなたは手に大きな石を取り、それらを、ユダヤ人たちの目の前で、タフパンヘスにあるファラオの宮殿の入り口にある敷石の漆喰の中に隠して、'),
('JPN', '耶利米书', 24, 43, 10, '彼らに言え。『イスラエルの神、万軍の主はこう言われる。見よ。わたしは人を遣わし、わたしのしもべ、バビロンの王ネブカドネツァルを連れて来て、彼の王座を、わたしが隠したこれらの石の上に据える。彼はその石の上に本営を張る。'),
('JPN', '耶利米书', 24, 43, 11, '彼は来てエジプトの地を討ち、死に定められた者を死に渡し、捕囚に定められた者を捕囚にし、剣に定められた者を剣に渡す。'),
('JPN', '耶利米书', 24, 43, 12, 'わたしがエジプトの神々の神殿に火をつけるので、彼はそれらを焼き、神々を奪い去る。彼は、羊飼いが自分の衣をまとうようにエジプトの地をまとい、ここから安らかに去って行く。'),
('JPN', '耶利米书', 24, 43, 13, 'また、エジプトの地にある太陽の神殿の石柱を砕き、エジプトの神々の神殿を火で焼く。』」'),
('JPN', '耶利米书', 24, 44, 1, 'エジプトの地に住むすべてのユダヤ人、すなわちミグドル、タフパンヘス、メンフィス、およびパテロス地方に住む者たちに対する、エレミヤにあったことばは、次のとおりである。'),
('JPN', '耶利米书', 24, 44, 2, '「イスラエルの神、万軍の主はこう言われる。『あなたがたは、わたしがエルサレムとユダのすべての町に下した、あのすべてのわざわいを見た。見よ。その町々は今日、廃墟となって、そこに住む者もいない。'),
('JPN', '耶利米书', 24, 44, 3, '彼らが悪を行って、わたしの怒りを引き起こしたためだ。彼らは、自分自身も、あなたがたも、父祖たちも知らなかったほかの神々のところに行き、犠牲を供えて仕えた。'),
('JPN', '耶利米书', 24, 44, 4, 'それで、わたしはあなたがたに、わたしのしもべであるすべての預言者たちを早くからたびたび遣わして、わたしの憎むこの忌み嫌うべきことを行わないように言ってきたが、'),
('JPN', '耶利米书', 24, 44, 5, '彼らは聞かず、耳を傾けず、ほかの神々に犠牲を供えることをやめて悪から立ち返ることはなかった。'),
('JPN', '耶利米书', 24, 44, 6, 'そのため、わたしの憤りと怒りが、ユダの町々とエルサレムの通りに注がれて燃え上がり、それらは今日のように廃墟となって荒れ果てている。』'),
('JPN', '耶利米书', 24, 44, 7, '今、イスラエルの神、万軍の神、主はこう言われる。『なぜ、あなたがたは自分自身に大きなわざわいを招き、ユダの中から男も女も、幼子も乳飲み子も断って、残りの者を生かしておかないようにするのか。'),
('JPN', '耶利米书', 24, 44, 8, 'なぜ、あなたがたは、寄留しようとしてやって来たエジプトの地でも、ほかの神々に犠牲を供えて、自分の手のわざによってわたしの怒りを引き起こすのか。こうして、あなたがたは自分たち自身を絶ち滅ぼして、地のすべての国々の中で、ののしりとそしりの的になろうとしている。'),
('JPN', '耶利米书', 24, 44, 9, 'あなたがたは、ユダの地とエルサレムの通りで行った、自分たちの先祖の悪、ユダの王たちの悪、王妃たちの悪、自分たちの悪、自分たちの妻たちの悪を忘れたのか。'),
('JPN', '耶利米书', 24, 44, 10, '彼らは今日まで心砕かれず、恐れず、わたしがあなたがたとあなたがたの先祖の前に与えたわたしの律法と掟に歩まなかった。』'),
('JPN', '耶利米书', 24, 44, 11, 'それゆえ、イスラエルの神、万軍の主はこう言われる。『見よ。わたしはあなたがたに顔を向け、わざわいを下し、ユダのすべての民を絶ち滅ぼす。'),
('JPN', '耶利米书', 24, 44, 12, 'わたしは、エジプトの地へ行ってそこに寄留しようと決意したユダの残りの者を取り分ける。彼らはみな、エジプトの地で、剣と飢饉に倒れて滅びる。身分の低い者も高い者もみな、剣と飢饉で死に、のろいと恐怖のもと、ののしりとそしりの的となる。'),
('JPN', '耶利米书', 24, 44, 13, 'わたしは、エルサレムを罰したのと同じように、エジプトの地に住んでいる者たちを、剣と飢饉と疫病で罰する。'),
('JPN', '耶利米书', 24, 44, 14, 'エジプトの地に寄留した後、ユダの地へ帰ろうとしているユダの残りの者には、逃れる者も生き残る者もいない。彼らはそこに帰って住みたいと心から望んでいるが、わずかな逃れる者以外は帰らない。』」'),
('JPN', '耶利米书', 24, 44, 15, 'そのとき、自分たちの妻がほかの神々に犠牲を供えていることを知っている男たちのすべてと、大集団をなしてそばに立っている女たちすべて、すなわち、エジプトの地とパテロスに住むすべての民は、エレミヤに答えた。'),
('JPN', '耶利米书', 24, 44, 16, '「あなたが主の名によって私たちに語ったことばに、私たちは従うわけにはいかない。'),
('JPN', '耶利米书', 24, 44, 17, '私たちは、私たちの口から出たことばをみな必ず行って、私たちも父祖たちも、私たちの王たちも首長たちも、ユダの町々やエルサレムの通りで行っていたように、天の女王に犠牲を供え、それに注ぎのぶどう酒を注ぎたい。私たちはそのとき、パンに満ち足りて幸せで、わざわいにあわなかった。'),
('JPN', '耶利米书', 24, 44, 18, 'だが、天の女王に犠牲を供え、それに注ぎのぶどう酒を注ぐのをやめたときから、私たちは万事に不足し、剣と飢饉に滅ぼされたのだ。」'),
('JPN', '耶利米书', 24, 44, 19, '「私たち女が、天の女王に犠牲を供え、彼女に注ぎのぶどう酒を注ぐとき、女王にかたどった供えのパン菓子を作り、注ぎのぶどう酒を注いだのは、夫をなおざりにしてのことだったでしょうか。」'),
('JPN', '耶利米书', 24, 44, 20, 'そこでエレミヤは、そのすべての者、すなわち、男たちと女たち、また彼に口答えした者たち全員に言った。'),
('JPN', '耶利米书', 24, 44, 21, '「ユダの町々やエルサレムの通りで、あなたがたや、あなたがたの先祖、王たち、首長たち、また民衆が犠牲を供えたことを、主が覚えず、心に上らせなかったことがあるだろうか。'),
('JPN', '耶利米书', 24, 44, 22, '主は、あなたがたの悪い行い、あなたがたが行ったあの忌み嫌うべきことのために、もう耐えることができず、それであなたがたの地は今日のように、住む者もなく、廃墟となり、恐怖のもと、ののしりの的となったのだ。'),
('JPN', '耶利米书', 24, 44, 23, 'あなたがたが犠牲を供えたため、また、主の前に罪ある者となって、主の御声に聞き従わず、主の律法と掟と証しに歩まなかったために、今日のように、あなたがたにこのわざわいが起こったのだ。」'),
('JPN', '耶利米书', 24, 44, 24, 'それからエレミヤは、すべての民、すべての女たちに言った。「エジプトの地にいるすべてのユダの人々よ、主のことばを聞け。'),
('JPN', '耶利米书', 24, 44, 25, '『イスラエルの神、万軍の主はこう言われる。あなたがたとあなたがたの妻は、自分たちの口で約束し、自分の手で果たしてきた。あなたがたは、天の女王に犠牲を供えて彼女に注ぎのぶどう酒を注ぐという誓願を、必ず実行すると言っている。では、あなたがたの誓願を確かなものとし、あなたがたの誓願を必ず実行せよ。』'),
('JPN', '耶利米书', 24, 44, 26, 'それゆえ、エジプトの地に住むすべてのユダの人々よ、主のことばを聞け。『見よ、わたしはわたしの大いなる名によって誓う──主は言われる──。エジプトの全土において、「神である主は生きておられる」と、わたしの名がユダの人々の口に上ることはもうなくなる。'),
('JPN', '耶利米书', 24, 44, 27, '見よ、わたしは彼らを見張っている。わざわいのためであって、幸いのためではない。エジプトの地にいるすべてのユダの人々は、剣と飢饉によって、ついには完全に滅び失せる。'),
('JPN', '耶利米书', 24, 44, 28, '剣を逃れる少数の者だけが、エジプトの地からユダの地に帰る。こうして、エジプトの地に来て寄留しているユダの残りの者たちはみな、わたしのことばと彼らのことばの、どちらが成就するかを知る。'),
('JPN', '耶利米书', 24, 44, 29, 'これが、あなたがたへのしるしである──主のことば──。わたしはこの場所であなたがたを罰する。あなたがたにわざわいを下すというわたしのことばが必ず成就することを、あなたがたが知るためである。』'),
('JPN', '耶利米书', 24, 44, 30, '主はこう言われる。『見よ。わたしは、エジプトの王ファラオ・ホフラをその敵の手に、そのいのちを狙う者たちの手に渡す。ちょうどユダの王ゼデキヤを、そのいのちを狙っていた彼の敵、バビロンの王ネブカドネツァルの手に渡したように。』」'),
('JPN', '耶利米书', 24, 45, 1, 'ユダの王、ヨシヤの子エホヤキムの第四年に、ネリヤの子バルクが、エレミヤの口述によってこれらのことばを書物に書いたとき、預言者エレミヤが彼に語ったことばは、こうである。'),
('JPN', '耶利米书', 24, 45, 2, '「バルクよ、イスラエルの神、主は、あなたについてこう言われる。'),
('JPN', '耶利米书', 24, 45, 3, '『あなたは言った。ああ、私はわざわいだ。主は私の痛みに悲しみを加えられた。私は嘆きで疲れ果て、憩いを見出せない、と。』」'),
('JPN', '耶利米书', 24, 45, 4, '「エレミヤよ、あなたは彼にこう言え。『主はこう言われる。見よ。わたしは自分が建てたものを自分で壊し、わたしが植えたものを自分で引き抜く。この全土をそうする。'),
('JPN', '耶利米书', 24, 45, 5, 'あなたは、自分のために大きなことを求めるのか。求めるな。見よ。わたしがすべての肉なる者に、わざわいを下そうとしているからだ──主のことば──。しかしわたしは、あなたが行くどこででも、あなたのいのちを戦勝品としてあなたに与える。』」'),
('JPN', '耶利米书', 24, 46, 1, '諸国の民について、預言者エレミヤにあった主のことば。'),
('JPN', '耶利米书', 24, 46, 2, 'エジプトについて、すなわちユーフラテス河畔のカルケミシュにいたエジプトの王ファラオ・ネコの軍勢について。ユダの王、ヨシヤの子エホヤキムの第四年に、バビロンの王ネブカドネツァルがこれを打ち破った。'),
('JPN', '耶利米书', 24, 46, 3, '「盾と大盾を整えて、戦いに向かえ。'),
('JPN', '耶利米书', 24, 46, 4, '騎兵たちよ、馬に鞍をつけて乗れ。かぶとを着けて配置につけ。槍を磨き、よろいをまとえ。'),
('JPN', '耶利米书', 24, 46, 5, '何ということか、この有様は。彼らはおじ惑い、うしろに退く。勇士たちは打たれ、うしろも振り向かずに逃げ去る。恐怖が取り囲んでいる。──主のことば──'),
('JPN', '耶利米书', 24, 46, 6, '足の速い者も逃げられない。勇士たちも逃れられない。北の方、ユーフラテス川のほとりで、彼らはつまずき倒れる。'),
('JPN', '耶利米书', 24, 46, 7, 'ナイル川のように湧き上がり、奔流のように逆巻くこの者はだれか。'),
('JPN', '耶利米书', 24, 46, 8, 'エジプトは、ナイル川のように湧き上がり、奔流のように逆巻く。彼は言う。『湧き上がって地をおおい、町も住民も滅ぼそう。』'),
('JPN', '耶利米书', 24, 46, 9, '馬よ、進め。戦車よ、走れ。勇士たちは出陣せよ。盾を取るクシュ人、プテ人、弓を引くルデ人よ。'),
('JPN', '耶利米书', 24, 46, 10, 'その日は、万軍の神、主の日、敵に復讐する復讐の日。剣は食らって満ち足り、彼らの血に酔う。北の地、ユーフラテス川のほとりでは、万軍の神、主に、いけにえが献げられる。'),
('JPN', '耶利米书', 24, 46, 11, 'おとめである娘エジプトよ、ギルアデに上って乳香を取れ。多くの薬を用いても無駄だ。おまえには癒やしがない。'),
('JPN', '耶利米书', 24, 46, 12, '国々は、おまえの恥辱のことを聞く。おまえの哀れな叫び声は地に満ちる。勇士が勇士につまずき、ともに倒れるからだ。」'),
('JPN', '耶利米书', 24, 46, 13, 'バビロンの王ネブカドネツァルが来て、エジプトの地を討つことについて、主が預言者エレミヤに語られたことば。'),
('JPN', '耶利米书', 24, 46, 14, 'エジプトで告げ、ミグドルで聞かせ、メンフィスとタフパンヘスで聞かせて言え。「配置について、備えをせよ。剣がおまえの周りを食い尽くすからだ。'),
('JPN', '耶利米书', 24, 46, 15, 'なぜ、おまえの雄牛は押し流されるのか。それは踏みとどまり得ない。主が彼を突き倒されたからだ。'),
('JPN', '耶利米书', 24, 46, 16, '多くの者がつまずき、倒れる。彼らは互いに言う。『さあ、われわれの民のところ、生まれ故郷に帰ろう。あの虐げる者の剣を避けて。』'),
('JPN', '耶利米书', 24, 46, 17, '彼らはそこで叫んだ。エジプトの王ファラオは、時期を逸して騒ぐ者。'),
('JPN', '耶利米书', 24, 46, 18, 'わたしは生きている。──その名を万軍の主という王のことば──タボルが山々の間にあるように、カルメルが海のそばにあるように、彼は必ず来る。'),
('JPN', '耶利米书', 24, 46, 19, 'エジプトに住む娘よ、捕囚となる身支度をせよ。メンフィスは荒れ果て、焼かれて住む者もいなくなるからだ。'),
('JPN', '耶利米书', 24, 46, 20, 'エジプトは、かわいらしい雌の子牛。しかし北からアブが襲って来る。'),
('JPN', '耶利米书', 24, 46, 21, 'その中にいた傭兵も、肥えた子牛のようだ。彼らもまた、背を向けてともに逃げ、立ち止まろうともしない。彼らの滅びの日、刑罰の時が、彼らの上に来るからだ。'),
('JPN', '耶利米书', 24, 46, 22, '彼女の声は逃げ去る蛇の音のようだ。敵が軍勢を率い、木こりのように、斧を持って入って来るからだ。'),
('JPN', '耶利米书', 24, 46, 23, '彼らはその森を切り倒す。──主のことば──それがいかに奥深くても。実に、彼らはいなごより多くて数えきれない。'),
('JPN', '耶利米书', 24, 46, 24, '娘エジプトは辱められ、北の民の手に渡される。」'),
('JPN', '耶利米书', 24, 46, 25, 'イスラエルの神、万軍の主は言われる。「見よ。わたしは、テーベのアモン、ファラオとエジプト、その神々と王たち、ファラオと彼に拠り頼む者たちを罰する。'),
('JPN', '耶利米书', 24, 46, 26, 'わたしは彼らを、そのいのちを狙う者たちの手に、バビロンの王ネブカドネツァルの手とその家来たちの手に渡す。その後エジプトには、昔のように人が住むようになる──主のことば。'),
('JPN', '耶利米书', 24, 46, 27, 'わたしのしもべヤコブよ、恐れるな。イスラエルよ、おののくな。見よ。わたしがあなたを遠くから、あなたの子孫を捕囚の地から救うからだ。ヤコブは帰って来て、だれにも脅かされずに平穏に安らかに生きる。'),
('JPN', '耶利米书', 24, 46, 28, 'わたしのしもべヤコブよ、恐れるな。──主のことば──わたしが、あなたとともにいるからだ。わたしは、あなたを追いやった先のすべての国々を滅ぼし尽くす。しかし、あなたを滅ぼし尽くすことはない。ただし、さばきによってあなたを懲らしめる。決してあなたを罰せずにおくことはない。」'),
('JPN', '耶利米书', 24, 47, 1, 'ファラオがガザを討つ前に、ペリシテ人について預言者エレミヤにあった主のことば。'),
('JPN', '耶利米书', 24, 47, 2, '主はこう言われる。「見よ。北から水が上って来てあふれる流れとなり、地とそこに満ちているもの、町とその住民を押し流す。人々はわめき、地の住民はみな泣き叫ぶ。'),
('JPN', '耶利米书', 24, 47, 3, '荒馬のひづめの音のため、戦車の響き、車輪のとどろきに、父親たちは気力を失い、子どもたちを顧みない。'),
('JPN', '耶利米书', 24, 47, 4, 'すべてのペリシテ人を破滅させる日、ツロとシドンを助ける生き残りの者すべてを断ち切る日が来たからだ。まことに主は、ペリシテ人を、カフトルの島の残りの者を破滅させる。'),
('JPN', '耶利米书', 24, 47, 5, 'ガザは頭を剃られ、アシュケロンは黙らされる。平地の残りの者よ、いつまで、おまえは身を傷つけるのか。」'),
('JPN', '耶利米书', 24, 47, 6, '「ああ、主の剣よ。いつまで休まないのか。さやに収まり、静かに休め。」'),
('JPN', '耶利米书', 24, 47, 7, 'どうして、休めるだろうか。主が剣に命じられたのだ。アシュケロンとその海岸、そこに剣を向けられたのだ。'),
('JPN', '耶利米书', 24, 48, 1, 'モアブについて。イスラエルの神、万軍の主はこう言われる。「わざわいだ、ネボ。これは荒らされた。キルヤタイムも辱められ、攻め取られた。その砦は辱められ、打ちのめされた。'),
('JPN', '耶利米书', 24, 48, 2, 'もはやモアブの誉れはない。ヘシュボンは、これに悪事を企んでいる。『行って、あの国民を絶ち滅ぼし、無き者にしよう』と。マデメンよ、おまえも黙らされる。剣がおまえの後を追っている。'),
('JPN', '耶利米书', 24, 48, 3, 'ホロナイムから叫び声がする。『暴行だ。大いなる破滅だ』と。'),
('JPN', '耶利米书', 24, 48, 4, 'モアブは打ち破られる。その幼き者たちは叫び声をあげる。'),
('JPN', '耶利米书', 24, 48, 5, 'まことに、ルヒテの坂は嘆きの中にあり、彼らは泣きながら上る。ホロナイムの下り坂では、痛々しい破滅の叫びが聞こえる。'),
('JPN', '耶利米书', 24, 48, 6, '逃げて、自分自身を救え。荒野の中の灌木のようになれ。'),
('JPN', '耶利米书', 24, 48, 7, 'おまえは自分が作ったものと財宝に拠り頼んだので、おまえも捕らえられ、ケモシュはその祭司や首長たちとともに、捕囚となって出て行く。'),
('JPN', '耶利米书', 24, 48, 8, '荒らす者がすべての町に入って来る。町は一つも逃れられない。谷は滅び失せ、平地は根絶やしにされる。──主がそう言われる──'),
('JPN', '耶利米书', 24, 48, 9, 'モアブに翼を与えて、飛び去らせよ。その町々は住む者もなくて荒れ果てる。'),
('JPN', '耶利米书', 24, 48, 10, '主のみわざをおろそかにする者は、のろわれよ。その剣をとどめて血を流さないようにする者は、のろわれよ。'),
('JPN', '耶利米书', 24, 48, 11, 'モアブは若いときから安らかであった。彼はぶどう酒の澱の上によどみ、桶から桶へ空けられたこともなく、捕囚として連れて行かれたこともなかった。それゆえ、その味はそのまま残り、香りも変わらなかった。'),
('JPN', '耶利米书', 24, 48, 12, 'それゆえ、見よ、その時代が来る──主のことば──。そのとき、わたしは彼に酒蔵の番人たちを送る。彼らは彼を桶から移し、彼の桶を空にして、壺を砕く。'),
('JPN', '耶利米书', 24, 48, 13, 'モアブは、ケモシュのゆえに恥を見る。イスラエルの家が、彼らが拠り頼むベテルのゆえに恥を見たように。'),
('JPN', '耶利米书', 24, 48, 14, 'どうして、おまえたちは言えるだろうか。『われわれは勇士、戦いの豪の者だ』と。'),
('JPN', '耶利米书', 24, 48, 15, 'モアブは荒らされ、その町々は襲われて、選り抜きの若者たちが屠り場に下って行く。──その名を万軍の主という王のことば──'),
('JPN', '耶利米书', 24, 48, 16, 'モアブの滅びは近づいた。そのわざわいは速やかにやって来る。'),
('JPN', '耶利米书', 24, 48, 17, '周りの者、その名を知る者はみな、これのために嘆け。『どうして、力ある杖、輝かしい笏が砕かれたのか』と。'),
('JPN', '耶利米书', 24, 48, 18, 'ディボンに住む娘よ。栄光の座から降りて、潤いのない地に座れ。モアブを荒らす者が、おまえのところに攻め上り、おまえの要塞を滅ぼしたからだ。'),
('JPN', '耶利米书', 24, 48, 19, 'アロエルに住む女よ。道の傍らに立って見張れ。逃げる男、逃れる女に尋ねて、『何が起こったのか』と言え。'),
('JPN', '耶利米书', 24, 48, 20, 'モアブは打ちのめされ、辱められた。泣き叫び、わめけ。アルノンで『モアブは荒らされた』と告げよ。'),
('JPN', '耶利米书', 24, 48, 21, 'さばきは次の平地に臨んだ。ホロン、ヤハツ、メファアテ、'),
('JPN', '耶利米书', 24, 48, 22, 'ディボン、ネボ、ベテ・ディブラタイム、'),
('JPN', '耶利米书', 24, 48, 23, 'キルヤタイム、ベテ・ガムル、ベテ・メオン、'),
('JPN', '耶利米书', 24, 48, 24, 'ケリヨテ、ボツラ、モアブの地の遠くの町、近くの町すべてに。'),
('JPN', '耶利米书', 24, 48, 25, 'モアブの角は切り落とされ、その腕は砕かれた──主のことば。'),
('JPN', '耶利米书', 24, 48, 26, '彼を酔わせよ。主に対して高ぶったからだ。モアブは、へどを吐き、彼も笑いものとなる。'),
('JPN', '耶利米书', 24, 48, 27, 'イスラエルは、おまえにとって笑いものではなかったのか。それとも、おまえが彼のことを語るたびに彼に向かって頭を振っていたのは、彼が盗人の間に見つけられたためか。'),
('JPN', '耶利米书', 24, 48, 28, 'モアブの住民よ。町を見捨てて岩間に住め。穴の入り口のそばに巣を作る鳩のようになれ。'),
('JPN', '耶利米书', 24, 48, 29, 'われわれはモアブの高ぶりを、──彼は実に高ぶる者──その傲慢、その高ぶりを、その誇り、その慢心を聞いた。'),
('JPN', '耶利米书', 24, 48, 30, 'わたしは彼の不遜さを知っている。──主のことば──その自慢話は正しくない。その行いも正しくない。'),
('JPN', '耶利米书', 24, 48, 31, 'それゆえ、わたしはモアブのために泣き叫び、モアブ全体のために叫ぶ。人々はキル・ヘレスの人々のために嘆く。'),
('JPN', '耶利米书', 24, 48, 32, 'シブマのぶどうの木よ。わたしはヤゼルの涙にまさり、おまえのために泣く。おまえのつるは伸びて海を越えた。ヤゼルの海に達した。そして、おまえの夏の果物とぶどうの収穫を、荒らす者が襲った。'),
('JPN', '耶利米书', 24, 48, 33, 'モアブの果樹園から、その地から、喜びと楽しみが取り去られる。わたしは石がめから酒を絶えさせた。喜びの声をあげてぶどうを踏む者もなく、ぶどう踏みの喜びの声は、もはや喜びの声ではない。'),
('JPN', '耶利米书', 24, 48, 34, 'ヘシュボンが悲鳴をあげたので、その声はエルアレとヤハツまで、ツォアルからホロナイムやエグラテ・シェリシヤまで届く。ニムリムの水さえ荒廃するからだ。'),
('JPN', '耶利米书', 24, 48, 35, 'わたしはモアブで──主のことば──高き所でいけにえを献げる者を、その神々に犠牲を供える者を取り除く。'),
('JPN', '耶利米书', 24, 48, 36, 'それゆえ、わたしの心は、モアブのために笛のように鳴る。わたしの心は、キル・ヘレスの人々のために笛のように鳴る。彼らの得た富も消え失せたからだ。'),
('JPN', '耶利米书', 24, 48, 37, '実に、彼らは頭の毛をみな剃り、ひげもみな切り取り、手もみな傷つけ、腰に粗布を着けている。'),
('JPN', '耶利米书', 24, 48, 38, 'モアブのあらゆる屋根の上や広場には、嘆きしかない。わたしがモアブを、だれも欲しがらない器のように砕いたからだ──主のことば──。'),
('JPN', '耶利米书', 24, 48, 39, 'どんなにか打ちのめされて、泣き叫ぶことか。どんなにかモアブは恥を見て、背を見せることか。モアブは、その周りのすべての者の笑いものとなり、恐怖のもととなった。」'),
('JPN', '耶利米书', 24, 48, 40, 'まことに、主はこう言われる。「見よ。敵が鷲のように襲いかかり、モアブに対して翼を広げる。'),
('JPN', '耶利米书', 24, 48, 41, '町々は攻め取られ、要害は取られる。その日、モアブの勇士の心は、産みの苦しみにある女の心のようになる。'),
('JPN', '耶利米书', 24, 48, 42, 'モアブは滅ぼし尽くされて、民でなくなる。主に対して高ぶったからだ。'),
('JPN', '耶利米书', 24, 48, 43, 'モアブの住民よ、おまえを恐怖と落とし穴と罠が襲う。──主のことば──'),
('JPN', '耶利米书', 24, 48, 44, 'その恐怖から逃げる者は穴に落ち、穴から這い上る者は罠に捕らえられる。わたしがモアブに彼らの刑罰の年を来させるからだ。──主のことば──'),
('JPN', '耶利米书', 24, 48, 45, 'ヘシュボンの陰には、逃れる者たちが力尽きて立ち止まる。火がヘシュボンから、炎がシホンのうちから出るからだ。それは、モアブのこめかみと、騒がしい子どもの頭の頂を焼く。'),
('JPN', '耶利米书', 24, 48, 46, 'ああ、モアブ。ケモシュの民は滅びる。おまえの息子は捕らわれの身となり、娘は捕虜になって連れ去られるからだ。'),
('JPN', '耶利米书', 24, 48, 47, 'しかし終わりの日に、わたしはモアブを回復させる。──主のことば。」ここまでがモアブへのさばきである。'),
('JPN', '耶利米书', 24, 49, 1, 'アンモン人について。主はこう言われる。「イスラエルには子がいないのか。世継ぎがいないのか。なぜ、ミルコムがガドを所有し、その民が町々に住んでいるのか。'),
('JPN', '耶利米书', 24, 49, 2, 'それゆえ、見よ、その時代が来る。──主のことば──そのとき、わたしはアンモン人のラバに戦いの雄たけびを聞かせる。そこは荒れ果てた廃墟となり、その娘たちは火で焼かれる。イスラエルがその跡を継ぐ。──主は言われる──'),
('JPN', '耶利米书', 24, 49, 3, 'ヘシュボンよ、泣き叫べ。アイが荒らされたから。ラバの娘たちよ、わめけ。粗布をまとえ。嘆いて囲い場の中を走り回れ。ミルコムが、その祭司や首長たちとともに、捕囚として連れて行かれるからだ。'),
('JPN', '耶利米书', 24, 49, 4, '背信の娘よ、おまえの谷には水が流れている。なぜ、その谷を誇るのか。おまえは自分の財宝に拠り頼んで言う。『だれが私のところに来るだろう』と。'),
('JPN', '耶利米书', 24, 49, 5, '見よ。わたしは四方からおまえに恐怖をもたらす。──万軍の神、主のことば──おまえたちはみな散らされて、逃げる者を集める者もいない。'),
('JPN', '耶利米书', 24, 49, 6, 'その後、わたしはアンモン人を回復させる。──主のことば。」'),
('JPN', '耶利米书', 24, 49, 7, 'エドムについて。万軍の主はこう言われる。「テマンには、もう知恵がないのか。賢い者から分別が消え失せ、彼らの知恵は朽ちたのか。'),
('JPN', '耶利米书', 24, 49, 8, 'デダンの住民よ、逃げよ。そこを離れよ。深く潜め。わたしが彼の上にエサウの災難を、彼を罰する時を、もたらすからだ。'),
('JPN', '耶利米书', 24, 49, 9, 'ぶどうを収穫する者がおまえのところに来るなら、彼らは取り残しの実を残さないだろう。盗人が夜中に来るなら、彼らの気がすむまで荒らすだろう。'),
('JPN', '耶利米书', 24, 49, 10, 'しかし、わたしはエサウを裸にし、その隠れ場をあらわにし、身を隠すこともできないようにする。彼の子孫も兄弟も隣人も踏みにじられ、彼はいなくなる。'),
('JPN', '耶利米书', 24, 49, 11, 'おまえのみなしごたちを見捨てよ。わたしが彼らを生かし続ける。おまえのやもめたちは、わたしに拠り頼まなければならない。」'),
('JPN', '耶利米书', 24, 49, 12, 'まことに主はこう言われる。「見よ。その杯を飲むように定められていない者でも、それを必ず飲まなければならないのなら、おまえだけが罰を免れられるだろうか。罰を受けずにはすまされない。おまえは必ず飲まなければならない。'),
('JPN', '耶利米书', 24, 49, 13, 'まことに、わたしは自分にかけて誓う──主のことば──。必ずボツラは恐怖のもと、そしりの的、廃墟、そしてののしりの的となる。そのすべての町は、永遠の廃墟となる。」'),
('JPN', '耶利米书', 24, 49, 14, '私は主から知らせを聞いた。「使者が国々に送られた。『集まって、エドムに攻め入れ。戦いに向けて立ち上がれ。』'),
('JPN', '耶利米书', 24, 49, 15, '見よ。わたしがおまえを国々の中の小さい者、人に蔑まれる者としたからだ。'),
('JPN', '耶利米书', 24, 49, 16, '岩の裂け目に住む者、丘の頂を占める者よ。おまえの脅かしと高慢は、おまえ自身を欺いている。鷲のように巣を高くしても、わたしは、おまえをそこから引きずり降ろす。──主のことば。」'),
('JPN', '耶利米书', 24, 49, 17, 'エドムは廃墟となり、そこを通り過ぎる者はみな呆気にとられ、そのすべての打ち傷を見て嘲笑する。'),
('JPN', '耶利米书', 24, 49, 18, 'ソドムとゴモラとその近隣の町々が破滅したときのように──主は言われる──そこに人は住まず、そこに人の子は宿らない。'),
('JPN', '耶利米书', 24, 49, 19, '「見よ。獅子がヨルダンの密林から常に潤う牧場に上って来るように、わたしは一瞬にして彼らをそこから追い出し、選ばれた人をそこに置く。だれがわたしのようであろうか。だれがわたしを呼びつけるだろうか。だれがわたしの前に立つことができる牧者であろうか。」'),
('JPN', '耶利米书', 24, 49, 20, 'それゆえ、聞け。エドムに対して立てられた主の計画を、テマンの住民に対して練られた策を。必ず、彼らは、群れの中の小さいものまで引きずって行かれ、必ず、彼らの牧場は彼らのことで恐れ惑う。'),
('JPN', '耶利米书', 24, 49, 21, '彼らの倒れる音で地は震え、その悲鳴は葦の海でも聞こえる。'),
('JPN', '耶利米书', 24, 49, 22, '見よ。彼は鷲のように舞い上がっては襲いかかり、ボツラに敵対して翼を広げる。その日、エドムの勇士の心も、産みの苦しみにある女の心のようになる。'),
('JPN', '耶利米书', 24, 49, 23, 'ダマスコについて。「ハマテとアルパデは恥を見た。まことに、彼らは悪い知らせを聞き、海のようにかき乱され、静まることもできない。'),
('JPN', '耶利米书', 24, 49, 24, 'ダマスコは弱り、恐怖にとらわれ、身を翻して逃げた。産婦の陣痛のような苦しみにとらえられて。'),
('JPN', '耶利米书', 24, 49, 25, 'どうして、誉れの町、わたしの喜びの都が捨てられたのか。'),
('JPN', '耶利米书', 24, 49, 26, 'それゆえ、その日、その若い男たちは町の広場に倒れ、その戦士たちもみな、黙らされる。──万軍の主のことば──'),
('JPN', '耶利米书', 24, 49, 27, 'わたしは、ダマスコの城壁に火をつける。その火はベン・ハダドの宮殿を食い尽くす。」'),
('JPN', '耶利米书', 24, 49, 28, 'バビロンの王ネブカドネツァルが討ったケダルとハツォルの王国について。主はこう言われる。「さあ、ケダルへ攻め上り、東の人々を荒らせ。'),
('JPN', '耶利米书', 24, 49, 29, 'その天幕と羊の群れは奪われ、その幕屋も、すべての器も、らくだも、運び去られる。人々は彼らに向かって叫ぶ。『恐怖が取り囲んでいる』と。'),
('JPN', '耶利米书', 24, 49, 30, 'ハツォルの住民よ、逃げよ。遠くへ逃れよ。深く潜め──主のことば──。バビロンの王ネブカドネツァルが、おまえたちに対してはかりごとをめぐらし、おまえたちに対して計略をめぐらしているからだ。'),
('JPN', '耶利米书', 24, 49, 31, 'さあ、安んじて住む穏やかな国に攻め上れ。──主のことば──そこには扉もなく、かんぬきもなく、その民は孤立して住んでいる。'),
('JPN', '耶利米书', 24, 49, 32, '彼らのらくだは獲物になり、その家畜の群れは分捕り物になる。わたしは、もみ上げを刈り上げている者たちを四方に吹き散らし、あらゆる方向から彼らに災難をもたらす。──主のことば──'),
('JPN', '耶利米书', 24, 49, 33, 'ハツォルはとこしえまでも荒れ果てて、ジャッカルの住みかとなる。そこに人は住まず、そこに人の子は宿らない。」'),
('JPN', '耶利米书', 24, 49, 34, 'ユダの王ゼデキヤの治世の初めに、エラムについて預言者エレミヤにあった主のことば。'),
('JPN', '耶利米书', 24, 49, 35, '万軍の主はこう言われる。「見よ。わたしはエラムの力の源であるその弓を折る。'),
('JPN', '耶利米书', 24, 49, 36, 'わたしは天の四隅から、四方の風をエラムに吹きつけさせ、彼らをこの四方の風で吹き散らす。エラムの散らされた者が入らない国はない。'),
('JPN', '耶利米书', 24, 49, 37, 'わたしは、エラムを敵の前に、そのいのちを狙う者たちの前にうろたえさせ、彼らの上にわざわいを、わたしの燃える怒りをその上に下す。──主のことば──わたしは、彼らのうしろに剣を送って、彼らを絶ち滅ぼす。'),
('JPN', '耶利米书', 24, 49, 38, 'わたしはエラムにわたしの王座を置き、王や首長たちをそこから滅ぼす。──主のことば──'),
('JPN', '耶利米书', 24, 49, 39, 'しかし、終わりの日になると、わたしはエラムを回復させる。──主のことば。」'),
('JPN', '耶利米书', 24, 50, 1, '主が預言者エレミヤを通して、バビロンについて、すなわちカルデア人の地について語られたことば。'),
('JPN', '耶利米书', 24, 50, 2, '「国々の間に告げ、旗を掲げて知らせよ。隠さずに言え。『バビロンは攻め取られた。ベルは辱められ、メロダクは打ちのめされた。その像は辱められ、その偶像は打ちのめされた。』'),
('JPN', '耶利米书', 24, 50, 3, 'まことに、北から一つの国がそこに攻め上り、その地を荒れ果てさせた。そこには住むものもない。人から家畜に至るまで逃げ去った。'),
('JPN', '耶利米书', 24, 50, 4, 'その日、その時──主のことば──イスラエルの民もユダの民も、ともにやって来る。彼らは泣きながら歩みつつ、その神、主を尋ね求める。'),
('JPN', '耶利米书', 24, 50, 5, '彼らはシオンを求め、その道に顔を向けて言う。『さあ、私たちは主に連なろう。忘れられることのない永遠の契約によって』と。'),
('JPN', '耶利米书', 24, 50, 6, 'わたしの民は、迷った羊の群れであった。その羊飼いたちが彼らを迷わせ、山々へ連れ去った。彼らは山から丘へと行き巡り、休み場も忘れた。'),
('JPN', '耶利米书', 24, 50, 7, '彼らを見つける者はみな彼らを食らい、彼らの敵は言った。『私たちには責めはない。彼らが、義の住まいである主、彼らの先祖の望みであった主に対して罪を犯したためだ』と。'),
('JPN', '耶利米书', 24, 50, 8, 'バビロンの中から逃げ、カルデア人の地から出て行け。群れの先頭に立つやぎのようになれ。'),
('JPN', '耶利米书', 24, 50, 9, '見よ。わたしは、大国の集団を奮い立たせ、北の地からバビロンに攻め上らせる。彼らはこれに向かって陣備えをし、バビロンはそこから攻め取られる。彼らの矢は熟練した勇士の矢のようで、空しくは帰らない。'),
('JPN', '耶利米书', 24, 50, 10, 'カルデアは略奪され、これを略奪する者はみな、満ち足りる。──主のことば。'),
('JPN', '耶利米书', 24, 50, 11, 'わたしのゆずりの地を略奪する者たちよ。おまえたちは楽しみ、喜び躍り、打穀する雌の子牛のようにはしゃぎ、荒馬のようにいななくが、'),
('JPN', '耶利米书', 24, 50, 12, 'おまえたちの母はひどく恥を見、おまえたちを産んだ者は屈辱を受ける。見よ。彼女は国々のうちの最後のものとなり、荒野となり、砂漠と荒れた地となる。'),
('JPN', '耶利米书', 24, 50, 13, '主の御怒りによって、そこに住む者はなく、ことごとく廃墟と化す。バビロンの近くを通り過ぎる者はみな呆気にとられ、そのすべての打ち傷を見て嘲笑する。'),
('JPN', '耶利米书', 24, 50, 14, 'すべて弓を引く者よ。バビロンの周りに陣備えをし、これを射よ。矢を惜しむな。彼女が主に対して罪を犯したからだ。'),
('JPN', '耶利米书', 24, 50, 15, 'その周りで、ときの声をあげよ。彼女は降伏する。その柱は倒れ、その城壁は壊れる。これこそ主の復讐だ。彼女に復讐せよ。彼女がしたとおりに、これにせよ。'),
('JPN', '耶利米书', 24, 50, 16, '種を蒔く者や、刈り入れの時に鎌を取る者を、バビロンから断ち切れ。虐げる者の剣を避けて、人はそれぞれ自分の民のもとに帰り、自分の土地へ逃げて行く。」'),
('JPN', '耶利米书', 24, 50, 17, 'イスラエルは雄獅子に散らされた羊。先にはアッシリアの王がこれを食らい、今度はついに、その骨をバビロンの王ネブカドネツァルが食らった。'),
('JPN', '耶利米书', 24, 50, 18, 'それゆえ、イスラエルの神、万軍の主はこう言われる。「見よ。わたしはアッシリアの王を罰したように、バビロンの王とその地を罰する。'),
('JPN', '耶利米书', 24, 50, 19, 'わたしはイスラエルをその牧場に帰らせる。彼はカルメルとバシャンで草を食べ、エフライムの山とギルアデで満ち足りる。'),
('JPN', '耶利米书', 24, 50, 20, 'その日、その時──主のことば──イスラエルの咎を探しても、それはない。ユダの罪も見つからない。わたしが残す者を、わたしが赦すからだ。」'),
('JPN', '耶利米书', 24, 50, 21, '「メラタイムの地、ペコデの住民のところに攻め上れ。彼らを追って、殺し、聖絶せよ。──主のことば──すべて、わたしがあなたに命じたとおりに行え。'),
('JPN', '耶利米书', 24, 50, 22, 'その地には戦いの声、大いなる破滅。'),
('JPN', '耶利米书', 24, 50, 23, '全地を打った鉄槌は、どうして折られ、砕かれたのか。バビロンよ、どうして国々の恐怖のもととなったのか。'),
('JPN', '耶利米书', 24, 50, 24, 'バビロンよ。わたしがおまえに罠をかけ、おまえは捕らえられた。おまえはそれを知らなかった。おまえは見つけられて捕まえられた。主に争いを仕掛けたからだ。'),
('JPN', '耶利米书', 24, 50, 25, '主はその倉を開き、その憤りの武器を持ち出した。それは、カルデア人の国での、万軍の神、主の仕事だ。'),
('JPN', '耶利米书', 24, 50, 26, '四方からそこに攻め入れ。その穀物倉を開け。これを麦束のように積み上げ、これを聖絶して、何一つ残すな。'),
('JPN', '耶利米书', 24, 50, 27, 'その雄牛をみな滅ぼせ。屠り場に下らせよ。わざわいだ、彼らは。彼らの日、その刑罰の時が来たからだ。」'),
('JPN', '耶利米书', 24, 50, 28, 'バビロンの地から逃れて来た者の声がする。シオンで、私たちの神、主の復讐のこと、その神殿の復讐のことを告げ知らせている。'),
('JPN', '耶利米书', 24, 50, 29, 'バビロンに対して、射手を呼び集めよ。すべて弓を引く者を。これを囲んで陣を敷き、一人も逃すな。その行いに応じてこれに報い、これがしたとおりに、これにせよ。主に向かい、イスラエルの聖なる方に向かって高ぶったからだ。'),
('JPN', '耶利米书', 24, 50, 30, '「それゆえ、その日、その若い男たちは町の広場に倒れ、その戦士たちもみな、黙らされる。──主のことば──'),
('JPN', '耶利米书', 24, 50, 31, '高ぶる者よ。見よ、わたしはおまえを敵とする。──万軍の神、主のことば──おまえの日、わたしがおまえを罰する時が来たからだ。'),
('JPN', '耶利米书', 24, 50, 32, 'そこで、高ぶる者はつまずき倒れ、これを起こす者もいない。わたしは、その町々に火をつける。火はその周りのものすべてを焼き尽くす。」'),
('JPN', '耶利米书', 24, 50, 33, '万軍の主はこう言われる。「イスラエルの子らとユダの子らは、ともに虐げられている。彼らを捕らえて行った者はみな、彼らを固くつかんで解放することを拒んでいる。」'),
('JPN', '耶利米书', 24, 50, 34, '彼らを贖う方は強い。その名は万軍の主。主は、必ずや彼らの訴えを取り上げて、その地を憩わせるが、バビロンの住民は震え上がらせる。'),
('JPN', '耶利米书', 24, 50, 35, '「剣がカルデア人に下り、──主のことば──バビロンの住民、その首長たち、知恵ある者たちに下る。'),
('JPN', '耶利米书', 24, 50, 36, '剣が易者たちにも下り、彼らは愚かになる。剣がその勇士たちにも下り、彼らは気をくじかれる。'),
('JPN', '耶利米书', 24, 50, 37, '剣が、その馬と車、そこに住む混血の傭兵にも下り、彼らは女たちのようになる。剣がその財宝にも下り、それらはかすめ取られる。'),
('JPN', '耶利米书', 24, 50, 38, '日照りがその水の上に下り、それは涸れる。そこは刻んだ像の地で、偶像に狂っているからだ。'),
('JPN', '耶利米书', 24, 50, 39, 'それゆえ、荒野の獣が山犬とともに住み、だちょうがそこに住む。もはや永久に、人は住まず、代々にわたって、住む者はいない。'),
('JPN', '耶利米书', 24, 50, 40, '神が、ソドムとゴモラと、近隣の町々を滅ぼしたように、──主のことば──そこには人が住まず、そこには人の子が宿らない。'),
('JPN', '耶利米书', 24, 50, 41, '見よ、一つの民が北から来る。大きな国と多くの王が、地の果てという果てから奮い立つ。'),
('JPN', '耶利米书', 24, 50, 42, '彼らは弓と投げ槍を固く握り、残忍で、あわれむことがない。その声は海のようにとどろく。娘バビロンよ。彼らは馬に乗り、一つとなって戦列を整え、おまえを攻める。'),
('JPN', '耶利米书', 24, 50, 43, 'バビロンの王は、彼らのうわさを聞いて気力を失い、苦しみが彼をとらえる。産婦のような激痛が。'),
('JPN', '耶利米书', 24, 50, 44, '見よ。獅子がヨルダンの密林から常に潤う牧場に上って来るように、わたしは一瞬にして彼らをそこから追い出し、選ばれた人をそこに置く。だれがわたしのようであろうか。だれがわたしを呼びつけるだろうか。だれがわたしの前に立つことができる牧者であろうか。」'),
('JPN', '耶利米书', 24, 50, 45, 'それゆえ、聞け。バビロンに対して立てられた主の計画を。カルデア人の国に対して練られた策を。必ず、彼らは、群れの中の小さいものまで引きずって行かれ、必ず、彼らの牧場は彼らのことで恐れ惑う。'),
('JPN', '耶利米书', 24, 50, 46, 'バビロンが捕らえられる音で地は震え、その叫びは国々の間にも聞こえる。'),
('JPN', '耶利米书', 24, 51, 1, '主はこう言われる。「見よ。わたしはバビロンに対し、レブ・カマイの住民に対して、滅ぼす者の霊を奮い立たせ、'),
('JPN', '耶利米书', 24, 51, 2, '他国人たちをバビロンに送る。彼らはこれを吹き散らし、その地を滅ぼす。彼らは、わざわいの日に、四方からこれを攻める。」'),
('JPN', '耶利米书', 24, 51, 3, '射手には弓を引かせるな。よろいを着けて立ち上がらせるな。そこの若い男たちを惜しむな。その全軍を聖絶せよ。'),
('JPN', '耶利米书', 24, 51, 4, '刺し殺された者たちが、カルデア人の地に、突き刺された者たちが、その通りに倒れる。'),
('JPN', '耶利米书', 24, 51, 5, 'しかし、イスラエルもユダも、その神、万軍の主に見捨てられることはない。彼らはイスラエルの聖なる方から離れ、彼らの地は罪過で満ちていたが。'),
('JPN', '耶利米书', 24, 51, 6, 'バビロンの中から逃げ、それぞれ自分自身を救え。バビロンの咎のために絶ち滅ぼされるな。これは、主の復讐の時、主がこれに報いをなさるからだ。'),
('JPN', '耶利米书', 24, 51, 7, 'バビロンは主の手にある金の杯。すべての国々はこれに酔い、国々はそのぶどう酒を飲む。それゆえ、国々は正気を失う。'),
('JPN', '耶利米书', 24, 51, 8, 'バビロンは、たちまち倒れて砕かれる。バビロンのために泣き叫べ。その痛みのために乳香を取れ。もしかしたら、癒やされるかもしれない。'),
('JPN', '耶利米书', 24, 51, 9, '私たちはバビロンを癒やそうとした。だが、それは癒やされなかった。私たちはこれを見捨てて、それぞれ自分の土地へ帰ろう。バビロンへのさばきが、天に達し、大空まで上ったからだ。'),
('JPN', '耶利米书', 24, 51, 10, '主は私たちの義を明らかにされた。さあ、私たちはシオンで、私たちの神、主のみわざを語ろう。'),
('JPN', '耶利米书', 24, 51, 11, '矢を研ぎ、小盾を取れ。主はメディア人の王たちの霊を奮い立たせられる。御思いは、バビロンを滅ぼすこと。それは主の復讐、ご自分の神殿の復讐だからである。'),
('JPN', '耶利米书', 24, 51, 12, 'バビロンの城壁に向かって旗を掲げよ。見張りを強くし、番兵を立て、伏兵を備えよ。主は計画を練って、バビロンの住民について語ったことを実行されるからだ。'),
('JPN', '耶利米书', 24, 51, 13, '大水のほとりに住む、財宝に富む者よ。おまえの最期、おまえの寿命が尽きる時が来た。'),
('JPN', '耶利米书', 24, 51, 14, '万軍の主はご自分にかけて誓われた。「わたしは必ず、バッタの大群のような人々でおまえを満たす。彼らはおまえに対して叫び声をあげる。」'),
('JPN', '耶利米书', 24, 51, 15, '主は、御力をもって地を造り、知恵をもって世界を堅く据え、英知をもって天を張られた。'),
('JPN', '耶利米书', 24, 51, 16, '主の御声に、天では水のざわめきが起こる。主は地の果てから雲を上らせ、雨のために稲妻を造り、ご自分の倉から風を出される。'),
('JPN', '耶利米书', 24, 51, 17, 'すべての人間は愚かで無知だ。すべての金細工人は、彫像のために恥を見る。その鋳た像は偽りで、その中には息がない。'),
('JPN', '耶利米书', 24, 51, 18, 'それは空しいもの、物笑いの種だ。刑罰の時に、それらは滅びる。'),
('JPN', '耶利米书', 24, 51, 19, 'ヤコブの受ける分は、このようなものではない。主は万物を造る方。イスラエルは主のゆずりの民。その御名は万軍の主。'),
('JPN', '耶利米书', 24, 51, 20, '「あなたはわたしの鉄槌、戦いの道具だ。わたしはあなたによって国々を砕き、あなたによって諸王国を滅ぼす。'),
('JPN', '耶利米书', 24, 51, 21, 'あなたによって馬も騎手も砕き、あなたによって戦車も御者も砕き、'),
('JPN', '耶利米书', 24, 51, 22, 'あなたによって男も女も砕き、あなたによって年寄りも幼い者も砕き、あなたによって若い男も若い女も砕き、'),
('JPN', '耶利米书', 24, 51, 23, 'あなたによって牧者も群れも砕き、あなたによって農夫もくびきを負う牛も砕き、あなたによって総督や長官たちも砕く。'),
('JPN', '耶利米书', 24, 51, 24, 'わたしはバビロンとカルデアの全住民に対し、彼らがシオンで行ったすべての悪に、あなたがたの目の前で報復する。──主のことば──'),
('JPN', '耶利米书', 24, 51, 25, '全地を破壊する、破壊の山よ。見よ、わたしはおまえを敵とする。──主のことば──わたしはおまえに手を伸ばし、おまえを岩から突き落とし、おまえを焼けた山とする。'),
('JPN', '耶利米书', 24, 51, 26, 'だれもおまえから石を取って、要の石とする者はなく、礎の石とする者もない。おまえは永遠に荒れ果てた地となる。──主のことば。」'),
('JPN', '耶利米书', 24, 51, 27, 'この地に旗を掲げ、国々の中で角笛を鳴らせ。バビロンに向けて国々を聖別せよ。バビロンに向けて王国を召集せよ。アララテ、ミンニ、アシュケナズを。バビロンに向けて司令官を立て、群がるバッタのように、馬を上らせよ。'),
('JPN', '耶利米书', 24, 51, 28, 'バビロンを攻めるため国々を聖別せよ。メディアの王たち、その総督やすべての長官たち、その支配にある全土の民を。'),
('JPN', '耶利米书', 24, 51, 29, '地は震え、もだえる。主はご計画をバビロンに成し遂げ、バビロンの地を住む者もいない荒れ果てた地とされる。'),
('JPN', '耶利米书', 24, 51, 30, 'バビロンの勇士たちは戦いをやめ、砦の中に座り込む。彼らの力は干からびて、女たちのようになる。その住まいは焼かれ、かんぬきは砕かれる。'),
('JPN', '耶利米书', 24, 51, 31, '飛脚はほかの飛脚に走り次ぎ、使者もほかの使者に取り次いで、バビロンの王に告げて言う。「都は、くまなく攻め取られ、'),
('JPN', '耶利米书', 24, 51, 32, '渡し場も取られ、湿地も火で焼かれ、戦士たちはおじ惑っています」と。'),
('JPN', '耶利米书', 24, 51, 33, 'イスラエルの神、万軍の主が、こう言われるからだ。「娘バビロンは、踏まれるときの打ち場のようだ。もうしばらくで、刈り入れの時が来る。'),
('JPN', '耶利米书', 24, 51, 34, '『バビロンの王ネブカドネツァルは、私を食い尽くし、私をかき乱して、空の器にした。竜のように私を吞み込み、私という美味で腹を満たし、私を洗い流した。』'),
('JPN', '耶利米书', 24, 51, 35, 'シオンに住む者は言え。『私と私の肉親になされた暴虐が、バビロンに降りかかれ』と。エルサレムは言え。『私の血がカルデアの住民に注がれよ』と。」'),
('JPN', '耶利米书', 24, 51, 36, 'それゆえ、主はこう言われる。「見よ。わたしはあなたの訴えを取り上げ、あなたのために報復する。バビロンの海を干上がらせ、その泉を涸らす。'),
('JPN', '耶利米书', 24, 51, 37, 'バビロンは石くれの山、ジャッカルの住みかとなり、恐怖のもと、また嘲りの的となって、住む者はいなくなる。'),
('JPN', '耶利米书', 24, 51, 38, '彼らはともに、若獅子のように吼え、獅子の子のようにうなる。'),
('JPN', '耶利米书', 24, 51, 39, '彼らが苛立っているとき、わたしは彼らに宴会を開き、彼らを酔わせる。彼らは陽気になり、永遠の眠りについて、目覚めることはない。──主のことば──'),
('JPN', '耶利米书', 24, 51, 40, 'わたしは彼らを、子羊のように、また雄羊か雄やぎのように、屠り場に下らせる。'),
('JPN', '耶利米书', 24, 51, 41, 'ああ、バビロンは攻め取られ、全地の誉れであった者は捕らえられた。ああ、バビロンは国々の間で恐怖のもととなった。'),
('JPN', '耶利米书', 24, 51, 42, '海がバビロンの上にのしかかり、波のざわめきにおおわれた。'),
('JPN', '耶利米书', 24, 51, 43, 'その町々は荒れ果てた地となり、その地は砂漠と荒れ地となり、だれも住まず、人の子が通りもしないところとなる。'),
('JPN', '耶利米书', 24, 51, 44, 'わたしはバビロンでベルを罰し、これが吞み込んだ物を吐き出させる。国々はもう、そこに流れ込むことはない。バビロンの城壁さえも倒れてしまった。'),
('JPN', '耶利米书', 24, 51, 45, 'わたしの民よ、その中から出よ。主の燃える怒りから逃れ、それぞれ自分自身を救え。'),
('JPN', '耶利米书', 24, 51, 46, 'そうでないと、あなたがたの心は弱まり、この地に聞こえるうわさを恐れることになる。今年、うわさが立ち、その後、次の年にも、うわさは立つ。この地には暴虐があり、支配者はほかの支配者に立ち向かう。'),
('JPN', '耶利米书', 24, 51, 47, 'それゆえ、見よ、その時代が来る。そのとき、わたしはバビロンの彫像を罰する。この全土は恥を見、刺し殺された者はみなそのただ中に倒れる。'),
('JPN', '耶利米书', 24, 51, 48, '天と地とその中にあるすべてのものは、バビロンのことで喜び歌う。北からこれに向かって、荒らす者たちが来るからだ──主のことば──。'),
('JPN', '耶利米书', 24, 51, 49, 'イスラエルの刺し殺された者たちよ、バビロンは必ず倒れる。バビロンによって全地の刺し殺された者たちが倒れたように。'),
('JPN', '耶利米书', 24, 51, 50, '剣を逃れた者よ、行け。立ち止まるな。遠くから主を思い出せ。エルサレムを心に思い浮かべよ。'),
('JPN', '耶利米书', 24, 51, 51, '『私たちは、そしりを聞いて、恥を見た。恥辱が私たちの顔をおおった。他国人が主の宮の聖所に入ったからだ。』'),
('JPN', '耶利米书', 24, 51, 52, 'それゆえ、見よ、その時代が来る。──主のことば──そのとき、わたしはその彫像を罰する。刺された者がその全土でうめく。'),
('JPN', '耶利米书', 24, 51, 53, 'たとえバビロンが天に上っても、たとえ、砦を高くして近寄りがたくしても、わたしのもとから荒らす者たちがそこへ行く。──主のことば。」'),
('JPN', '耶利米书', 24, 51, 54, 'バビロンから、叫ぶ声がする。カルデア人の地から、大いなる破滅の音が。'),
('JPN', '耶利米书', 24, 51, 55, '主がバビロンを荒らして、そこから大いなる声を絶やされるからだ。その波は大水のように鳴りとどろき、その声は鳴りどよめく。'),
('JPN', '耶利米书', 24, 51, 56, 'まことに、荒らす者がバビロンを攻めに来て、その勇士たちは捕らえられ、その弓も折られる。主は報復の神であり、必ず報復されるからだ。'),
('JPN', '耶利米书', 24, 51, 57, '「わたしは、その首長たちや知恵のある者、総督や長官、勇士たちを酔わせる。彼らは永遠の眠りについて、目覚めることはない──その名を万軍の主という王のことば。」'),
('JPN', '耶利米书', 24, 51, 58, '万軍の主はこう言われる。「バビロンの厚い城壁は完全にくつがえされ、その高い門にも火が放たれる。国々の民は無駄に労し、諸国の民は、ただ火に焼かれて、力尽きる。」'),
('JPN', '耶利米书', 24, 51, 59, 'マフセヤの子ネリヤの子セラヤが、ユダの王ゼデキヤとともに、その治世の第四年にバビロンへ行ったとき、預言者エレミヤがセラヤに命じたことば。そのとき、セラヤは宿営の長であった。'),
('JPN', '耶利米书', 24, 51, 60, 'エレミヤはバビロンに下るすべてのわざわい、すなわち、バビロンについて記された、これらすべてのことばを一つの書物に記した。'),
('JPN', '耶利米书', 24, 51, 61, 'エレミヤはセラヤに言った。「あなたがバビロンに入ったときに、これらすべてのことばをよく注意して読み、'),
('JPN', '耶利米书', 24, 51, 62, 'こう言いなさい。『主よ。あなたはこの場所について、これを滅ぼし、人から家畜に至るまで住むものがないようにし、永遠に荒れ果てた地とする、と語られました。』'),
('JPN', '耶利米书', 24, 51, 63, 'そしてこの書物を読み終えたら、それに石を結び付けて、ユーフラテス川の中に投げ入れ、'),
('JPN', '耶利米书', 24, 51, 64, 'こう言いなさい。『このように、バビロンは沈み、浮かび上がれない。わたしがもたらすわざわいを前にして。彼らは力尽きる。』」ここまでが、エレミヤのことばである。'),
('JPN', '耶利米书', 24, 52, 1, 'ゼデキヤは二十一歳で王となり、エルサレムで十一年間、王であった。彼の母の名はハムタルといい、リブナ出身のエレミヤの娘であった。'),
('JPN', '耶利米书', 24, 52, 2, '彼は、すべてエホヤキムがしたように、主の目に悪であることを行った。'),
('JPN', '耶利米书', 24, 52, 3, '実に、エルサレムとユダが主の前から投げ捨てられるに至ったのは、主の怒りによるものであった。その後、ゼデキヤはバビロンの王に反逆した。'),
('JPN', '耶利米书', 24, 52, 4, 'ゼデキヤの治世の第九年、第十の月の十日に、バビロンの王ネブカドネツァルは、その全軍勢を率いてエルサレムを攻めに来て、これに対して陣を敷き、周囲に塁を築いた。'),
('JPN', '耶利米书', 24, 52, 5, 'こうして都はゼデキヤ王の第十一年まで包囲されていた。'),
('JPN', '耶利米书', 24, 52, 6, '第四の月の九日、都の中で食糧難がひどくなり、民衆に食物がなくなった。'),
('JPN', '耶利米书', 24, 52, 7, 'そのとき、都は破られ、戦士たちはみな逃げて、夜のうちに、王の園に近い二重の城壁の間にある、門の道から都を出た。カルデア人が都を包囲していたので、彼らはアラバへの道を行った。'),
('JPN', '耶利米书', 24, 52, 8, 'カルデアの軍勢は王の後を追い、エリコの草原でゼデキヤに追いついた。すると、王の軍隊はみな王から離れて散ってしまった。'),
('JPN', '耶利米书', 24, 52, 9, 'カルデアの軍勢は王を捕らえ、ハマテの地のリブラにいるバビロンの王のところへ彼を連れ上った。バビロンの王は彼に宣告を下した。'),
('JPN', '耶利米书', 24, 52, 10, 'バビロンの王は、ゼデキヤの息子たちを彼の目の前で虐殺し、ユダの首長たちもみなリブラで虐殺した。'),
('JPN', '耶利米书', 24, 52, 11, 'さらに、ゼデキヤの目をつぶし、彼を青銅の足かせにつないだ。バビロンの王は、彼をバビロンへ連れて行き、彼を死ぬ日まで獄屋に入れておいた。'),
('JPN', '耶利米书', 24, 52, 12, '第五の月の十日、バビロンの王ネブカドネツァル王の第十九年のこと、バビロンの王の家来、親衛隊の長ネブザルアダンがエルサレムに来て、'),
('JPN', '耶利米书', 24, 52, 13, '主の宮と王宮とエルサレムのすべての家を焼き、そのおもだった建物をことごとく火で焼いた。'),
('JPN', '耶利米书', 24, 52, 14, '親衛隊の長と一緒にいたカルデアの全軍勢は、エルサレムを取り巻く城壁すべてを打ち壊した。'),
('JPN', '耶利米书', 24, 52, 15, '親衛隊の長ネブザルアダンは、民の貧しい者たちの一部と、都に残されていた残りの民、バビロンの王に降伏した投降者たち、そのほか技術に秀でた人たちを捕らえ移した。'),
('JPN', '耶利米书', 24, 52, 16, 'しかし、親衛隊の長ネブザルアダンは、その地の貧しい民の一部を残し、ぶどうを作る者と農夫にした。'),
('JPN', '耶利米书', 24, 52, 17, 'カルデア人は、主の宮の青銅の柱と、車輪付きの台と、主の宮にある青銅の「海」を砕いて、その青銅をみなバビロンへ運んだ。'),
('JPN', '耶利米书', 24, 52, 18, 'また、灰壺、十能、芯取りばさみ、鉢、平皿、奉仕に用いるすべての青銅の器具を奪った。'),
('JPN', '耶利米书', 24, 52, 19, 'また親衛隊の長は、小鉢、火皿、鉢、灰壺、燭台、平皿、水差しなど、純金や純銀のものを奪った。'),
('JPN', '耶利米书', 24, 52, 20, 'ソロモン王が主の宮のために作った二本の柱、一つの「海」、車輪付きの台の下にある十二の青銅の牛、これらすべての物の青銅の重さは、量りきれなかった。'),
('JPN', '耶利米书', 24, 52, 21, 'その柱は、一本の柱の高さが十八キュビト、その周囲は十二キュビト、その厚さは指四本分で、中は空洞になっていた。'),
('JPN', '耶利米书', 24, 52, 22, 'その上の柱頭は青銅で、一つの柱頭の高さは五キュビトであった。柱頭の周りに格子細工とざくろがあって、すべて青銅であった。もう一本の柱も、そのざくろも、これと同様であった。'),
('JPN', '耶利米书', 24, 52, 23, '周りには九十六のざくろがあり、周りの格子細工の上には全部で百のざくろがあった。'),
('JPN', '耶利米书', 24, 52, 24, '親衛隊の長は、祭司のかしらセラヤと次席祭司ゼパニヤと三人の入り口を守る者を捕らえ、'),
('JPN', '耶利米书', 24, 52, 25, '戦士たちの指揮官であった一人の宦官、都にいた王の七人の側近、民衆を徴兵する軍の長の書記、そして都の中にいた民衆六十人を、都から連れ去った。'),
('JPN', '耶利米书', 24, 52, 26, '親衛隊の長ネブザルアダンは彼らを捕らえ、リブラにいるバビロンの王のもとへ連れて行った。'),
('JPN', '耶利米书', 24, 52, 27, 'バビロンの王はハマテの地のリブラで、彼らを打ち殺した。こうして、ユダはその国から捕らえ移された。'),
('JPN', '耶利米书', 24, 52, 28, 'ネブカドネツァルが捕らえ移した民の数は次のとおりである。第七年には、三千二十三人のユダヤ人。'),
('JPN', '耶利米书', 24, 52, 29, 'ネブカドネツァルの第十八年には、エルサレムから八百三十二人。'),
('JPN', '耶利米书', 24, 52, 30, 'ネブカドネツァルの第二十三年には、親衛隊の長ネブザルアダンが、七百四十五人のユダヤ人を捕らえ移し、その合計は四千六百人であった。'),
('JPN', '耶利米书', 24, 52, 31, 'ユダの王エホヤキンが捕らえ移されて三十七年目の第十二の月の二十五日、バビロンの王エビル・メロダクは、即位した年のうちにユダの王エホヤキンを呼び戻して、獄屋から出し、'),
('JPN', '耶利米书', 24, 52, 32, '優しいことばをかけ、バビロンで彼とともにいた王たちの位よりも、彼の位を高くした。'),
('JPN', '耶利米书', 24, 52, 33, '彼は囚人の服を脱ぎ、その一生の間、いつも王の前で食事をした。'),
('JPN', '耶利米书', 24, 52, 34, '彼の生活費は、死ぬ日までその一生の間、日々の分をいつもバビロンの王から支給されていた。'),
('JPN', '耶利米哀歌', 25, 1, 1, 'ああ、ひとり寂しく座っている。人で満ちていた都が。彼女はやもめのようになった。国々の間で力に満ちていた者、もろもろの州の女王が、苦役に服することになった。'),
('JPN', '耶利米哀歌', 25, 1, 2, '彼女は泣きながら夜を過ごす。涙が頬を伝っている。彼女が愛する者たちの中には、慰める者はだれもいない。その友もみな裏切り、彼女の敵となってしまった。'),
('JPN', '耶利米哀歌', 25, 1, 3, '悩みと多くの労役の後に、ユダは捕らえ移された。彼女は諸国の中に住み、憩いを見出すことがない。追い迫る者たちはみな追いついた。彼女が苦しみのただ中にあるときに。'),
('JPN', '耶利米哀歌', 25, 1, 4, 'シオンへの道は喪に服し、例祭に行く者はだれもいない。その門はみな荒れ果て、その祭司たちはうめく。おとめたちは憂いに沈む。シオンが苦しんでいるのだ。'),
('JPN', '耶利米哀歌', 25, 1, 5, '彼女に逆らう者がかしらとなり、彼女の敵が栄えている。彼女の多くの背きのゆえに、主が憂いを与えられたのだ。幼子たちも、捕らわれの身となり、逆らう者の前に出て行った。'),
('JPN', '耶利米哀歌', 25, 1, 6, '娘シオンから、そのすべての輝きが去った。彼女の首長たちは、青草を見出せない鹿のようになり、追い迫る者の前をただ力無く歩んで行った。'),
('JPN', '耶利米哀歌', 25, 1, 7, 'エルサレムは思い出す。苦しみとさすらいの日々にあって、昔から持っていた自分のすべての宝を。その民が敵の手に倒れ、だれも助ける者がいないとき、敵はその破滅を見て、あざ笑う。'),
('JPN', '耶利米哀歌', 25, 1, 8, 'エルサレムは罪に罪を重ねた。そのため、汚らわしいものとなった。彼女を尊んだ者たちはみな、その裸を見て、これを卑しめる。彼女もうめいて、その背を向ける。'),
('JPN', '耶利米哀歌', 25, 1, 9, '彼女の汚れは裾に付いている。彼女は自分の末路を考えない。それで、驚くほど落ちぶれて、だれも彼女を慰めない。「主よ、私の苦しみを顧みてください。敵が勝ち誇っています。」'),
('JPN', '耶利米哀歌', 25, 1, 10, '敵は、彼女が宝としているものすべてにその手を伸ばした。諸国の民がその聖所に入るのを彼女は見た。あなたの集いに加わってはならないと、あなたが命じた者たちが。'),
('JPN', '耶利米哀歌', 25, 1, 11, '彼女の民はみなうめき、食べ物を探している。気力を取り戻そうとして、自分の宝を食物に換えている。「主よ、よく見てください。私は卑しい女になりました。」'),
('JPN', '耶利米哀歌', 25, 1, 12, 'あなたがたには関係がないのか。道行くすべての人よ、よく見よ。このような苦痛がほかにあるか。私が被り、主の燃える怒りの日に主が私を悩ませたような苦痛が。'),
('JPN', '耶利米哀歌', 25, 1, 13, '主はいと高き所から私の骨の中に火を送り込まれた。私の足もとに網を張り、私が背を向けるようにされた。私を荒れすさんだ女、終日、病んでいる女とされた。'),
('JPN', '耶利米哀歌', 25, 1, 14, '私の背きのくびきは重く、主の手で、私に結びつけられ、私の首の上に載せられた。主は私の力をくじき、私を渡された。私が立ち向かえない者の手に。'),
('JPN', '耶利米哀歌', 25, 1, 15, '主は、私のうちの強者たちをみな追い払われた。私を標的として「例祭」を呼びかけ、私の若い男たちを滅ぼされた。主は、ぶどう踏みをするように、おとめ、娘ユダを踏みつぶされた。'),
('JPN', '耶利米哀歌', 25, 1, 16, 'これらのことで、私は泣いている。私の目、この目から涙があふれる。元気づけ、慰めてくれる者が、私から遠く離れたからだ。敵に圧倒されて、私の子らは啞然とする。'),
('JPN', '耶利米哀歌', 25, 1, 17, 'シオンが両手を差し出しても、これを慰める者はいない。主は、ヤコブの周囲の者たちが彼の敵となるように命じられた。エルサレムは彼らの間で汚らわしいものとなった。'),
('JPN', '耶利米哀歌', 25, 1, 18, '主は正しい方である。しかし、私は主の命令に逆らった。すべての国々の民よ、聞け。私の苦痛を見よ。若い女たちも、若い男たちも、捕らわれの身となって行った。'),
('JPN', '耶利米哀歌', 25, 1, 19, '私は、私を愛する者たちを呼んだが、彼らは私を欺いた。私の祭司も長老たちも、都の中で息絶えた。気力を取り戻そうとして、食物を探していたときに。'),
('JPN', '耶利米哀歌', 25, 1, 20, '「主よ、ご覧ください。私は苦しみの中にあり、はらわたはかき回され、私の心は私のうちで打ちのめされています。私が逆らい続けたからです。外では剣が子を奪い、家の中は死のようです。'),
('JPN', '耶利米哀歌', 25, 1, 21, '私のうめきを聞いても、慰めてくれる者はだれもいません。敵はみな、私のわざわいを聞いて喜びました。あなたがそうなさったからです。あなたが告げられた日を来させてください。彼らも私と同じようになるために。'),
('JPN', '耶利米哀歌', 25, 1, 22, '彼らの悪のすべてが、御前に出されますように。そして彼らに報いてください。あなたが、私のすべての背きに対して報いを返されたように。私のうめきは大きく、私の心は弱っています。」'),
('JPN', '耶利米哀歌', 25, 2, 1, 'ああ、主は娘シオンを御怒りの雲でおおい、イスラエルの栄えを天から地に投げ落とし、御怒りの日に、ご自分の足台を思い出されなかった。'),
('JPN', '耶利米哀歌', 25, 2, 2, 'ヤコブのすべての住まいを主は吞み込み、容赦なさらなかった。憤って娘ユダの要塞を打ち壊し、地に打ち倒して、王国とその首長たちを汚された。'),
('JPN', '耶利米哀歌', 25, 2, 3, '燃える怒りをもって、イスラエルのすべての角を折り、敵の前で右の手を引き戻し、あたりを焼き尽くす炎のように、ヤコブを焼かれた。'),
('JPN', '耶利米哀歌', 25, 2, 4, '主は敵のようにして、弓を引き絞り、はむかう者のようにして、右の手でしっかり構え、いとしい者たちをみな虐殺した。主は娘シオンの天幕に、火のように憤りを注がれた。'),
('JPN', '耶利米哀歌', 25, 2, 5, '主は、敵のようになって、イスラエルを吞み込まれた。そのすべての宮殿を吞み込み、その要塞を破壊し、娘ユダにうめきと嘆きを増し加えられた。'),
('JPN', '耶利米哀歌', 25, 2, 6, '主は、園にするように、ご自分の幕屋を荒らし、例祭の場所を滅ぼされた。主はシオンでの例祭と安息日を忘れさせ、激しい憤りをもって、王と祭司を退けられた。'),
('JPN', '耶利米哀歌', 25, 2, 7, '主は、その祭壇を拒み、聖所を退け、その宮殿の城壁を敵の手に引き渡された。例祭の日のように、彼らは主の宮で声をあげた。'),
('JPN', '耶利米哀歌', 25, 2, 8, '主は、娘シオンの城壁を打ち壊そうと決め、測り縄でこれを測り、滅ぼすことから手を引かれなかった。塁と城壁は悲しみ嘆き、ともに崩れ落ちた。'),
('JPN', '耶利米哀歌', 25, 2, 9, '彼女の城門は地に沈み込み、主はそのかんぬきを打ち壊して砕かれた。その王も首長たちも異邦の民の中にあり、もはや律法はなく、預言者たちも、主からの幻を見出さなかった。'),
('JPN', '耶利米哀歌', 25, 2, 10, '娘シオンの長老たちは、地に座して黙し、頭にちりをかぶり、身に粗布をまとった。エルサレムのおとめたちは、頭を地に付くほど垂れた。'),
('JPN', '耶利米哀歌', 25, 2, 11, '私の目は涙でかすみ、はらわたはかき回され、肝は地に注ぎ出された。私の民の娘の破滅のために。幼子や乳飲み子が都の広場で衰え果てている。'),
('JPN', '耶利米哀歌', 25, 2, 12, '彼らは母親に言い続ける。穀物とぶどう酒はどこにあるのかと。町の広場で負傷した者のように衰え果てたときに、母親の懐で息絶えそうなときに。'),
('JPN', '耶利米哀歌', 25, 2, 13, '娘エルサレムよ。あなたのことをどう証言し、何になぞらえよう。おとめ、娘シオンよ。あなたを何に比べて、あなたを慰めよう。実に、あなたの傷は海のように大きい。だれがあなたを癒やすことができよう。'),
('JPN', '耶利米哀歌', 25, 2, 14, 'あなたの預言者たちは、あなたについて、むなしい、ごまかしの幻を見た。あなたの咎を暴いて、あなたを元どおりにしようとはせず、あなたについて、むなしい宣告と、惑わすことばの幻を見た。'),
('JPN', '耶利米哀歌', 25, 2, 15, '道行く人はみな、あなたに向かって手を打ち鳴らし、娘エルサレムを嘲って頭を振り、「これが、美の極み、全地の喜びと言われた都か」と言う。'),
('JPN', '耶利米哀歌', 25, 2, 16, 'あなたの敵はみな、あなたに向かって大きく口を開け、口笛を吹き、歯をむき出しにして言う。「われわれがこれを吞み込んだ。ああ、これこそ待ち望んでいた日。これに巡り会い、じかに見た」と。'),
('JPN', '耶利米哀歌', 25, 2, 17, '主は計画したことを行い、昔から命じていた自らのことばを成し遂げられた。滅ぼして、容赦せず、あなたのことで敵を喜ばせ、逆らう者の角を高く上げられた。'),
('JPN', '耶利米哀歌', 25, 2, 18, '彼らは主に向かって心の底から叫んだ。娘シオンの城壁よ、昼も夜も、川のように涙を流せ。自分に休みを与えるな。あなたの瞳を休ませてはならない。'),
('JPN', '耶利米哀歌', 25, 2, 19, '夜、見張りの始まりに、立って大声で叫べ。あなたの心を主の前に、水のように注ぎ出せ。あなたの幼子たちのいのちのために、主に向かって両手を上げよ。彼らは街頭のいたるところで、飢えのために衰えきっている。'),
('JPN', '耶利米哀歌', 25, 2, 20, '「主よ、よくご覧ください。だれにこのような仕打ちをなさったのかを。女たちが、自分の胎の実を、養い育てた幼子を食べてよいでしょうか。祭司や預言者が、主の聖所で虐殺されてよいでしょうか。'),
('JPN', '耶利米哀歌', 25, 2, 21, '幼い者も年寄りも道端で地に横たわり、若い女たちも若い男たちも剣に倒れました。あなたは御怒りの日に虐殺し、屠り、容赦されませんでした。'),
('JPN', '耶利米哀歌', 25, 2, 22, 'あなたは、例祭の日のように、私の恐怖を、四方から呼び集めました。そのため主の御怒りの日には、生き残る者も逃れる者もいませんでした。私が養い育てた者たちを、私の敵は滅ぼし尽くしました。」'),
('JPN', '耶利米哀歌', 25, 3, 1, '私は、主の激しい怒りのむちを受けて苦しみにあった者。'),
('JPN', '耶利米哀歌', 25, 3, 2, '主は、私を連れ去り、光のない闇を歩ませ、'),
('JPN', '耶利米哀歌', 25, 3, 3, '御手をもって一日中、繰り返し私を攻められた。'),
('JPN', '耶利米哀歌', 25, 3, 4, '主は、私の肉と皮をすり減らし、私の骨を砕き、'),
('JPN', '耶利米哀歌', 25, 3, 5, '私に対して陣を敷き、苦味と苦難で私を取り巻き、'),
('JPN', '耶利米哀歌', 25, 3, 6, '私を暗い所に住まわせられた。はるか昔に死んだ者のように。'),
('JPN', '耶利米哀歌', 25, 3, 7, '主は私を囲いに入れて出られなくし、私の青銅の足かせを重くされた。'),
('JPN', '耶利米哀歌', 25, 3, 8, '私が助けを求めて叫んでも、主は私の祈りを聞き入れず、'),
('JPN', '耶利米哀歌', 25, 3, 9, '私の道を切り石で囲み、私の通り道をねじ曲げられた。'),
('JPN', '耶利米哀歌', 25, 3, 10, '主は、私には待ち伏せる熊、隠れたところにいる獅子。'),
('JPN', '耶利米哀歌', 25, 3, 11, '主は私を道から外れさせ、私を引き裂き、無残な姿にされた。'),
('JPN', '耶利米哀歌', 25, 3, 12, '弓を引き絞り、私を矢の的のようにして、'),
('JPN', '耶利米哀歌', 25, 3, 13, '矢筒の矢を、私の腎臓に射込まれた。'),
('JPN', '耶利米哀歌', 25, 3, 14, '私は一日中、民全体の笑いもの、彼らの嘲りの歌となった。'),
('JPN', '耶利米哀歌', 25, 3, 15, '主は私を苦菜で満腹にし、苦よもぎで酔わせ、'),
('JPN', '耶利米哀歌', 25, 3, 16, '私の歯を砂利で砕き、灰の中で私を踏みつけられた。'),
('JPN', '耶利米哀歌', 25, 3, 17, '私のたましいは平安から見放され、私は幸せを忘れてしまった。'),
('JPN', '耶利米哀歌', 25, 3, 18, '私は言った。「私の誉れと、主から受けた望みは消え失せた」と。'),
('JPN', '耶利米哀歌', 25, 3, 19, '私の苦しみとさすらいの思い出は、苦よもぎと苦味だけ。'),
('JPN', '耶利米哀歌', 25, 3, 20, '私のたましいは、ただこれを思い出しては沈む。'),
('JPN', '耶利米哀歌', 25, 3, 21, '私はこれを心に思い返す。それゆえ、私は言う。「私は待ち望む。'),
('JPN', '耶利米哀歌', 25, 3, 22, '主の恵みを。」実に、私たちは滅び失せなかった。主のあわれみが尽きないからだ。'),
('JPN', '耶利米哀歌', 25, 3, 23, 'それは朝ごとに新しい。「あなたの真実は偉大です。'),
('JPN', '耶利米哀歌', 25, 3, 24, '主こそ、私への割り当てです」と私のたましいは言う。それゆえ、私は主を待ち望む。'),
('JPN', '耶利米哀歌', 25, 3, 25, '主はいつくしみ深い。主に望みを置く者、主を求めるたましいに。'),
('JPN', '耶利米哀歌', 25, 3, 26, '主の救いを静まって待ち望むのは良い。'),
('JPN', '耶利米哀歌', 25, 3, 27, '人が、若いときに、くびきを負うのは良い。'),
('JPN', '耶利米哀歌', 25, 3, 28, 'それを負わされたなら、ひとり静まって座っていよ。'),
('JPN', '耶利米哀歌', 25, 3, 29, '口を土のちりにつけよ。もしかすると希望があるかもしれない。'),
('JPN', '耶利米哀歌', 25, 3, 30, '自分を打つ者には頬を向け、十分に恥辱を受けよ。'),
('JPN', '耶利米哀歌', 25, 3, 31, '主は、いつまでも見放してはおられない。'),
('JPN', '耶利米哀歌', 25, 3, 32, '主は、たとえ悲しみを与えたとしても、その豊かな恵みによって、人をあわれまれる。'),
('JPN', '耶利米哀歌', 25, 3, 33, '主が人の子らを、意味もなく、苦しめ悩ませることはない。'),
('JPN', '耶利米哀歌', 25, 3, 34, '地上の捕らわれ人をみな足の下に踏みにじり、'),
('JPN', '耶利米哀歌', 25, 3, 35, '人の権利を、いと高き方の前で曲げ、'),
('JPN', '耶利米哀歌', 25, 3, 36, '訴訟で人を不当に扱うのを、主は見ておられないだろうか。'),
('JPN', '耶利米哀歌', 25, 3, 37, '主が命じられたのでなければ、だれが語って、このようなことが起きたのか。'),
('JPN', '耶利米哀歌', 25, 3, 38, 'わざわいも幸いも、いと高き方の御口から出るのではないか。'),
('JPN', '耶利米哀歌', 25, 3, 39, '生きている人間は、なぜ不平を言い続けるのか。自分自身の罪のゆえにか。'),
('JPN', '耶利米哀歌', 25, 3, 40, '自分たちの道を尋ね調べて、主のみもとに立ち返ろう。'),
('JPN', '耶利米哀歌', 25, 3, 41, '自分たちの心を、両手とともに、天におられる神に向けて上げよう。'),
('JPN', '耶利米哀歌', 25, 3, 42, '「私たちは背き、逆らいました。あなたは赦してくださいませんでした。'),
('JPN', '耶利米哀歌', 25, 3, 43, 'あなたは、怒りを身にまとい、私たちを追い、容赦なく殺されました。'),
('JPN', '耶利米哀歌', 25, 3, 44, 'あなたは雲を身にまとい、私たちの祈りをさえぎり、'),
('JPN', '耶利米哀歌', 25, 3, 45, '私たちを諸国の民の間で、ごみ屑とされました。」'),
('JPN', '耶利米哀歌', 25, 3, 46, '私たちの敵はみな、私たちに向かって口を大きく開け、')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '耶利米哀歌', 25, 3, 47, '恐れと落とし穴、荒廃と破滅が私たちに臨んだ。'),
('JPN', '耶利米哀歌', 25, 3, 48, '娘である私の民の破滅のために、私の目から涙が川のように流れる。'),
('JPN', '耶利米哀歌', 25, 3, 49, '私の目は絶えず涙を流して、やむことなく、'),
('JPN', '耶利米哀歌', 25, 3, 50, '主が天から見下ろして、顧みられるときまで続く。'),
('JPN', '耶利米哀歌', 25, 3, 51, '私の目は、都のすべての娘たちを見て、この心を苦しめる。'),
('JPN', '耶利米哀歌', 25, 3, 52, '私の敵たちは、わけもなく、鳥を狙うように、私をつけ狙った。'),
('JPN', '耶利米哀歌', 25, 3, 53, '私を穴に落として、いのちを滅ぼそうとし、私に石を投げつけた。'),
('JPN', '耶利米哀歌', 25, 3, 54, '水は私の頭の上にあふれ、私は「断ち切られた」と言った。'),
('JPN', '耶利米哀歌', 25, 3, 55, '「主よ、私は御名を呼びました。穴の深みから。'),
('JPN', '耶利米哀歌', 25, 3, 56, 'あなたは私の声を聞かれました。私のうめき声に、私の叫びに、耳を閉ざさないでください。'),
('JPN', '耶利米哀歌', 25, 3, 57, '私があなたを呼び求めると、あなたは近づき、『恐れるな』と言われました。'),
('JPN', '耶利米哀歌', 25, 3, 58, '主よ。あなたは私のたましいの訴えを取り上げ、私のいのちを贖ってくださいました。'),
('JPN', '耶利米哀歌', 25, 3, 59, '主よ。あなたは、私が虐げられるのをご覧になりました。どうか、私の訴えを正しくさばいてください。'),
('JPN', '耶利米哀歌', 25, 3, 60, 'あなたは、私に対する彼らの復讐を、彼らの企みのすべてをご覧になりました。'),
('JPN', '耶利米哀歌', 25, 3, 61, '主よ。あなたは、私に対する彼らのそしりを、彼らの企みのすべてを聞かれました。'),
('JPN', '耶利米哀歌', 25, 3, 62, '私に向かい立つ者たちの唇と嘲りが、一日中、私に向けられています。'),
('JPN', '耶利米哀歌', 25, 3, 63, '彼らの起き伏しに目を留めてください。私は彼らのからかいの歌となっています。'),
('JPN', '耶利米哀歌', 25, 3, 64, '主よ。彼らの手のわざに応じて、彼らに報復し、'),
('JPN', '耶利米哀歌', 25, 3, 65, '彼らの心に覆いをかけ、彼らに、あなたののろいを下してください。'),
('JPN', '耶利米哀歌', 25, 3, 66, '御怒りをもって彼らを追い、主の天の下から根絶やしにしてください。」'),
('JPN', '耶利米哀歌', 25, 4, 1, 'ああ、金は黒ずみ、美しい黄金は色あせ、聖なる石は、道端のいたるところに投げ捨てられている。'),
('JPN', '耶利米哀歌', 25, 4, 2, '高価であり、純金で値踏みされるシオンの子らが、ああ、土の壺、陶器師の手のわざと見なされている。'),
('JPN', '耶利米哀歌', 25, 4, 3, 'ジャッカルさえも乳房をふくませて、その子に乳を飲ませる。しかし、娘である私の民は、荒野のだちょうのように無慈悲となった。'),
('JPN', '耶利米哀歌', 25, 4, 4, '乳飲み子の舌は渇いて上あごにへばり付き、幼子たちがパンを求めても、割いてやる者もいない。'),
('JPN', '耶利米哀歌', 25, 4, 5, 'ごちそうを食べていた者たちは街頭で痩せ衰え、緋色の衣で育てられた者たちは堆肥をかき集めるようになった。'),
('JPN', '耶利米哀歌', 25, 4, 6, '娘である私の民の咎はソドムの罪よりも大きかった。人の手によらずに、一瞬で崩壊したソドムより。'),
('JPN', '耶利米哀歌', 25, 4, 7, 'その聖別された者たちは雪よりも清く、乳よりも白かった。そのからだは珊瑚よりも赤く、容姿はサファイアのようであった。'),
('JPN', '耶利米哀歌', 25, 4, 8, 'しかし、彼らの顔はすすより黒くなり、街頭でもそれと分からない。彼らの皮膚は干からびて骨に付き、乾いて木のようになった。'),
('JPN', '耶利米哀歌', 25, 4, 9, '剣で殺される人は、飢えで殺される者たちより幸せであった。その者たちは、畑の実りがないために、痩せ衰えて死んでいった。'),
('JPN', '耶利米哀歌', 25, 4, 10, 'あわれみ深い女たちが、自分の手で自分の子を煮た。娘である私の民が破滅したとき、それが彼女たちの食物となった。'),
('JPN', '耶利米哀歌', 25, 4, 11, '主は憤りを出し尽くし、燃える怒りを注ぎ出された。主はシオンに火を放ち、火はその礎を焼き尽くした。'),
('JPN', '耶利米哀歌', 25, 4, 12, '地の王たちは信じていなかった。世界に住むすべての者も。仇や敵がエルサレムの門に入って来るとは。'),
('JPN', '耶利米哀歌', 25, 4, 13, 'これはその預言者たちの罪、祭司たちの咎のためである。彼らは、その町のただ中で、正しい人たちの血を流した。'),
('JPN', '耶利米哀歌', 25, 4, 14, '彼らは血で汚れ、目の見えない人のように街頭をさまよい、だれも彼らの衣に触れることはできなかった。'),
('JPN', '耶利米哀歌', 25, 4, 15, '「向こうへ行け。汚れた者」と人々は彼らに叫ぶ。「向こうへ行け。向こうへ行け。さわるな。」彼らは、立ち去って、なおもさまよい歩く。国々の中で人々は言う。「彼らは二度とここに寄留してはならない」と。'),
('JPN', '耶利米哀歌', 25, 4, 16, '主ご自身が彼らを散らされた。もう彼らに目を留められることはない。祭司たちは尊ばれず、長老たちは敬われなかった。'),
('JPN', '耶利米哀歌', 25, 4, 17, 'そのうえ、私たちの目は衰えていき、助けを求めたが、空しかった。私たちは、救いをもたらさない国に期待をかけ、見張り場で見張りをしたのだ。'),
('JPN', '耶利米哀歌', 25, 4, 18, '私たちの歩みはつけ狙われて、広場を歩くこともできなかった。私たちの終わりは近づいた。私たちの日は満ちた。私たちの終わりが来たのだ。'),
('JPN', '耶利米哀歌', 25, 4, 19, '私たちを追う者たちは、大空の鷲よりも速かった。山々の上まで追い迫り、荒野で私たちを待ち伏せした。'),
('JPN', '耶利米哀歌', 25, 4, 20, '私たちの鼻の息、主に油注がれた者が、彼らの落とし穴で捕らえられた。私たちは「この方の陰なら、国々の中でも生き延びられる」と思っていた。'),
('JPN', '耶利米哀歌', 25, 4, 21, 'ウツの地に住む娘エドムよ、楽しみ喜べ。だが、あなたにも杯は巡って来る。あなたは酔って自分の裸をさらす。'),
('JPN', '耶利米哀歌', 25, 4, 22, '娘シオンよ、あなたへの刑罰は果たされた。主はもう、あなたを捕らえ移すことはなさらない。だが、娘エドムよ、主はあなたの咎を罰し、あなたの罪を暴かれる。'),
('JPN', '耶利米哀歌', 25, 5, 1, '主よ。私たちに起こったことを心に留め、私たちの汚名に目を留めて、よく見てください。'),
('JPN', '耶利米哀歌', 25, 5, 2, '私たちのゆずりの地は他国人の手に、私たちの家は異国の民の手に渡りました。'),
('JPN', '耶利米哀歌', 25, 5, 3, '私たちは父のいないみなしごとなり、母はやもめのようになりました。'),
('JPN', '耶利米哀歌', 25, 5, 4, '私たちは自分の水を、金を払って飲みます。薪も、代価を払って手に入れます。'),
('JPN', '耶利米哀歌', 25, 5, 5, '私たちはくびきを負って、追い立てられ、疲れ果てても憩いを与えられません。'),
('JPN', '耶利米哀歌', 25, 5, 6, '私たちは十分な食物を得ようと、エジプトやアッシリアに手を伸ばしました。'),
('JPN', '耶利米哀歌', 25, 5, 7, '私たちの先祖は罪を犯し、今はもういません。彼らの咎は私たちが負いました。'),
('JPN', '耶利米哀歌', 25, 5, 8, '奴隷たちが私たちを支配し、彼らの手から解き放ってくれる者はいません。'),
('JPN', '耶利米哀歌', 25, 5, 9, '荒野には剣があり、私たちは、いのちがけで食物を得ています。'),
('JPN', '耶利米哀歌', 25, 5, 10, '私たちの皮膚は、飢饉の激しい熱で、かまどのように熱くなりました。'),
('JPN', '耶利米哀歌', 25, 5, 11, '女たちはシオンで、おとめたちはユダの町々で、辱められました。'),
('JPN', '耶利米哀歌', 25, 5, 12, '首長たちは彼らの手で木につるされ、長老たちは尊ばれませんでした。'),
('JPN', '耶利米哀歌', 25, 5, 13, '若い男たちはひき臼をひかされ、幼い者たちは薪を背負ってよろめきました。'),
('JPN', '耶利米哀歌', 25, 5, 14, '長老たちは、城門のところに集まることを、若い男たちは、楽器を鳴らすことをやめました。'),
('JPN', '耶利米哀歌', 25, 5, 15, '私たちの心から喜びが消え、踊りは喪に変わりました。'),
('JPN', '耶利米哀歌', 25, 5, 16, '冠も頭から落ちました。私たちは、ああ、罪ある者となりました。'),
('JPN', '耶利米哀歌', 25, 5, 17, 'このために、私たちの心は病みました。これらのために、目は暗くなりました。'),
('JPN', '耶利米哀歌', 25, 5, 18, '荒れ果てたシオンの山の上を、そこを狐が歩き回っています。'),
('JPN', '耶利米哀歌', 25, 5, 19, '主よ。あなたはとこしえに御座に着かれ、あなたの王座は代々に続きます。'),
('JPN', '耶利米哀歌', 25, 5, 20, 'なぜ、いつまでも私たちをお忘れになるのですか。私たちを長い間、捨てておかれるのですか。'),
('JPN', '耶利米哀歌', 25, 5, 21, '主よ、あなたのみもとに帰らせてください。そうすれば、私たちは帰ります。昔のように、私たちの日々を新しくしてください。'),
('JPN', '耶利米哀歌', 25, 5, 22, 'あなたが本当に、私たちを退け、極みまで私たちを怒っておられるのでなければ。'),
('JPN', '以西结书', 26, 1, 1, '第三十年の第四の月の五日、私がケバル川のほとりで捕囚の民とともにいたとき、天が開け、私は神々しい幻を見た。'),
('JPN', '以西结书', 26, 1, 2, 'それはエホヤキン王が捕囚となってから五年目の時であった。その月の五日に、'),
('JPN', '以西结书', 26, 1, 3, 'カルデア人の地のケバル川のほとりで、ブジの子、祭司エゼキエルに主のことばが確かに臨んだ。その場所で主の御手が彼の上にあった。'),
('JPN', '以西结书', 26, 1, 4, '私が見ていると、見よ、激しい風が北からやって来た。それは大きな雲と、きらめき渡る火を伴い、その周りには輝きがあった。その火の中央からは琥珀のようなきらめきが出ていた。'),
('JPN', '以西结书', 26, 1, 5, 'その中に生きもののようなものが四つ現れ、その姿は次のようであった。彼らは人間のような姿をしていたが、'),
('JPN', '以西结书', 26, 1, 6, 'それぞれ四つの顔と四つの翼を持っていた。'),
('JPN', '以西结书', 26, 1, 7, 'その足はまっすぐで、足の裏は子牛の足の裏のようであり、磨かれた青銅のようにきらめいていた。'),
('JPN', '以西结书', 26, 1, 8, 'その翼の下から人間の手が四方に出ていた。また、その四つの生きものの顔と翼は次のようであった。'),
('JPN', '以西结书', 26, 1, 9, '彼らの翼は互いに触れ合っていて、進むときには向きを変えず、それぞれ正面に向かってまっすぐに進んだ。'),
('JPN', '以西结书', 26, 1, 10, '彼らの顔かたちは人間の顔で、四つとも右側には獅子の顔、四つとも左側には牛の顔、さらに四つとも鷲の顔を持っていた。'),
('JPN', '以西结书', 26, 1, 11, 'これが彼らの顔であった。彼らの翼は上方に広げられ、それぞれ、二つは互いに触れ合っていて、もう二つはそれぞれのからだをおおっていた。'),
('JPN', '以西结书', 26, 1, 12, '彼らはそれぞれ前を向いてまっすぐに進んだ。霊が進ませるところに彼らは進み、進むときには向きを変えなかった。'),
('JPN', '以西结书', 26, 1, 13, 'それらの生きものの姿は燃える炭火のようであり、たいまつのように見えた。火がそれらの生きものの間を行き来していた。火には輝きがあり、その火から稲妻が出ていた。'),
('JPN', '以西结书', 26, 1, 14, 'それらの生きものは、閃光のように出たり入ったりしていた。'),
('JPN', '以西结书', 26, 1, 15, '私がその生きものを見ていると、それら四つの顔の生きもののそばには、地の上にそれぞれ輪が一つずつあった。'),
('JPN', '以西结书', 26, 1, 16, 'それらの輪の形と作りは、輝く緑柱石のようで、四つともよく似ていた。それらの形と作りは、ちょうど、輪の中に輪があるようであった。'),
('JPN', '以西结书', 26, 1, 17, 'それらは四方のどの方向にも進み、進むときには向きを変えなかった。'),
('JPN', '以西结书', 26, 1, 18, 'その輪の周りの縁は高さがあって恐ろしく、四つの輪の周りの縁は一面、目で満ちていた。'),
('JPN', '以西结书', 26, 1, 19, '生きものが進むときには輪もそのそばを進み、生きものが地上から上がるときには輪も上がった。'),
('JPN', '以西结书', 26, 1, 20, 'これらは霊が進もうとするところに進み、輪もまたそれらとともに上がった。生きものの霊が輪の中にあったからである。'),
('JPN', '以西结书', 26, 1, 21, '生きものが進むときには輪も進み、生きものが止まるときには輪も止まり、生きものが地上から上がるときには輪も上がった。生きものの霊が輪の中にあったからである。'),
('JPN', '以西结书', 26, 1, 22, '生きものの頭上には、まばゆい水晶のような大空に似たものがあり、頭上高く広がっていた。'),
('JPN', '以西结书', 26, 1, 23, 'その大空の下で、その翼が互いにまっすぐに伸び、それぞれ一対の翼が彼らをおおっていた。それぞれの一対の翼が彼らのからだをおおっていたのである。'),
('JPN', '以西结书', 26, 1, 24, '彼らが進むとき、私は彼らの翼の音を聞いた。それは大水のとどろきのよう、全能者の声のようであり、そのどよめきは陣営の騒音のようであった。彼らが止まるときに、その翼は垂れた。'),
('JPN', '以西结书', 26, 1, 25, '彼らの頭上にある大空から声があった。彼らが止まったとき、その翼は垂れた。'),
('JPN', '以西结书', 26, 1, 26, '彼らの頭上、大空のはるか上の方には、サファイアのように見える王座に似たものがあり、その王座に似たもののはるか上には、人間の姿に似たものがあった。'),
('JPN', '以西结书', 26, 1, 27, '私が見ると、その腰と見えるところから上の方は、その中と周りが琥珀のきらめきのように輝き、火のように見えた。腰と見えるところから下の方に、私は火のようなものを見た。その方の周りには輝きがあった。'),
('JPN', '以西结书', 26, 1, 28, 'その方の周りにある輝きは、雨の日の雲の間にある虹のようであり、まさに主の栄光の姿のようであった。私はこれを見て、ひれ伏した。そのとき、私は語る者の声を聞いた。'),
('JPN', '以西结书', 26, 2, 1, 'その方は私に言われた。「人の子よ、自分の足で立て。わたしがあなたに語る。」'),
('JPN', '以西结书', 26, 2, 2, 'その方が私に語りかけると、霊が私のうちに入り、私を自分の足で立たせた。そのとき、私は自分に語りかけることばを聞いた。'),
('JPN', '以西结书', 26, 2, 3, 'その方は私に言われた。「人の子よ。わたしはあなたをイスラエルの民に、わたしに反抗する国民に遣わす。彼らもその先祖たちも、今日までわたしに背いてきた。'),
('JPN', '以西结书', 26, 2, 4, '彼らは厚かましく、頑なである。わたしはあなたを彼らに遣わす。あなたは彼らに『神である主はこう言われる』と言え。'),
('JPN', '以西结书', 26, 2, 5, '反逆の家だから、聞く聞かないに関わりなく、彼らは自分たちのうちに預言者がいることを知らなければならない。'),
('JPN', '以西结书', 26, 2, 6, '人の子よ。あなたは彼らや彼らのことばを恐れるな。あざみと茨があなたと一緒にあり、サソリの間に住んでも、恐れるな。そのことばを恐れるな。彼らの顔におびえるな。彼らは反逆の家なのだから。'),
('JPN', '以西结书', 26, 2, 7, '彼らは反逆の家だから、聞く聞かないに関わりなく、あなたはわたしのことばを彼らに語れ。'),
('JPN', '以西结书', 26, 2, 8, '人の子よ。あなたは、わたしがあなたに語ることを聞け。反逆の家のように、あなたは逆らってはならない。あなたの口を大きく開けて、わたしがあなたに与えるものを食べよ。」'),
('JPN', '以西结书', 26, 2, 9, '私が見ると、なんと、私の方に手が伸ばされていて、その中に一つの巻物があった。'),
('JPN', '以西结书', 26, 2, 10, 'その方はそれを私の前で広げた。それは表にも裏にも文字が書かれていた。そこに嘆きと、うめきと、悲痛が記されていた。'),
('JPN', '以西结书', 26, 3, 1, 'その方は私に言われた。「人の子よ。あなたの前にあるものを食べよ。この巻物を食べ、行ってイスラエルの家に告げよ。」'),
('JPN', '以西结书', 26, 3, 2, '私が口を開けると、その方は私にその巻物を食べさせ、'),
('JPN', '以西结书', 26, 3, 3, 'そして言われた。「人の子よ。わたしがあなたに与えるこの巻物を食べ、それで腹を満たせ。」私がそれを食べると、それは口の中で蜜のように甘かった。'),
('JPN', '以西结书', 26, 3, 4, 'その方はまた、私に言われた。「人の子よ。さあ、イスラエルの家に行き、わたしのことばをもって彼らに語れ。'),
('JPN', '以西结书', 26, 3, 5, 'あなたは、難しい外国語を話す民にではなく、イスラエルの家に遣わされるのだ。'),
('JPN', '以西结书', 26, 3, 6, 'あなたを、そのことばを聞いても分からないような、難しい外国語を話す多くの民に遣わすのではない。もし、わたしがこれらの民にあなたを遣わしたのなら、彼らはあなたの言うことを聞いたであろう。'),
('JPN', '以西结书', 26, 3, 7, 'しかし、イスラエルの家はあなたの言うことを聞こうとはしない。彼らがわたしの言うことを聞こうとしないからだ。イスラエルの全家は額が硬く、心が頑なだからだ。'),
('JPN', '以西结书', 26, 3, 8, '見よ。わたしはあなたの顔を、彼らの顔に合わせて硬くし、あなたの額を、彼らの額に合わせて硬くする。'),
('JPN', '以西结书', 26, 3, 9, 'わたしはあなたの額を、火打石よりも硬いダイヤモンドのようにする。彼らを恐れるな。彼らの顔におびえるな。彼らは反逆の家なのだから。」'),
('JPN', '以西结书', 26, 3, 10, 'その方は私に言われた。「人の子よ。わたしがあなたに告げるすべてのことばをあなたの心に納め、あなたの耳で聞け。'),
('JPN', '以西结书', 26, 3, 11, 'さあ、捕囚になっているあなたの民のところへ行き、彼らに告げよ。彼らが聞いても、聞かなくても、『神である主はこう言われる』と彼らに言え。」'),
('JPN', '以西结书', 26, 3, 12, 'それから、霊が私を引き上げた。そのとき私は、うしろの方で、「主の栄光が御住まいでほめたたえられますように」という大きなとどろきを聞いた。'),
('JPN', '以西结书', 26, 3, 13, 'それは、互いに触れ合う生きものたちの翼の音と、そのそばの輪の音で、大きなとどろきになっていた。'),
('JPN', '以西结书', 26, 3, 14, '霊は私を持ち上げ、私を捕らえた。それで、私は自分の霊の憤りを覚えつつ、苦々しい思いで出て行った。主の御手は私の上に強くのしかかっていた。'),
('JPN', '以西结书', 26, 3, 15, '私はテル・アビブの捕囚の民のところへ行った。彼らはケバル川のほとりに住んでいたが、私は彼らが住んでいるその場所で、七日間、茫然として彼らの中に座っていた。'),
('JPN', '以西结书', 26, 3, 16, '七日の終わりになって、次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 3, 17, '「人の子よ。わたしはあなたをイスラエルの家の見張りとした。あなたは、わたしの口からことばを聞き、わたしに代わって彼らに警告を与えよ。'),
('JPN', '以西结书', 26, 3, 18, 'わたしが、悪い者に『あなたは必ず死ぬ』と言うとき、もしあなたが彼に警告を与えず、悪い者に悪の道から離れて生きるように警告しないなら、その悪い者は自分の不義のゆえに死ぬ。そして、わたしは彼の血の責任をあなたに問う。'),
('JPN', '以西结书', 26, 3, 19, 'もしあなたが悪い者に警告を与えても、彼がその悪と悪の道から立ち返ることがないなら、彼は自分の不義のゆえに死ななければならない。しかし、あなたは自分のいのちを救うことになる。'),
('JPN', '以西结书', 26, 3, 20, 'また、正しい人がその正しい行いをやめて不正を行うなら、わたしは彼の前につまずきを置く。彼は死ななければならない。あなたが彼に警告を与えなかったので、彼は自分の罪のゆえに死ぬ。彼が行った正しい行いは覚えられない。そして、わたしは彼の血の責任をあなたに問う。'),
('JPN', '以西结书', 26, 3, 21, 'しかし、もしあなたがその正しい人に、罪を犯さないように警告を与え、彼が罪を犯さないようになれば、彼は警告を聞いたのであるから、彼は必ず生き、あなたも自分のいのちを救うことになる。」'),
('JPN', '以西结书', 26, 3, 22, 'その場所で主の御手が私の上にあった。主は私に言われた。「さあ、平地に出て行け。そこでわたしはあなたに語ろう。」'),
('JPN', '以西结书', 26, 3, 23, '私は平地に出て行った。すると、主の栄光が、かつて私がケバル川のほとりで見た栄光のように、そこにとどまっていた。それで私はひれ伏した。'),
('JPN', '以西结书', 26, 3, 24, 'それから、霊が私のうちに入り、私を自分の足で立たせた。主は私に語りかけられた。「行って、あなたの家に閉じこもっていなさい。'),
('JPN', '以西结书', 26, 3, 25, '人の子よ。今に人々があなたに縄をかけて縛るので、あなたは彼らのところに出て行けなくなる。'),
('JPN', '以西结书', 26, 3, 26, 'わたしがあなたの舌を上あごに付かせるので、あなたは話せなくなり、あなたは彼らにとって責める者ではなくなる。彼らは反逆の家なのだから。'),
('JPN', '以西结书', 26, 3, 27, 'しかしわたしは、あなたと語るときにあなたの口を開く。あなたは彼らに『神である主はこう言われる』と言え。聞く者には聞かせ、聞かない者には聞かせるな。彼らは反逆の家なのだから。'),
('JPN', '以西结书', 26, 4, 1, '人の子よ。あなたは粘土の板を一枚取り、それを自分の前に置き、その上にエルサレムの町を描け。'),
('JPN', '以西结书', 26, 4, 2, 'それから、それに対する包囲網を張れ。それに対して塁を築き、包囲壁を作れ。それに対して陣営を設け、周りに城壁崩しを配備せよ。'),
('JPN', '以西结书', 26, 4, 3, 'また、鉄の板一つを取り、それをあなたと町との間に鉄の壁として立てよ。あなたが自分の顔をしっかりとこの町に向けると、この町は包囲される。あなたがこれを攻め囲むのだ。これがイスラエルの家に対するしるしだ。'),
('JPN', '以西结书', 26, 4, 4, 'あなたは左脇を下にして身を横たえ、イスラエルの家の咎をその上に置け。あなたがそのように横たわっている日数だけ彼らの咎を負え。'),
('JPN', '以西结书', 26, 4, 5, 'わたしはあなたのために、彼らの咎の年数を日数にして三百九十日とする。このように、あなたはイスラエルの家の咎を負わなければならない。'),
('JPN', '以西结书', 26, 4, 6, 'あなたがこれらのことを終えたら、次に右脇を下にして身を横たえ、ユダの家の咎を四十日間、負わなければならない。わたしは一年を一日としてあなたに課す。'),
('JPN', '以西结书', 26, 4, 7, 'それから、あなたは顔をしっかりと、包囲されているエルサレムの方に向け、腕をまくり、これに向かって預言せよ。'),
('JPN', '以西结书', 26, 4, 8, '見よ。わたしはあなたに縄をかけ、あなたの包囲の期間が終わるまで寝返りができないようにする。'),
('JPN', '以西结书', 26, 4, 9, 'あなたは小麦、大麦、そら豆、レンズ豆、粟、裸麦を取り、それらを一つの器に入れ、それで自分のためにパンを作り、あなたが脇を下にして横たわっている日数、すなわち三百九十日間それを食べよ。'),
('JPN', '以西结书', 26, 4, 10, 'あなたが食べる食物は、重さにして一日分二十シェケルである。一日一回それを食べよ。'),
('JPN', '以西结书', 26, 4, 11, 'あなたが飲む水も、六分の一ヒンを量って、それを一日一回飲め。'),
('JPN', '以西结书', 26, 4, 12, 'あなたは大麦のパン菓子を食べよ。それを彼らの目の前で、人の糞で焼け。」'),
('JPN', '以西结书', 26, 4, 13, '主は言われた。「このようにイスラエルの民は、わたしが追いやる国々の中で、自分たちの汚れたパンを食べなければならない。」'),
('JPN', '以西结书', 26, 4, 14, 'そこで私は言った。「ああ、神、主よ。私は身を汚したことがありません。幼い時から今まで、死んだ動物や野獣にかみ裂かれたものを食べたことも、不浄な肉を口にしたこともありません。」'),
('JPN', '以西结书', 26, 4, 15, 'すると、主は私に言われた。「では、人の糞の代わりに牛の糞でよい。あなたはその上で自分のパンを作れ。」'),
('JPN', '以西结书', 26, 4, 16, 'そして私に言われた。「人の子よ、見よ。わたしはエルサレムで、パンの蓄えをなくそうとしている。彼らは恐る恐る量ってパンを食べ、おびえながら水を量って飲む。'),
('JPN', '以西结书', 26, 4, 17, 'こうしてパンと水が乏しくなり、だれもかれもが茫然として、自分たちの咎のゆえに朽ち果てる。'),
('JPN', '以西结书', 26, 5, 1, '人の子よ、あなたは鋭い剣を取れ。それを床屋のかみそりのように使って、あなたの髪とひげを剃れ。それから秤を使って量り、その毛を分けよ。'),
('JPN', '以西结书', 26, 5, 2, 'その三分の一を、包囲の期間の終わるときに町の中で焼き、またもう三分の一を取って町の周りで剣で打ち、残りの三分の一を風に乗せて散らせ。わたしは剣を抜いてその後を追う。'),
('JPN', '以西结书', 26, 5, 3, 'あなたはそこからわずかな毛を取って、あなたの衣の裾に包み、'),
('JPN', '以西结书', 26, 5, 4, 'その中からさらにいくらかを取って、火の中に投げ入れ、火で燃やせ。火がそこから出て、イスラエルの全家に燃え移る。」'),
('JPN', '以西结书', 26, 5, 5, '神である主はこう言われる。「これがエルサレムだ。わたしはこれを諸国の民のただ中に置き、その周りを国々が取り囲むようにした。'),
('JPN', '以西结书', 26, 5, 6, 'エルサレムは悪事を働き、諸国の民以上にわたしの定めに、周囲の国々以上にわたしの掟に逆らった。実に、エルサレムはわたしの定めを嫌い、わたしの掟に従って歩まなかった。'),
('JPN', '以西结书', 26, 5, 7, 'それゆえ──神である主はこう言われる──あなたがたは周りの国々よりも粗暴な者たちで、わたしの掟に従って歩まず、わたしの定めを行わず、それどころか、あなたがたの周りの国々の定めさえ行わなかった。'),
('JPN', '以西结书', 26, 5, 8, 'それゆえ──神である主はこう言われる──今、わたしはあなたを敵とし、国々の目の前で、あなたのただ中でさばきを下す。'),
('JPN', '以西结书', 26, 5, 9, 'あなたのしたすべての忌み嫌うべきことのゆえに、これまでしたこともなく、これからもしないようなことを、あなたに対して行う。'),
('JPN', '以西结书', 26, 5, 10, 'それで、あなたのうちの父は自分の子どもを食べ、子どもは自分の父を食べるようになる。わたしは、あなたにさばきを下し、あなたのうちの残りの者をみな四方に散らす。'),
('JPN', '以西结书', 26, 5, 11, 'それゆえ──神である主のことば──わたしは生きている。あなたが、あらゆる忌まわしいものと、あらゆる忌み嫌うべきことによって、わたしの聖所を汚したので、わたしもまた身を引き、あわれみをかけない。わたしもまた、惜しまない。'),
('JPN', '以西结书', 26, 5, 12, 'あなたの三分の一は疫病で死ぬか、あなたのただ中で飢饉によって滅び、三分の一はあなたの周りで剣に倒れ、残りの三分の一を、わたしは四方に散らし、剣を抜いて彼らの後を追う。'),
('JPN', '以西结书', 26, 5, 13, 'わたしの怒りが出し尽くされると、わたしは彼らに対する憤りを収めて満足する。わたしが彼らに対する憤りを終わらせたとき、彼らは、主であるわたしが、ねたみをもって語ったことを知る。'),
('JPN', '以西结书', 26, 5, 14, 'わたしは、あなたの周りの国々の中で、通り過ぎるすべての者の目の前で、あなたを廃墟とし、そしりの的とする。'),
('JPN', '以西结书', 26, 5, 15, 'わたしが、怒り、憤り、また憤りによる懲罰をもってあなたにさばきを下すとき、あなたは周りの国々のそしりとののしりの的、教訓と恐怖となる。主であるわたしがこれを告げる。'),
('JPN', '以西结书', 26, 5, 16, 'わたしが飢饉という悪しき矢を、滅びのため彼らに放ち、あなたがたを滅ぼそうとして放つとき、わたしは飢饉をあなたがたの上にいっそう増して、あなたがたのパンの蓄えをなくす。'),
('JPN', '以西结书', 26, 5, 17, 'わたしはあなたがたに飢饉と悪い獣を送る。それらはあなたに子を失わせる。疫病と流血があなたのうちに起こる。わたしはあなたの上に剣をもたらす。主であるわたしがこれを告げる。」'),
('JPN', '以西结书', 26, 6, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 6, 2, '「人の子よ。イスラエルの山々に顔を向け、それらに向かって預言せよ。'),
('JPN', '以西结书', 26, 6, 3, '『イスラエルの山々よ、神である主のことばを聞け。神である主は、山や丘、谷川や谷に向かってこう言われる。見よ。わたしは剣をあなたがたの上にもたらし、あなたがたの高き所を滅ぼす。'),
('JPN', '以西结书', 26, 6, 4, 'あなたがたの祭壇は荒らされ、あなたがたの香の台は破壊される。わたしはあなたがたの中の刺し殺された者どもを、あなたがたの偶像の前に投げ捨てる。'),
('JPN', '以西结书', 26, 6, 5, 'わたしはイスラエルの民の屍を彼らの偶像の前に置き、あなたがたの骨をあなたがたの祭壇の周りに散らす。'),
('JPN', '以西结书', 26, 6, 6, 'あなたがたがどこに住もうとも、町々は廃墟となり、高き所は荒らされる。こうして、あなたがたの祭壇は廃墟となり、罰を受ける。あなたがたの偶像は破壊されて消滅し、あなたがたの香の台は切り倒され、あなたがたのわざは消し去られ、'),
('JPN', '以西结书', 26, 6, 7, '刺し殺された者があなたがたのただ中に横たわる。そのときあなたがたは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 6, 8, 'しかし、わたしは、あなたがたのうちのある者を残しておく。あなたがたが諸国に追い散らされるとき、剣から逃れる者たちを国々の中に残す。'),
('JPN', '以西结书', 26, 6, 9, 'あなたがたのうちで逃れた者たちは、捕虜になって行った国々で、わたしから離れた彼らの姦淫の心と、偶像を慕う彼らの姦淫の目に、わたしがどんなに傷ついたかを思い起こす。自分たちのした悪や、あらゆる忌み嫌うべきことを、彼ら自らが嫌うようになるとき、'),
('JPN', '以西结书', 26, 6, 10, '彼らは、わたしが主であること、また、わたしが理由もなく、このわざわいを彼らに下すと言ったのではないことを知る。』」'),
('JPN', '以西结书', 26, 6, 11, '神である主はこう言われる。「あなたは手をたたき、足を踏み鳴らして、イスラエルの家の、忌み嫌うべきすべての悪のゆえに、『ああ』と嘆け。彼らが剣と飢饉と疫病によって倒れるからだ。'),
('JPN', '以西结书', 26, 6, 12, '遠くにいる者は疫病で死に、近くにいる者は剣に倒れ、生き残って監視されている者は飢饉で死ぬ。こうして、わたしは彼らに対する激しい憤りを終わらせる。'),
('JPN', '以西结书', 26, 6, 13, '彼らのうちの刺し殺された者たちが、祭壇の周りの自分たちの偶像の間に、すべての高い丘の上や山々の頂に、すべての青々とした木の下や、すべての茂った樫の木の下に、すなわち、彼らがあらゆる偶像に芳ばしい香りを供えた場所に横たわるとき、あなたがたは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 6, 14, 'わたしが彼らの上に手を伸ばし、すべて彼らの住む所、荒野からリブラまでの地を完全に荒廃した地とするとき、彼らは、わたしが主であることを知る。」'),
('JPN', '以西结书', 26, 7, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 7, 2, '「人の子よ、あなたは言え。『イスラエルの地に対して神である主はこう言われる。終わりだ。終わりが来た。この国の四隅にまで。'),
('JPN', '以西结书', 26, 7, 3, '今、あなたに終わりが臨む。わたしは怒りをあなたのうちに送り、あなたの生き方にしたがってあなたをさばき、あなたのすべての忌み嫌うべきわざに報いる。'),
('JPN', '以西结书', 26, 7, 4, 'わたしはあなたにあわれみをかけない。わたしはあなたを惜しまない。忌み嫌うべきことが、あなたの中にあるうちに、わたしはあなたの行いをあなたの上に返す。そのときあなたがたは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 7, 5, '神である主はこう言う。わざわいだ。類のないわざわいだ。見よ、それは来る。'),
('JPN', '以西结书', 26, 7, 6, '終わりが来る。終わりが来る。あなたのために機が熟した。見よ、それは来る。'),
('JPN', '以西结书', 26, 7, 7, '地に住む者よ、あなたの上に終局が来る。その時が来る。その日は近い。山々での歓声の日ではなく、恐慌の日だ。'),
('JPN', '以西结书', 26, 7, 8, '今、間もなく、わたしは憤りをあなたに注ぎ、わたしの怒りをあなたに出し尽くす。あなたの生き方のとおりにあなたをさばき、あなたのすべての忌み嫌うべきわざに報いる。'),
('JPN', '以西结书', 26, 7, 9, 'わたしはあわれみをかけない。惜しまない。忌み嫌うべきことが、あなたの中にあるうちに、わたしはあなたの行いのとおりに報いる。このとき、あなたがたは知る。わたしがあなたがたを打つ主であることを。'),
('JPN', '以西结书', 26, 7, 10, '見よ、その日だ。その日が来る。あなたの終局が来ている。杖がつぼみを出し、横柄さを花咲かせた。'),
('JPN', '以西结书', 26, 7, 11, '暴虐が起こって悪の杖となり、彼らもその群衆も、彼らの富もなくなり、彼らのために嘆く者もいなくなる。'),
('JPN', '以西结书', 26, 7, 12, 'その時が来た。その日がやって来た。買う者も喜ぶな。売る者も嘆くな。燃える怒りがそのすべての群衆に臨むからだ。'),
('JPN', '以西结书', 26, 7, 13, '両者が生き延びても、売る者は、売った物を取り戻せないからだ。群衆すべてに関わる幻は取り消すことができず、だれもが自分の不義のうちにいるため、奮い立って生きることができないからだ。'),
('JPN', '以西结书', 26, 7, 14, 'ラッパが吹き鳴らされ、すべての準備ができても、戦いに行く者はいない。わたしの燃える怒りが群衆すべてに臨むからだ。'),
('JPN', '以西结书', 26, 7, 15, '外には剣、内には疫病と飢饉。野にいる者は剣で死に、町にいる者を飢饉と疫病が滅ぼし尽くす。'),
('JPN', '以西结书', 26, 7, 16, '逃れた者たちが逃れて山々の上にいても、谷間の鳩のようにみな泣き悲しむ。自分の不義のゆえに。'),
('JPN', '以西结书', 26, 7, 17, 'どの手も力無く垂れ下がり、どの膝も震える。'),
('JPN', '以西结书', 26, 7, 18, '彼らは粗布を身にまとい、戦慄に包まれ、みな恥じて顔を赤くし、彼らの頭からは毛が引き抜かれる。'),
('JPN', '以西结书', 26, 7, 19, '彼らの銀は道端に投げ捨てられ、彼らの金は不浄の物のようになる。彼らの銀も金も、主の激しい怒りの日に彼らを救い出すことはできない。銀も金も、彼らの欲望を満足させることも、彼らの腹を満たすこともできない。それは彼らを不義に引き込むものであったから。'),
('JPN', '以西结书', 26, 7, 20, '彼らはこれを、美しい飾り物として誇り、これで自分たちのために忌み嫌うべきもの、忌まわしいものの像を造った。だから、わたしはそれを不浄の物とする。'),
('JPN', '以西结书', 26, 7, 21, 'わたしはそれを他国人の手に獲物として、地の悪者どもに分捕り物として渡し、それを汚させる。'),
('JPN', '以西结书', 26, 7, 22, 'わたしは彼らから顔を背け、わたしが秘宝とする所は汚される。無法者がそこに入り込み、そこを侵す。'),
('JPN', '以西结书', 26, 7, 23, '鎖を作れ。この国は流血のさばきに満ち、この都は暴虐に満ちているからだ。'),
('JPN', '以西结书', 26, 7, 24, 'わたしは異邦の民の最も悪い者どもを来させて、彼らの家々を占領させ、有力者たちの高ぶりをくじき、彼らのもろもろの聖所を汚させる。'),
('JPN', '以西结书', 26, 7, 25, '恐怖がやって来る。彼らは平安を求めるが、それはない。'),
('JPN', '以西结书', 26, 7, 26, '災難の上に災難が訪れ、うわさがうわさを生む。彼らは預言者に幻を求めるようになる。祭司から律法が、長老から助言が失われる。'),
('JPN', '以西结书', 26, 7, 27, '王は喪に服し、君主は恐怖に包まれ、民衆の手はわななく。わたしが、彼らの行いにしたがって彼らに報い、彼らのやり方にしたがって彼らをさばくとき、彼らは、わたしが主であることを知る。』」'),
('JPN', '以西结书', 26, 8, 1, '第六年の第六の月の五日、私が自分の家に座っていて、ユダの長老たちも私の前に座っていたとき、神である主の御手がそこで私の上に下った。'),
('JPN', '以西结书', 26, 8, 2, '私が見ると、火のように見える姿があった。その腰と見えるところから下の方が火であり、腰から上の方が琥珀のきらめきのように輝いて見えた。'),
('JPN', '以西结书', 26, 8, 3, 'すると、その方は手の形をしたものを伸ばし、私の髪の房をつかまれた。すると、霊が私を地と天の間に持ち上げ、神々しい幻のうちに私をエルサレムへと携え行き、ねたみを引き起こす「ねたみ」という像がある、北に面した内門の入り口に連れて行った。'),
('JPN', '以西结书', 26, 8, 4, 'なんと、そこには、私がかつて平地で見た幻と同じような、イスラエルの神の栄光があった。'),
('JPN', '以西结书', 26, 8, 5, 'その方は私に言われた。「人の子よ。さあ、目を上げて北の方を見よ。」私が目を上げて北の方を見ると、なんと、北の方の祭壇の門の入り口に「ねたみ」という像があった。'),
('JPN', '以西结书', 26, 8, 6, 'この方は私に言われた。「人の子よ。あなたには彼らのしていることが見えるか。イスラエルの家は、わたしの聖所から遠く離れようとして、ここで大きな忌み嫌うべきことをしているではないか。あなたはなおもまた、大きな忌み嫌うべきことを見る。」'),
('JPN', '以西结书', 26, 8, 7, 'それから、この方は私を庭の入り口に連れて行かれた。見ると、壁に一つの穴があった。'),
('JPN', '以西结书', 26, 8, 8, 'この方は私に言われた。「人の子よ。さあ、壁に穴を開けて通り抜けよ。」私が壁に穴を開けて通り抜けると、一つの入り口があった。'),
('JPN', '以西结书', 26, 8, 9, 'この方は私に言われた。「入って行き、彼らがここでしている悪い忌み嫌うべきことを見よ。」'),
('JPN', '以西结书', 26, 8, 10, '私が入って行って見ると、なんと、這うものや動物のあらゆる形、すなわち忌むべきものや、イスラエルの家のすべての偶像が、周りの壁一面に彫られていた。'),
('JPN', '以西结书', 26, 8, 11, 'また、イスラエルの家の七十人の長老が、その前に立っていて、その中にはシャファンの子ヤアザンヤも立っていた。彼らはみなその手に香炉を持ち、香の濃い雲が立ち上っていた。'),
('JPN', '以西结书', 26, 8, 12, 'この方は私に言われた。「人の子よ。あなたは、イスラエルの家の長老たちが、暗闇の中、それぞれ自分自身の偶像の部屋で行っていることを見たか。彼らは、『主は私たちを見ておられない。主はこの地を見捨てられた』と言っているのだ。」'),
('JPN', '以西结书', 26, 8, 13, 'また私に言われた。「あなたはなおもまた、彼らが行っている大きな忌み嫌うべきことを見る。」'),
('JPN', '以西结书', 26, 8, 14, 'それから、この方は私を主の宮の北の門の入り口へ連れて行かれた。するとそこには、女たちがタンムズのために泣きながら座っていた。'),
('JPN', '以西结书', 26, 8, 15, 'この方は私に言われた。「見たか、人の子よ。あなたはなおもまた、これよりも大きな忌み嫌うべきことを見る。」'),
('JPN', '以西结书', 26, 8, 16, 'それから、この方は私を主の宮の内庭に連れて行かれた。すると、なんと、主の神殿の入り口、すなわち、玄関広間と祭壇との間に二十五人ばかりの人がいた。彼らは主の神殿に背を向け、顔を東の方に向けていた。東の方を向いて、太陽を拝んでいた。'),
('JPN', '以西结书', 26, 8, 17, 'この方は私に言われた。「見たか、人の子よ。ユダの家にとって、彼らがここでしているような忌み嫌うべきことをするのは、些細なことだろうか。彼らはこの地を暴虐で満たし、わたしの怒りをいっそう駆り立てている。見よ、彼らはぶどうのつるを自分たちの鼻にさしているではないか。'),
('JPN', '以西结书', 26, 8, 18, 'だから、わたしも激しい憤りをもって応じる。わたしはあわれみをかけない。わたしは彼らを惜しまない。彼らがわたしの耳に大声で叫んでも、わたしは彼らの言うことを聞かない。」'),
('JPN', '以西结书', 26, 9, 1, 'この方は私の耳に大声で叫ばれた。「破壊する武器をそれぞれ手に持った、この都を罰する者たちを連れて来い。」'),
('JPN', '以西结书', 26, 9, 2, '見ると、六人の男が、それぞれ打ち壊す武器を手に持って、北に面する上の門を通ってやって来た。もう一人の人が、亜麻布の衣をまとい、腰には書記の筆入れを付けて、彼らの中にいた。彼らは入って来て、青銅の祭壇のそばに立った。'),
('JPN', '以西结书', 26, 9, 3, 'ケルビムの上にあったイスラエルの神の栄光が、ケルビムから立ち上り、神殿の敷居へ向かっていた。腰に書記の筆入れを付け、亜麻布の衣をまとっている者を呼び寄せて、'),
('JPN', '以西结书', 26, 9, 4, '主は彼にこう言われた。「都の中、エルサレムの中を行き巡り、ここで行われているすべての忌み嫌うべきことを嘆き悲しんでいる人々の額に、しるしをつけよ。」'),
('JPN', '以西结书', 26, 9, 5, 'また、私が聞いていると、ほかの者たちに主はこう言われた。「この者の後について都の中を行き巡って、打ち殺せ。あわれみをかけてはならない。惜しんではならない。'),
('JPN', '以西结书', 26, 9, 6, '年寄りも、若い男も、若い娘も、幼子も、女たちも殺して滅ぼせ。しかし、しるしが付けられた者には、だれにも近づいてはならない。まず、わたしの聖所から始めよ。」そこで、彼らは神殿の前にいた老人たちから始めた。'),
('JPN', '以西结书', 26, 9, 7, 'それから主は彼らに言われた。「神殿を汚し、庭を刺し殺された者で満たせ。さあ、行け。」彼らは出て行って、都の中で打ち殺した。'),
('JPN', '以西结书', 26, 9, 8, '彼らが打ち殺しているとき、私だけが残された。私はひれ伏して叫んだ。「ああ、神、主よ。あなたはエルサレムの上にあなたの憤りを注ぎ出し、イスラエルの残りの者たちを、ことごとく滅ぼされるのですか。」'),
('JPN', '以西结书', 26, 9, 9, '主は私に言われた。「イスラエルとユダの家の咎は非常に大きく、地は流血で満ち、都も不正で満ちている。彼らは『主はこの地を見捨てられた。主は見ておられない』と言っているのだ。'),
('JPN', '以西结书', 26, 9, 10, 'だから、わたしもあわれみをかけない。わたしは惜しまない。わたしは彼らの頭上に彼らの行いを返す。」'),
('JPN', '以西结书', 26, 9, 11, 'そのとき、腰に筆入れを付け、亜麻布の衣をまとった、あの人がこう報告した。「私は、あなたが私に命じられたとおりに行いました。」'),
('JPN', '以西结书', 26, 10, 1, '私が見ていると、ケルビムの頭上の大空に、サファイアのような、王座に似たものがあり、それがケルビムの上に現れた。'),
('JPN', '以西结书', 26, 10, 2, '主は亜麻布の衣をまとった者に命じられた。「ケルビムの下にある車輪の間に入り、ケルビムの間の炭火をあなたの両手に満たし、それを都の上にまき散らせ。」この人は私の目の前でそこに入って行った。'),
('JPN', '以西结书', 26, 10, 3, 'その人が入って行ったとき、ケルビムは神殿の南側に立っていて、雲がその内庭を満たしていた。'),
('JPN', '以西结书', 26, 10, 4, '主の栄光がケルビムの上から上り、神殿の敷居に向かった。神殿は雲で満たされ、また、庭は主の栄光の輝きで満たされた。'),
('JPN', '以西结书', 26, 10, 5, 'そのとき、ケルビムの翼の音が外庭にまで聞こえた。それは、全能の神が語られるときの声のようであった。'),
('JPN', '以西结书', 26, 10, 6, '主が亜麻布の衣をまとった者に「車輪の間、ケルビムの間から火を取れ」と命じられると、この人は入って行き、輪のそばに立った。'),
('JPN', '以西结书', 26, 10, 7, 'すると、ケルビムのひとりがケルビムの間から、ケルビムの間にある火の方に手を伸ばして、その火を取り、亜麻布の衣をまとった者の両手にそれを盛った。この人はそれを受け取ると、出て行った。'),
('JPN', '以西结书', 26, 10, 8, 'ケルビムの翼の下には人間の手の形があった。'),
('JPN', '以西结书', 26, 10, 9, '私が見ると、ケルビムのそばに四つの輪があり、一つの輪は一方のケルビムのそばに、もう一つの輪はもう一方のケルビムのそばに、それぞれあった。その輪は緑柱石の輝きのように見えた。'),
('JPN', '以西结书', 26, 10, 10, 'それらの形は四つとも同じで、一つの輪がもう一つの輪の中にあるようであった。'),
('JPN', '以西结书', 26, 10, 11, 'それらが進むとき、それらは四方のどの方向にも進み、進むときには向きを変えなかった。なぜなら、頭が向かうところにほかの輪も従い、それらが進むときには向きを変えなかったからである。'),
('JPN', '以西结书', 26, 10, 12, 'それらのからだ全体と、その背、その手、その翼、さらに輪、すなわちその四つの輪には、周りに目がたくさん付いていた。'),
('JPN', '以西结书', 26, 10, 13, '私はそれらの輪が「車輪」と呼ばれるのを聞いた。'),
('JPN', '以西结书', 26, 10, 14, 'それぞれに四つの顔があり、第一の顔はケルビムの顔、第二の顔は人間の顔、第三の顔は獅子の顔、第四の顔は鷲の顔であった。'),
('JPN', '以西结书', 26, 10, 15, 'そのとき、ケルビムは飛び立った。それは、私がかつてケバル川のほとりで見た生きものであった。'),
('JPN', '以西结书', 26, 10, 16, 'ケルビムが行くと輪もそのそばを進み、ケルビムが翼を広げて地上から上るとき輪もそのそばを離れず、向きを変えなかった。'),
('JPN', '以西结书', 26, 10, 17, 'ケルビムが止まると輪も立ち止まり、ケルビムが上ると輪も一緒に上った。生きものの霊が輪の中にあったからである。'),
('JPN', '以西结书', 26, 10, 18, '主の栄光が神殿の敷居から出て行って、ケルビムの上にとどまった。'),
('JPN', '以西结书', 26, 10, 19, 'すると、ケルビムは翼を広げて、私の目の前で地上から上って行った。出て行くとき、輪もそのそばについて行き、主の宮の東の門の入り口で止まった。イスラエルの神の栄光が彼らの上にあった。'),
('JPN', '以西结书', 26, 10, 20, '彼らは、かつて私がケバル川のほとりで、イスラエルの神の下に見た生きものであった。私は彼らがケルビムであることを知った。'),
('JPN', '以西结书', 26, 10, 21, '彼らはそれぞれ四つの顔と、それぞれ四つの翼を持っていた。その翼の下には人間の手のようなものがあった。'),
('JPN', '以西结书', 26, 10, 22, '彼らの顔かたち、それは、私がかつてケバル川のほとりでその容貌と姿を見たとおりの顔であった。彼らはみな、前の方へまっすぐに進んで行った。'),
('JPN', '以西结书', 26, 11, 1, '霊は私を引き上げて、主の宮の東に面した東の門に連れて行った。見よ、その門の入り口には二十五人の者がいた。そしてその中に、民の長であるアズルの子ヤアザンヤと、ベナヤの子ペラテヤがいるのを私は見た。'),
('JPN', '以西结书', 26, 11, 2, '主は私に言われた。「人の子よ。この者たちは、この都でよこしまなことを謀り、悪いはかりごとをめぐらし、'),
('JPN', '以西结书', 26, 11, 3, '『当分、家を建てなくともよい。この都は鍋であり、われわれはその肉だ』と言っている。'),
('JPN', '以西结书', 26, 11, 4, 'だから、彼らに向かって預言せよ。人の子よ、預言せよ。」'),
('JPN', '以西结书', 26, 11, 5, '主の霊が私に下り、私に言われた。「あなたは言え。『主はこう言われる。イスラエルの家よ。あなたがたはあのように言ったが、わたしは、あなたがたの霊の思いをよく知っている。'),
('JPN', '以西结书', 26, 11, 6, 'あなたがたはこの都で、刺し殺された者を増し加え、都の通りを刺し殺された者で満たした。'),
('JPN', '以西结书', 26, 11, 7, 'それゆえ、神である主はこう言われる。あなたがたが町の中に横たえた、刺し殺された者こそが肉であり、この町は鍋である。しかしわたしは、あなたがたをその中から連れ出す。'),
('JPN', '以西结书', 26, 11, 8, 'あなたがたは剣を恐れているが、わたしはあなたがたの上に剣をもたらす──神である主のことば──。'),
('JPN', '以西结书', 26, 11, 9, 'わたしはあなたがたを町から連れ出して、他国人の手に渡し、あなたがたにさばきを下す。'),
('JPN', '以西结书', 26, 11, 10, 'あなたがたが剣に倒れ、わたしがイスラエルの国境であなたがたをさばくとき、あなたがたは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 11, 11, 'この都はあなたがたにとって鍋とはならず、あなたがたはその中の肉とはならない。わたしは、イスラエルの国境であなたがたをさばく。'),
('JPN', '以西结书', 26, 11, 12, 'あなたがたは、わたしが主であることを知る。あなたがたが、わたしの掟に従って歩まず、わたしの定めを守らず、あなたがたの周りの国々の慣わしに従ったからである。』」'),
('JPN', '以西结书', 26, 11, 13, '私が預言していたとき、ベナヤの子ペラテヤが死んだ。それで、私はひれ伏して大声で叫んだ。「ああ、神、主よ。あなたはイスラエルの残りの者たちを滅ぼし尽くされるのでしょうか。」'),
('JPN', '以西结书', 26, 11, 14, 'そのとき、次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 11, 15, '「人の子よ。エルサレムの住民は、あなたの兄弟、同胞、あなたに買い戻しの権利がある親類の者たち、またイスラエルの全家のすべての者に対して、こう言った。『主から遠く離れよ。この地はほかでもないわれわれの所有地として与えられているのだ。』'),
('JPN', '以西结书', 26, 11, 16, 'それゆえ言え。『神である主はこう言われる。わたしは彼らを遠く異邦の民の中へ移し、国々の中に散らした。しかし、わたしは彼らが行ったその国々で、しばらくの間、彼らの聖所となっていた。』'),
('JPN', '以西结书', 26, 11, 17, 'それゆえ言え。『神である主はこう言われる。わたしはあなたがたを諸国の民の中から集め、あなたがたが散らされていた国々からあなたがたを呼び寄せ、あなたがたにイスラエルの地を与える。』'),
('JPN', '以西结书', 26, 11, 18, '彼らがそこに来るとき、すべての忌まわしいもの、すべての忌み嫌うべきものをそこから取り除く。'),
('JPN', '以西结书', 26, 11, 19, 'わたしは彼らに一つの心を与え、あなたがたのうちに新しい霊を与える。わたしは彼らのからだから石の心を取り除き、彼らに肉の心を与える。'),
('JPN', '以西结书', 26, 11, 20, 'こうして、彼らはわたしの掟に従って歩み、わたしの定めを守り行う。彼らはわたしの民となり、わたしは彼らの神となる。'),
('JPN', '以西结书', 26, 11, 21, 'しかし、忌むべきもの、忌み嫌うべきものの心を、自分の心として歩む者には、その行いを頭上に返す──神である主のことば。」'),
('JPN', '以西结书', 26, 11, 22, 'するとケルビムは翼を広げ、輪もその横についた。イスラエルの神の栄光がその上の方にあった。'),
('JPN', '以西结书', 26, 11, 23, '主の栄光はその都の中心から上って、都の東にある山の上にとどまった。'),
('JPN', '以西结书', 26, 11, 24, '霊は私を引き上げて、幻のうちに、私をカルデアにいる捕囚の民のところへ、神の霊によって連れて行った。そして、私が見たその幻は、私から去って上って行った。'),
('JPN', '以西结书', 26, 11, 25, '私は、主が私に示されたことをことごとく捕囚の民に告げた。'),
('JPN', '以西结书', 26, 12, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 12, 2, '「人の子よ。あなたは反逆の家の中に住んでいる。彼らは見る目があるのに見ず、聞く耳があるのに聞こうとしない。彼らが反逆の家だからである。'),
('JPN', '以西结书', 26, 12, 3, '人の子よ。あなたは捕囚のための荷物を整え、彼らが見ている前で、昼のうちに移れ。彼らの見ている前で、今いる場所からほかの場所へ移れ。もしかしたら、彼らに自分たちが反逆の家であることが分かるかもしれない。'),
('JPN', '以西结书', 26, 12, 4, 'あなたは、昼のうちに彼らが見ている前で、自分の荷物を捕囚のときの荷物のようにして持ち出せ。そして、捕囚に行く人々のように、彼らの見ている前で夕方出て行け。'),
('JPN', '以西结书', 26, 12, 5, '彼らの見ている前で壁に穴を開け、そこから荷物を運び出せ。'),
('JPN', '以西结书', 26, 12, 6, '彼らの見ている前で、あなたは荷物を肩に担ぎ、暗いうちに出て行き、顔をおおって地を見るな。わたしがあなたをイスラエルの家のためにしるしとするからだ。」'),
('JPN', '以西结书', 26, 12, 7, 'そこで、私は命じられたとおりにした。自分の荷物を捕囚のときの荷物のようにして昼のうちに持ち出し、夕方、自分の手で壁に穴を開け、彼らの見ている前で、暗いうちに荷物を背負って出て行った。'),
('JPN', '以西结书', 26, 12, 8, '翌朝、私に次のような主のことばがあった。'),
('JPN', '以西结书', 26, 12, 9, '「人の子よ。反逆の家、イスラエルの家は、あなたに『何をしているのか』と尋ねなかったか。'),
('JPN', '以西结书', 26, 12, 10, '彼らに言え。『神である主はこう言われる。この宣告は、エルサレムの君主、およびそこにいるイスラエルの全家に関わるものである。』'),
('JPN', '以西结书', 26, 12, 11, 'また言え。『私は、あなたがたへのしるしである。私がしたようなことが彼らにもなされる。彼らは捕囚となって引いて行かれる。'),
('JPN', '以西结书', 26, 12, 12, '彼らのうちにいる君主は、暗いうちに荷物を背負って出て行く。出て行けるように壁に穴が開けられる。彼は顔をおおう。自分の目でその地を見ることはもうないからである。』'),
('JPN', '以西结书', 26, 12, 13, 'わたしはまた、彼の上にわたしの網をかけ、彼はわたしの罠にかかる。わたしは彼をカルデア人の地、バビロンへ連れて行く。しかし、彼はその地を見ずに、そこで死ぬ。'),
('JPN', '以西结书', 26, 12, 14, 'わたしはまた、周囲にいて彼を助ける者たちや、彼の軍隊をみな四方に追い散らし、剣を抜いて彼らの後を追う。'),
('JPN', '以西结书', 26, 12, 15, 'わたしが彼らを諸国の間に散らし、国々に追い散らすとき、彼らは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 12, 16, 'わたしは彼らの中のわずかな者を、剣や飢饉や疫病から免れさせる。こうして彼らは、行く先の国々の中で、自分たちのした忌み嫌うべきわざをことごとく語り告げるようになる。そのとき彼らは、わたしが主であることを知る。」'),
('JPN', '以西结书', 26, 12, 17, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 12, 18, '「人の子よ。震えながらあなたのパンを食べ、おののきながら、恐る恐るあなたの水を飲め。'),
('JPN', '以西结书', 26, 12, 19, 'この国の人々に言え。『神である主は、イスラエルの地にいるエルサレムの住民について、こう言われる。彼らは自分たちのパンを恐る恐る食べ、自分たちの水をおびえながら飲むようになる。こうしてその地は、そこに住むすべての者の暴虐のゆえに痩せ衰える。'),
('JPN', '以西结书', 26, 12, 20, '人の住んでいた町々が廃墟となり、その地が荒れ果てるそのとき、あなたがたは、わたしが主であることを知る。』」'),
('JPN', '以西结书', 26, 12, 21, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 12, 22, '「人の子よ。あなたがたがイスラエルの地について、『日は延ばされ、すべての幻は消え失せる』と言っている、あのことわざは何なのか。'),
('JPN', '以西结书', 26, 12, 23, 'それゆえ、彼らに言え。『神である主はこう言われる。わたしは、あのことわざをなくす。イスラエルでは、もうそのように言わなくなる。』かえって、彼らにこう告げよ。『その日は近づき、幻のすべては実現する』と。'),
('JPN', '以西结书', 26, 12, 24, 'もう、むなしい幻も、へつらいの占いも、ことごとくイスラエルの家からなくなるからだ。'),
('JPN', '以西结书', 26, 12, 25, 'それは、主であるわたしが語り、わたしが語ったことを実現し、決して引き延ばさないからだ。反逆の家よ。あなたがたが生きているうちに、わたしは言ったことを実現させる──神である主のことば。」'),
('JPN', '以西结书', 26, 12, 26, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 12, 27, '「人の子よ。今、イスラエルの家は言っている。『彼が見ている幻はずっと後のことについてであり、はるか遠い将来について預言しているのだ。』'),
('JPN', '以西结书', 26, 12, 28, 'それゆえ、彼らに言え。『神である主はこう言われる。わたしのすべてのことば、わたしが語ることは、もはや引き延ばされることはなく、必ず成就する──神である主のことば。』」'),
('JPN', '以西结书', 26, 13, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 13, 2, '「人の子よ。預言をしているイスラエルの預言者どもに対して預言せよ。自分の心のままに預言する者どもに向かって言え。『主のことばを聞け。'),
('JPN', '以西结书', 26, 13, 3, '神である主はこう言われる。わざわいだ。自分で何も見ないのに、自分の霊に従う愚かな預言者ども。'),
('JPN', '以西结书', 26, 13, 4, 'イスラエルよ。あなたの預言者どもは、廃墟にいる狐のようになった。'),
('JPN', '以西结书', 26, 13, 5, 'あなたがたは、主の日の戦いに耐えられるように、破れ口に上ったり、イスラエルの家の石垣を築いたりしなかった。'),
('JPN', '以西结书', 26, 13, 6, '彼らはむなしい幻を見、まやかしの占いをして、「主のことば」などと言っている。主が彼らを遣わしたのではないのに。しかも、彼らはそのことが成就するのを待ち望んでいる。'),
('JPN', '以西结书', 26, 13, 7, 'あなたがたが見ているのはむなしい幻、あなたがたが語るのはまやかしの占いではないか。「主のことば」などと言っているが、わたしが語っているのではない。'),
('JPN', '以西结书', 26, 13, 8, 'それゆえ、神である主はこう言われる。あなたがたは、むなしいことを語り、まやかしの幻を見てきた。それゆえ今、わたしはあなたがたに敵対する──神である主のことば──。'),
('JPN', '以西结书', 26, 13, 9, 'わたしは、むなしい幻を見、まやかしの占いをしている預言者どもに手を下す。彼らはわたしの民の交わりに加えられず、イスラエルの家の文書にもその名を記されない。イスラエルの地にも入ることができない。そのときあなたがたは、わたしが神、主であることを知る。'),
('JPN', '以西结书', 26, 13, 10, '実に彼らは、平安がないのに「平安」と言って、わたしの民を惑わし、壁を築くとすぐ、それに漆喰で上塗りをしてしまう。'),
('JPN', '以西结书', 26, 13, 11, '漆喰で上塗りをする者どもに言え。それははがれ落ちる、と。豪雨が起こり、わたしが雹を降らせ、激しい風を吹きつけると、'),
('JPN', '以西结书', 26, 13, 12, '壁は落ちる。人々はあなたがたに向かって「上塗りをした漆喰はどこにあるのか」と言わないだろうか。'),
('JPN', '以西结书', 26, 13, 13, 'それゆえ、神である主はこう言われる。わたしは、憤りによって激しい風を吹きつける。怒りによって豪雨が起こり、激しい憤りによって破壊のための雹が降る。'),
('JPN', '以西结书', 26, 13, 14, 'あなたがたが漆喰で上塗りした壁を、わたしが壊し、地に倒してしまうので、その土台までもあらわにされる。それが倒れ落ち、あなたがたがその中で滅びるとき、あなたがたは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 13, 15, 'わたしは、その壁と、それを漆喰で上塗りした者どもへのわたしの憤りを終わらせて、あなたがたに言う。「壁もなくなり、それに漆喰を塗った者どももいなくなった」と。'),
('JPN', '以西结书', 26, 13, 16, 'エルサレムについて預言し、平安がないのに平安の幻を見ていたイスラエルの預言者どもよ──神である主のことば。』'),
('JPN', '以西结书', 26, 13, 17, '人の子よ。あなたは、自分の心のままに預言するあなたの民の娘たちに顔を向け、彼女たちに預言せよ。'),
('JPN', '以西结书', 26, 13, 18, '『神である主はこう言われる。わざわいだ。どの人の手首にも呪法のひもを縫い合わせ、あらゆる高さの頭にも合うようにベールを作って、人々のたましいを罠にかける女たち。あなたがたは、わたしの民のたましいを罠にかけ、自分たちのたましいのために人々を生かしているのだ。'),
('JPN', '以西结书', 26, 13, 19, 'あなたがたは、ひとつかみの大麦のため、少しばかりのパンのために、まやかしに聞き従うわたしの民にまやかしを行い、死んではならないたましいを死なせ、生きていてはならないたましいを生かして、わたしの民のうちでわたしを汚した。'),
('JPN', '以西结书', 26, 13, 20, 'それゆえ、神である主はこう言われる。見よ。あなたがたが、鳥を捕るように人々のたましいを罠にかけた、呪いのひもにわたしは敵対する。それらをあなたがたの腕からもぎ取り、あなたがたが鳥を捕るように罠にかけたたましいを、わたしは解き放つ。'),
('JPN', '以西结书', 26, 13, 21, 'わたしはあなたがたのベールをはがし、わたしの民をあなたがたの手から救い出す。罠にかかった者たちは、もうあなたがたの手のうちにはいなくなる。そのときあなたがたは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 13, 22, 'あなたがたは、わたしが悲しませなかったのに、正しい人の心を偽りで悲しませた。悪しき者を力づけ、彼が悪の道から立ち返って生きることがないようにした。'),
('JPN', '以西结书', 26, 13, 23, 'それゆえ、あなたがたは、もう、むなしい幻を見ることができず、占いもできなくなる。わたしは、わたしの民をあなたがたの手から救い出す。そのときあなたがたは、わたしが主であることを知る。』」'),
('JPN', '以西结书', 26, 14, 1, 'イスラエルの長老たちの何人かが来て、私の前に座った。'),
('JPN', '以西结书', 26, 14, 2, 'そのとき、私に次のような主のことばがあった。'),
('JPN', '以西结书', 26, 14, 3, '「人の子よ。これらの者たちは自分たちの偶像を心の中に秘め、自分たちを不義に引き込むものを、顔の前に置いている。わたしは、どうして彼らに応じられるだろうか。'),
('JPN', '以西结书', 26, 14, 4, 'それゆえ、彼らに告げて、こう言え。『神である主はこう言われる。心の中に偶像を秘めて、不義に引き込むものを自分の顔の前に置きながら、預言者のところに来るすべてのイスラエルの家の者には、その偶像の多さに応じて、主であるわたしが答える。'),
('JPN', '以西结书', 26, 14, 5, 'こうして、偶像のゆえにみなわたしから離されてしまったイスラエルの家の心を、わたしがとらえる。』'),
('JPN', '以西结书', 26, 14, 6, 'それゆえ、イスラエルの家に言え。『神である主はこう言われる。立ち返れ。あなたがたのすべての偶像から身を翻せ。すべての忌み嫌うべきものをあなたがたの前から遠ざけよ。'),
('JPN', '以西结书', 26, 14, 7, 'イスラエルの家の者でも、イスラエルに寄留している者でも、だれでもわたしから離れ、心の中に偶像を秘めて、自分を不義に引き込むものを顔の前に置きながら、わたしに尋ねようと預言者のところに来る者には、主であるわたし自身が答える。'),
('JPN', '以西结书', 26, 14, 8, 'わたしはそのような者に敵対してわたしの顔を向け、彼をしるしとし、語りぐさとして、わたしの民の間から絶ち滅ぼす。そのときあなたがたは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 14, 9, 'もし預言者が惑わされてことばを語るなら、主であるわたしがその預言者を惑わしたのである。わたしはその者に手を伸ばして、わたしの民イスラエルのうちから根絶やしにする。'),
('JPN', '以西结书', 26, 14, 10, 'このような者たちは自分の咎を負う。その預言者の咎と、尋ね求めた者の咎は同じである。'),
('JPN', '以西结书', 26, 14, 11, 'こうしてイスラエルの家は、もうわたしから迷い出ることはなく、重ねて自分たちの背きによって自分自身を汚すことはなくなる。彼らはわたしの民となり、わたしは彼らの神となる──神である主のことば。』」'),
('JPN', '以西结书', 26, 14, 12, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 14, 13, '「人の子よ。国が、わたしに対して罪あるものとなって信頼を裏切り、そのためわたしがその国に手を伸ばし、そこのパンの蓄えをなくし、その国に飢饉を送り、人や家畜をそこから絶ち滅ぼすとき、'),
('JPN', '以西结书', 26, 14, 14, 'たとえ、そこにノアとダニエルとヨブの、これら三人の者がいても、彼らは自分たちの義によって自分たちのいのちを救い出すだけだ──神である主のことば──。'),
('JPN', '以西结书', 26, 14, 15, 'もし、その国にわたしが悪い獣を行き巡らせ、それを不毛にし、荒れ果てさせ、獣ゆえに通り過ぎる者もいなくなるなら、'),
('JPN', '以西结书', 26, 14, 16, 'たとえ、その中にこれら三人の者がいても──わたしは生きている。神である主のことば──彼らは決して自分の息子も娘も救い出すことはできない。ただ彼ら自身だけが救い出され、その地は荒れ果てる。'),
('JPN', '以西结书', 26, 14, 17, 'あるいは、わたしがその地の上に剣をもたらし、『剣よ、この地を行き巡れ』と言って、人や家畜をそこから絶ち滅ぼすとき、'),
('JPN', '以西结书', 26, 14, 18, 'たとえ、その地にこれら三人の者がいても──わたしは生きている。神である主のことば──彼らは決して自分の息子も娘も救い出すことはできない。ただ彼ら自身だけが救い出される。'),
('JPN', '以西结书', 26, 14, 19, 'あるいは、わたしがその地に疫病を送って、人や家畜をそこから絶ち滅ぼすために、流血をもってわたしの憤りをその地に注ぐとき、'),
('JPN', '以西结书', 26, 14, 20, 'たとえ、そこにノアとダニエルとヨブがいても──わたしは生きている。神である主のことば──彼らは決して息子も娘も救い出すことはできない。彼らは自分たちの義によって自分たちのいのちを救い出すだけだ。」'),
('JPN', '以西结书', 26, 14, 21, 'まことに、神である主はこう言われる。「人や家畜を絶ち滅ぼすために、わたしが剣と飢饉と悪い獣と疫病の、四つのひどい刑罰をエルサレムに送るとき、'),
('JPN', '以西结书', 26, 14, 22, '見よ。そこに逃れの者が残っていて、息子や娘たちを連れ出し、あなたがたのところにやって来る。あなたがたは彼らの生き方と行いを見て、わたしがエルサレムにもたらしたわざわいと、わたしがそこにもたらしたことすべてについて、慰めを受ける。'),
('JPN', '以西结书', 26, 14, 23, 'あなたがたは、彼らの生き方と行いとを見て慰められる。このとき、あなたがたは、わたしがそこでしたすべてのことは、理由もなくしたのではないことを知る──神である主のことば。」'),
('JPN', '以西结书', 26, 15, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 15, 2, '「人の子よ。ぶどうの木は森の木立の中にあって、ほかの木より枝がどれだけすぐれているのか。'),
('JPN', '以西结书', 26, 15, 3, '何か役に立つものを作る木材が、そこからとれるというのか。それとも、何かの器具を掛ける木鉤を作ることができるというのか。'),
('JPN', '以西结书', 26, 15, 4, '見よ。それは薪として火に投げ入れられ、火がその両端を焼き尽くす。その中まで焦げてしまえば、それは何の役に立つだろうか。'),
('JPN', '以西结书', 26, 15, 5, '見よ。それが完全なときでも何も作れないのに、まして、火がそれを燃やして焦がせば、それで何が作れるだろうか。」'),
('JPN', '以西结书', 26, 15, 6, 'それゆえ、神である主はこう言われる。「わたしが薪として火に投げ入れた、森の木立の間のぶどうの木のように、わたしはエルサレムの住民を火に投げ入れる。'),
('JPN', '以西结书', 26, 15, 7, 'わたしは彼らに敵対して顔を向ける。彼らが火から逃れても、火は彼らを焼き尽くす。わたしが彼らに顔を向けるそのとき、あなたがたはわたしが主であることを知る。'),
('JPN', '以西结书', 26, 15, 8, '彼らがわたしの信頼を裏切ったので、わたしはこの地を荒れ果てさせる──神である主のことば。」'),
('JPN', '以西结书', 26, 16, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 16, 2, '「人の子よ。エルサレムにその忌み嫌うべきわざを告げ知らせよ。'),
('JPN', '以西结书', 26, 16, 3, '『神である主はエルサレムについてこう言われる。あなたの出身、あなたの生まれはカナン人の地、あなたの父はアモリ人、あなたの母はヒッタイト人であった。'),
('JPN', '以西结书', 26, 16, 4, 'あなたの生まれについて言えば、あなたが生まれた日に、あなたは、へその緒を切られず、水で洗いきよめられず、塩でこすられず、布で包まれることもなかった。'),
('JPN', '以西结书', 26, 16, 5, 'だれもあなたにあわれみをかけず、これらのことの一つでもあなたにしてやって、あなたに同情しようとはしなかった。あなたの生まれた日に、あなたは嫌われ、野に捨てられた。'),
('JPN', '以西结书', 26, 16, 6, 'わたしがあなたのそばを通りかかったとき、あなたが自分の血の中でもがいているのを見て、わたしは血に染まったあなたに「生きよ」と言い、血に染まったあなたに、繰り返して「生きよ」と言った。'),
('JPN', '以西结书', 26, 16, 7, 'わたしはあなたを野原の新芽のように育て上げた。あなたは成長して大きくなり、十分に成熟して、乳房はふくらみ、髪も伸びた。しかし、あなたは丸裸であった。'),
('JPN', '以西结书', 26, 16, 8, 'わたしがそばを通りかかってあなたを見ると、ちょうど、あなたは恋をする年ごろになっていた。わたしは衣の裾をあなたの上に広げ、あなたの裸をおおった。わたしはあなたに誓って、あなたと契りを結んだ──神である主のことば──。そして、あなたはわたしのものとなった。'),
('JPN', '以西结书', 26, 16, 9, 'わたしはあなたを水で洗い、あなたの血を洗い落とし、あなたに油を塗った。'),
('JPN', '以西结书', 26, 16, 10, 'わたしはまた、あや織りの衣服をあなたに着せ、じゅごんの皮の履き物をはかせ、亜麻布をかぶらせ、絹物でおおった。'),
('JPN', '以西结书', 26, 16, 11, 'それから、わたしは飾り物であなたを飾り、腕には腕輪をはめ、首には首飾りをかけ、'),
('JPN', '以西结书', 26, 16, 12, '鼻には鼻輪、両耳には耳輪を着け、頭には輝かしい冠をかぶらせた。'),
('JPN', '以西结书', 26, 16, 13, 'あなたは金や銀で飾られ、亜麻布や絹やあや織物を着て、上等の小麦粉や蜜や油を食べた。こうして、あなたは非常に美しくなり、女王の位に進んだ。'),
('JPN', '以西结书', 26, 16, 14, 'あなたの美しさのゆえに、あなたの名は国々の間に広まった。それは、わたしがあなたにまとわせた、わたしの飾り物が完全であったからだ──神である主のことば。'),
('JPN', '以西结书', 26, 16, 15, 'ところが、あなたは自分の美しさに拠り頼み、自分の名声に乗じて姦淫を行い、通りかかる人がいれば、だれにでも身を任せて姦淫をした。'),
('JPN', '以西结书', 26, 16, 16, 'あなたはまた、自分の衣服を取り出して、自分のために、斑に色どった高き所を造り、その上で淫行を行った。このようなことはかつてなく、あってはならないことだ。'),
('JPN', '以西结书', 26, 16, 17, 'あなたは、わたしが与えた金や銀の美しい品々を取って、自分のために男の像を造り、それらと姦淫を行った。'),
('JPN', '以西结书', 26, 16, 18, 'あなたはまた、あや織りの衣を取って、それらの像をおおい、わたしの油と、わたしの香をその前に供えた。'),
('JPN', '以西结书', 26, 16, 19, 'あなたは、わたしが与えたわたしのパンや、あなたに食べさせた上等の小麦粉や、油や蜜までも、その前に供えて芳ばしい香りとした。そうではなかったか──神である主のことば──。'),
('JPN', '以西结书', 26, 16, 20, 'あなたはまた、わたしのために産んだ自分の息子や娘たちを取り、それらの像にいけにえとして献げて食べさせた。これでもまだ、あなたは姦淫が十分ではないかのように、'),
('JPN', '以西结书', 26, 16, 21, 'わたしの子どもたちを殺し、これを焼いて、ささげ物とした。'),
('JPN', '以西结书', 26, 16, 22, 'あらゆる忌み嫌うべきことや姦淫をしているとき、あなたは、かつて自分が丸裸のまま、血の中でもがいていた若いころのことを思い出さなかった。'),
('JPN', '以西结书', 26, 16, 23, 'あなたはこのすべての悪行の後で──ああ、何ということか。神である主のことば──'),
('JPN', '以西结书', 26, 16, 24, 'どの広場にも自分のために祭儀台を設け、高台を造り、'),
('JPN', '以西结书', 26, 16, 25, '道のどの分かれ目にも高台を築き、通りかかるすべての人に身を任せ、姦淫を重ねて、自分の美しさを汚した。'),
('JPN', '以西结书', 26, 16, 26, 'あなたは、良いからだをした隣のエジプト人と姦通し、ますます姦淫を重ねて、わたしの怒りを引き起こした。'),
('JPN', '以西结书', 26, 16, 27, '見よ、わたしは、あなたに手を伸ばして、あなたの食糧を減らした。そして、あなたを憎み、あなたの淫らな行いによって辱めを受けたペリシテ人の娘たちの欲望にあなたを委ねた。'),
('JPN', '以西结书', 26, 16, 28, 'あなたは飽き足りず、アッシリア人と姦通した。彼らと姦通しても、まだ飽き足りず、'),
('JPN', '以西结书', 26, 16, 29, '商業の地カルデアとますます姦淫を重ねたが、それでも、あなたは飽き足りなかった。'),
('JPN', '以西结书', 26, 16, 30, 'あなたの心は、なんと燃え盛っていることか──神である主のことば──。厚かましい遊女のするようなこれらのことを、ことごとく行うとき。'),
('JPN', '以西结书', 26, 16, 31, 'あなたはどの通りの角にも自分の祭儀台を設け、どの広場にも高台を造った。しかし、あなたは報酬を嘲ったので、遊女のようではなかった。'),
('JPN', '以西结书', 26, 16, 32, '姦婦は自分の夫の代わりに、ほかの男と通じるものだ。'),
('JPN', '以西结书', 26, 16, 33, 'すべて遊女には代価が支払われるのに、あなたは自分のほうから愛人たちすべてに持参金を与え、贈り物もして、四方からあなたのところに来させて姦淫をした。'),
('JPN', '以西结书', 26, 16, 34, 'だから、あなたの姦淫はほかの女の場合と反対だ。だれも、あなたを求めて姦淫をする者はいなかった。あなたが報酬を支払い、あなたには、だれも報酬を支払わなかった。あなたは反対のことをしたのだ。'),
('JPN', '以西结书', 26, 16, 35, 'それゆえ、遊女よ、主のことばを聞け。'),
('JPN', '以西结书', 26, 16, 36, '神である主はこう言われる。あなたは愛人たちや忌み嫌うべき偶像と姦淫をして、自分の恥ずかしいところを見せ、自分の裸をあらわにし、それらに自分の子を献げて血を流したのだ。'),
('JPN', '以西结书', 26, 16, 37, 'それゆえ、見よ。わたしは今、あなたが戯れたすべての愛人たちや、あなたが恋した者や、憎んだ者をすべて寄せ集め、彼らを四方から集めて、あなたの裸を彼らにさらけ出す。彼らは丸裸のあなたを見る。'),
('JPN', '以西结书', 26, 16, 38, 'わたしは、姦通した女と殺人を犯した女に下す罰によってあなたをさばき、ねたみと憤りをもってあなたの血に報いる。')
on conflict (version, book, chapter, verse) do nothing;
